window.__SUM[9]={"LR003637":{"pair":"a -> Atrn","headline":"Agouti is reported as a low-affinity ligand for attractin from one mouse abstract-only paper; no binding constant is given.","interaction_type":"functional only","direction_and_effect":"Attractin acts as a low-affinity receptor for agouti protein but not Agrp, in vitro and in vivo; loss of attractin function in mahogany mutant mice blocks the effects of lethal yellow agouti overexpression [PMID:11137996].","molecular_requirements":"Not reported in our evidence beyond attractin being a transmembrane protein [PMID:11137996].","affinity_potency":[],"species_and_systems":"Mouse ligand and mouse receptor; transgenic, biochemical and genetic-interaction experiments [PMID:11137996].","localisation_and_range":"Agouti is flagged secreted [flag]; the abstract calls it a paracrine molecule normally limited to skin, and attractin a widely expressed transmembrane protein [PMID:11137996].","caveats":"Single paper, read as abstract only. Affinity is described only as low; no value reported. Specificity: agouti but not Agrp [PMID:11137996].","key_references":[{"PMID":"11137996","why":"Transgenic/genetic-interaction evidence that attractin is a low-affinity agouti receptor, not an Agrp receptor"}],"covers":["LR003637"]},"LR003556":{"pair":"ADAM12 -> SDC4","headline":"The ADAM12 cysteine-rich domain supports cell attachment through syndecan-4 and triggers beta1-integrin-dependent spreading.","interaction_type":"functional only","direction_and_effect":"rADAM12-cys supports cell attachment using syndecan-4 as a primary receptor, which then triggers beta(1) integrin-dependent spreading, stress fibres and focal adhesions via PKC-alpha and RhoA [PMID:12509413].","molecular_requirements":"Syndecan-2 could not replace syndecan-4, and a mutant syndecan-4 deficient in PKC-alpha activation failed to promote spreading; downstream beta1 integrin needed [PMID:12509413].","affinity_potency":[],"species_and_systems":"Human proteins recorded; recombinant ADAM12 cysteine-rich domain in cell assays including Chinese hamster ovary beta1 cells [PMID:12509413].","localisation_and_range":"ADAM12 is flagged secreted [flag]; the ligand here is a recombinant domain, not full-length membrane ADAM12.","caveats":"One paper, abstract only; the ligand is the isolated cysteine-rich domain; direct binding constants are not reported.","key_references":[{"PMID":"12509413","why":"ADAM12 cysteine-rich domain acts through syndecan-4"}],"covers":["LR000006","LR003556"]},"LR005392":{"pair":"ADAM17 -> CD9","headline":"CD9 directly associates with ADAM17 and dampens its sheddase activity; this is a regulatory partner pair, not a signalling ligand-receptor pair.","interaction_type":"direct binding","direction_and_effect":"Treatment with CD9-specific antibodies or CD9 neoexpression reduces ADAM17 sheddase activity, and CD9 silencing increases activity against TNF-alpha and ICAM-1 [PMID:21365281]. Curators label the effect antagonist.","molecular_requirements":"Not reported in our evidence beyond CD9 being a tetraspanin [PMID:21365281].","affinity_potency":[],"species_and_systems":"Human endothelial and monocytic cells; proximity ligation, co-IP, crosslinking and pull-down [PMID:21365281].","localisation_and_range":"Both partially co-localise on the cell surface [PMID:21365281]; ADAM17 is flagged not secreted [flag].","caveats":"One paper, abstract only. IntAct has an anti-bait co-IP record from another paper [DB:IntAct].","key_references":[{"PMID":"21365281","why":"Direct ADAM17-CD9 association with negative regulation of shedding"}],"covers":["LR002066","LR005392"]},"LR008209":{"pair":"ADAM17 -> ITGA5:ITGB1","headline":"ADAM17 supports alpha5beta1-dependent adhesion in HeLa and other cell lines; functional evidence from one abstract-only paper.","interaction_type":"functional only","direction_and_effect":"Recombinant ADAM-17 ectodomain fragments mediate adhesion through alpha5beta1 in trans, sensitive to RGD peptides and EDTA, consistent with the integrin ligand pocket [PMID:14970227].","molecular_requirements":"The complex alpha5beta1 is the tested receptor; the ADAM-17 binding site narrows to the disintegrin/cysteine-rich region [PMID:14970227]. Whether one chain alone suffices is not reported in our evidence.","affinity_potency":[],"species_and_systems":"Human; HeLa cells and a cell-line adhesion panel [PMID:14970227].","localisation_and_range":"ADAM17 is flagged non-secreted [flag]. Trans adhesion to recombinant fragments; co-localisation at ruffles, focal adhesions and the leading edge of wounded monolayers [PMID:14970227].","caveats":"Abstract read only; functional, not direct binding. IntAct records exist for ADAM17 with ITGB1 [DB:IntAct].","key_references":[{"PMID":"14970227","why":"ADAM-17 / alpha5beta1 functional interaction"}],"covers":["LR008209"]},"LR003565":{"pair":"ADAM28 -> ITGA4","headline":"ADAM28 disintegrin domain is recognised by integrin alpha4beta1 on human lymphocyte lines; abstract only.","interaction_type":"functional only","direction_and_effect":"Jurkat adhesion to the MDC-L (ADAM 28) disintegrin domain was inhibited by anti-alpha4 and anti-beta1 mAbs, and alpha4beta1-transfected K562 cells adhered while untransfected did not [PMID:11724793].","molecular_requirements":"Both alpha4 and beta1 are implicated; adhesion correlated with alpha4 expression across cell lines [PMID:11724793].","affinity_potency":[],"species_and_systems":"Human; Jurkat T-lymphoma and K562 transfectants with recombinant Fc fusions [PMID:11724793].","localisation_and_range":"ADAM28 is flagged secreted [flag], but the paper says MDC-L is expressed on the surface of human lymphocytes [PMID:11724793].","caveats":"Abstract read only; adhesion assays.","key_references":[{"PMID":"11724793","why":"ADAM28 disintegrin is a ligand for alpha4beta1"}],"covers":["LR000015","LR003565"]},"LR003574":{"pair":"ADAM9 -> ITGB1","headline":"ADAM9 disintegrin domain binds beta1 integrins (alpha6beta1 shown); two abstract-only papers, human and mouse reagents.","interaction_type":"direct binding","direction_and_effect":"Murine meltrin gamma (ADAM9)-Fc bound integrin alpha6beta1 on HT1080 and Wehi 164 fibroblast lines in solid-phase and antibody-inhibition assays; cells on it showed rounded morphology and eight- to tenfold higher motility than on laminin, reduced by ROCK inhibitor Y-27632 [PMID:10825303]. Disintegrin domain capture of beta1 and other chains from renal lysate [PMID:15361064]. Curated effect: Stimulatory [flag].","molecular_requirements":"alpha6 partner shown for beta1 [PMID:10825303]; other beta1 integrins (alpha3, alphav) captured as chains [PMID:15361064]. The disintegrin domain is sufficient [PMID:15361064].","affinity_potency":[],"species_and_systems":"Mouse ADAM9-Fc on human cell lines [PMID:10825303]; human HEK-293 and renal lysate [PMID:15361064]. Mouse pair in the dossier is ortholog-inferred.","localisation_and_range":"Annotation flags mark ADAM9 as secreted [flag], but the papers use its disintegrin domain as a recombinant or cell-surface-expressed protein, so the physiologically relevant range (juxtacrine versus shed) is not settled in our evidence.","caveats":"Both read as abstracts only. ITGB1 alone is a shared chain, so the pair is broad across alpha partners. Affinity not reported.","key_references":[{"PMID":"10825303","why":"meltrin gamma-Fc binds alpha6beta1 and drives motility"},{"PMID":"15361064","why":"disintegrin domain recovers beta1 and other chains"}],"covers":["LR000024","LR003574"]},"LR003583":{"pair":"ADM2 -> RAMP1","headline":"ADM2 binds the RAMP1-CLR extracellular complex (crystal structure); RAMP1 acts with CLR, not alone.","interaction_type":"direct binding","direction_and_effect":"AM2/IMD bound the purified RAMP1-CLR ECD complex, and a 2.05 \u00c5 crystal structure with an antagonist fragment showed a triple beta-turn conformation, confirmed by mutagenesis [PMID:30139742]. GtoPdb lists a full agonist [DB:GtoPdb]. A PDB structure is recorded [DB:PDB 6D1U].","molecular_requirements":"RAMP1 together with CLR; AM2/IMD bound all three RAMP-CLR ECD complexes, preferring the RAMP1 (CGRP) and RAMP3 (AM2) complexes [PMID:30139742]. A bound fragment was an antagonist, not the full agonist peptide.","affinity_potency":[],"species_and_systems":"Purified recombinant ECD complexes; curators annotate human ligand and receptor. Mouse pair projected from human.","localisation_and_range":"RAMP1 is flagged receptor [flag]; ADM2 flagged secreted [flag].","caveats":"Abstract-only. The structure used an antagonist fragment. Agonism evidence is only the GtoPdb record. Review-only and abstract_insufficient papers not shown.","key_references":[{"PMID":"30139742","why":"crystal structure and binding of AM2/IMD to RAMP-CLR ECD"}],"covers":["LR000033","LR003583"]},"LR002089":{"pair":"AGGF1 -> ITGB1","headline":"Same paper as the ITGA5 pair: AGGF1 acts through integrin alpha5beta1, where beta1 is the partner chain; antibody and pull-down evidence in endothelial cells.","interaction_type":"functional only","direction_and_effect":"Neutralising antibodies identified alpha5beta1 as the AGGF1 receptor on ECs; AGGF1 activates FAK, Src and AKT [PMID:34551592].","molecular_requirements":"Two different anti-beta1 antibodies and an anti-alpha5beta1 antibody disrupted HUVEC binding to AGGF1; the angiogenic-domain deletion mutant failed to precipitate integrin alpha5 and beta1 [PMID:34551592]. Beta1 needs alpha5 in this evidence; CCC scoring should use the pair.","affinity_potency":[{"value":"T1/2 18.7 nM","assay":"half-maximum binding concentration, cell adhesion assay (not a Kd)","system":"HUVEC","cite":"PMID:34551592"}],"species_and_systems":"Human HUVEC, also mouse aortic endothelial cells and a mouse peripheral-artery-disease model [PMID:34551592]. The mouse pair is projected from human.","localisation_and_range":"AGGF1 is flagged secreted [flag]; ITGB1 is flagged not secreted and receptor [flag].","caveats":"One paper. Pull-down in the excerpts shows integrin alpha5 from HUVEC extract; beta1 evidence is antibodies and domain-deletion pull-down. Not purified-protein binding.","key_references":[{"PMID":"34551592","why":"alpha5beta1 as AGGF1 receptor in endothelial cells"}],"covers":["LR002089","LR005415"]},"LR001639":{"pair":"AGRN -> DAG1","headline":"Agrin acting through dystroglycan is supported by one full-text mouse cardiomyocyte paper plus database records; direct binding is suggested but not shown here.","interaction_type":"functional only","direction_and_effect":"Recombinant agrin promoted cardiomyocyte proliferation, and a blocking antibody against the agrin-binding site of Dag1 diminished agrin-induced ERK activation and blocked agrin-induced P7 cardiomyocyte proliferation [PMID:28581497]. Agrin acts as a stimulatory ligand; UniProt function text also describes AGRN binding to alpha-dystroglycan [DB:UniProt].","molecular_requirements":"Agrin was found in glycerol-gradient fractions containing dystrophin-glycoprotein complex components after 2 h, which the authors read as suggesting agrin binds this complex [PMID:28581497]. Reactome lists AGRN:alpha-dystroglycan and Dystroglycan:AGRN:HSPG2 complexes [DB:Reactome].","affinity_potency":[],"species_and_systems":"Mouse primary cardiomyocytes and mouse in vivo, using recombinant rat agrin [PMID:28581497]. Human and mouse pair entries are both ortholog-inferred.","localisation_and_range":"Agrin is flagged as secreted and DAG1 as a receptor [flag]; agrin is described in the paper as an extracellular matrix component [PMID:28581497].","caveats":"Evidence here is an antibody-block experiment and co-fractionation, not a binding measurement with purified proteins [PMID:28581497]. Database records include Far Western and cross-linking entries [DB:BioGRID] [DB:IntAct]. Affinity not reported in our evidence.","key_references":[{"PMID":"28581497","why":"Antibody against the agrin-binding site of Dag1 reduced agrin-induced ERK activation and proliferation (full text read)"}],"covers":["LR001639","LR005027"]},"LR011692":{"pair":"AGRN -> DOK7:MUSK","headline":"No paper evidence for this complex entry; support comes only from database records of the agrin/LRP4/MuSK complex.","interaction_type":"database-asserted only","direction_and_effect":"Database records say the AGRN-LRP4 complex induces phosphorylation and activation of MUSK [DB:UniProt]. Reactome lists an AGRN:LRP4:MUSK complex [DB:Reactome].","molecular_requirements":"The receptor entry lists DOK7 and MUSK, but the records in our evidence describe a 1:1:1 agrin/LRP4/MuSK complex, with LRP4 as the agrin-binding partner; DOK7 is not mentioned in them [DB:PDB 8S9P] [DB:Reactome].","affinity_potency":[],"species_and_systems":"Not reported in our evidence; PDB 8S9P is an electron microscopy structure of the agrin/LRP4/MuSK complex [DB:PDB 8S9P].","localisation_and_range":"Not reported in our evidence.","caveats":"No curator-verified papers; two other judgments were review_only and three abstract_insufficient. The DOK7 component has no support in the dossier.","key_references":[],"covers":["LR011692"]},"LR005419":{"pair":"AGRN -> NCAM1","headline":"A 1996 abstract-only study shows NCAM-expressing cells adhere to agrin, a heterophilic adhesion rather than classical signalling.","interaction_type":"functional only","direction_and_effect":"Mouse L cells transfected with chicken NCAM were used to identify agrin as a ligand mediating NCAM adhesion [PMID:8807193]. Reactome lists NCAM-1:Agrin and AGRN:NCAM1, PTPRS complexes [DB:Reactome].","molecular_requirements":"Chondroitin sulfate degradation decreased adhesion in agrin-containing fractions but increased it if agrin had been removed, so proteoglycan chains influence the interaction [PMID:8807193].","affinity_potency":[],"species_and_systems":"Chicken NCAM expressed in mouse L cells, tested against chick brain membrane fractions; this is not human [PMID:8807193]. Curation tags human/human.","localisation_and_range":"NCAM1 is flagged secreted and transmembrane [flag]; the adhesion was to membrane fractions [PMID:8807193].","caveats":"Abstract-only; perlecan did not support NCAM adhesion, so binding is selective among proteoglycans [PMID:8807193]. Direct binding with purified proteins is not shown. The curator effect label 'agonist' fits poorly an adhesion result.","key_references":[{"PMID":"8807193","why":"NCAM-transfected cells adhere to agrin"}],"covers":["LR002093","LR005419"]},"LR003592":{"pair":"AGRP -> MC4R","headline":"AGRP is a well-supported MC4R antagonist with binding, functional and structural abstract-level evidence and domain mapping.","interaction_type":"direct binding","direction_and_effect":"Recombinant AGRP was a potent, selective antagonist of Mc3r and Mc4r [PMID:9311920]; ART (AGRP) is an antagonist of human MC-3 and MC-4 receptors in functional assay [PMID:9299416]. GtoPdb lists an antagonist interaction with pIC50 units [DB:GtoPdb]. UniProt says the antagonist AGRP precludes agonist-induced signalling [DB:UniProt].","molecular_requirements":"Exoloops 2 and 3 of MC4R are needed for AGRP(87-132) binding, as substituting them with MC1R loops cut affinity and inhibitory activity [PMID:10318826] [PMID:12815165]. The AGRP 110-117 fragment instead depends on transmembrane domains 3 and 4 [PMID:12815165]. The RFF111-113 triplet and the Cys-110 to Cys-117 loop are critical for antagonism [PMID:9893984].","affinity_potency":[{"value":"pIC50 9.3","assay":"inhibition of radiolabeled alpha-MSH analog binding; functional antagonism","system":"human MC-4 receptor (companion MC-3 row, same paper)","cite":"PMID:9299416"}],"species_and_systems":"Human AGRP fragments and recombinant protein on human receptors or chimeras, mostly heterologous cells; transgenic mice for in vivo obesity [PMID:9311920] [PMID:12815165].","localisation_and_range":"AGRP is flagged secreted and non-transmembrane [flag].","caveats":"All six papers read as abstracts. The NMR structure is of the ligand alone [PMID:11747427]. The pIC50 9.3 comes from a row that the curator tied to MC3R and MC4R together. The pIC50 value is the dossier's affinity field and is not itemised per receptor in the abstract.","key_references":[{"PMID":"9299416","why":"Human ART/AGRP antagonises MC-3 and MC-4 receptors; pIC50 9.3"},{"PMID":"9311920","why":"Selective Mc3r/Mc4r antagonist, transgenic obesity"},{"PMID":"12815165","why":"Maps MC4R exoloop and transmembrane determinants of AGRP binding"}],"covers":["LR000042","LR003592"]},"LR002098":{"pair":"ALB -> FCGRT","headline":"Albumin binds FcRn directly with 1:1 stoichiometry and strong pH dependence; supported by one binding paper and structural database records.","interaction_type":"direct binding","direction_and_effect":"FcRn binds and protects albumin, returning it to the extracellular compartment; binding is high affinity at low pH in the acid endosome and weaker at neutral pH [PMID:16605266]. Complex structures are deposited [DB:PDB 4N0F].","molecular_requirements":"Albumin and IgG bind noncooperatively to distinct sites on FcRn; ITC shows 1:1 stoichiometry [PMID:16605266].","affinity_potency":[{"value":"~200-fold lower affinity at neutral than acidic pH","assay":"surface plasmon resonance","system":"human FcRn and albumin (per curator)","cite":"PMID:16605266"}],"species_and_systems":"Curator records human protein and human receptor; recombinant binding assays [PMID:16605266].","localisation_and_range":"Acts in the acidic endosome; FCGRT flagged receptor [flag].","caveats":"Absolute Kd not reported in our evidence. Paper read as abstract only. Mouse pair is ortholog-inferred. FcRn-albumin kinetics are rapid [PMID:16605266].","key_references":[{"PMID":"16605266","why":"SPR and ITC of albumin-FcRn binding and pH dependence"}],"covers":["LR002098","LR005424"]},"LR001648":{"pair":"AMBN -> CD63","headline":"Ameloblastin binds CD63 in human-based studies; abstract-level evidence from two papers, with downstream integrin beta1/Src signalling.","interaction_type":"direct binding","direction_and_effect":"Ameloblastin binds CD63 and promotes CD63 binding to integrin beta1, leading to Src inactivation and osteogenic differentiation; anti-CD63 antibody abrogated the effect [PMID:21149578]. Described as an agonist-type effect [PMID:21149578].","molecular_requirements":"CD63 residues 103-205 interact with ameloblastin and enamelin as well as amelogenin; the binding region is predicted to lie within the CD63 extracellular domain 2 [PMID:17708745]. Integrin beta1 is required downstream [PMID:21149578].","affinity_potency":[],"species_and_systems":"Curators recorded human ligand and receptor [PMID:17708745] [PMID:21149578]; cell systems are not reported in our evidence.","localisation_and_range":"Ameloblastin is flagged secreted [flag]; the paper proposes interaction of secreted matrix proteins with membrane CD63 at ameloblast secretory surfaces [PMID:17708745]. Matrix protein acting on a cell-surface tetraspanin.","caveats":"Both papers were read as abstracts only. No affinity values. No database records support this pair.","key_references":[{"PMID":"17708745","why":"Mapping CD63 region 103-205 binding ameloblastin and other enamel proteins"},{"PMID":"21149578","why":"Ameloblastin-CD63-integrin beta1-Src signalling in osteoblasts"}],"covers":["LR001648","LR005036"]},"LR005428":{"pair":"ANGPT2 -> ITGAV","headline":"One abstract-only paper shows Ang2 interacting with alphaVbeta1 integrin and signalling in Tie2-deficient glioma cells.","interaction_type":"functional only","direction_and_effect":"Ang2 interacts with alpha(v)beta(1) integrin in Tie2-deficient human glioma cells, activating FAK, p130(Cas), ERK1/2 and JNK and enhancing MMP-2 expression and secretion; the curator labels it agonist and the pathway is Tie2-independent [PMID:16424009].","molecular_requirements":"Functional inhibition of both beta1 and alpha(v) integrins attenuated the pathway, so both chains are required; the measured receptor is alphaVbeta1, not alphaVbeta3 as the entity name suggests [PMID:16424009].","affinity_potency":[],"species_and_systems":"Human glioma cells and murine brain xenografts [PMID:16424009]; the mouse pair is ortholog-inferred.","localisation_and_range":"ANGPT2 is flagged as secreted [flag]; ITGAV is flagged as a receptor.","caveats":"Abstract only; the abstract reports 'interacts' and functional inhibition, not a direct binding measurement or affinity. The receptor entity name is alphaVbeta3 but the paper concerns alphaVbeta1. No database records for this pair.","key_references":[{"PMID":"16424009","why":"Ang2 signals via alphaVbeta1 integrin in Tie2-deficient glioma cells"}],"covers":["LR002102","LR005428"]},"LR005437":{"pair":"ANGPTL4 -> ITGB5","headline":"ANGPTL4 is reported to bind integrin \u03b25 directly; abstract-level paper plus IntAct SPR and co-IP records.","interaction_type":"direct binding","direction_and_effect":"ANGPTL4 binds integrins \u03b21 and \u03b25, but not \u03b23, as novel binding partners [PMID:20952587]. The downstream FAK-Src-PAK1 signalling in the paper is attributed to \u03b21-bound ANGPTL4, so an effect through \u03b25 is not reported in our evidence [PMID:20952587].","molecular_requirements":"Integrin \u03b25 alone is named; \u03b1 partner not reported in our evidence.","affinity_potency":[],"species_and_systems":"Keratinocyte/mouse wound model; species of binding assays not recorded [PMID:20952587]. The mouse pair is ortholog-inferred, not tested directly.","localisation_and_range":"ANGPTL4 flagged secreted; ITGB5 flagged receptor [flag].","caveats":"Abstract only. IntAct lists surface plasmon resonance and anti-bait co-immunoprecipitation from PMID 21397862 [DB:IntAct].","key_references":[{"PMID":"20952587","why":"ANGPTL4 binds integrins \u03b21 and \u03b25 but not \u03b23"}],"covers":["LR002115","LR005437"]},"LR001657":{"pair":"APELA -> APLNR","headline":"ELA/Elabela is a well-supported endogenous agonist of the apelin receptor, shown by binding, signalling and in vivo studies in several species.","interaction_type":"direct binding","direction_and_effect":"ELA is an agonist of APLNR (APJ). It inhibited forskolin-induced cAMP, recruited beta-arrestin and induced internalisation, and competed for apelin binding in human heart [PMID:28137936]; it suppressed cAMP, stimulated ERK1/2 phosphorylation and weakly induced calcium mobilisation in CHO cells [PMID:25639753]. Chimeric apela bound APJ directly and apelin competed [PMID:25995451]. In zebrafish, loss of Ela phenocopies loss of aplnr [PMID:24316148]. GtoPdb lists it as an agonist [DB:GtoPdb].","molecular_requirements":"Single-chain GPCR; no co-receptor reported in our evidence. Longer ELA peptides bind better: ELA-32 pKi=9.59\u00b10.08, ELA-21 pKi=8.52\u00b10.11, ELA-11 pKi=7.85\u00b10.05 in human left ventricle [PMID:28137936]. ELA-11 retained full activity in the cAMP assay [PMID:28137936].","affinity_potency":[{"value":"Kd = 0.51 nm","assay":"binding of chimeric apela ligand to APJ","system":"abstract only; species unspecified","cite":"PMID:25995451"},{"value":"EC50 of 11.1 nM (cAMP suppression); 14.3 nM (ERK1/2 phosphorylation)","assay":"cell signalling","system":"CHO cells over-expressing human APJ","cite":"PMID:25639753"},{"value":"pKi=9.59\u00b10.08 (ELA-32)","assay":"competition binding","system":"human left ventricle homogenate","cite":"PMID:28137936"}],"species_and_systems":"Human recombinant and native human heart tissue, CHO and HEK293 cells [PMID:28137936][PMID:25639753]; rat isolated hearts [PMID:26611206]; zebrafish embryos [PMID:24316148]; mouse aortic rings [PMID:25639753]. The mouse pair is inferred from human evidence (ortholog_inferred).","localisation_and_range":"ELA is flagged secreted and non-transmembrane; APLNR is a transmembrane receptor [flag]. ELA is described as a secreted hormone expressed in adult kidney [PMID:25639753], consistent with endocrine or paracrine action.","caveats":"Several papers were read as abstracts only [PMID:25995451][PMID:26611206][PMID:24316148]. The zebrafish paper shows genetic, not binding, evidence [PMID:24316148]. Structures 7W0N, 7W0O and 7W0P contain both chains [DB:PDB 7W0N].","key_references":[{"PMID":"28137936","why":"Competition binding in human heart, signalling, and in vivo effects."},{"PMID":"25995451","why":"Direct binding with Kd and Gi signalling."},{"PMID":"25639753","why":"Potency in mammalian cells."}],"covers":["LR001657","LR005044"]},"LR005446":{"pair":"APLP1 -> CNTN3","headline":"APLP1 binds CNTN3 ectodomain in a systematic binding screen with crystal-structure context; direction as ligand to receptor is arbitrary for this adhesion pair.","interaction_type":"direct binding","direction_and_effect":"APLP1 interacts with CNTN3; the paper reports that APP and APLP1 interact with CNTN3-5 [PMID:34958801]. Signalling direction or agonist/antagonist effect is not reported in our evidence; contactins are described as forming coreceptor complexes with transmembrane proteins to transmit signals [PMID:34958801].","molecular_requirements":"Interaction involves the second fibronectin type III repeat of the contactin and the copper-binding domain of the amyloid protein, a conserved interface across five CNTN-amyloid structures [PMID:34958801]. Binding was tested with the APLP1 E1 domain and FN1-FN3 fragments of CNTN3-5 by biolayer interferometry [PMID:34958801]. CNTN3 is among the three that bind APLP1; APLP2 does not bind CNTN3 [PMID:34958801]. APLP1 appeared to bind CNTN4 more strongly than CNTN3 [PMID:34958801].","affinity_potency":[],"species_and_systems":"Human proteins in AlphaScreen extracellular binding assay and biolayer interferometry; zebrafish used for expression and some structures [PMID:34958801]. The mouse pair is inferred from human evidence.","localisation_and_range":"Contactins are GPI-anchored to the membrane [PMID:34958801]. Interaction could occur in cis on the same cell or in trans across cells [PMID:34958801]. Entity flags list APLP1 as secreted [flag], which conflicts with a membrane-anchored role.","caveats":"Paper was read for evidence as abstract per the curator, with full-text excerpts available [PMID:34958801]. The authors note that their BLI affinities are weaker than earlier reported values for APP and APLP1 with CNTN3-5 (17-35 nM), attributed to oligomeric state [PMID:34958801]. No APLP1-specific Kd is in our excerpts. IntAct has a pull-down record [DB:IntAct].","key_references":[{"PMID":"34958801","why":"Systematic binding and structural study of contactin-amyloid pairs."}],"covers":["LR002129","LR005446"]},"LR005455":{"pair":"APOA1 -> TREM2","headline":"Bio-layer interferometry shows APOA1 binding TREM2-Fc in one paper; UniProt repeats the claim.","interaction_type":"direct binding","direction_and_effect":"APOA1 showed robust binding to TREM2-Fc by bio-layer interferometry, not to control Fc proteins [PMID:27477018]. UniProt states TREM2 acts as a receptor for apolipoproteins including APOA1 and enhances their uptake in microglia [DB:UniProt].","molecular_requirements":"Not reported in our evidence; TYROBP involvement is not tested here (see the TREM2:TYROBP dossier).","affinity_potency":[],"species_and_systems":"TREM2-Fc fusion protein; species of the proteins is not reported in the curated record. The same paper reports uptake of LDL, CLU and APOE, not APOA1, by TREM2-expressing cells [PMID:27477018].","localisation_and_range":"TREM2 is flagged secreted and receptor [flag].","caveats":"The evidence sentence was browser-read and its spot-check is pending. The functional uptake data in the abstract do not name APOA1 [PMID:27477018].","key_references":[{"PMID":"27477018","why":"BLI binding of apolipoproteins and LDL to TREM2-Fc"}],"covers":["LR002138","LR005455"]},"LR005464":{"pair":"APOE -> LSR","headline":"Old binding-type evidence for apoE-rich lipoproteins at LSR plus a genetic association; indirect.","interaction_type":"functional only","direction_and_effect":"LSR showed higher apparent affinity for triglyceride-rich lipoproteins and apoE-supplemented lipid emulsions than for apoB-only LDL; apoE2/2 VLDL failed to bind [PMID:7509190]. A study of LSR and APOE polymorphisms found age-specific epistasis on lipid levels [PMID:29178324].","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Human fibroblasts (FH, LDL-receptor-lacking) and rat hepatocytes [PMID:7509190]; human cohorts [PMID:29178324]. Mouse pair is ortholog-inferred.","localisation_and_range":"ApoE flagged secreted; LSR flagged receptor and not secreted [flag].","caveats":"Binding is to lipoproteins, not purified apoE; the 2018 paper is a genetic association, not binding; both abstract only. One paper pending.","key_references":[{"PMID":"7509190","why":"LSR lipoprotein binding, apoE dependence"},{"PMID":"29178324","why":"LSR-APOE epistasis, genetic only"}],"covers":["LR002149","LR005464"]},"LR003628":{"pair":"APOE -> VLDLR","headline":"No curator-verified paper; support is IntAct ELISA and UniProt text only.","interaction_type":"database-asserted only","direction_and_effect":"IntAct lists an ELISA interaction [DB:IntAct]. UniProt states apoE binds receptors including VLDLR that mediate uptake of apoE-containing lipoprotein particles [DB:UniProt].","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Species not reported in our evidence; human pair is ortholog-inferred.","localisation_and_range":"ApoE flagged secreted, VLDLR flagged transmembrane [flag].","caveats":"Three papers were abstract-insufficient and one review-only; none confirmed.","key_references":[],"covers":["LR000079","LR003628"]},"LR005473":{"pair":"APP -> CNTN5","headline":"APP binds CNTN5 in the same Fn2/copper-binding-domain mode as CNTN4, but the only paper shows weaker binding.","interaction_type":"direct binding","direction_and_effect":"APP and APLP1 interact with CNTN3-5 [PMID:34958801]. A mouse CNTN5-APP complex structure at 3.5 \u00c5 shows a binding site similar to the CNTN4-APP interface [PMID:34958801]. The paper says CNTN4 associates more strongly with amyloid proteins than CNTN3 or CNTN5 [PMID:34958801].","molecular_requirements":"Conserved interface of the CNTN second fibronectin repeat with the APP copper-binding domain [PMID:34958801]. Contactins act through co-receptor complexes because they lack an intracellular region [PMID:34958801].","affinity_potency":[{"value":"K = 26.8 \u03bcM","assay":"biolayer interferometry","system":"zebrafish APPb with CNTN5","cite":"PMID:34958801"}],"species_and_systems":"Recombinant protein work (extracellular binding, BLI, crystallography) with human, mouse, chicken and zebrafish proteins [PMID:34958801]. Human pair is ortholog-inferred.","localisation_and_range":"CNTN5 is flagged secreted and receptor, APP secreted and transmembrane [flag]; contactins are described as GPI-anchored [PMID:34958801].","caveats":"Single paper, read as abstract plus excerpts; no database record. The only affinity shown for APP-CNTN5 is the zebrafish value, and the human/mouse APP-CNTN5 value is not in our excerpts. ","key_references":[{"PMID":"34958801","why":"Binding and structure of CNTN5-APP"}],"covers":["LR002158","LR005473"]},"LR007093":{"pair":"APP -> PLXNA4","headline":"No verified paper; only one IntAct surface plasmon resonance record.","interaction_type":"database-asserted only","direction_and_effect":"Not reported in our evidence beyond a database record of an interaction.","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Not reported in our evidence; IntAct SPR record of unspecified species [DB:IntAct].","localisation_and_range":"Both flagged transmembrane [flag].","caveats":"Rests on one IntAct record; judged papers were abstract_insufficient or a different entity.","key_references":[],"covers":["LR007093"]},"LR005482":{"pair":"ARTN -> NCAM1","headline":"One 2019 paper reports direct ARTN-NCAM binding by SPR and NCAM-dependent neurite outgrowth; a single-study, alternative-receptor claim.","interaction_type":"direct binding","direction_and_effect":"ARTN binds NCAM directly and ARTN-induced neuritogenesis requires NCAM expression and NCAM-associated signalling, so NCAM is proposed as an alternative ARTN receptor (agonist-type effect) [PMID:30853893]. Effects of ARTN and the ARTN-derived peptide artefin were inhibited by abrogating either NCAM or RET [PMID:30853893].","molecular_requirements":"Recombinant NCAM Ig1-3 domains bound ARTN in SPR. The paper links the NCAM-binding site to the heel region of ARTN (via the artefin peptide) [PMID:30853893]. RET is also needed for the full effect, so NCAM and RET both appear required [PMID:30853893].","affinity_potency":[{"value":"low micromolar range (no number given in excerpts)","assay":"surface plasmon resonance, ARTN with NCAM Ig1-3","system":"recombinant rat NCAM Ig1-3 domain","cite":"PMID:30853893"}],"species_and_systems":"Ligand and receptor recorded as human; SPR used recombinant rat NCAM Ig1-3, and neurite outgrowth used cerebellar granule neurons (transfected with a rat neuron kit) [PMID:30853893]. Full text was available.","localisation_and_range":"ARTN is flagged secreted; NCAM1 is flagged both secreted and transmembrane [flag]. Range was not tested in our evidence.","caveats":"Only one paper, and both mouse and human pair records are ortholog-inferred. The affinity is far weaker than the low nanomolar ARTN-GFRalpha3 binding noted in the same paper. Whether NCAM acts alone or only with RET is not resolved.","key_references":[{"PMID":"30853893","why":"SPR binding of ARTN to NCAM and NCAM-dependent neurite outgrowth"}],"covers":["LR002168","LR005482"]},"LR003646":{"pair":"AVP -> OXTR","headline":"Vasopressin acts as a partial agonist at the oxytocin receptor, supported by human receptor assays and GtoPdb; the mouse pair is projected from human.","interaction_type":"direct binding","direction_and_effect":"AVP is a full agonist of vasopressin receptors but acts as a partial agonist on the oxytocin receptor [PMID:8955347]; GtoPdb lists Agonist, Partial agonist [DB:GtoPdb].","molecular_requirements":"Two aromatic residues of the oxytocin receptor determine the partial response: AVP becomes a full agonist when they are replaced by the residues found in vasopressin receptor subtypes [PMID:8955347]. Co-receptors or subunits: not reported in our evidence.","affinity_potency":[{"value":"Ki 48 nmol/L","assay":"radioligand competition binding (value recorded by curators; abstract truncated)","system":"human receptor-transfected cell lines","cite":"PMID:10519430"},{"value":"pKi 7.3 to 9.3","assay":"GtoPdb affinity range","system":"not stated","cite":"DB:GtoPdb"}],"species_and_systems":"Experiments used human ligand and human receptor, in transfected cells [PMID:10519430] and in a human OT receptor functional study [PMID:8955347]. The mouse pair is inferred from human evidence.","localisation_and_range":"Ligand is flagged secreted and receptor transmembrane [flag]; this implies paracrine or endocrine signalling to a cell-surface receptor.","caveats":"Only 2 of the 5 judged papers measure AVP at this receptor [PMID:10519430, PMID:8955347]; the other 3 are about synthetic V1b analogues and use OT as a selectivity comparator, with no AVP value for OT [PMID:12446593, PMID:15084136, PMID:16158071]. All papers were read as abstracts only. Cross-reactivity within the vasopressin/oxytocin family is not quantified beyond the Ki above.","key_references":[{"PMID":"8955347","why":"AVP is a partial agonist at human OT receptor; two receptor residues identified"},{"PMID":"10519430","why":"Receptor binding Ki in transfected human receptor cell lines"}],"covers":["LR000097","LR003646"]},"LR012358":{"pair":"BAMBI -> FZD1:LRP6","headline":"Database-asserted only: a single IntAct coimmunoprecipitation record; no curator-verified paper for this pair.","interaction_type":"database-asserted only","direction_and_effect":"BAMBI is annotated as stimulatory toward this receptor complex [flag]. The only support is one IntAct coimmunoprecipitation record citing PMID 18838381 [DB:IntAct]. No verified paper for this pair is in our evidence; the one judged abstract was marked insufficient.","molecular_requirements":"Complex FZD1:LRP6 is annotated; LRP6 carries a transmembrane flag [flag]. Which subunit the IntAct record covers, and whether both are needed, is not reported in our evidence.","affinity_potency":[],"species_and_systems":"Human pair [flag]. IntAct method: anti tag coimmunoprecipitation [DB:IntAct]; cell system not reported in our evidence.","localisation_and_range":"Not reported in our evidence; BAMBI has no secreted or transmembrane flag in the dossier.","caveats":"Database support only, from one co-IP record. BAMBI is called a pseudoreceptor in the related paper title [PMID:18838381], so a ligand role is unclear. The same record is attached to several Frizzled:LRP6 pairs, so it does not distinguish between Frizzled paralogs.","key_references":[],"covers":["LR012358"]},"LR012394":{"pair":"BAMBI -> FZD9:LRP6","headline":"Database-asserted only: a single IntAct coimmunoprecipitation record; no curator-verified paper for this pair.","interaction_type":"database-asserted only","direction_and_effect":"BAMBI is annotated as stimulatory toward this receptor complex [flag]. The only support is one IntAct coimmunoprecipitation record citing PMID 18838381 [DB:IntAct]. No verified paper for this pair is in our evidence; the one judged abstract was marked insufficient.","molecular_requirements":"Complex FZD9:LRP6 is annotated; LRP6 carries a transmembrane flag [flag]. Which subunit the IntAct record covers, and whether both are needed, is not reported in our evidence.","affinity_potency":[],"species_and_systems":"Human pair [flag]. IntAct method: anti tag coimmunoprecipitation [DB:IntAct]; cell system not reported in our evidence.","localisation_and_range":"Not reported in our evidence; BAMBI has no secreted or transmembrane flag in the dossier.","caveats":"Database support only, from one co-IP record. BAMBI is called a pseudoreceptor in the related paper title [PMID:18838381], so a ligand role is unclear. The same record is attached to several Frizzled:LRP6 pairs, so it does not distinguish between Frizzled paralogs.","key_references":[],"covers":["LR012394"]},"LR005491":{"pair":"BGN -> P2RX7","headline":"Biglycan activates the NLRP3 inflammasome through TLR2/4 and P2X7; evidence is functional, one abstract-only paper.","interaction_type":"functional only","direction_and_effect":"Soluble biglycan induces the NLRP3/ASC inflammasome in macrophages, activating caspase-1 and releasing mature IL-1beta; this is brought about by interaction of biglycan with TLR2/4 and purinergic P2X(4)/P2X(7) receptors, which induces receptor cooperativity [PMID:19605353]. Biglycan-deficient mice had lower active caspase-1 and mature IL-1beta in kidney and lung in obstruction and sepsis models [PMID:19605353].","molecular_requirements":"TLR2/4 are also involved, and P2X4 and P2X7 are named together; whether P2X7 alone is sufficient is not reported in our evidence [PMID:19605353].","affinity_potency":[],"species_and_systems":"Macrophages and biglycan-deficient mice (mouse); human and mouse pairs are both ortholog-inferred [PMID:19605353].","localisation_and_range":"Soluble biglycan (secreted flag) acting on macrophage surface receptors [flag][PMID:19605353].","caveats":"Abstract-only. P2X4 and P2X7 are not distinguished in the evidence sentence, and no direct binding or affinity is shown.","key_references":[{"PMID":"19605353","why":"biglycan activates NLRP3 inflammasome via TLR2/4 and P2X4/P2X7"}],"covers":["LR002177","LR005491"]},"LR003655":{"pair":"BMP10 -> ACVRL1","headline":"Well supported: BMP10 binds ALK1 (ACVRL1) in structural and binding studies and activates it in endothelial cells.","interaction_type":"direct binding","direction_and_effect":"BMP10 acts as an ALK1 agonist, activating signalling in endothelial cells [PMID:17068149; PMID:32238803]. It is called 'a potent ALK1 ligand' and, with BMP9, potently inhibits endothelial migration and growth and induces ALK1-responsive genes [PMID:17068149].","molecular_requirements":"Crystal structure of the BMP10:ALK1 extracellular domain complex at 2.3 A shows 2:2 stoichiometry with the two ALK1 monomers not in contact [PMID:32238803]. BMP10 and BMP9 bind ALK1 with similar affinity whether or not the prodomain is present [PMID:32238803]. A type II receptor is not required for this binding result; BMP10 does not discriminate among type II receptors [PMID:22718755].","affinity_potency":[],"species_and_systems":"Human recombinant proteins for binding and structure [PMID:32238803; PMID:22718755]; microvascular endothelial cells for function [PMID:17068149]. Mouse pair is ortholog-inferred.","localisation_and_range":"BMP10 is annotated as secreted and the receptor as transmembrane [flag], so signalling would be paracrine or autocrine; no paper in our evidence tests range.","caveats":"All three papers were read as abstracts (excerpts for one). No numeric affinity is given in our evidence, only 'similar affinities' or 'comparable affinity'. The ALK1 ternary structure in the 2012 paper is of BMP9, not BMP10.","key_references":[{"PMID":"32238803","why":"Crystal structure of BMP10:ALK1; prodomain does not interfere"},{"PMID":"22718755","why":"Kinetic/thermodynamic binding of BMP9/BMP10 to ALK1 and type II receptors"},{"PMID":"17068149","why":"BMP10 as an ALK1 ligand in endothelial cells"}],"covers":["LR000106","LR003655"]},"LR003664":{"pair":"BMP15 -> BMPR2","headline":"Well supported: BMP15 binds BMPR2 in radioligand and SPR assays, with a functional neutralisation result as well.","interaction_type":"direct binding","direction_and_effect":"A radiolabelled BMP15 covalent-dimer variant bound endogenous BMPR2 (with BMPR1B) on COV434 cells and in COS cells overexpressing them [PMID:22294741]. BMPR2 high-affinity growth factors include BMP15, BMP10 and Nodal [PMID:35643319]. The BMPRII ectodomain most effectively blocked BMP15 activity in granulosa cells [PMID:12419820].","molecular_requirements":"BMPR2 acted with BMPR1B in the signalling complex [PMID:22294741].","affinity_potency":[{"value":"KD 6.3E-09 M (SD 1.0E-09)","assay":"SPR, BMP15 over captured BMPRII-Fc","system":"recombinant proteins","cite":"PMID:35643319"}],"species_and_systems":"Human recombinant BMP15, COV434 and COS cells [PMID:22294741]; rat primary granulosa cells [PMID:12419820]. Mouse pair is ortholog-inferred.","localisation_and_range":"BMP15 is annotated as secreted [flag]; paracrine from oocyte per the 2012 abstract [PMID:22294741].","caveats":"All abstracts; the KD comes from a table in full-text excerpts, which also says BMP15 had fast association and dissociation [PMID:35643319]. Only the engineered covalent dimer kept binding after iodination [PMID:22294741].","key_references":[{"PMID":"22294741","why":"Radioligand binding of BMP15 to BMPR1B/BMPR2"},{"PMID":"35643319","why":"SPR affinity of BMP15 for BMPR2"},{"PMID":"12419820","why":"BMPRII ectodomain neutralises BMP15"}],"covers":["LR000115","LR003664"]},"LR003673":{"pair":"BMP3 -> ACVR2A","headline":"BMP3 binds ACVR2A (ActRII) by SPR, but with low affinity; one paper, ortholog-projected.","interaction_type":"direct binding","direction_and_effect":"BMP-3 binds ActRII with Kd approximately 1.8 microM but ActRIIb with 30-fold higher affinity [PMID:17924656]. Mutating Ser-28 or Asp-33 of BMP-3 to alanine raised affinity up to 20-fold [PMID:17924656].","molecular_requirements":"The low affinity was attributed to Ser-28 and Asp-33 of BMP-3; the BMP-3-S28A mutant gave signalling comparable to BMP-6 in a Smad-luciferase assay [PMID:17924656].","affinity_potency":[{"value":"Kd approximately 1.8 microM","assay":"SPR (BIAcore)","system":"purified proteins; species not reported","cite":"PMID:17924656"},{"value":"Kd approximately 53 nM","assay":"SPR (BIAcore), ActRIIb comparator","system":"purified proteins; species not reported","cite":"PMID:17924656"}],"species_and_systems":"SPR with recombinant proteins; species not reported. Both human and mouse pairs are projected from other evidence (ortholog_inferred).","localisation_and_range":"BMP3 flagged secreted and ACVR2A transmembrane [flag].","caveats":"Single paper read as abstract; the micromolar affinity suggests a weak interaction relative to ActRIIb. No database records.","key_references":[{"PMID":"17924656","why":"SPR shows BMP-3 binds ActRII weakly (microM) and ActRIIb tighter"}],"covers":["LR000124","LR003673"]},"LR002179":{"pair":"BMP4 -> CDCP1","headline":"CDCP1 CUB domains bind BMP4 directly (BIAcore) but CDCP1 did not modulate BMP signalling; single abstract-only paper.","interaction_type":"direct binding","direction_and_effect":"BIAcore showed CDCP1 CUB domains bind directly to TGF-beta1 and BMP4 [PMID:31302030]. CDCP1 enhanced TGF-beta1 reporter activity and phospho-Smad2 but did not modulate the BMP signalling pathway [PMID:31302030].","molecular_requirements":"CUB domains of CDCP1 mediate binding [PMID:31302030]. A signalling partner for BMP4 is not reported.","affinity_potency":[],"species_and_systems":"BIAcore recombinant proteins and cell reporter assays; curators record human [PMID:31302030].","localisation_and_range":"BMP4 is flagged secreted; CDCP1 is flagged secreted and receptor [flag], so the receptor may be soluble or shed.","caveats":"Binding does not translate to a BMP signalling effect, so the interaction may be non-functional or regulatory. Abstract only; no affinity value in our evidence. The curator's agonist label is not supported by the paper's abstract for BMP4.","key_references":[{"PMID":"31302030","why":"BIAcore binding of CDCP1 CUB domains to BMP4"}],"covers":["LR002179","LR005493"]},"LR011197":{"pair":"BMP5 -> ACVR2A","headline":"BMP5 to ACVR2A rests on a GtoPdb agonist assertion only; no verified paper in our evidence.","interaction_type":"database-asserted only","direction_and_effect":"GtoPdb lists BMP5 as agonist (Stimulatory) on the receptor chain(s) [DB:GtoPdb].","molecular_requirements":"Single receptor chain; coreceptor requirements are not reported in our evidence.","affinity_potency":[],"species_and_systems":"Experimental species and system not reported in our evidence; the pair is annotated human.","localisation_and_range":"BMP5 is flagged secreted and not transmembrane [flag], so signalling would be paracrine or endocrine; the receptor's localisation is not reported in our evidence.","caveats":"No curator-confirmed paper. Screened papers: 1 different_entity, 3 abstract_insufficient. GtoPdb entries show no affinity ('Affinity Units=-') [DB:GtoPdb].","key_references":[],"covers":["LR011197"]},"LR007129":{"pair":"BMP5 -> BMPR1A:BMPR2","headline":"BMP5 to BMPR1A:BMPR2 rests on GtoPdb and UniProt statements only; no verified paper in our evidence.","interaction_type":"database-asserted only","direction_and_effect":"GtoPdb lists BMP5 as agonist (Stimulatory) on the receptor chain(s) [DB:GtoPdb]. UniProt (BMP5, P22003) states BMP5 associates with type I receptor BMPR1A and type II receptor BMPR2 [DB:UniProt][PMID:11580864].","molecular_requirements":"Chains in the complex: BMPR1A and BMPR2; whether both are required or either alone suffices is not reported in our evidence. The pair is a complex; the database rows are per chain, not for the assembled complex, and not every chain has UniProt support.","affinity_potency":[],"species_and_systems":"Experimental species and system not reported in our evidence; the pair is annotated human.","localisation_and_range":"BMP5 is flagged secreted and not transmembrane [flag], so signalling would be paracrine or endocrine; the receptor's localisation is not reported in our evidence.","caveats":"No curator-confirmed paper. Screened papers: 4 review_only, 1 abstract_insufficient. GtoPdb entries show no affinity ('Affinity Units=-') [DB:GtoPdb].","key_references":[],"covers":["LR007129"]},"LR003682":{"pair":"BMP6 -> ACVR1","headline":"BMP6 binds ALK-2 (ACVR1) in cross-linking assays, but only together with type II receptors; one 1999 paper plus database records.","interaction_type":"direct binding","direction_and_effect":"Curators label the effect agonist. In COS-7 cells, 125I-BMP-6 strongly bound ALK-2 together with the type II receptors BMPR-II and ActR-II [PMID:10504300]. UniProt (BMP6) says BMP6 initiates BMP signalling by associating with type I receptor ACVR1 and type II receptor ACVR2B [DB:UniProt][PMID:18070108]; GtoPdb lists BMP6 as agonist at ACVR1 [DB:GtoPdb].","molecular_requirements":"A type II receptor (BMPR-II or ActR-II) was needed for BMP-6 binding to ALK-2 in the paper's co-transfection experiments [PMID:10504300]. ACVR1 alone is not shown to bind BMP6 in our evidence.","affinity_potency":[],"species_and_systems":"Recombinant human BMP-6; receptor constructs in COS-7 cells (receptor species not explicitly stated); endogenous binding in mouse MC3T3-E1 and C2C12 cell lines [PMID:10504300]. The human and mouse pairs are both projected from this evidence.","localisation_and_range":"BMP6 is flagged secreted [flag]; receptor localisation not reported in our evidence.","caveats":"Affinity not reported. A third judged row was review_only. Binding in ROB-C26 cells to ALK-2 was described as less efficient than to BMPR-IB.","key_references":[{"PMID":"10504300","why":"cross-linking of 125I-BMP-6 to ALK-2 with type II receptors"}],"covers":["LR000133","LR003682"]},"LR007138":{"pair":"BMP6 -> BMPR1A:BMPR2","headline":"Complex row resting on one weak-binding paper that does not show BMPR2 binding; plus database agonist records.","interaction_type":"direct binding","direction_and_effect":"BMP-6 weakly bound BMPR-IA (ALK-3) [PMID:10504300]. GtoPdb lists BMP6 as agonist at BMPR1A and BMPR2 [DB:GtoPdb].","molecular_requirements":"The paper's evidence sentence names only BMPR-IA; the BMPR2 chain rests on database records, including BioGRID BMPR2-BMP6 affinity capture-western [DB:BioGRID].","affinity_potency":[],"species_and_systems":"Cell systems C2C12 and MC3T3-E1 [PMID:10504300]; the curator recorded human ligand and receptor species. Abstract-level read for this row; full-text excerpts repeat the BMPR-IA sentence.","localisation_and_range":"BMP6 is flagged as secreted [flag], so action would be paracrine or endocrine; the receptor is flagged as a transmembrane receptor [flag].","caveats":"Binding was explicitly weak, unlike the strong ALK-2 binding. BMPR2 is not shown by this paper's cited sentence in this row. Five review-only and one abstract-insufficient paper.","key_references":[{"PMID":"10504300","why":"Weak BMP-6 binding to BMPR-IA in C2C12 and MC3T3-E1 cells"}],"covers":["LR007138"]},"LR003691":{"pair":"BMP7 -> BMPR1A","headline":"BMP7 binds BMPR1A (ALK-3) less efficiently than other type I receptors; support is from abstracts of 1990s binding papers.","interaction_type":"direct binding","direction_and_effect":"In transfected COS cells OP-1 bound ALK-3 less efficiently than ALK-2 and ALK-6, and also bound ALK-3 in some nontransfected cell lines with cell-type-dependent profiles [PMID:8006002]. BMPR-II binds BMP-7 in association with type I receptors including BMPR-IA [PMID:7791754]. GtoPdb lists an agonist action [DB:GtoPdb].","molecular_requirements":"BMPR1A is a type I chain; binding in COS cells was seen without type II receptors and increased with co-transfected DAF-4 [PMID:8006002]. BMPR-II association is ligand dependent [PMID:7791754].","affinity_potency":[],"species_and_systems":"Human proteins in COS cells and various nontransfected cell lines [PMID:8006002]; cloned human BMPR-II in mammalian cells [PMID:7791754]. Mouse pair is ortholog-inferred.","localisation_and_range":"BMP7 is flagged secreted and the receptor transmembrane [flag], suggesting paracrine signalling to a cell-surface receptor; the papers do not address range.","caveats":"Both papers were read as abstracts only. BMPR1A is a secondary BMP7 receptor relative to ALK-2/ALK-6 in the 1994 study [PMID:8006002]. PMID 7791754 is a BMPR-II study and shows BMP7 with BMPR-IA only in a type II context. Two papers were abstract_insufficient and one review_only.","key_references":[{"PMID":"8006002","why":"OP-1 binds ALK-3 less efficiently than ALK-2/ALK-6"},{"PMID":"7791754","why":"BMPR-II binds BMP-7 in association with BMPR-IA"}],"covers":["LR000142","LR003691"]},"LR007147":{"pair":"BMP7 -> BMPR1A:BMPR2","headline":"One abstract-level paper supports BMP7 binding BMPR-II in association with BMPR-IA; ligand-dependent complex.","interaction_type":"direct binding","direction_and_effect":"BMPR-II binds BMP-2 and BMP-7 in association with type I receptors including BMPR-IA/Brk1, BMPR-IB and ActR-I [PMID:7791754]. GtoPdb lists agonist action for each chain [DB:GtoPdb].","molecular_requirements":"In mammalian cells BMPR-II interaction is restricted to BMP type I receptors and is ligand dependent; BMPR-II binds BMP-2 and -7 on its own, but binding is enhanced by type I coexpression [PMID:7791754]. BMP signalling needed the kinase activity of both receptors [PMID:7791754].","affinity_potency":[],"species_and_systems":"Cloned human BMPR-II in mammalian cells and yeast two-hybrid [PMID:7791754].","localisation_and_range":"BMP7 is flagged secreted and the receptor transmembrane [flag], suggesting paracrine signalling to a cell-surface receptor; the papers do not address range.","caveats":"Single paper read as abstract only; the abstract lists BMPR-IA among several type I partners without a BMPR-IA-specific experiment. Five papers were review_only, one abstract_insufficient.","key_references":[{"PMID":"7791754","why":"Cloning of BMPR-II; BMP-7 binding with type I receptors"}],"covers":["LR007147"]},"LR002188":{"pair":"BMP7 -> RGMB","headline":"BMP7 binds RGMB directly by SPR (Kd 166 nM); single abstract-level paper with full-text support, human proteins.","interaction_type":"direct binding","direction_and_effect":"Curators record the effect as agonist; the paper's abstract describes RGM proteins as co-receptors that enhance cellular responses to BMP ligands, but this paper measured binding only [PMID:23029472].","molecular_requirements":"Binding was measured for the RGM protein alone; type I/II BMP receptor requirements are not reported in our evidence.","affinity_potency":[{"value":"Kd 166 nM","assay":"surface plasmon resonance","system":"recombinant human proteins (curator-annotated species)","cite":"PMID:23029472"}],"species_and_systems":"SPR with recombinant proteins; curators annotate both partners as human, mouse pair is ortholog-inferred [PMID:23029472].","localisation_and_range":"BMP7 is flagged secreted; RGMB is flagged not secreted [flag], and its membrane or soluble form is not stated in our evidence.","caveats":"RGMB bound BMP7 with the lowest affinity among the three RGMs [PMID:23029472]. BMP7 had the lowest relative affinity of the BMPs tested for the RGMs, and BMP7-RGM data needed CM4 sensor chips because fitting on CM5 chips was poor [PMID:23029472]. Curator read depth is abstract-only. Only one paper.","key_references":[{"PMID":"23029472","why":"SPR kinetics of all RGM-BMP pairs including BMP7"}],"covers":["LR002188","LR005502"]},"LR001666":{"pair":"BMP8A -> ACVR2B","headline":"BMP8A acts through ACVR2B in mouse spermatogonia (functional, abstract-level); GtoPdb also lists agonism.","interaction_type":"functional only","direction_and_effect":"Agonist (curator annotation). ACVR2B is named only as a type II partner of ALK5 for SMAD2/3 activation, not for SMAD1/5/8 [PMID:28465413]. GtoPdb lists an agonist record [DB:GtoPdb].","molecular_requirements":"ACVR2B works with ALK5, alongside ACVR2A or TGFBR2 [PMID:28465413].","affinity_potency":[],"species_and_systems":"Undifferentiated mouse spermatogonia and cultured mouse testis explants; abstract-only read; the human pair is listed without ortholog inference but the experiments were mouse [PMID:28465413].","localisation_and_range":"BMP8A is flagged secreted [flag]; the abstract does not state range of action.","caveats":"Evidence is signalling through receptor complexes, not binding; no affinity reported. Abstract only.","key_references":[{"PMID":"28465413","why":"BMP8A signals through SMAD1/5/8 and SMAD2/3 receptor complexes in mouse spermatogonia"}],"covers":["LR001666"]},"LR007156":{"pair":"BMP8A -> BMPR1A:BMPR2","headline":"BMP8A -> BMPR1A:BMPR2 is supported functionally in mouse spermatogonia (ALK3 with BMPR2); databases agree.","interaction_type":"functional only","direction_and_effect":"Agonist signalling: ALK3 (BMPR1A per curator note) with BMPR2 drove SMAD1/5/8 activation, promoting spermatogonial differentiation [PMID:28465413]. GtoPdb lists agonist records for both chains [DB:GtoPdb]; UniProt says BMP8A associates with BMPR1A and BMPR2 [DB:UniProt].","molecular_requirements":"The type I (BMPR1A) and type II (BMPR2) chains are both named; ACVR2A can replace BMPR2 [PMID:28465413].","affinity_potency":[],"species_and_systems":"Undifferentiated mouse spermatogonia and cultured mouse testis explants; abstract-only read; the human pair is listed without ortholog inference but the experiments were mouse [PMID:28465413].","localisation_and_range":"BMP8A is flagged secreted [flag]; the abstract does not state range of action.","caveats":"Evidence is functional only, abstract-level; no binding or affinity data. Three papers were review-only.","key_references":[{"PMID":"28465413","why":"BMP8A signals through SMAD1/5/8 and SMAD2/3 receptor complexes in mouse spermatogonia"}],"covers":["LR007156"]},"LR008452":{"pair":"BMP8B -> ACVR1","headline":"BMP8B -> ACVR1 rests on GtoPdb agonist records only; no paper confirmed it.","interaction_type":"database-asserted only","direction_and_effect":"GtoPdb lists BMP8B as an agonist at ACVR1 [DB:GtoPdb]; no verified paper supports the effect.","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"No experimental system reported in our evidence.","localisation_and_range":"Not reported in our evidence; the ligand has no secretion flag in the dossier.","caveats":"Judged papers were abstract-insufficient, review-only or about a different entity; none confirmed this pair. No affinity.","key_references":[],"covers":["LR008452"]},"LR008263":{"pair":"BMP8B -> ACVR2B:BMPR1A","headline":"BMP8B -> ACVR2B:BMPR1A rests on GtoPdb agonist records only; no paper confirmed it.","interaction_type":"database-asserted only","direction_and_effect":"GtoPdb lists BMP8B as an agonist at ACVR2B and BMPR1A [DB:GtoPdb]; no verified paper supports the effect.","molecular_requirements":"Complex is assembled from separate chain records; subunit requirements are not reported in our evidence.","affinity_potency":[],"species_and_systems":"No experimental system reported in our evidence.","localisation_and_range":"Not reported in our evidence; the ligand has no secretion flag in the dossier.","caveats":"Judged papers were abstract-insufficient, review-only or about a different entity; none confirmed this pair. No affinity.","key_references":[],"covers":["LR008263"]},"LR010828":{"pair":"BTC -> ERBB2:ERBB4","headline":"BTC binds the ERBB2/ERBB4 heterodimer with moderate to very high affinity in one soluble-receptor study.","interaction_type":"direct binding","direction_and_effect":"The ErbB2/4 heterodimer bound all eleven ErbB ligands tested, BTC among them [PMID:10214951]. Reactome lists ERBB4 binding NRGs or EGF-like ligands [DB:Reactome]. A GtoPdb record with pIC50 exists [DB:GtoPdb] but the value is not given.","molecular_requirements":"Requires an ErbB2/ErbB4 heterodimer in the assay; whether a single chain suffices is not reported in our evidence. PDB 8U4J and 8U4K contain BTC with ERBB4 and ERBB2 chains separately [DB:PDB 8U4J].","affinity_potency":[],"species_and_systems":"Soluble receptor-ligand binding across six ErbB combinations [PMID:10214951]; species wording as human.","localisation_and_range":"BTC is flagged secreted and transmembrane [flag].","caveats":"Abstract only; two other papers were abstract-insufficient; the quantitative affinity for BTC specifically is not in our evidence.","key_references":[{"PMID":"10214951","why":"Soluble ErbB combinations; ErbB2/4 binds all ligands including BTC."}],"covers":["LR010828"]},"LR005509":{"pair":"C1QA -> CD44","headline":"C1q signalling through CD44 in human neural stem cells, supported by functional knockdown or blockade; direct binding is not shown in our excerpts.","interaction_type":"functional only","direction_and_effect":"CD44 mediates C1q-induced hNSC signalling and chemotaxis in vitro; receptor knockdown or blockade abolished the response [PMID:32894219]. Curator label: stimulatory.","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Human neural stem cells; the mouse pair is ortholog-inferred [PMID:32894219]. C1q concentrations tested included 28 ng/mL, 400 ng/mL [PMID:32894219].","localisation_and_range":"C1q annotated secreted; CD44 annotated secreted and transmembrane, so soluble and membrane forms are both flagged [flag].","caveats":"Only one paper is shown (two confirmed rows counted). CD44 was one of five screen candidates; no affinity reported.","key_references":[{"PMID":"32894219","why":"CD44 identified and functionally validated for C1q signalling and chemotaxis"}],"covers":["LR002195","LR005509"]},"LR005527":{"pair":"C1QL1 -> ADGRB3","headline":"C1QL1 binds the thrombospondin-repeat domain of ADGRB3 (BAI3) with high affinity; one abstract-level paper plus UniProt.","interaction_type":"direct binding","direction_and_effect":"Biochemical binding of C1ql proteins to BAI3; submicromolar C1ql proteins decrease synapse density in cultured neurons, prevented by the BAI3 thrombospondin-repeat fragment, which binds C1ql proteins and acts as a decoy [PMID:21262840].","molecular_requirements":"Binding is to the extracellular thrombospondin-repeat domain of BAI3 and is mediated by the globular C1q domain of the ligand [PMID:21262840]. Further subunits are not reported in our evidence.","affinity_potency":[],"species_and_systems":"Paper tested all four C1ql proteins together; the abstract does not name the species or cell type (curator labels human/human; both listed interactions are ortholog-inferred, none experiment-derived here). UniProt records the interaction [DB:UniProt].","localisation_and_range":"C1QL1 is flagged secreted, ADGRB3 transmembrane [flag]; paracrine or trans-synaptic action is suggested by the paper [PMID:21262840].","caveats":"Abstract only; affinity described as 'high' without a number. Effect shown only for the C1ql protein set in cultured neurons, not C1QL1 alone. Curator label 'antagonist' is unclear.","key_references":[{"PMID":"21262840","why":"All four C1ql proteins bind the BAI3 thrombospondin-repeat domain with high affinity via the gC1q domain"}],"covers":["LR002214","LR005527"]},"LR001675":{"pair":"C3 -> CR2","headline":"C3d fragment binds CR2 SCR1-2; strong structural, binding and database support.","interaction_type":"direct binding","direction_and_effect":"CR2 (CD21) SCR1-2 mediate C3d binding [PMID:19164292]. CR2 isolated from B cells adhered to C3d-coated particles [PMID:6230668]. Reactome records CR2 binding C3d, C3dg, iC3b [DB:Reactome].","molecular_requirements":"SCR1 and SCR2 and the linker form the C3d surface, with distinct binding modes [PMID:19164292]. UniProt: via N-terminal Sushi 1 and 2 [DB:UniProt]. Structures exist [DB:PDB 1GHQ].","affinity_potency":[],"species_and_systems":"Human proteins: NMR with SCR1-2 [PMID:19164292], B lymphocytes and Raji cells [PMID:6230668], molecular dynamics at pH 7.4, 6.0 and 5.0 [PMID:30566277]. Mouse pair is ortholog-inferred.","localisation_and_range":"CR2 is flagged transmembrane [flag]: contact-dependent on B cells.","caveats":"All papers abstract only. Ligand is the C3d fragment, not intact C3. The NMR surface disagrees with a prior crystal structure [PMID:19164292]. Binding is pH dependent in simulation [PMID:30566277].","key_references":[{"PMID":"19164292","why":"NMR mapping of C3d site on CR2"},{"PMID":"6230668","why":"Identification of CR2 as C3d receptor on B cells"},{"PMID":"30566277","why":"pH effects on C3d-CR2, simulation"}],"covers":["LR001675","LR005052"]},"LR008740":{"pair":"C3 -> IFITM1","headline":"No curated paper supports it; only Reactome complement-receptor records.","interaction_type":"database-asserted only","direction_and_effect":"No direction or effect reported in our evidence.","molecular_requirements":"Not reported; Reactome records C3d-complexed antigen binding to a complement receptor generically [DB:Reactome].","affinity_potency":[],"species_and_systems":"not reported in our evidence","localisation_and_range":"Not assessed.","caveats":"No papers were confirmed (one review only). Reactome entries do not name IFITM1 directly in the shown text.","key_references":[],"covers":["LR008740"]},"LR007183":{"pair":"C3 -> ITGAM:ITGB2","headline":"iC3b fragment of C3 binds the CR3 complex (ITGAM:ITGB2); one abstract-only paper plus database records.","interaction_type":"direct binding","direction_and_effect":"CR3 was isolated by iC3b-Sepharose affinity chromatography from human spleen membranes and leukocytes [PMID:4062888]. BioGRID and IntAct list reconstituted-complex, pull-down and sieving records [DB:BioGRID][DB:IntAct].","molecular_requirements":"Complex of ITGAM (alphaM) and ITGB2 (beta2); both members are required for a complex-level score [PMID:4062888]. Structures contain C3 with ITGAM [DB:PDB 4M76].","affinity_potency":[],"species_and_systems":"Human spleen membranes and polymorphonuclear leucocytes [PMID:4062888].","localisation_and_range":"Membrane integrin complex; contact-dependent by annotation [flag].","caveats":"Single abstract-only paper from 1985. Ligand is iC3b, not intact C3.","key_references":[{"PMID":"4062888","why":"iC3b affinity chromatography isolating CR3"}],"covers":["LR007183"]},"LR003709":{"pair":"C3 -> ITGB2","headline":"C3 fragments bind the CD18 (ITGB2)-containing integrins; supported by binding papers, but the beta chain alone is not shown sufficient.","interaction_type":"direct binding","direction_and_effect":"iC3b-Sepharose isolated CR3 and p150,95, which share a beta2 subunit [PMID:4062888]. C3(H2O) bound recombinant CD11b/CD18 directly by quartz crystal microbalance and flow cytometry [PMID:26293614]. iC3b-erythrocytes bound Mac-1 transfectants [PMID:7679388].","molecular_requirements":"Binding is by alpha:beta2 heterodimers; the I domain of the alpha chain is the recognition site [PMID:7679388]. Whether ITGB2 alone is sufficient is not reported in our evidence.","affinity_potency":[],"species_and_systems":"Human proteins: membranes, recombinant CD11b/CD18, COS transfectants [PMID:4062888][PMID:26293614][PMID:7679388]. Mouse pair is ortholog-inferred.","localisation_and_range":"Membrane integrin; contact-dependent (annotation [flag]).","caveats":"Two papers abstract only; PMID 7679388 full-text excerpt only mentions iC3b-E binding as a control (data not shown). Evidence is for the alpha:beta2 complexes, so the ITGB2 chain row is chain-level. Ligand forms are iC3b or C3(H2O).","key_references":[{"PMID":"26293614","why":"Direct C3(H2O)-CD11b/CD18 binding"},{"PMID":"4062888","why":"iC3b affinity isolation of beta2 integrins"}],"covers":["LR000160","LR003709"]},"LR005536":{"pair":"CADM1 -> CADM2","headline":"CADM1 interacts with CADM2 by SPR imaging in one full-text paper; no other direct evidence.","interaction_type":"direct binding","direction_and_effect":"CADM1-Fc injected on a chip with immobilized IgSF-Fc proteins showed interaction with CADM2 [PMID:30131958]. Effect direction is not reported in our evidence.","molecular_requirements":"CADM1 and CADM2 extracellular Fc fusion proteins [PMID:30131958].","affinity_potency":[],"species_and_systems":"Human recombinant extracellular proteins in a cell-free SPRi platform [PMID:30131958]. The mouse pair is ortholog-inferred.","localisation_and_range":"Both flagged non-secreted; CADM1 transmembrane [flag]; suggests contact-dependent adhesion.","caveats":"Single paper; the specific kinetics for CADM2 are not reported in our excerpts. Reactome records cover Necl transhomodimerization, not this heterophilic pair [DB:Reactome].","key_references":[{"PMID":"30131958","why":"SPRi shows CADM1-CADM2 interaction"}],"covers":["LR002226","LR005536"]},"LR005059":{"pair":"CADM3 -> CADM3","headline":"Homophilic CADM3 adhesion shown in cell-aggregation assays and SPRi; two papers.","interaction_type":"direct binding","direction_and_effect":"Necl-1 (CADM3) showed Ca2+-independent homophilic cell-cell adhesion [PMID:15741237]. SPRi detected homophilic interactions of CADM3 [PMID:30131958]. Self-binding, so no direction.","molecular_requirements":"Homodimer of the ectodomain; no extra subunit reported.","affinity_potency":[],"species_and_systems":"Cell aggregation assays, abstract only [PMID:15741237]; recombinant SPRi [PMID:30131958]. Human and mouse pairs both listed, not inferred.","localisation_and_range":"Membrane-bound [flag]; Necl-1 sits at non-junctional contact sites of axons, terminals and glial processes, in neural tissue [PMID:15741237]. Reactome lists Necl transhomodimerisation [DB:Reactome].","caveats":"Abstract-level for the aggregation study. No Kd for CADM3-CADM3 in our evidence; the SPRi curated sentence is about CADM1-Fc.","key_references":[{"PMID":"15741237","why":"Homophilic Necl-1 adhesion"},{"PMID":"30131958","why":"SPRi CADM-family interactions"}],"covers":["LR001683","LR005059"]},"LR001684":{"pair":"CADM3 -> NECTIN1","headline":"Heterophilic CADM3-nectin-1 adhesion shown in cell-aggregation assay; one abstract-level paper plus Reactome.","interaction_type":"functional only","direction_and_effect":"Necl-1 (CADM3) showed Ca2+-independent heterophilic cell-cell adhesion with nectin-1, but not nectin-2 or Necl-5 [PMID:15741237]. Reactome lists a Necl-1:Nectin-1 trans heterodimer [DB:Reactome].","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Cell-aggregation assays; abstract only, human-labelled [PMID:15741237]. Both species pairs are ortholog-inferred.","localisation_and_range":"Membrane-bound [flag]; Necl-1 is neural-specific at axon-glia contact sites [PMID:15741237]. Trans, contact-dependent.","caveats":"Abstract only. Adhesion assays do not exclude other cell-surface mediators; curators labelled it direct binding. No affinity reported.","key_references":[{"PMID":"15741237","why":"Necl-1 heterophilic adhesion with nectin-1"}],"covers":["LR001684","LR005060"]},"LR005545":{"pair":"CADM4 -> CADM2","headline":"CADM4 and CADM2 interact by SPRi (family-wide screen); direct binding, one paper, no pair-specific affinity.","interaction_type":"direct binding","direction_and_effect":"SPRi of CADM2-Fc, CADM3-Fc and CADM4-Fc detected homophilic and heterophilic interactions with all CADM family proteins [PMID:30131958]. No functional effect or direction is reported for this pair.","molecular_requirements":"SPRi only detects direct interactions between two molecules; no accessory protein needed in this assay [PMID:30131958].","affinity_potency":[],"species_and_systems":"Recombinant Fc-fusion ectodomains in SPRi (human proteins) [PMID:30131958]. Mouse pair is projected from human evidence (ortholog_inferred), not tested.","localisation_and_range":"CADM2 transmembrane status is not flagged; CADM4 is flagged transmembrane [flag]. The paper describes CADM family adhesion between cells [PMID:30131958].","caveats":"Support is a family-level statement from one paper; the tabulated Kd values are for CADM1 and are not for this pair [PMID:30131958]. Affinity for CADM4-CADM2 not reported in our evidence.","key_references":[{"PMID":"30131958","why":"SPRi screen of CADM-family pairwise interactions, with Kd table and cell assays"}],"covers":["LR002235","LR005545"]},"LR003718":{"pair":"CALCA -> RAMP2","headline":"alpha-CGRP shows weaker cAMP signalling at RAMP2-containing receptors than at RAMP1; evidence is two abstract-level functional papers.","interaction_type":"functional only","direction_and_effect":"alpha-CGRP binding and signalling were markedly weaker with CTR2/RAMP2 than with CTR2/RAMP1 or CRLR/RAMP1 in HEK-293 cells [PMID:14722252]. With CTRa, chimeras carrying the RAMP2 C-terminal domain did not increase CGRP potency [PMID:16531504]. GtoPdb lists agonist records [DB:GtoPdb].","molecular_requirements":"Activity is seen only as RAMP/receptor heterodimers (CTR2/RAMP2 [PMID:14722252], CTRa chimeras [PMID:16531504]); RAMP2 alone is not shown to bind CGRP. Structure 7TYH exists with chains P01258 and O60895 [DB:PDB 7TYH].","affinity_potency":[{"value":"pEC50 6.2 to 9.7","assay":"GtoPdb agonist record","system":"database record","cite":"DB:GtoPdb"}],"species_and_systems":"Human CTR2/CTRa with RAMP2 expressed in HEK-293 [PMID:14722252] or COS-7 cells [PMID:16531504]. Mouse pair is projected from human evidence.","localisation_and_range":"Ligand flagged secreted [flag].","caveats":"Both papers were read as abstracts only. The signal is weak relative to RAMP1, and the RAMP2 result in [PMID:16531504] is a lack of potentiation. No binding to RAMP2 by CGRP itself is reported in our evidence.","key_references":[{"PMID":"14722252","why":"CGRP signalling weaker at CTR2/RAMP2 than RAMP1"},{"PMID":"16531504","why":"RAMP2 C-terminus does not raise CGRP potency"}],"covers":["LR000173","LR003718"]},"LR006823":{"pair":"CALM1 -> PDE1B","headline":"Calmodulin activates PDE1B per GtoPdb and UniProt.","interaction_type":"database-asserted only","direction_and_effect":"GtoPdb lists calmodulin as activator [DB:GtoPdb]. UniProt says type I PDEs are activated by calmodulin binding in the presence of Ca2+ [DB:UniProt].","molecular_requirements":"Requires Ca2+ [DB:UniProt].","affinity_potency":[],"species_and_systems":"Species not stated.","localisation_and_range":"Intracellular calmodulin; no secreted flag in our evidence. Not reported in our evidence beyond the entity annotation flags.","caveats":"No papers were confirmed; support is from curated database records only. The one judged row was review_only.","key_references":[],"covers":["LR006823"]},"LR008461":{"pair":"CALM3 -> MYLK2","headline":"CALM3 activates MYLK2 according to GtoPdb only; no curated paper supports the pair.","interaction_type":"database-asserted only","direction_and_effect":"GtoPdb lists CALM3 as an activator of MYLK2 (Type=Activator; Action=Activation), and the interaction is annotated Stimulatory [DB:GtoPdb].","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Human entities; no experimental system or species of assay is reported in our evidence.","localisation_and_range":"Not reported in our evidence; no localisation flag is given for the ligand.","caveats":"Support rests on a database record alone, with no affinity (Affinity Units=-) and no verified primary paper. One judged paper was review-only and one concerned a different entity. Calmodulin acts here as a Ca2+-sensor regulator of an enzyme rather than a classical secreted ligand; the receptor label comes from an annotation flag [flag].","key_references":[],"covers":["LR008461"]},"LR008470":{"pair":"CALM3 -> PDE1B","headline":"CALM3 activates PDE1B according to GtoPdb only; no curated paper supports the pair.","interaction_type":"database-asserted only","direction_and_effect":"GtoPdb lists CALM3 as an activator of PDE1B (Type=Activator; Action=Activation), and the interaction is annotated Stimulatory [DB:GtoPdb].","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Human entities; no experimental system or species of assay is reported in our evidence.","localisation_and_range":"Not reported in our evidence; no localisation flag is given for the ligand.","caveats":"Support rests on a database record alone, with no affinity (Affinity Units=-) and no verified primary paper. One judged paper was review-only. Calmodulin acts here as a Ca2+-sensor regulator of an enzyme rather than a classical secreted ligand; the receptor label comes from an annotation flag [flag].","key_references":[],"covers":["LR008470"]},"LR009028":{"pair":"CALR -> TSHR","headline":"Only a BioGRID Western capture record links calreticulin and TSHR; no verified paper.","interaction_type":"database-asserted only","direction_and_effect":"Direction and effect are not reported in our evidence. BioGRID lists CALR - TSHR as Affinity Capture-Western [DB:BioGRID].","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Species and system are not reported in our evidence.","localisation_and_range":"CALR is flagged secreted and TSHR transmembrane [flag].","caveats":"A single BioGRID record (PMID 12383251) is the sole support; both judged papers concerned a different entity. The interaction may reflect calreticulin as an ER chaperone for TSHR.","key_references":[],"covers":["LR009028"]},"LR005554":{"pair":"CBLN1 -> NRXN2","headline":"One paper identifies NRXN2 as the receptor mediating CBLN1 axon growth and guidance in embryos.","interaction_type":"functional only","direction_and_effect":"Cbln1 functions as a growth and guidance cue; these functions are mediated by neurexin-2, described as the Cbln1 receptor for axon growth and guidance [PMID:36395107]. Cbln1 acts in an autocrine manner and as an attractive cue.","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Mouse and chick embryos, including commissural neurons [PMID:36395107]. The pair is ortholog-inferred in both human and mouse.","localisation_and_range":"CBLN1 is flagged secreted and NRXN2 transmembrane [flag]; the paper says Cbln1 is expressed on axons and growth cones and in intermediate targets [PMID:36395107].","caveats":"Functional only; no binding measurement is reported in our evidence. The curator's full-text read gave only discussion text. A second confirmed paper was not shown.","key_references":[{"PMID":"36395107","why":"Cbln1 axon growth and guidance mediated by Nrxn2"}],"covers":["LR002244","LR005554"]},"LR003727":{"pair":"CCL11 -> ACKR2","headline":"CCL11 binds the atypical receptor ACKR2 (D6) with relatively low affinity and is taken up by it; atypical scavenger, two confirming papers.","interaction_type":"direct binding","direction_and_effect":"Human D6 binds eotaxin (detectable but relatively lower affinity than other beta-chemokines) and does not flux calcium [PMID:9405404]. In human trophoblasts and HEK-ACKR2 cells, excess unlabeled CCL11 reduced CCL2 uptake, consistent with ACKR2-mediated scavenging [PMID:25297873]. UniProt lists CCL11 among ACKR2 chemokine ligands [DB:UniProt].","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Human receptor; primary human trophoblasts and HEK cells; Ackr2-deficient mice used for phenotypes [PMID:25297873]. Mouse pair is projected.","localisation_and_range":"CCL11 flagged secreted, ACKR2 transmembrane [flag].","caveats":"The first paper notes the physiological relevance of the eotaxin interaction remains to be determined [PMID:9405404]. CCL11 evidence in the second paper is competition for uptake, not direct binding. No affinity numbers in our evidence.","key_references":[{"PMID":"9405404","why":"Cloning of human D6 and chemokine binding profile"},{"PMID":"25297873","why":"ACKR2 scavenging in human trophoblasts, competed by CCL11"}],"covers":["LR000182","LR003727"]},"LR006751":{"pair":"Ccl12 -> Ccr2","headline":"Mouse Ccl12 is proposed as a Ccr2 ligand driving fibrocyte recruitment in lung fibrosis; in vivo evidence only, one paper.","interaction_type":"functional only","direction_and_effect":"Ccr2-null mice were protected from FITC-induced lung fibrosis while Ccl2-null mice were not, and only CCL12 neutralisation reduced fibrosis, so CCL12 is proposed as the CCR2 ligand driving fibroproliferation [PMID:16543609]. UniProt states CCR2 can bind CCL12 [DB:UniProt].","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Mouse in vivo (FITC lung fibrosis model) and in vitro fibrocyte chemotaxis [PMID:16543609].","localisation_and_range":"Secreted ligand [flag]; chemoattractant for fibrocytes [PMID:16543609].","caveats":"Single abstract-only paper; no direct binding data in our evidence. The inference is genetic and neutralisation-based.","key_references":[{"PMID":"16543609","why":"CCL12 neutralisation and Ccr2 knockout in lung fibrosis"}],"covers":["LR006751"]},"LR000199":{"pair":"CCL15 -> CCR3","headline":"CCL15 (MIP-5) binds human CCR3 with low-nanomolar competition IC50; one binding paper plus GtoPdb.","interaction_type":"direct binding","direction_and_effect":"CCL15 competed with 125I-MCP-3 for CCR3 binding [PMID:9346309]; GtoPdb lists a full agonist [DB:GtoPdb].","molecular_requirements":"Not reported in our evidence.","affinity_potency":[{"value":"IC50 2.5 nM","assay":"competition with 125I-MCP-3","system":"CCR3 receptor-binding assay","cite":"PMID:9346309"}],"species_and_systems":"Human ligand and receptor; abstract-only reading [PMID:9346309].","localisation_and_range":"Secreted ligand and transmembrane receptor according to entity annotation flags [flag]; paracrine/endocrine range implied by the secreted flag only.","caveats":"Single primary paper; affinity is higher here than at CCR1 (IC50 12 nM) in the same study [PMID:9346309]. Functional activation at CCR3 is not detailed in our evidence beyond the GtoPdb record.","key_references":[{"PMID":"9346309","why":"MIP-5 binds CCR3 and CCR1"}],"covers":["LR000199"]},"LR003736":{"pair":"CCL19 -> ACKR4","headline":"Well supported direct, high-affinity binding of CCL19 to the atypical receptor ACKR4, which acts as a scavenger rather than a classical signaller.","interaction_type":"direct binding","direction_and_effect":"ACKR4 internalises CCL19 as a decoy receptor and recruits beta-arrestins in response to CCL19 [PMID:23341447]; no classical Gi signalling, though a pertussis-toxin-insensitive CRE-reporter response was seen and required an intact DRY motif [PMID:23341447]. A systematic screen classed CCL19 as a beta-arrestin-recruiting agonist [PMID:32480426].","molecular_requirements":"Not reported in our evidence beyond ACKR4 alone in transfected systems.","affinity_potency":[{"value":"pKi 8.4","assay":"binding (as curated)","system":"human CCX-CKR/ACKR4","cite":"PMID:23341447"},{"value":"pEC50 8.5-9.1","assay":"GtoPdb agonist record","system":"not specified","cite":"DB:GtoPdb"}],"species_and_systems":"Human ligand and receptor in all papers [PMID:23341447][PMID:10706668][PMID:32480426]; radiolabelled competition binding with CCX CKR-expressing cells [PMID:10706668]. Mouse pair is projected from human evidence (ortholog inferred).","localisation_and_range":"Ligand is flagged as secreted and not transmembrane [flag], so signalling is presumably paracrine or endocrine; receptor is flagged transmembrane [flag].","caveats":"All three papers read as abstract only. The 2000 paper reports ELC (CCL19 by alias) as a high-affinity ligand with IC50 <15 nM [PMID:10706668]. Reactome and BioGRID also record the interaction [DB:Reactome][DB:BioGRID].","key_references":[{"PMID":"23341447","why":"Decoy function, beta-arrestin recruitment, pKi 8.4"},{"PMID":"10706668","why":"Radioligand binding, IC50 <15 nM"},{"PMID":"32480426","why":"beta-arrestin screen confirms CCL19 as ACKR4 agonist"}],"covers":["LR000208","LR003736"]},"LR003754":{"pair":"CCL2 -> ACKR4","headline":"One abstract-read paper shows high-affinity MCP-1 binding and chemotaxis response in cells expressing the receptor now called ACKR4.","interaction_type":"direct binding","direction_and_effect":"Receptor transfection gave responsiveness to MCP-4, MCP-2 and MCP-1 in chemotaxis assays; MCP-1 competed for binding with IC50 10.7 nM, and MCP-3 and eotaxin bound with greater affinity but acted as agonists only at 100-fold higher concentrations [PMID:10734104].","molecular_requirements":"Not reported in our evidence.","affinity_potency":[{"value":"IC50 10.7 nM","assay":"competition binding vs radiolabeled MCP-4","system":"receptor-transfected murine L1.2 cells","cite":"PMID:10734104"}],"species_and_systems":"Human ligand and receptor expressed in murine L1.2 cells [PMID:10734104]. Mouse pair is ortholog-inferred.","localisation_and_range":"Ligand is flagged as secreted and not transmembrane [flag], so signalling is presumably paracrine or endocrine; receptor is flagged transmembrane [flag].","caveats":"Single paper, abstract only; the paper calls the receptor CCR11 (alias). No database record in our evidence.","key_references":[{"PMID":"10734104","why":"Chemotaxis and competition binding, MCP-1 IC50 10.7 nM"}],"covers":["LR000233","LR003754"]},"LR005563":{"pair":"CCL22 -> ACKR4","headline":"One systematic abstract-read screen shows CCL22 as a potent partial agonist of ACKR4 in a beta-arrestin recruitment assay.","interaction_type":"functional only","direction_and_effect":"CCL22 acted as a potent partial agonist of ACKR4 in a beta-arrestin recruitment screen of 43 human chemokines [PMID:32480426]. ACKR4 is described as a regulator or scavenger of chemokines [PMID:32480426].","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Human chemokines and human ACKR4 in a beta-arrestin recruitment assay [PMID:32480426]. The mouse pair is projected from human. No database record.","localisation_and_range":"Ligand is flagged secreted and receptor flagged transmembrane [flag]; this is an annotation, not from the papers, and implies paracrine/endocrine signalling to a cell-surface receptor.","caveats":"Single paper, abstract only; no affinity or potency value quoted. CCL22 is described as a CCR4 and ACKR2 ligand elsewhere in the abstract [PMID:32480426].","key_references":[{"PMID":"32480426","why":"systematic screen identifying CCL22 as ACKR4 partial agonist"}],"covers":["LR002260","LR005563"]},"LR003745":{"pair":"CCL22 -> CCR4","headline":"CCL22 is a high-affinity agonist ligand of CCR4, shown by direct binding and calcium signalling in transfected cells.","interaction_type":"direct binding","direction_and_effect":"CCL22 (MDC) acts as an agonist: it bound CCR4-transfected L1.2 cells with high affinity, competed with TARC, and induced calcium flux only in CCR4-transfected cells among seven CC receptors tested [PMID:9430724]. N-terminal truncation by two residues impaired CCR4 binding and abolished T-cell chemotaxis but kept monocyte attraction [PMID:9743322]; CD26/DPP IV-processed MDC(5-69) gave impaired CCR4 calcium mobilisation [PMID:9933589].","molecular_requirements":"Single receptor (CCR4) was sufficient in transfectants [PMID:9430724]. The intact N-terminus matters: MDC(1-69) is the active form, truncated forms are weaker at CCR4 [PMID:9743322][PMID:9933589].","affinity_potency":[{"value":"Kd 0.18 nM","assay":"binding of MDC-secreted alkaline phosphatase fusion","system":"CCR4-transfected L1.2 cells","cite":"PMID:9430724"}],"species_and_systems":"Experiments used human ligand and human receptor in transfected L1.2 cells and primary cells [PMID:9430724][PMID:9743322]. The mouse pair is ortholog-inferred, with no mouse experiments in our evidence. BioGRID and GtoPdb records point to PMID 9430724 [DB:BioGRID][DB:GtoPdb].","localisation_and_range":"Ligand is flagged secreted, receptor transmembrane [flag]; so paracrine signalling to CCR4-bearing cells.","caveats":"All papers were read as abstracts only. A possible additional MDC receptor on monocytes is suggested [PMID:9743322].","key_references":[{"PMID":"9430724","why":"Kd, competition and calcium flux for CCL22-CCR4"},{"PMID":"9743322","why":"N-terminal truncation impairs CCR4 binding"},{"PMID":"9933589","why":"DPP IV processing reduces CCR4 activity"}],"covers":["LR000218","LR003745"]},"LR003763":{"pair":"CCL3 -> CCR3","headline":"Mouse CCR3 binds mouse MIP-1 alpha in COS cells (abstract); human pair is projected from this and is thinly supported.","interaction_type":"direct binding","direction_and_effect":"Murine CCR-3 binds murine MIP-1 alpha and murine MIP-1 alpha is a potent chemoattractant for murine eosinophils [PMID:7594543].","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Mouse ligand and mouse receptor in transiently transfected COS cells [PMID:7594543]; the human pair is ortholog-inferred, with no human experiment in our evidence.","localisation_and_range":"CCL3 is flagged as secreted and CCR3 as transmembrane [flag].","caveats":"One paper, read as abstract only; no affinity given for CCR3 (the Kd values in the abstract belong to CCR-1). A review-only paper is not shown.","key_references":[{"PMID":"7594543","why":"Cloning of murine CCR-3 which binds murine MIP-1 alpha"}],"covers":["LR000247","LR003763"]},"LR001693":{"pair":"CCL3L1 -> ACKR2","headline":"CCL3L1 competes for CCL2 uptake by ACKR2 in one browser-read paper; indirect and thinly supported.","interaction_type":"functional only","direction_and_effect":"Unlabelled CCL3L1 at 10-fold molar excess reduced CCL2 uptake by HEK-ACKR2 cells and trophoblasts, which indicates that CCL3L1 binds ACKR2; ACKR2 scavenges chemokines without activating migration signalling [PMID:25297873].","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"HEK-ACKR2 cells and primary human trophoblasts [PMID:25297873]. UniProt lists CCL3L1 among ACKR2 ligands [DB:UniProt].","localisation_and_range":"CCL3L1 is flagged as secreted and ACKR2 as transmembrane [flag].","caveats":"The supporting sentence was read in a browser, was not stored, and its spot-check is pending; only competition against another labelled chemokine, no direct binding or affinity.","key_references":[{"PMID":"25297873","why":"Competition of CCL3L1 for chemokine uptake by ACKR2"}],"covers":["LR001693"]},"LR003772":{"pair":"CCL5 -> SDC1","headline":"One abstract-level paper reports RANTES co-immunoprecipitating with syndecan-1 on human macrophages; proteoglycan binding, not classical signalling.","interaction_type":"direct binding","direction_and_effect":"RANTES associated with syndecan-1 and syndecan-4 but not syndecan-2 or betaglycan in co-immunoprecipitation from human monocyte-derived macrophages [PMID:14637022]. Glycosaminidase pre-treatment strongly reduced RANTES binding to syndecan-1 and -4, implicating glycosaminoglycan chains [PMID:14637022]. BioGRID lists Affinity Capture-Western from the same paper [DB:BioGRID].","molecular_requirements":"Binding depends on glycosaminoglycans per the abstract; syndecan-1 acts as an attachment proteoglycan that may facilitate subsequent RANTES-CCR5 interaction [PMID:14637022]. No signalling through syndecan-1 is reported.","affinity_potency":[],"species_and_systems":"Human macrophages, endogenous proteins [PMID:14637022]; mouse pair is ortholog-inferred.","localisation_and_range":"CCL5 is flagged secreted; the syndecan-1 entry is flagged both secreted and transmembrane [flag].","caveats":"Abstract only; co-IP shows association, not direct binding or affinity. The only support is this one paper plus the BioGRID record from it.","key_references":[{"PMID":"14637022","why":"RANTES co-IPs with syndecan-1/-4 on human macrophages"}],"covers":["LR000262","LR003772"]},"LR003781":{"pair":"CCL7 -> ACKR1","headline":"Human ACKR1 (DARC) binds CCL7 in two papers, one with Ki 6.6 nM; ACKR1 is an atypical receptor and signalling was not shown.","interaction_type":"direct binding","direction_and_effect":"DARC bound pro-inflammatory chemokines including CCL7 in competition binding, but not lymphoid chemokines [PMID:13679391]. CCL2 bound to DARC failed to induce a Ca2+ response in CCR2B cells, suggesting down-regulation of chemokine activity; this was shown for CCL2, not CCL7 [PMID:13679391]. No signalling by CCL7 via ACKR1 is reported.","molecular_requirements":"Not reported in our evidence. A PDB structure with chains of P80098 and Q16570 is recorded [DB:PDB 8JPS].","affinity_potency":[{"value":"Ki 6.6 nM","assay":"125I-CXCL8 displacement binding","system":"human erythrocytes","cite":"PMID:15358176"}],"species_and_systems":"Human erythrocytes (PMID:15358176) and DARC-expressing cells; DARC-knockout mice showed no lymph node change [PMID:13679391]. Mouse pair is ortholog-inferred.","localisation_and_range":"CCL7 flagged secreted; ACKR1 flagged transmembrane receptor [flag].","caveats":"13679391 read as abstract only. The abstract lists CCL7 as a binder but gives no CCL7 affinity. Decoy role is suggested by the abstract's CCL2 result, not shown for CCL7.","key_references":[{"PMID":"15358176","why":"CCL7 Ki 6.6 nM at Duffy on erythrocytes"},{"PMID":"13679391","why":"DARC binds CCL7 among inflammatory chemokines"}],"covers":["LR000271","LR003781"]},"LR002269":{"pair":"CCN1 -> TLR2","headline":"CCN1 binds TLR2 directly (SPR KD 227 nM) and activates MyD88-dependent inflammatory signalling; one primary paper.","interaction_type":"direct binding","direction_and_effect":"Recombinant TLR2 bound immobilized CCN1 in a dose-dependent manner and CCN1 bound TLR2 directly, activating MyD88-dependent signaling and cytokine expression [PMID:32144270]. Induction of Tnfa and Il6 was reduced in Tlr2-deficient macrophages and abolished in Myd88-deficient cells, so CCN1 acts as a DAMP-like agonist [PMID:32144270].","molecular_requirements":"A CCN1 double mutant (DM) lost TLR2 binding yet still bound TLR4, so the TLR2 binding site is separable [PMID:32144270]. No co-receptor is reported for TLR2.","affinity_potency":[{"value":"KD 227 nM","assay":"surface plasmon resonance, TLR2 immobilized, CCN1 as analyte","system":"recombinant human TLR2","cite":"PMID:32144270"}],"species_and_systems":"Human recombinant TLR2 in binding assays; functional work in mouse bone-marrow-derived macrophages and mice [PMID:32144270]. The species of CCN1 protein is not stated in the excerpt.","localisation_and_range":"CCN1 is flagged secreted [flag] but described in the papers as matrix-associated, so adhesion-type contact with receptors on neighbouring cells is plausible.","caveats":"Single paper, also reporting TLR4 binding (KD 291 nM). Cytokine induction was reduced, not absent, in Tlr2-deficient cells, so TLR4 contributes [PMID:32144270].","key_references":[{"PMID":"32144270","why":"Direct CCN1-TLR2 binding by solid-phase and SPR; MyD88-dependent activation"}],"covers":["LR002269","LR005570"]},"LR005572":{"pair":"CCN2 -> EGFR","headline":"CCN2 binds the EGFR extracellular domain by SPR and activates EGFR signalling; evidence is abstract-level from one paper.","interaction_type":"direct binding","direction_and_effect":"The paper reports CCN2 as a novel EGFR ligand with agonist effect: its C-terminal module (CCN2-IV) increased renal EGFR phosphorylation in mice, and EGFR kinase inhibition reduced CCN2-IV-induced ERK activation and inflammation [PMID:23929714].","molecular_requirements":"The EGFR-binding site was localised to the C-terminal module (CCN2-IV) [PMID:23929714]. EGFR/TrkA crosstalk occurred after CCN2-IV stimulation, and CCN2 blockade inhibited TGF-beta-induced EGFR activation [PMID:23929714].","affinity_potency":[],"species_and_systems":"SPR with soluble EGFR extracellular domain; in vivo injection in mice; cultured tubular epithelial cells (species not specified in the abstract) [PMID:23929714]. BioGRID also lists affinity-capture Western records [DB:BioGRID].","localisation_and_range":"CCN2 is flagged as secreted [flag], so paracrine or autocrine action is plausible; this is annotation, not shown by the papers.","caveats":"Abstract read only. Binding was shown for the C-terminal module; full-length affinity is not reported in our evidence. BioGRID support is Affinity Capture-Western from PMID 23175185 [DB:BioGRID].","key_references":[{"PMID":"23929714","why":"SPR binding of CCN2 to EGFR plus in vivo and cell signalling"}],"covers":["LR002271","LR005572"]},"LR005068":{"pair":"CCN2 -> IGF2R","headline":"CCN2 binds M6P/IGF2R with high affinity in corneal fibroblasts and IGF2R is needed for CTGF-driven proliferation; abstract-level.","interaction_type":"direct binding","direction_and_effect":"CTGF binds the M6P/IGF-2-R, and knockout fibroblasts did not proliferate at all in response to CTGF, indicating an agonist-type signalling receptor role [PMID:22511630].","molecular_requirements":"A 280 kDa cross-linked 125I-CTGF complex was immunoprecipitated by antibodies to CTGF or to M6P/IGF-2-R [PMID:22511630]. Radiolabeled CTGF binding was displaced by CTGF but not related growth factors [PMID:22511630].","affinity_potency":[],"species_and_systems":"Radiolabeled recombinant human CTGF on human corneal fibroblasts; M6P/IGF-2-R knockout fibroblasts (species not specified in the abstract) [PMID:22511630]. Both human and mouse pairs are ortholog-inferred.","localisation_and_range":"CCN2 is flagged as secreted [flag], so paracrine or autocrine action is plausible; this is annotation, not shown by the papers.","caveats":"Abstract read only. Scatchard analysis showed high- and low-affinity sites, with best-fit favouring a single high-affinity site; no Kd value is given in our evidence [PMID:22511630]. IGF2R is also a clearance receptor, so binding may not imply classical signalling; the authors report proliferation dependence.","key_references":[{"PMID":"22511630","why":"Binding and knockout functional dependence of CTGF on M6P/IGF2R"}],"covers":["LR001699","LR005068"]},"LR002278":{"pair":"CCN3 -> ITGAV","headline":"CCN3 binds integrin alphavbeta3 directly (half-maximal binding 10 nM); supported by full text and databases.","interaction_type":"direct binding","direction_and_effect":"CCN3 acts as an agonist, supporting HUVEC adhesion and migration through alphavbeta3 [PMID:12695522]. CCN3 binds directly to immobilized integrins alphavbeta3 and alpha5beta1 with half-maximal binding at 10 nM and 50 nM CCN3 respectively [PMID:12695522].","molecular_requirements":"The receptor is the alphavbeta3 heterodimer; UniProt lists ITGAV:ITGB3 and ITGAV:ITGB5 as CCN3 partners [DB:UniProt]. The paper shows binding for alphavbeta3 only [PMID:12695522]. Adhesion by alphavbeta3 was only partly blocked by the LM609 antibody [PMID:12695522].","affinity_potency":[{"value":"10 nM","assay":"half-maximal binding (EC50), solid-phase ELISA with immobilized alphavbeta3","system":"purified integrin, recombinant human CCN3","cite":"PMID:12695522"}],"species_and_systems":"Recombinant human CCN3 (baculovirus-expressed) and purified integrins; HUVEC cells; rat cornea angiogenesis assay [PMID:12695522].","localisation_and_range":"CCN3 is a matricellular protein, and its adhesion activity is shown on coated protein [PMID:12695522]; a secretion annotation for CCN3 is not in our dossier.","caveats":"Single primary paper; UniProt and GtoPdb cite it [DB:UniProt][DB:GtoPdb]. UniProt also lists ITGAV:ITGB5, which the dossier does not detail.","key_references":[{"PMID":"12695522","why":"Direct CCN3-integrin binding and HUVEC adhesion, migration and angiogenesis"}],"covers":["LR002278","LR005579"]},"LR005581":{"pair":"CCN3 -> ITGB3","headline":"CCN3 binds integrin alphavbeta3 directly (half-maximal binding 10 nM); beta3 evidence via the alphavbeta3 heterodimer.","interaction_type":"direct binding","direction_and_effect":"CCN3 is an agonist, supporting HUVEC adhesion and migration through alphavbeta3 [PMID:12695522]. CCN3 binds directly to immobilized integrins alphavbeta3 and alpha5beta1 with half-maximal binding at 10 nM and 50 nM CCN3 respectively [PMID:12695522].","molecular_requirements":"The receptor is the alphavbeta3 heterodimer (UniProt: ITGAV:ITGB3 interacts with CCN3) [DB:UniProt][PMID:12695522]. Whether the beta3 chain alone suffices is not reported in our evidence.","affinity_potency":[{"value":"10 nM","assay":"half-maximal binding (EC50) to alphavbeta3, solid-phase ELISA","system":"purified integrin, recombinant human CCN3","cite":"PMID:12695522"}],"species_and_systems":"Recombinant human CCN3 (baculovirus-expressed) and purified integrins; HUVEC cells; rat cornea angiogenesis assay [PMID:12695522].","localisation_and_range":"CCN3 is a matricellular protein, and its adhesion activity is shown on coated protein [PMID:12695522]; a secretion annotation for CCN3 is not in our dossier.","caveats":"The 10 nM value is for the alphavbeta3 heterodimer, not ITGB3 alone. Single primary paper; UniProt and GtoPdb cite it [DB:UniProt][DB:GtoPdb].","key_references":[{"PMID":"12695522","why":"Direct CCN3-integrin binding and HUVEC adhesion, migration and angiogenesis"}],"covers":["LR002280","LR005581"]},"LR003790":{"pair":"CD14 -> ITGB1","headline":"Direct binding of CD14-Fc to integrin alpha4beta1 reported in one abstract-read paper; ITGB1 is the shared chain.","interaction_type":"direct binding","direction_and_effect":"CD14-Fc bound affinity-purified alpha4beta1 dose-dependently, and Jurkat adhesion to CD14-Fc was alpha4beta1-dependent [PMID:17274987].","molecular_requirements":"The evidence is for the alpha4beta1 heterodimer; K562 cells lacking alpha4 did not adhere until alpha4 was re-expressed, so beta1 alone is not shown to suffice [PMID:17274987].","affinity_potency":[],"species_and_systems":"Human cells and recombinant CD14-Fc; mouse pair is ortholog-inferred only [PMID:17274987].","localisation_and_range":"CD14 flagged secreted and receptor [flag]; tested as adhesion to immobilised protein [PMID:17274987].","caveats":"Single paper, abstract only; chain-level assignment to ITGB1 is inferred from the heterodimer; no database records.","key_references":[{"PMID":"17274987","why":"CD14-Fc binds alpha4beta1"}],"covers":["LR000280","LR003790"]},"LR005077":{"pair":"CD22 -> PTPRC","headline":"CD22 binds sialylated glycans on CD45; low affinity and glycan-mediated, so not a clean protein-specific pair.","interaction_type":"direct binding","direction_and_effect":"Soluble CD22-Ig engagement of CD45 modulated early T-cell signals in antigen receptor/CD3-mediated stimulation; added alpha2-6 sialic acid on CD22 abrogated CD22-ligand interactions [PMID:7537381].","molecular_requirements":"CD22 binds alpha2-6-linked sialic acid on N-glycans; CD45 is one such carrier [PMID:7537381][PMID:12115612]. Affinity for CD45, sialylated CD4 and a synthetic alpha2-6-sialoglycoconjugate did not differ substantially, so CD45 preference is suggested to reflect multiple glycan copies [PMID:12115612].","affinity_potency":[{"value":"Kd 130 microM","assay":"surface plasmon resonance, native CD45, 25 degrees C","system":"human proteins","cite":"PMID:12115612"},{"value":"koff >=18 s-1","assay":"surface plasmon resonance","system":"human proteins","cite":"PMID:12115612"}],"species_and_systems":"Human proteins; soluble CD22-Ig and T cells expressing wild-type and chimeric CD45 [PMID:7537381]; human and mouse pairs listed.","localisation_and_range":"Both partners flagged transmembrane [flag]; transient cell-surface contact.","caveats":"Very low affinity with fast kinetics [PMID:12115612]; binding is glycan-dependent rather than protein-specific. Both papers abstract only. BioGRID and IntAct also list the pair [DB:BioGRID][DB:IntAct].","key_references":[{"PMID":"12115612","why":"SPR affinity of CD22 for native CD45"},{"PMID":"7537381","why":"CD22-CD45 engagement modulates T-cell signalling"}],"covers":["LR001710","LR005077"]},"LR008425":{"pair":"CD27 -> CD70","headline":"CD70 is the ligand of CD27; this pair is recorded in the reverse role. Supported by cloning paper and databases.","interaction_type":"direct binding","direction_and_effect":"CD70 was cloned and shown to be the CD27 ligand; CD70 expressed in COS cells induced proliferation of PHA-costimulated T cells [PMID:8120384]. UniProt describes CD70 as ligand of the CD27 receptor on T cells [DB:UniProt]. Reactome, BioGRID, IntAct and PDB 7KX0 record a complex [DB:Reactome][DB:PDB 7KX0].","molecular_requirements":"Reactome describes a CD27:CD70 homotrimer complex [DB:Reactome]. UniProt reports CD70 ligation activates a TRAF2-PTPN6 axis [DB:UniProt].","affinity_potency":[],"species_and_systems":"Human proteins; transfected COS cells, activated lymphocytes (abstract only) [PMID:8120384].","localisation_and_range":"CD70 is a type II transmembrane protein [PMID:8120384]; UniProt places it on B cells and CD27 on T cells [DB:UniProt]; contact-dependent.","caveats":"One paper, abstract only, with identification by cloning and bioassay rather than affinity. No Kd.","key_references":[{"PMID":"8120384","why":"Cloning of CD70 and identification as CD27 ligand"}],"covers":["LR008425"]},"LR002287":{"pair":"CD40LG -> ITGA2B","headline":"Soluble CD40L binds purified integrin alphaIIbbeta3; ITGA2B alone not tested separately.","interaction_type":"direct binding","direction_and_effect":"rsCD40L specifically bound purified integrin alphaIIbbeta3 and activated platelets in a beta3-dependent manner and induced platelet spreading [PMID:11875495]. CD154 bound alphaIIbbeta3 with an affinity about 4-fold higher than for alpha5beta1 [PMID:22461623].","molecular_requirements":"Binding was shown with the alphaIIbbeta3 heterodimer; a KGD integrin-recognition sequence in rsCD40L was needed for in vivo thrombosis [PMID:11875495]. Role of alphaIIb chain alone not reported.","affinity_potency":[],"species_and_systems":"Recombinant soluble proteins, purified integrin, platelets, in vivo mouse thrombosis [PMID:11875495]; mouse pair projected.","localisation_and_range":"CD40LG flagged secreted [flag]; soluble CD40L acts on platelets.","caveats":"Abstracts only. Evidence is for the alphaIIbbeta3 complex, so ITGA2B alone is chain-only attribution.","key_references":[{"PMID":"11875495","why":"rsCD40L binds alphaIIbbeta3 via KGD"},{"PMID":"22461623","why":"CD154 affinity ~4-fold higher for alphaIIbbeta3 than alpha5beta1"}],"covers":["LR002287","LR005586"]},"LR005590":{"pair":"CD40LG -> ITGB1","headline":"CD40L binding to integrin beta1 partners (alpha5beta1, alpha4beta1) rests on abstract-level papers and UniProt.","interaction_type":"direct binding","direction_and_effect":"CD154 binds alpha5beta1, binds CD40 simultaneously, and together they activated p38 and ERK1/2 and synergised in MMP-2/-9 release [PMID:22461623]. Soluble CD40L activated soluble and cell-surface alphavbeta3, alpha5beta1 and alpha4beta1, including in CD40-negative CHO cells [PMID:33571526]. UniProt records an integrin receptor role for CD40LG [DB:UniProt].","molecular_requirements":"ITGB1 is shared by alpha5beta1 and alpha4beta1; the alpha partner is the one tested, so beta1 alone is not shown to suffice [PMID:33571526]. Integrins bind the CD40L trimeric interface [PMID:33571526].","affinity_potency":[],"species_and_systems":"Human; U937 cells and CHO cells and cell-free soluble integrins [PMID:22461623][PMID:33571526]. Mouse pair is ortholog-inferred.","localisation_and_range":"Ligand carries secreted and transmembrane flags [flag]; soluble CD40L used [PMID:33571526].","caveats":"Abstract-only reads; evidence is at heterodimer level (curators stored it per subunit). The binding paper's experiment species are recorded as unspecified [PMID:22461623]. The UniProt entry text names ITGA5:ITGB3 [DB:UniProt]. Two more confirmed papers are not shown.","key_references":[{"PMID":"22461623","why":"CD154 binding to alpha5beta1"},{"PMID":"33571526","why":"sCD40L activates alpha4beta1 and alpha5beta1"}],"covers":["LR002291","LR005590"]},"LR005086":{"pair":"CD44 -> SELE","headline":"CD44 glycoforms act as E-selectin ligands in two abstract-only papers plus IntAct and Reactome records; direction is reversed in the pair.","interaction_type":"direct binding","direction_and_effect":"The sialylated, fucosylated N-glycan glycoform of CD44 on human CD34+ progenitor cells serves as an E-selectin ligand, mediating rolling over a wider shear range than PSGL-1 [PMID:11402070]. Glycoproteomics in breast cancer cells identified CD44 (HCELL) and CD13 as key E-selectin ligands [PMID:29777742]. IntAct has coimmunoprecipitation and solid-phase assay records for the pair [DB:IntAct P16070-P16581].","molecular_requirements":"Activity depends on a specific glycoform (sLeX-type decoration on N-glycans) present only on primitive CD34+ cells, not mature hematopoietic cells [PMID:11402070]. Glycan-dependent, so gene-level expression will not predict it.","affinity_potency":[],"species_and_systems":"Human progenitor cells in shear-based adhesion assays [PMID:11402070]; human breast cancer cell lines and clinical tissue [PMID:29777742].","localisation_and_range":"CD44 carries secreted, receptor and transmembrane flags and SELE a transmembrane flag [flag]; the interaction is cell-surface and contact-dependent in rolling assays [PMID:11402070].","caveats":"Both papers abstract-only (the first also had full-text excerpts). Binding is to a glycan on CD44 rather than a protein-protein interface. E-selectin is the receptor here, CD44 the ligand as in the pair. Species for the breast cancer study not recorded in the dossier [PMID:29777742].","key_references":[{"PMID":"11402070","why":"CD44 glycoform as E-selectin ligand on human progenitors"},{"PMID":"29777742","why":"CD44 (HCELL) and CD13 as E-selectin ligands in breast cancer"}],"covers":["LR001719","LR005086"]},"LR000289":{"pair":"CD70 -> CD27","headline":"CD70 is the established ligand of CD27, supported by cloning, antibody competition, binding databases and functional studies, mostly in human cells.","interaction_type":"direct binding","direction_and_effect":"CD70 engagement of CD27 is stimulatory in B-cell assays: CD70 transfectants raised IgG, IgM and IgA synthesis with IL-10, blocked by anti-CD70 [PMID:9767422], and raised IgE synthesis with IL-4 plus anti-CD40 [PMID:9862673]. In haematopoietic progenitors the effect was inhibitory: CD70 reduced colony-forming potential in vitro and lymphocyte outgrowth in vivo [PMID:15723067]. CD27-transfected cells inhibited T-cell-dependent IgG production, consistent with a decoy-like effect [PMID:7479974]. Stimulatory modulatory effect annotated in the interaction record.","molecular_requirements":"Not reported in our evidence beyond a CD27:CD70 homotrimer complex and a PDB structure with one chain of each [DB:Reactome R-HSA-5669095] [DB:PDB 7KX0]. Anti-CD70 antibodies interfered with CD27L antibody binding on transfected mouse fibroblasts [PMID:8186199].","affinity_potency":[],"species_and_systems":"Human cells throughout the papers, using mouse pre-B or fibroblast cells and monkey kidney cells as transfection hosts [PMID:7479974] [PMID:8120384]; the progenitor study is listed as human on both sides [PMID:15723067]. A mouse pair is also in the dossier.","localisation_and_range":"CD70 is a type II transmembrane protein [PMID:8120384], so signalling is by cell contact; the annotation flags list it as neither secreted nor transmembrane [flag]. Cell-to-cell contact is stated for CD27/CD70 in B cells [PMID:9767422].","caveats":"All papers were read as abstracts only. No affinity value is reported in our evidence. Binding is supported by BioGRID, IntAct, GtoPdb, Reactome and PDB records [DB:BioGRID] [DB:IntAct] [DB:PDB 7KX0] but the GtoPdb record gives no action or affinity [DB:GtoPdb]. Effect depends on context (stimulatory versus inhibitory).","key_references":[{"PMID":"8120384","why":"Expression cloning shows CD70 is identical to the CD27 ligand"},{"PMID":"8186199","why":"Antibody competition shows CD70 is the CD27 ligand"},{"PMID":"15723067","why":"CD70 stimulation of CD27+ progenitors is inhibitory"}],"covers":["LR000289","LR003798"]},"LR002296":{"pair":"CD72 -> CD5","headline":"CD72 was reported as a CD5 ligand by direct binding and transfection in 1991, with costimulatory functional follow-up; the evidence is old and abstract-level.","interaction_type":"direct binding","direction_and_effect":"Biotinylated purified human CD5 bound CD72, blocked by anti-CD72 antibodies, and CD72-transfected non-B cells gained CD5 binding [PMID:1711157]. Engagement of CD5 and/or CD72 with agonistic antibodies delivered costimulatory signals in B-1a, B-2 and chronic lymphocytic leukemia B cells [PMID:8757302]. Soluble CD5 raised thymidine uptake 2- to 5-fold in anti-sIgM-activated B cells, and this was abolished by soluble recombinant CD72 [PMID:8806810].","molecular_requirements":"Not reported in our evidence.","affinity_potency":[{"value":"0.15 microM","assay":"lowest effective concentration of soluble CD5 in a B-cell thymidine uptake assay (potency, not Kd)","system":"human B cells activated with immobilized anti-sIgM","cite":"PMID:8806810"}],"species_and_systems":"Human proteins and cells; transfection into mouse L-cell fibroblasts and human Jurkat T cells [PMID:1711157]. The mouse pair is ortholog-inferred from human evidence; Lyb-2 is named as the mouse CD72 in the paper [PMID:1711157].","localisation_and_range":"CD72 is a B-cell surface protein [PMID:1711157]. The annotation flags list CD5 as secreted and CD72 as transmembrane [flag]; contact between T and B cells is suggested for this pair [PMID:8757302].","caveats":"All three papers were read as abstracts only. In the costimulation study, the two anti-CD72 antibodies but not soluble CD5 costimulated with suboptimal anti-CD40 or IL-4 [PMID:8806810]. Functional readouts rely largely on agonistic antibodies [PMID:8757302]. BioGRID, IntAct and UniProt rest on the same 1991 paper [DB:BioGRID] [DB:UniProt]. One further paper is pending and not shown.","key_references":[{"PMID":"1711157","why":"Direct CD5-biotin binding to CD72 and transfectant gain-of-binding"},{"PMID":"8806810","why":"Soluble recombinant CD72 abolished the CD5 costimulatory effect"},{"PMID":"8757302","why":"Costimulatory signalling by CD5/CD72 engagement in B-cell subsets"}],"covers":["LR002296","LR005595"]},"LR001729":{"pair":"CD80 -> CD28","headline":"CD80 binds CD28 and is well supported by mutagenesis, binding assays and databases, though two curated papers are indirect.","interaction_type":"direct binding","direction_and_effect":"The interaction record annotates CD80 as stimulatory to CD28. Mutagenesis of soluble CD80 mapped 11 IgV-domain residues supporting receptor binding, with similar effects on CTLA4Ig and CD28Ig binding, suggesting overlapping sites [PMID:7545666]. Recombinant soluble s1CD80 bound CD28-Ig and CD152-Ig, and recombinant sCD80 inhibited the mixed lymphocyte reaction and T-cell proliferation, a decoy-like effect [PMID:17953528].","molecular_requirements":"Membrane CD80 uses both IgV and IgC domains: IgC-domain mutations of conserved residues completely ablated receptor binding [PMID:7545666]. The soluble form s1CD80 lacks the transmembrane domain; s2CD80 also lacks the IgC-like domain [PMID:17953528].","affinity_potency":[],"species_and_systems":"Human CD80 and CD28 constructs [PMID:7545666] [PMID:17953528]. The mouse pair is ortholog-inferred. Reactome has CD28:B7-1 complexes [DB:Reactome] and BioGRID/IntAct hold reconstituted-complex and solid-phase records [DB:BioGRID] [DB:IntAct].","localisation_and_range":"CD80 is membrane-bound on antigen-presenting cells with a soluble spliced form in serum (0 to 1 mg/l in 24% of healthy people) [PMID:17953528]; the CD80 flags show secreted and transmembrane [flag].","caveats":"Both main papers were abstract-only. No affinity in our evidence. PMID:21530327 is about B7-H2 binding CD28, and only its statement that B7-1 and B7-2 use different domains concerns this pair; it was curated from the abstract.","key_references":[{"PMID":"7545666","why":"Mutagenesis mapping of CD80 residues for CD28/CTLA-4 binding"},{"PMID":"17953528","why":"Soluble CD80 binds CD28-Ig and inhibits T-cell responses"}],"covers":["LR001729","LR005094"]},"LR005095":{"pair":"CD80 -> CTLA4","headline":"CD80 binds CTLA-4, the inhibitory partner, with structural database support and two functional or binding papers; no affinity in our evidence.","interaction_type":"direct binding","direction_and_effect":"Recombinant s1CD80 bound CD152 (CTLA-4)-Ig and inhibited T-cell proliferation, suggesting a decoy-like effect [PMID:17953528]. Interaction of CTLA-4 with CD80 or CD86 inhibits human T-cell activation; blocking anti-CTLA-4 antibodies enhanced activation in CD80- or CD80/CD86-dependent assays [PMID:10583602]. The interaction record's Stimulatory annotation does not match this inhibitory function.","molecular_requirements":"Not reported in our evidence beyond a co-crystal structure [DB:PDB 1I8L] and a PP2A:CTLA4:B7-1/B7-2 complex [DB:Reactome].","affinity_potency":[],"species_and_systems":"Human cells and proteins [PMID:17953528] [PMID:10583602]. Databases include a co-crystal structure [DB:BioGRID] [DB:PDB 1I8L] and surface plasmon resonance [DB:IntAct]. The mouse pair is ortholog-inferred.","localisation_and_range":"CD80 is membrane-bound on antigen-presenting cells with a soluble spliced form [PMID:17953528]; flags show secreted for both partners [flag].","caveats":"Both papers were read as abstracts only. The functional paper uses antibody blockade rather than direct binding. Two pending rows are not shown.","key_references":[{"PMID":"10583602","why":"CTLA-4 interaction with CD80/CD86 inhibits human T-cell activation"},{"PMID":"17953528","why":"Soluble CD80 binds CTLA-4-Ig"}],"covers":["LR001730","LR005095"]},"LR008812":{"pair":"CDH1 -> PTPRM","headline":"Support is a single BioGRID co-purification record; three papers judged not to concern this pair.","interaction_type":"database-asserted only","direction_and_effect":"Direction and effect are not reported in our evidence. The only record is BioGRID PTPRM - CDH1, Affinity Capture-Western [DB:BioGRID] [PMID:9531566].","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Not reported in our evidence beyond the database record.","localisation_and_range":"Both partners are flagged as membrane receptors; the pair is classed Receptor-Receptor [flag].","caveats":"No curator-verified paper supports this pair; three papers were judged to involve a different entity. Affinity Capture-Western does not show direct binding.","key_references":[{"PMID":"9531566","why":"Source paper of the BioGRID record (not verified by curators)"}],"covers":["LR008812"]},"LR005608":{"pair":"CDH2 -> CDH2","headline":"N-cadherin homophilic ligation signals through PI3K/Akt in human prostate carcinoma cells; evidence is functional.","interaction_type":"functional only","direction_and_effect":"Homophilic N-cadherin ligation activated PI3K-dependent Akt and Bad Ser136 phosphorylation, with a 3.5-fold Bcl-2 increase and Bax unchanged [PMID:12095980]. E-cadherin ligation in the same cells did not activate Akt (curator note) [PMID:12095980].","molecular_requirements":"PI3K co-immunoprecipitated with the N-cadherin/catenin complex and recruitment required an intact actin cytoskeleton (blocked by cytochalasin D) [PMID:12095980].","affinity_potency":[],"species_and_systems":"Human PC3/PC3N prostate carcinoma cells, abstract only [PMID:12095980]. The mouse pair is ortholog-inferred.","localisation_and_range":"Membrane-bound homophilic trans adhesion, contact-dependent [flag][PMID:12095980].","caveats":"Direct homophilic binding is not measured in our evidence; only cell responses. Ligand and receptor are the same molecule, so direction is a formality. Abstract-only.","key_references":[{"PMID":"12095980","why":"N-cadherin homophilic ligation activates PI3K/Akt"}],"covers":["LR002310","LR005608"]},"LR005617":{"pair":"CDH6 -> CDH9","headline":"Type II cadherin heterophilic pair: cadherin-6 binds cadherin-9 in SPR on mouse proteins.","interaction_type":"direct binding","direction_and_effect":"On cadherin-6 surfaces cadherin-6 analyte was strongest, followed by binding of cadherin-9 and cadherin-10 [PMID:29742438].","molecular_requirements":"Cadherin-6, -9 and -10 form one specificity group [PMID:29742438].","affinity_potency":[],"species_and_systems":"Type II cadherin binding was measured by SPR and AUC on purified mouse EC1-EC2 fragments, with A431D cell co-culture; the human pair is inferred by orthology [PMID:29742438].","localisation_and_range":"Membrane-bound adhesion molecules, so contact-dependent (juxtacrine); neither partner is flagged secreted [flag].","caveats":"Single paper; SPR heterophilic affinities could not be determined because of competing homodimerization, so only relative response levels are available [PMID:29742438]. Human result is ortholog-projected, not measured.","key_references":[{"PMID":"29742438","why":"SPR matrix of type II cadherin binding"}],"covers":["LR002319","LR005617"]},"LR001738":{"pair":"CEACAM1 -> HAVCR2","headline":"Direct CEACAM1-TIM-3 binding by biochemical, biophysical and crystallographic methods, with PDB structure; also cis expression effects.","interaction_type":"direct binding","direction_and_effect":"CEACAM1 and TIM-3 bind in trans through their N-terminal domains [PMID:25363763]; the paper describes biochemical, biophysical and X-ray crystallography binding characterisation. UniProt states CEACAM1 inhibits T cells through its interaction with HAVCR2 [DB:UniProt]. Co-expressed CEACAM1 enhanced cell surface expression of TIM-3 in HEK293T cells [PMID:25363763].","molecular_requirements":"Membrane-distal IgV-like N-terminal domains mediate binding [PMID:25363763] [DB:UniProt]. PDB 5DZL has a chain of each partner [DB:PDB 5DZL].","affinity_potency":[],"species_and_systems":"Mouse Ceacam1-/- T-cell tolerance experiments and human cells/HEK293T in the same paper [PMID:25363763]; curated pair covers human and mouse entries.","localisation_and_range":"Both are membrane proteins; interaction in trans and cis on T cells [PMID:25363763].","caveats":"Evidence read as abstract with excerpts; one primary paper. Counts also include a review-only row and two abstract-insufficient rows. No affinity in our evidence.","key_references":[{"PMID":"25363763","why":"CEACAM1-TIM-3 binding in trans and cis; crystal structure"}],"covers":["LR001738","LR005102"]},"LR005626":{"pair":"CEMIP -> LRP1","headline":"CEMIP is one of ten direct LRP1 ligands confirmed in cartilage by one study; abstract-level evidence.","interaction_type":"direct binding","direction_and_effect":"Direct binding of CEMIP to purified LRP1 was confirmed, and LRP1 affinity correlated with endocytosis rate; conditional Lrp1 knockout mice show LRP1 regulates these ligands in cartilage [PMID:36028175]. Effect is labelled agonist, but the abstract describes endocytic handling rather than signalling [PMID:36028175].","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Human chondrocytes, purified LRP1, LRP1-deficient cells and a mouse conditional knockout [PMID:36028175]; mouse pair is ortholog-inferred.","localisation_and_range":"CEMIP is flagged secreted [flag]; ligand taken up by cell-surface LRP1 endocytosis [PMID:36028175].","caveats":"Abstract only; no affinity values given; no database records. Part of a systematic ligandome screen with nine companion ligands.","key_references":[{"PMID":"36028175","why":"Direct LRP1 binding of CEMIP among ten chondrocyte ligands"}],"covers":["LR002337","LR005626"]},"LR000298":{"pair":"CGA -> TSHR","headline":"No curated paper supports CGA alone on TSHR; support is database records for the TSH complex.","interaction_type":"database-asserted only","direction_and_effect":"GtoPdb lists an agonist interaction [DB:GtoPdb]. Reactome records TSHR binding TSH/thyrostimulin [DB:Reactome]. Cryo-EM structures of human TSH bound to TSHR with miniGs are in PDB [DB:PDB 7T9I] [DB:PDB 7UTZ].","molecular_requirements":"CGA is the shared alpha chain; the structures contain a chain of CGA and of TSHR [DB:PDB 7T9I]. Beta chain role not reported in our evidence.","affinity_potency":[],"species_and_systems":"Human structures [DB:PDB 7T9I]; mouse pair is ortholog-inferred.","localisation_and_range":"CGA flagged secreted; TSHR transmembrane [flag].","caveats":"No papers shown; outcomes are abstract_insufficient (2) and review_only (1). Support rests on databases alone, and the records concern the TSH heterodimer.","key_references":[],"covers":["LR000298","LR003805"]},"LR003808":{"pair":"CLCF1 -> CNTFR","headline":"The CLC/CLF composite cytokine binds membrane CNTFR; supported by binding, functional and structural records.","interaction_type":"direct binding","direction_and_effect":"The CLC/CLF composite cytokine preferentially interacted with the CNTFR subunit in membrane binding analysis [PMID:11294841]. It acts as an agonist, activating gp130, LIFR and STAT3 and enhancing motor neuron survival [PMID:10966616][PMID:11285233]. GtoPdb lists it as an agonist [DB:GtoPdb].","molecular_requirements":"The ligand is a CLC/CLF heterodimer; co-expression of CLC with CNTFR generated a secreted composite cytokine [PMID:11285233]. Membrane-bound CNTFR is required; soluble CNTFR did not substitute, unlike for CNTF [PMID:11294841]. Signalling needs gp130 and LIFR [PMID:10966616].","affinity_potency":[],"species_and_systems":"Human cells and proteins in all three papers (receptor reconstitution and mammalian cell co-expression); mouse pair is ortholog-inferred.","localisation_and_range":"Ligand flagged secreted, but the paper reports a membrane-bound CNTFR requirement [flag][PMID:11294841].","caveats":"All three papers were read as abstracts only. No affinity reported in our evidence. A cryo-EM structure of the CLCF1 signalling complex is listed [DB:PDB 8D7R].","key_references":[{"PMID":"11294841","why":"Membrane binding; membrane CNTFR required"},{"PMID":"10966616","why":"Identifies CLC/CLF heteromeric CNTFR ligand"},{"PMID":"11285233","why":"CLC-CNTFR composite cytokine activates gp130-LIFR"}],"covers":["LR000302","LR003808"]},"LR001747":{"pair":"CLEC11A -> ITGB1","headline":"ITGB1 is the beta partner of the alpha11beta1 Osteolectin receptor; same single paper as ITGA11, with the alpha chain being the one named.","interaction_type":"direct binding","direction_and_effect":"alpha11beta1 integrin binds Osteolectin with high affinity and the alpha11 chain is required for bone-mass maintenance; Osteolectin acts as an agonist [PMID:30632962].","molecular_requirements":"ITGB1 acts as the partner of alpha11 in the heterodimer; the curator note says the paper's title names the alpha11 row [PMID:30632962]. Whether beta1 alone binds is not reported in our evidence.","affinity_potency":[],"species_and_systems":"Cells are LepR+ skeletal stem cells and osteoblasts; curated species human/human, mouse pair is ortholog-inferred [PMID:30632962].","localisation_and_range":"CLEC11A flagged secreted; ITGB1 flagged a receptor, not secreted [flag].","caveats":"Single paper, with the abstract-level evidence naming alpha11 specifically. Binding of beta1 alone is not reported in our evidence. No database records.","key_references":[{"PMID":"30632962","why":"alpha11beta1 binds Osteolectin"}],"covers":["LR001747","LR005107"]},"LR005635":{"pair":"CLSTN3 -> NRXN2","headline":"Calsyntenin-3 binds \u03b2-neurexins as a synaptic adhesion pair; isoform-specific evidence for NRXN2 is not shown (abstract only).","interaction_type":"direct binding","direction_and_effect":"Clstn3 is a postsynaptic adhesion molecule that induces presynaptic differentiation via presynaptic neurexins; \u03b2-Nrxns directly interact via their LNS domain with Clstn3 and Clstn3 cadherin domains [PMID:32434929].","molecular_requirements":"Splice site 4 (SS4) insert-positive \u03b2-Nrxn variants, but not insert-negative variants, reversed the impaired Clstn3 synaptogenic activity; Clstn3 selectively formed complexes with SS4-positive Nrxns in vivo [PMID:32434929].","affinity_potency":[],"species_and_systems":"Species not specified in the dossier; hippocampal neurons and Clstn3 conditional knockout mice (mouse pair is the non-inferred one) [PMID:32434929]. Human pair is ortholog-inferred.","localisation_and_range":"Both partners transmembrane/adhesion proteins (not flagged secreted [flag]); trans-synaptic, contact-dependent [PMID:32434929].","caveats":"Abstract only. The evidence sentence names \u03b2-Nrxns collectively, not NRXN2 specifically; the paper title mentions both \u03b1- and \u03b2-neurexins but gene-level assignment is not shown. Earlier debate on whether Nrxns bind Clstn3 directly is noted [PMID:32434929].","key_references":[{"PMID":"32434929","why":"\u03b2-neurexin LNS domain binds Clstn3; SS4-dependent synaptogenic activity"}],"covers":["LR002355","LR005635"]},"LR002359":{"pair":"CLU -> PLXNA4","headline":"Clusterin binds PLXNA4 directly with Kd 10.8 nM in a solid-phase assay; one full-text paper.","interaction_type":"direct binding","direction_and_effect":"CLU binds PLXNA4 in a direct, high-affinity manner; CLU co-immunoprecipitated with PLXNA4 from wild-type but not Clu-null brain lysates [PMID:27378688]. Effect on signalling is not shown; PLXNA4 is described as a CLU receptor.","molecular_requirements":"Not reported beyond PLXNA4 itself; no co-receptor described [PMID:27378688].","affinity_potency":[{"value":"Kd 10.8 nM","assay":"cell-free solid-phase binding assay","system":"immobilized human PLXNA4 with human CLU","cite":"PMID:27378688"}],"species_and_systems":"Human recombinant proteins in the binding assay; mouse brain lysates and Plxna4 knockout mice for in vivo work [PMID:27378688]. Human AD brain showed about 50% lower PLXNA4. Human pair is ortholog-inferred.","localisation_and_range":"Clusterin is flagged secreted [flag]; CSF CLU was elevated about 34% in Plxna4-/- mice [PMID:27378688].","caveats":"Single paper. Mass spectrometry hit from mouse brain. Database support is a BioGRID reconstituted-complex record [DB:BioGRID 2484893].","key_references":[{"PMID":"27378688","why":"Identifies PLXNA4 as high-affinity CLU receptor; Kd 10.8 nM"}],"covers":["LR002359","LR005639"]},"LR005644":{"pair":"CNTN1 -> NFASC","headline":"Direct contactin-1 / neurofascin-155 adhesion complex supported by crystal structures and a cell-aggregation assay.","interaction_type":"direct binding","direction_and_effect":"Contactin-1 and neurofascin-155 interact across cells to form paranodal myelin-axon junctions [PMID:36329006]. Cells expressing human CNTN1/CASPR1 aggregated with Nfasc155-expressing cells, and patient Nfasc155 variants (p.P705T, p.P939Ter) abolished this interaction [PMID:31501903].","molecular_requirements":"The Nfasc155 isoform is the glial partner; Nfasc186 and Nfasc140 are axonal isoforms [PMID:31501903]. In the aggregation assay CNTN1 was co-expressed with CASPR1 [PMID:31501903]. Reactome lists a Neurofascin:CNTN1:CASPR complex [DB:Reactome]. Complexed structures reveal competing and complementary interfaces, glycosylation and splice-variant effects [PMID:36329006].","affinity_potency":[],"species_and_systems":"Crystal structures [PMID:36329006]; transfected N2A cell aggregation with human proteins [PMID:31501903].","localisation_and_range":"Both are cell-surface proteins forming a trans adhesion junction (paper text) [PMID:36329006]; this is contact-dependent, not diffusible.","caveats":"Structure paper read as abstract only. The cell assay used CNTN1 together with CASPR1, so CNTN1-alone contribution is not separated. Mouse pair is inferred from human evidence.","key_references":[{"PMID":"36329006","why":"Crystal structures of contactin-1 / neurofascin-155 complex"},{"PMID":"31501903","why":"Aggregation assay; patient variants abolish binding"}],"covers":["LR002364","LR005644"]},"LR003817":{"pair":"CNTN2 -> NRCAM","headline":"Heterophilic TAG-1/NrCAM binding seen in a bead-aggregation assay in one paper.","interaction_type":"direct binding","direction_and_effect":"TAG-1-Fc beads formed mixed aggregates with NrCAM-Fc beads, and CHO cells with transmembrane NrCAM interacted with TAG-1 Fc chimeras [PMID:12139915]. Effect direction recorded as agonist.","molecular_requirements":"Total extracellular domain or Ig domains alone of TAG-1 sufficed for the cell interaction [PMID:12139915].","affinity_potency":[],"species_and_systems":"Human proteins as Fc chimeras and in CHO cells [PMID:12139915]. Both species ortholog-inferred. BioGRID lists reconstituted complex [DB:BioGRID].","localisation_and_range":"Cell adhesion, membrane contact based on the Fc-chimera and transfected-cell format [PMID:12139915].","caveats":"One paper confirms; four others abstract_insufficient. No affinity reported.","key_references":[{"PMID":"12139915","why":"Mixed aggregates of TAG-1 and NrCAM beads"}],"covers":["LR000311","LR003817"]},"LR002368":{"pair":"CNTN3 -> APP","headline":"Direct CNTN3-APP binding mapped to domains by fusion-protein binding and alanine scanning; one abstract-level paper plus full-text excerpts.","interaction_type":"direct binding","direction_and_effect":"CNTN3 and APP bind directly; the curator labels the effect agonist, but the paper reports only binding, not signalling [PMID:31318883].","molecular_requirements":"The second fibronectin domain (Fn2) of CNTN3 mediates APP binding, and the copper-binding domain (CuBD) of APP mediates CNTN3 binding; single residues such as CNTN3 V752A and APP H137A and E183A abolished binding [PMID:31318883]. Deleting the six N-terminal Ig domains of CNTN3 had no effect [PMID:31318883].","affinity_potency":[],"species_and_systems":"APP-alkaline phosphatase and CNTN-Fc fusion proteins in 96-well binding assays; curator labels species human; the paper's own text does not say which species the constructs come from beyond that [PMID:31318883]. The mouse pair is listed as non-projected, the human pair as ortholog-inferred.","localisation_and_range":"CNTN3 is annotated non-secreted and APP secreted and transmembrane [flag]; the assays used extracellular domains, so contact-dependent binding is plausible but not tested in cells [PMID:31318883].","caveats":"Single paper, recorded as abstract only, though full-text excerpts were available; binding was in vitro with recombinant fragments. Among CNTNs, CNTN3 and CNTN4 bound APP best and CNTN1, CNTN2 and CNTN6 weakly [PMID:31318883].","key_references":[{"PMID":"31318883","why":"Domain-level and residue-level mapping of the APP-CNTN3 interface"}],"covers":["LR002368","LR005648"]},"LR005653":{"pair":"CNTNAP1 -> NFASC","headline":"The neurofascin NF155 extracellular domain binds the CASPR-contactin complex on cells and from brain lysate; the CASPR chain alone is not isolated.","interaction_type":"direct binding","direction_and_effect":"NF155 extracellular domain binds specifically to cells expressing the paranodin/Caspr-contactin complex and to that complex from brain lysates in vitro; NF155 antibodies and the extracellular domain inhibit myelination in cocultures [PMID:11839274].","molecular_requirements":"The binding is to the Caspr-contactin cis complex, so contactin is part of the receptor unit; whether Caspr alone suffices is not reported in our evidence [PMID:11839274]. Reactome lists a Neurofascin:CNTN1:CASPR complex [DB:Reactome R-HSA-373682].","affinity_potency":[],"species_and_systems":"Transfected cells, brain lysate and myelinating cocultures; species not reported in our evidence [PMID:11839274].","localisation_and_range":"Both partners are annotated non-secreted [flag]; the paper frames this as a trans axon-glia interaction at paranodal junctions [PMID:11839274].","caveats":"Abstract-only read; the pair is stored with CNTNAP1 as ligand, but the paper tested NF155 as the glial protein binding the Caspr-contactin complex [PMID:11839274].","key_references":[{"PMID":"11839274","why":"NF155 binds the paranodin/Caspr-contactin complex"}],"covers":["LR002373","LR005653"]},"LR006850":{"pair":"COL11A1 -> ITGA10:ITGB1","headline":"Evidence is an abstract-level TNBC study showing COL11A1 binding to ITGB1 only; the named integrin heterodimer is not tested.","interaction_type":"functional only","direction_and_effect":"COL11A1 promoted TNBC metastasis by binding ITGB1, initiating a FAK/YAP cascade; siRNA and rotating magnetic fields suppressed tumour growth and lung metastasis, reversed by an ITGB1 agonist [PMID:41391796].","molecular_requirements":"The paper names the integrin b1 chain only; the alpha subunit (ITGA10) is not reported in our evidence, so the heterodimer assignment is not supported [PMID:41391796].","affinity_potency":[],"species_and_systems":"TNBC cells and an in vivo tumour model; the abstract does not give host species [PMID:41391796].","localisation_and_range":"COL11A1 is annotated secreted and not transmembrane [flag].","caveats":"Abstract-only; no alpha-subunit-specific data. Other judged papers were review-only, so no primary support for this heterodimer in our evidence [PMID:41391796].","key_references":[{"PMID":"41391796","why":"COL11A1 binding ITGB1 in TNBC"}],"covers":["LR006850"]},"LR002377":{"pair":"COL11A2 -> ITGA2","headline":"Only a cell-based report that integrin a2b1/DDR2 bind collagen XI; abstract-level and not chain-specific for COL11A2.","interaction_type":"functional only","direction_and_effect":"Integrin a2b1 and DDR2, but not a11b1, mediated high-affinity binding of cancer-associated fibroblasts to collagen type XI [PMID:36233024].","molecular_requirements":"The a2b1 heterodimer is what the paper names [PMID:36233024].","affinity_potency":[],"species_and_systems":"CAFs; species not reported in our evidence [PMID:36233024]. The human pair is ortholog-inferred.","localisation_and_range":"COL11A2 is annotated secreted and not transmembrane [flag].","caveats":"Abstract-only; the paper says collagen type XI without naming a chain, and does not isolate individual integrin subunits [PMID:36233024].","key_references":[{"PMID":"36233024","why":"Integrin a2b1 and DDR2 binding to collagen XI in CAFs"}],"covers":["LR002377","LR005656"]},"LR003826":{"pair":"COL18A1 -> ITGB1","headline":"Endostatin binds alpha5beta1 by RGD-competable binding in one abstract-read paper; BioGRID and IntAct also list COL18A1-ITGB1.","interaction_type":"direct binding","direction_and_effect":"Human endostatin competes with fibronectin/RGD cyclic peptide to bind alpha5beta1 integrin; its antimigratory activity is mediated by that integrin [PMID:12682293].","molecular_requirements":"The partner is the alpha5beta1 heterodimer, so ITGB1 alone is not shown sufficient [PMID:12682293]. Ligand is endostatin, the NC1 fragment of collagen XVIII.","affinity_potency":[],"species_and_systems":"Human endostatin; abstract only [PMID:12682293]. BioGRID: reconstituted complex [DB:BioGRID, PMID:19542224]; IntAct: pull down [DB:IntAct, PMID:17615292].","localisation_and_range":"Ligand is a secreted fragment; receptor is membrane-bound.","caveats":"Abstract-only read; no affinity reported. Database records name ITGB1 without an alpha chain.","key_references":[{"PMID":"12682293","why":"Endostatin competes with RGD peptide to bind alpha5beta1"}],"covers":["LR000320","LR003826"]},"LR001756":{"pair":"COL18A1 -> PTPRS","headline":"Collagen XVIII binds chicken PTPsigma in vitro, dependent on heparan sulfate chains; one abstract-read paper in avian system.","interaction_type":"direct binding","direction_and_effect":"Collagen XVIII and agrin interact with high affinity with chicken cPTPsigma in vitro [PMID:11865065]. Effect on receptor signalling is not reported in our evidence.","molecular_requirements":"Binding depends entirely on the heparan sulfate chains of the ligand; the binding site maps to the first immunoglobulin-like domain of cPTPsigma [PMID:11865065].","affinity_potency":[],"species_and_systems":"Experiments used the avian orthologue cPTPsigma/CRYPalpha, not human or mouse PTPRS, so the human and mouse pairs are inferred [PMID:11865065].","localisation_and_range":"Ligand is a basal-lamina proteoglycan; receptor is a transmembrane phosphatase (entity flags list both as secreted [flag]).","caveats":"Glycan-mediated rather than protein-specific; other heparan sulfate proteoglycans would be expected to bind similarly (curator note). Avian species only; abstract-only read; no affinity value.","key_references":[{"PMID":"11865065","why":"HSPGs including collagen XVIII bind chicken PTPsigma"}],"covers":["LR001756","LR005114"]},"LR003835":{"pair":"COL1A1 -> ITGB1","headline":"Beta1 integrins bind type I collagen (alpha11beta1 affinity capture, chondrocyte adhesion blocking); abstract-level evidence.","interaction_type":"direct binding","direction_and_effect":"Anti-beta1 completely blocked chondrocyte adhesion to native collagens I and II [PMID:7688313]; alpha11beta1 bound collagen type I-Sepharose [PMID:10464311].","molecular_requirements":"Beta1 acts with an alpha chain: alpha11beta1 heterodimer [PMID:10464311]; anti-alpha2 reduced binding by only 40-50% [PMID:7688313]. ITGB1 alone is not shown to bind.","affinity_potency":[],"species_and_systems":"Human alpha11 integrin binding to collagen I-Sepharose [PMID:10464311]; human fetal chondrocyte adhesion [PMID:7688313].","localisation_and_range":"COL1A1 is flagged secreted and not transmembrane [flag]; type I collagen is an extracellular matrix ligand, so signalling is by cell contact with matrix (inferred from the flag; not stated in the papers read).","caveats":"Both papers read as abstracts. Collagen I is a heterotrimer, so COL1A1 is not separated from COL1A2. BioGRID co-purification [DB:BioGRID]. One row was judged different_entity.","key_references":[{"PMID":"10464311","why":"alpha11beta1 binds collagen type I-Sepharose"},{"PMID":"7688313","why":"Anti-beta1 blocks chondrocyte adhesion to collagens"}],"covers":["LR000329","LR003835"]},"LR002386":{"pair":"COL1A2 -> DDR1","headline":"Type I collagen binds and activates DDR1; direct binding and phosphorylation shown in 1997 full-text papers.","interaction_type":"direct binding","direction_and_effect":"Collagen I induces DDR1 phosphorylation as an agonist [PMID:9659899] and stimulates DDR1 ectodomain shedding [PMID:16440311].","molecular_requirements":"Receptor activation requires native triple-helical collagen per the abstract [PMID:9659899]. DDR1 binding to type I collagen was detectable but needed more material than DDR2 (3 vs 1 mg loaded) [PMID:9659900].","affinity_potency":[],"species_and_systems":"Radiolabelled DDR1-Fc binding to bovine dermal collagen I [PMID:9659900]; mouse tail collagen on 293 cells transfected with DDR1b [PMID:9659899]; carcinoma and transfected cells, species unspecified [PMID:16440311].","localisation_and_range":"COL1A2 is flagged secreted and not transmembrane [flag]; type I collagen is an extracellular matrix ligand, so signalling is by cell contact with matrix (inferred from the flag; not stated in the papers read).","caveats":"PMID:16440311 read as abstract only. Collagen I is a heterotrimer; chain-level contribution of COL1A2 not reported. Two other judged rows were review_only.","key_references":[{"PMID":"9659900","why":"Slot-blot binding of DDR1 to collagen I"},{"PMID":"9659899","why":"Collagen activates DDR1 phosphorylation"},{"PMID":"16440311","why":"Collagen I induces DDR1 shedding"}],"covers":["LR002386","LR005665"]},"LR003844":{"pair":"COL2A1 -> ITGA2","headline":"Alpha2 integrin binds and mediates cell adhesion to collagen II in several systems; ITGA2 evidence is mostly alpha2beta1 cell and I-domain studies.","interaction_type":"direct binding","direction_and_effect":"Recombinant alpha2 I domain bound collagens I-III [PMID:16043429]. Alpha2beta1 mediated HCS-2/8 chondrosarcoma binding to native type II collagen [PMID:7520045], and alpha2 transfectants spread on collagen types I-V [PMID:10713152]. Collagen to integrin; adhesion/activation.","molecular_requirements":"Cell studies concern the alpha2beta1 heterodimer; alpha2 I domain alone binds collagen in solution [PMID:16043429; PMID:10713152].","affinity_potency":[],"species_and_systems":"Human recombinant I domains [PMID:16043429]; human chondrosarcoma cells [PMID:7520045]; bovine chondrocyte membranes [PMID:7688313]; CHO transfectants, species of cDNA not stated [PMID:10713152]. Mouse pair is projected.","localisation_and_range":"Matrix ligand, cell-surface receptor [flag].","caveats":"Eight papers are confirmed but four are shown; most read as abstracts. Alpha2 binding to denatured collagen differs: denatured collagen used an alpha5beta1-fibronectin bridge [PMID:7520045]. Alpha2I affinity for the three collagens is described as slightly different, but no values appear in our excerpt [PMID:16043429].","key_references":[{"PMID":"16043429","why":"SPR of alpha2 I domain and collagens"},{"PMID":"7520045","why":"Alpha2beta1 binds native collagen II in chondrosarcoma cells"},{"PMID":"10713152","why":"CHO alpha2 cells spread on collagens I-V"}],"covers":["LR000338","LR003844"]},"LR005671":{"pair":"COL3A1 -> ITGA1","headline":"SPR shows the recombinant alpha1 I domain binds collagen III with similar affinity to collagens I and II; I domain only.","interaction_type":"direct binding","direction_and_effect":"Recombinant alpha1 I domain bound fibrillar collagen types I-III with similar affinities and bound a GROGER peptide from type III collagen [PMID:16043429]. Collagen to integrin.","molecular_requirements":"Only the I domain was tested; beta1 not reported [PMID:16043429].","affinity_potency":[{"value":"KD1 0.15-0.32 uM; KD2 5.5-7.3 uM","assay":"SPR (BIAcore), alpha1 I domain over collagens I-III","system":"recombinant human proteins","cite":"PMID:16043429"}],"species_and_systems":"Recombinant human proteins; mouse pair projected [PMID:16043429].","localisation_and_range":"Matrix ligand [flag]; contact-dependent.","caveats":"Full text read; KDs are across all three collagens, not collagen III alone. A second confirmed paper is counted but not shown.","key_references":[{"PMID":"16043429","why":"SPR alpha1 I domain and collagen III"}],"covers":["LR002392","LR005671"]},"LR003853":{"pair":"COL4A1 -> ITGB8","headline":"Beta8 integrins mediate neuron interactions with collagen IV in chick neurons; indirect and abstract only.","interaction_type":"functional only","direction_and_effect":"An anti-beta8 antibody inhibited sensory neurite outgrowth on collagen IV (and laminin-1, fibronectin) [PMID:7542940].","molecular_requirements":"The beta8 subunit associates with one or more alpha subunits, not identified [PMID:7542940]; the curator notes the entity should be folded into a heterodimer.","affinity_potency":[],"species_and_systems":"Chick sensory neurons; human and mouse pairs are inferred by homology [PMID:7542940].","localisation_and_range":"Ligand is flagged secreted, not transmembrane [flag]; as a collagen it is a matrix ligand, but this is not shown by the cited papers.","caveats":"Antibody blockade, not direct binding; abstract only; collagen chain not identified.","key_references":[{"PMID":"7542940","why":"First ligands for beta8 integrins, including collagen IV"}],"covers":["LR000347","LR003853"]},"LR005707":{"pair":"COLEC12 -> LAIR1","headline":"Proteomic LAIR1 interactome study identifies COLEC12 as a high-affinity LAIR1 ligand; no affinity value reported.","interaction_type":"direct binding","direction_and_effect":"Proteomic definition of the LAIR1 interactome identified Colec12 as a high-affinity LAIR1 ligand; LAIR1 signaling triggered by Collagen1 and Colec12 highlighted survival, proliferation and differentiation pathways [PMID:34260887]. Lair1-/- mice had reduced Ly6C- monocytes [PMID:34260887].","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Mouse (Lair1 knockout, mouse melanoma model) with human clinical association; human pair is the primary species listed, mouse is ortholog-inferred [PMID:34260887].","localisation_and_range":"Ligand is not flagged secreted [flag]; the paper calls Colec12 a stromal factor, and its range (membrane or shed) is not reported in our evidence [PMID:34260887].","caveats":"Abstract only; the numerical affinity is not given in the abstract.","key_references":[{"PMID":"34260887","why":"Colec12 identified as high-affinity LAIR1 ligand"}],"covers":["LR002428","LR005707"]},"LR003871":{"pair":"CORT -> GHSR","headline":"Cortistatin displaces a radioligand from human pituitary membranes at about 10^-7 M; one abstract-level binding paper.","interaction_type":"direct binding","direction_and_effect":"In competition binding, ghrelin and cortistatin (CST) fully displaced 125I-Tyr-Ala-hexarelin from pituitary membranes, whereas somatostatin fragments did not [PMID:11227737].","molecular_requirements":"Not reported in our evidence.","affinity_potency":[{"value":"4.6-5.4e-7 M (ghrelin and cortistatin, similar affinity)","assay":"125I-Tyr-Ala-hexarelin competition binding","system":"human pituitary membranes","cite":"PMID:11227737"}],"species_and_systems":"Human pituitary membranes; mouse pair is ortholog-inferred [PMID:11227737].","localisation_and_range":"CORT is secreted by flag [flag]; GHSR is a transmembrane receptor by flag [flag].","caveats":"About four orders of magnitude weaker than hexarelin [PMID:11227737]. Native membranes rather than recombinant GHSR, so receptor identity is inferred; abstract only; one further paper is still pending.","key_references":[{"PMID":"11227737","why":"Cortistatin displaces hexarelin radioligand on pituitary membranes"}],"covers":["LR000365","LR003871"]},"LR005716":{"pair":"CRIPTO -> LRP2","headline":"Cripto (TDGF1) binds LRP2 ectodomains in pull-downs; one full-text paper.","interaction_type":"direct binding","direction_and_effect":"LRP2 mini-receptor ectodomains bound TDGF1-AP with efficiency similar to CDON-Fc [PMID:32876567]. The paper is a mouse model in which Cdon interacts genetically with Tdgf1 [PMID:32876567].","molecular_requirements":"The LRP2 ectodomain has four repetitive modules; mini-receptor ectodomains were tested [PMID:32876567]. Which modules bind is not stated in the excerpts.","affinity_potency":[],"species_and_systems":"Pull-down assays in HEK293T cells; the study is a mouse model [PMID:32876567]. Mouse pair is inferred.","localisation_and_range":"CRIPTO is flagged secreted [flag].","caveats":"Single paper; no affinity or functional effect on LRP2 reported in our evidence. The curator note mentions sR3/sR4 modules, but our excerpts do not show this.","key_references":[{"PMID":"32876567","why":"Pull-down shows LRP2 binds TDGF1"}],"covers":["LR002437","LR005716"]},"LR003880":{"pair":"CRP -> OLR1","headline":"CRP interacts with LOX-1 in a calcium-dependent way and triggers complement activation; one paper, abstract only.","interaction_type":"direct binding","direction_and_effect":"CRP increased complement activation in LOX-1-expressing CHO cells but not native CHO cells, and activated the C1q-requiring classical pathway on immobilised recombinant LOX-1; anti-LOX-1 antibody reduced complement activation and leukocyte infiltration after CRP injection in hypertensive rats [PMID:21821723]. Curators label it an agonist effect [PMID:21821723].","molecular_requirements":"The interaction is Ca2+-dependent and competes with phosphocholine, suggesting LOX-1 binds the CRP B-face [PMID:21821723]. Annotated as transmembrane [flag].","affinity_potency":[],"species_and_systems":"Human CRP and LOX-1 in cultured CHO cells and recombinant protein; in vivo in hypertensive rats [PMID:21821723]. Mouse pair is ortholog-inferred.","localisation_and_range":"CRP is flagged as secreted and the receptor as a receptor [flag]; CRP would act as a soluble (paracrine/endocrine) ligand on receptor-bearing cells (inferred from flags only). The receptor is flagged transmembrane [flag].","caveats":"Abstract-only read; no affinity reported. The direct-binding claim in the abstract is partly background from earlier work, and this paper's own readouts are complement activation and competition [PMID:21821723].","key_references":[{"PMID":"21821723","why":"LOX-1-dependent complement activation by CRP"}],"covers":["LR000374","LR003880"]},"LR000379":{"pair":"CSF3 -> CSF3R","headline":"G-CSF binds CSF3R; strongly supported by two crystal structures, mutagenesis and human in vivo receptor downregulation.","interaction_type":"direct binding","direction_and_effect":"Crystal structures of human GCSF with the receptor ligand-binding region show a 2:2 complex [PMID:16492764] [PMID:10537111]. G-CSF infusion in humans downregulated its receptor (CD114) on neutrophils by 75% [PMID:11091218]. Curators label the effect stimulatory; GtoPdb lists agonist [DB:GtoPdb].","molecular_requirements":"Two G-CSF and two receptor molecules form the complex, via Ig-like domain cross-over [PMID:16492764]; the BN-BC domains are the principal ligand-binding region [PMID:10537111]. Arg288 of the receptor interacts with Glu19 of G-CSF; a chimera lacking the Ig domain bound G-CSF but did not signal, consistent with a lost binding site and failed dimerisation [PMID:10364174]. No other co-receptor is reported.","affinity_potency":[],"species_and_systems":"Human proteins in the 2.8 A crystal structure [PMID:16492764] and in vivo in eight healthy human volunteers [PMID:11091218]. A mouse pair is ortholog-inferred.","localisation_and_range":"Ligand annotated secreted, non-transmembrane; receptor transmembrane [flag]; systemic and neutrophil receptor effects are shown in vivo [PMID:11091218].","caveats":"Abstracts only. The receptor is downregulated by G-CSF in vivo, which may matter for expression-based scoring [PMID:11091218]. The 1999 mutagenesis paper species is listed as unspecified.","key_references":[{"PMID":"16492764","why":"2.8 A structure of the human GCSF/GCSF-R complex"},{"PMID":"10537111","why":"Crystal structure of GCSF with BN-BC receptor domains"},{"PMID":"11091218","why":"G-CSF downregulates CD114 in humans"}],"covers":["LR000379","LR003885"]},"LR002449":{"pair":"CSPG4 -> LGALS3","headline":"Galectin-3 is a facilitating partner in an NG2-alpha3beta1 complex; one abstract-read paper.","interaction_type":"direct binding","direction_and_effect":"NG2, galectin-3 and alpha3beta1 form a cell-surface complex; galectin-3-dependent oligomerization may potentiate NG2-mediated activation of alpha3beta1, while signalling is via alpha3beta1 [PMID:15181153].","molecular_requirements":"Galectin-3 acts as a facilitating co-receptor, not the signal transducer [PMID:15181153].","affinity_potency":[],"species_and_systems":"Curator labels list mouse experiments; endothelial cells in vitro and cornea in vivo [PMID:15181153]. Both pairs ortholog-inferred.","localisation_and_range":"LGALS3 is flagged secreted and non-transmembrane [flag].","caveats":"Abstract-only evidence; the pair is part of a complex and a gene-level LGALS3 row overstates a direct signalling role. Direct pairwise binding is not shown in our evidence.","key_references":[{"PMID":"15181153","why":"Galectin-3 and alpha3beta1 co-engaged by NG2 in endothelial cells"}],"covers":["LR002449","LR005725"]},"LR005725":{"pair":"CSPG4 -> LGALS3","headline":"Galectin-3 is a facilitating partner in an NG2-alpha3beta1 complex; one abstract-read paper.","interaction_type":"direct binding","direction_and_effect":"NG2, galectin-3 and alpha3beta1 form a cell-surface complex; galectin-3-dependent oligomerization may potentiate NG2-mediated activation of alpha3beta1, while signalling is via alpha3beta1 [PMID:15181153].","molecular_requirements":"Galectin-3 acts as a facilitating co-receptor, not the signal transducer [PMID:15181153].","affinity_potency":[],"species_and_systems":"Curator labels list mouse experiments; endothelial cells in vitro and cornea in vivo [PMID:15181153]. Both pairs ortholog-inferred.","localisation_and_range":"LGALS3 is flagged secreted and non-transmembrane [flag].","caveats":"Abstract-only evidence; the pair is part of a complex and a gene-level LGALS3 row overstates a direct signalling role. Direct pairwise binding is not shown in our evidence.","key_references":[{"PMID":"15181153","why":"Galectin-3 and alpha3beta1 co-engaged by NG2 in endothelial cells"}],"covers":["LR002449","LR005725"]},"LR000388":{"pair":"CTHRC1 -> FZD3","headline":"CTHRC1 co-precipitates with Fzd3 in HEK293 cells and modulates Wnt/PCP signalling; one full-text paper.","interaction_type":"direct binding","direction_and_effect":"Cthrc1 co-precipitated with Fzd3 in HEK293 cells, indicating interaction with multiple Fzd proteins; no binding to Smo or to C-terminally truncated Cthrc1 [PMID:18606138]. In HEK293T cells Cthrc1 activated the PCP pathway but suppressed canonical Wnt signalling [PMID:18606138].","molecular_requirements":"Cthrc1 forms a Cthrc1-Wnt-Fzd/Ror2 complex and enhances Wnt-Fzd/Ror2 interaction; it also bound Wnt3a, Wnt5a and Wnt11 [PMID:18606138]. Cthrc1 did not coprecipitate with LRP6 [PMID:18606138].","affinity_potency":[],"species_and_systems":"Co-IP in HEK293 cells; mouse knockout (Cthrc1 LacZ) and Vangl2 genetic interaction; curator labels list human species for the proteins, mouse pair ortholog-inferred [PMID:18606138].","localisation_and_range":"CTHRC1 flagged secreted [flag]; the paper describes cell-surface-anchored Cthrc1 binding [PMID:18606138].","caveats":"Co-IP shows association, not affinity or direct binding to purified protein; overexpression in cells. Single paper; Fzd paralogs bind similarly, so specificity among Fzd3/5/6 is not shown.","key_references":[{"PMID":"18606138","why":"Cthrc1 binds Fzd proteins and Ror2 and stabilizes the Wnt-receptor complex"}],"covers":["LR000388","LR003894"]},"LR001765":{"pair":"CX3CL1 -> ITGB3","headline":"Direct binding of CX3CL1 chemokine domain to integrin alphavbeta3 (beta3 chain) is reported, with a sub-nanomolar K(D) and integrin activation without CX3CR1.","interaction_type":"direct binding","direction_and_effect":"FKN-CD directly bound alpha(v)beta(3) at K(D) of 3.0 \u00d7 10(-10) M in 1 mM Mn(2+) [PMID:23125415]. FKN-CD activated recombinant alphavbeta3 in cell-free conditions, and the integrin-binding-defective mutant K36E/R37E did not [PMID:24789099]. UniProt describes ITGAV:ITGB3 as a coreceptor in CX3CR1-dependent signalling [DB:UniProt].","molecular_requirements":"Binding was tested on the alphavbeta3 heterodimer; the specificity loop of beta3 is described as involved in recognition of FKN-CD in the full-text excerpts, via a beta1 chimera [PMID:23125415]. A ternary complex with CX3CR1 is reported for signalling [PMID:24789099].","affinity_potency":[{"value":"Kd 3.0 x 10(-10) M","assay":"direct binding, ELISA-type, 1 mM Mn(2+)","system":"human FKN-CD with recombinant soluble alphavbeta3","cite":"PMID:23125415"}],"species_and_systems":"Human ligand and human receptor, recombinant protein and K562/CHO cells. Mouse pair ortholog-inferred. IntAct has co-IP, ELISA and pull-down records [DB:IntAct].","localisation_and_range":"Ligand flagged secreted and transmembrane [flag]; membrane-bound fractalkine also bound the integrins [PMID:23125415].","caveats":"Both papers are from the same group. Authors state the result contradicts earlier studies that found no direct integrin binding [PMID:23125415]. Receptor is one chain of a heterodimer; beta3 alone not tested.","key_references":[{"PMID":"23125415","why":"Direct binding and co-receptor model"},{"PMID":"24789099","why":"Integrin activation independent of CX3CR1"}],"covers":["LR001765","LR005123"]},"LR002458":{"pair":"CXCL10 -> ACKR5","headline":"CXCL10 binds GPR182 (ACKR5) with nanomolar affinity; it is a scavenger-type interaction without classical signalling.","interaction_type":"direct binding","direction_and_effect":"GPR182 bound CXCL10 with nanomolar affinity but chemokine binding did not induce Gq/Gi signalling or beta-arrestin recruitment; the receptor internalised ligand-independently and endothelial GPR182-deficient mice had higher plasma CXCL10 [PMID:33875597]. UniProt describes a scavenger role [DB:UniProt].","molecular_requirements":"Not reported in our evidence beyond a single receptor chain.","affinity_potency":[{"value":"KD 19 nM","assay":"saturation binding with fluorescent CXCL10","system":"HEK293 cells expressing GPR182","cite":"PMID:33875597"}],"species_and_systems":"Binding in HEK293 cells expressing human GPR182; the paper also used mice for in vivo work [PMID:33875597].","localisation_and_range":"GPR182 is expressed in microvascular and lymphatic endothelial cells of most organs [PMID:33875597]. CXCL10 is flagged secreted [flag].","caveats":"The curator-assigned effect \"agonist\" conflicts with the paper, which reports no typical signalling; treat as a scavenger. Single paper.","key_references":[{"PMID":"33875597","why":"GPR182 binds CXCL10, CXCL12 and CXCL13"}],"covers":["LR002458"]},"LR005734":{"pair":"Cxcl10 -> Gpr182","headline":"Mouse Cxcl10 binds Gpr182 with nanomolar affinity as a scavenger-type atypical receptor interaction.","interaction_type":"direct binding","direction_and_effect":"GPR182 bound CXCL10 with nanomolar affinity without typical Gq/Gi or beta-arrestin signalling and with ligand-independent internalisation; deficient mice had raised plasma CXCL10 [PMID:33875597]. UniProt describes a scavenger role [DB:UniProt].","molecular_requirements":"Not reported in our evidence beyond a single receptor chain.","affinity_potency":[{"value":"KD 19 nM","assay":"fluorescent hCXCL10 binding","system":"HEK293 cells expressing human GPR182","cite":"PMID:33875597"}],"species_and_systems":"Affinities were measured with human proteins; the paper states very similar affinities for murine chemokines binding mouse GPR182 [PMID:33875597].","localisation_and_range":"GPR182 is expressed in microvascular and lymphatic endothelial cells [PMID:33875597].","caveats":"The \"agonist\" label conflicts with the paper (no signalling). Single paper, read as abstract plus excerpts.","key_references":[{"PMID":"33875597","why":"GPR182 as chemokine scavenger receptor"}],"covers":["LR005734"]},"LR000397":{"pair":"CXCL11 -> CXCR3","headline":"CXCL11 is a high-affinity agonist of CXCR3, supported by binding, functional and database evidence.","interaction_type":"direct binding","direction_and_effect":"I-TAC/CXCL11 interacts selectively with CXCR3 with significantly higher affinity than IP-10 and HuMig, with higher potency and efficacy in calcium mobilization and chemotaxis in activated T cells and CXCR3 transfectants [PMID:9625760]. Potency rank CXCL11 >> CXCL10 > CXCL9 [PMID:15761110]. In mouse CXCR3 transfectants, ITAC induced chemotaxis and calcium increases [PMID:10556837]. GtoPdb lists a full agonist [DB:GtoPdb]. Activating.","molecular_requirements":"Single receptor chain; CXCL11 is monomeric at millimolar concentrations in an NMR study of the free ligand [PMID:15273303]. Binding determinants are not reported in our evidence.","affinity_potency":[{"value":"KD 1.41 +/- 0.20 nM","assay":"ligand binding to transfected cells","system":"murine CXCR3 in L1.2 cells","cite":"PMID:10556837"},{"value":"pKi 10.4-10.5","assay":"GtoPdb affinity record","system":"human, per database","cite":"PMID:15761110"}],"species_and_systems":"Human ligand and receptor in most papers [PMID:9625760][PMID:15761110]; the KD above comes from murine CXCR3 [PMID:10556837]. Mouse pair is listed.","localisation_and_range":"CXCL11 flagged secreted, CXCR3 transmembrane [flag]; paracrine.","caveats":"Most papers read as abstracts. 15273303 is a free-ligand NMR structure with no receptor experiment. In 12884299 CXCL11 agonism at CXCR3 is background; its own finding is CCR3 antagonism.","key_references":[{"PMID":"9625760","why":"Identification of I-TAC as the highest-affinity CXCR3 ligand"},{"PMID":"15761110","why":"Ligand potency rank order and Ki-based pharmacology"},{"PMID":"10556837","why":"Murine CXCR3 binding KD for ITAC"}],"covers":["LR000397","LR003902"]},"LR007174":{"pair":"CXCL12 -> DPP4","headline":"No curator-confirmed paper; the pair rests on an IntAct enzymatic-study record only.","interaction_type":"database-asserted only","direction_and_effect":"Not reported in our evidence. The only record is an IntAct 'enzymatic study' entry linking DPP4 and CXCL12 [DB:IntAct]; no effect on signalling is described.","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Human only; no experimental system is described in our evidence.","localisation_and_range":"CXCL12 is flagged secreted and DPP4 transmembrane [flag]; no paper text on range.","caveats":"Judged papers were review_only (1) and abstract_insufficient (2); none was confirmed. An enzymatic-study annotation does not show ligand-receptor engagement.","key_references":[],"covers":["LR007174"]},"LR003907":{"pair":"CXCL12 -> ITGB1","headline":"One abstract-only 2018 paper: CXCL12 binds integrin allosteric site 2 and activates integrins alpha4beta1 and alpha5beta1 independently of CXCR4.","interaction_type":"direct binding","direction_and_effect":"Integrin activation was shown by direct binding to the allosteric site 2: SDF1 activated soluble integrin alphavbeta3 in cell-free conditions and the site 2 peptide bound SDF1 [PMID:29301984]. SDF1 activated integrins alpha4beta1 and alpha5beta1 on CXCR4-negative CHO cells, suppressed by site 2 peptide and not by AMD3100 [PMID:29301984]. Effect is activating. UniProt agrees [DB:UniProt].","molecular_requirements":"The binding unit appears to be the alpha/beta heterodimer, not ITGB1 alone; the paper tested alphavbeta3, alpha4beta1 and alpha5beta1 [PMID:29301984]. Proteoglycan binding of SDF1 is proposed to facilitate activation. Mutations in SDF1's predicted site 2 binding region suppressed activation.","affinity_potency":[],"species_and_systems":"Cell-free soluble integrin and CHO cells; species labelled human by the curator, not stated in the abstract. The mouse pair is projected from human. One further abstract_insufficient paper was judged.","localisation_and_range":"CXCL12 is flagged secreted [flag]; activation was proposed for SDF1 presented on proteoglycans [PMID:29301984].","caveats":"Abstract only; one paper from one group; no affinity reported. Receptor is a heterodimer and CCC tools may score subunits separately.","key_references":[{"PMID":"29301984","why":"Only paper: CXCL12 site 2 integrin activation"}],"covers":["LR000402","LR003907"]},"LR002467":{"pair":"CXCL14 -> GPR85","headline":"One abstract-only 2018 breast-cancer paper reports CXCL14 binding GPR85 on fibroblasts; no affinity or independent support.","interaction_type":"functional only","direction_and_effect":"CXCL14 secreted by HIC1-deleted breast cancer cells bound GPR85 on mammary fibroblasts and activated them via ERK1/2, Akt and neddylation pathways; activated fibroblasts promoted progression through CCL17/CCR4 [PMID:30204129].","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Mouse mammary gland with conditional HIC1 deletion and breast cancer cells with mammary fibroblasts [PMID:30204129]; the dossier labels the experiment species human/human. Mouse pair is projected from human.","localisation_and_range":"Paracrine, tumour cell to fibroblast, in the microenvironment [PMID:30204129]; CXCL14 flagged secreted [flag].","caveats":"Single abstract-only paper; binding is stated, not quantified. BioGRID records an affinity capture-western from the same paper [DB:BioGRID]. No second source.","key_references":[{"PMID":"30204129","why":"CXCL14-GPR85 signalling between breast cancer cells and fibroblasts"}],"covers":["LR002467","LR005741"]},"LR005743":{"pair":"CXCL17 -> NRP1","headline":"One 2024 BRET study reports CXCL17 binding neuropilin-1 in cells in a GAG-dependent way; no affinity or second source.","interaction_type":"direct binding","direction_and_effect":"BRET-based assays showed CXCL17 interacts with neuropilin-1, a VEGFR2 coreceptor [PMID:38502733]. CXCL17 displaced labelled VEGF165a from Nluc/NRP1 (but not from Nluc/VEGFR2), and CXCL17-HiBiT gave a BRET increase with SNAP/NRP1 [PMID:38502733]. No downstream signalling effect on NRP1 is reported in our evidence.","molecular_requirements":"Binding depends on glycosaminoglycans: surfen or protamine sulfate abolished the CXCL17-HiBiT signal [PMID:38502733].","affinity_potency":[],"species_and_systems":"Transfected HEK293 cells; protein species not stated in our excerpts [PMID:38502733]. Mouse pair is projected from human.","localisation_and_range":"CXCL17 flagged secreted and NRP1 transmembrane [flag]; cell-surface interaction.","caveats":"Single paper, no affinity value. Cell-based BRET with GAG dependence, so direct protein-protein binding is not proven. No database record.","key_references":[{"PMID":"38502733","why":"NanoBRET evidence for CXCL17 binding to NRP1"}],"covers":["LR002469","LR005743"]},"LR003916":{"pair":"CXCL9 -> CXCR3","headline":"CXCL9 (Mig) is a CXCR3 agonist, directly bound with nM affinity in human and mouse receptor systems; strongly supported.","interaction_type":"direct binding","direction_and_effect":"Agonist (stimulatory). CXCL9 binds CXCR3 and induces chemotaxis and calcium rise with mouse CXCR3 [PMID:10556837]. Human HMEC-1 cells with CXCR3-A or CXCR3-B both bound CXCL9 [PMID:12782716]. Potency rank order was CXCL11 >> CXCL10 > CXCL9 [PMID:15761110]. GtoPdb lists a full agonist [DB:GtoPdb].","molecular_requirements":"Both CXCR3 splice isoforms, CXCR3-A and CXCR3-B, bind CXCL9, with different downstream effects (pro-survival vs. pro-apoptotic) [PMID:12782716].","affinity_potency":[{"value":"Ki 4.9 nM","assay":"radioligand competition binding","system":"heterologously expressed human CXCR3","cite":"PMID:9660793"},{"value":"Kd 11.65 nM","assay":"binding of Mig","system":"murine CXCR3 in L1.2 pre-B cells","cite":"PMID:10556837"}],"species_and_systems":"Human CXCR3 with human ligand [PMID:9660793, PMID:12782716]; murine CXCR3 with human ligand [PMID:10556837]. Dossier covers human and mouse pairs.","localisation_and_range":"Secreted ligand, transmembrane receptor [flag].","caveats":"Most papers abstract-only. The mouse-CXCR3 Kd is listed in the abstract for Mig among IP10, ITAC and Mig. CXCL9 binds CXCR3 more weakly than CXCL10 or CXCL11 [PMID:15761110]. CXCL9 also antagonises CCR3, a separate action; the CXCR3 agonist label here is background in PMID:12884299.","key_references":[{"PMID":"9660793","why":"CXCR3 binds MIG, Ki 4.9 nM"},{"PMID":"12782716","why":"binds both CXCR3-A and CXCR3-B"},{"PMID":"10556837","why":"mouse CXCR3 binding and chemotaxis"}],"covers":["LR000419","LR003916"]},"LR002476":{"pair":"DAG1 -> NRXN2","headline":"Dystroglycan binds the second LNS domain of neurexin-2alpha in vitro; one full-text paper.","interaction_type":"direct binding","direction_and_effect":"Direction and effect not reported in our evidence; the paper reports Ca2+-dependent complex formation [PMID:11470830].","molecular_requirements":"The second LNS domain of neurexins 1alpha, 2alpha and 3alpha formed tight Ca2+-dependent complexes with dystroglycan; only alpha-neurexins with LNS2 or LNS6 captured it [PMID:11470830].","affinity_potency":[],"species_and_systems":"Ig/GST-neurexin LNS fusion proteins with rat/mouse brain homogenate; neurexin 1alpha Ig bound DG+/- but not DG-/- ES cells [PMID:11470830]. Human pair is ortholog-projected.","localisation_and_range":"Neurexin-2 is flagged transmembrane [flag]; dystroglycan is flagged secreted and transmembrane [flag].","caveats":"Single paper; no affinity reported; neurexin-2 evidence is by extension from the shared LNS2 domain result.","key_references":[{"PMID":"11470830","why":"Alpha-neurexin LNS2 domains bind dystroglycan"}],"covers":["LR002476","LR005750"]},"LR008605":{"pair":"DCBLD2 -> SEMA4B","headline":"A 2007 abstract reports that CLCP1 (DCBLD2) interacts with semaphorin 4B; thin evidence.","interaction_type":"direct binding","direction_and_effect":"CLCP1 interacts with semaphorin 4B and regulates lung cancer cell motility; direction and agonist/antagonist role not reported in our evidence [PMID:17213806].","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Lung cancer cells, human [PMID:17213806].","localisation_and_range":"SEMA4B is flagged not secreted [flag]; DCBLD2 carries a receptor flag [flag]. Direction is unclear.","caveats":"One paper, abstract only, no assay detail, no affinity, no database support. Abstract uses protein names (CLCP1), found via a curator read.","key_references":[{"PMID":"17213806","why":"CLCP1 interacts with semaphorin 4B"}],"covers":["LR008605"]},"LR005752":{"pair":"DCHS1 -> FAT4","headline":"Human Fat4 and Ds1 (DCHS1) form complexes at cell boundaries in reconstituted cells; structures are also listed in PDB.","interaction_type":"direct binding","direction_and_effect":"Fat4-Ds1 complexes accumulate on cell boundaries in a threshold-like manner; co-expression is sufficient for complex formation [PMID:28826487]. Signalling direction not reported in our evidence.","molecular_requirements":"Not reported in our evidence beyond the two proteins.","affinity_potency":[],"species_and_systems":"Synthetic reconstitution of human Fat4 and Ds1 in mammalian cells with live imaging [PMID:28826487]. Mouse pair is ortholog-projected.","localisation_and_range":"Both partners are flagged not secreted [flag]; the cell-boundary accumulation suggests contact-dependent (juxtacrine) action [PMID:28826487].","caveats":"Abstract only. PDB 8EGW and 8EGX contain a chain of Q96JQ0 and a chain of Q6V0I7 [DB:PDB 8EGW] [DB:PDB 8EGX].","key_references":[{"PMID":"28826487","why":"Fat4-Ds1 complex accumulation in reconstituted cells"}],"covers":["LR002478","LR005752"]},"LR011944":{"pair":"DCN -> TGFB2","headline":"No curator-verified paper; one BioGRID reconstituted-complex record only.","interaction_type":"database-asserted only","direction_and_effect":"Direction and effect not reported in our evidence.","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Not reported in our evidence; BioGRID reconstituted complex [DB:BioGRID 297018].","localisation_and_range":"Both flagged secreted; TGFB2 is not flagged as a receptor [flag].","caveats":"Rests on one database record; all three judged papers were classed as different entity.","key_references":[],"covers":["LR011944"]},"LR001774":{"pair":"DCN -> TLR2","headline":"Decorin acts as a TLR2/TLR4 ligand in macrophages in one paper; functional evidence with a pull-down in HEK cells.","interaction_type":"functional only","direction_and_effect":"Decorin activated MAPKs p44/p42 and p38 and increased TNFalpha and IL-12p70 release in a TLR2- and TLR4-dependent manner in macrophages [PMID:22087031].","molecular_requirements":"TLR2 and TLR4 both implicated; dependence on co-receptors not reported in our evidence.","affinity_potency":[],"species_and_systems":"Mouse macrophages (Dcn+/+ and Il10-/- backgrounds), septic and tumour mouse models; HEK cells stably expressing TLR2 or TLR4 for binding [PMID:22087031].","localisation_and_range":"Decorin flagged secreted; TLR2 flagged receptor [flag]. Soluble paracrine ligand.","caveats":"Single paper, abstract plus excerpts; the excerpt on pull-down is truncated and no affinity is reported. The same paper supports TLR4 [PMID:22087031].","key_references":[{"PMID":"22087031","why":"Decorin as endogenous TLR2/TLR4 ligand"}],"covers":["LR001774","LR005131"]},"LR006760":{"pair":"Defb2 -> Tlr4","headline":"Mouse beta-defensin 2 is reported as a direct TLR4 ligand on immature dendritic cells; abstract only.","interaction_type":"functional only","direction_and_effect":"Murine beta-defensin 2 acts directly on immature dendritic cells as an endogenous ligand for TLR4, upregulating costimulatory molecules and driving maturation, with type 1 polarised adaptive responses in vivo [PMID:12411706].","molecular_requirements":"Not reported in our evidence (no co-receptor such as MD-2 or CD14 is mentioned).","affinity_potency":[],"species_and_systems":"Mouse beta-defensin 2 and mouse immature dendritic cells [PMID:12411706].","localisation_and_range":"Ligand is flagged secreted [flag]; no range data in our evidence, so paracrine action is implied by the flag only.","caveats":"Abstract only. No binding measurement or affinity is described in the abstract, so 'directly' rests on the authors' wording. Contamination controls (e.g. LPS) are not reported in our evidence.","key_references":[{"PMID":"12411706","why":"TLR4-dependent dendritic cell activation by mDF2beta"}],"covers":["LR006760"]},"LR003925":{"pair":"Defb3 -> Ccr6","headline":"Mouse Defb3 binds mouse CCR6 and attracts immature dendritic cells, per one abstract-level paper.","interaction_type":"direct binding","direction_and_effect":"Murine beta-defensins 2 and 3 bind murine CCR6 and chemoattract immature but not mature bone marrow-derived dendritic cells, similarly to MIP-3alpha [PMID:11714836]. Effect is chemoattraction, i.e. agonist-like; antagonism is not reported.","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Mouse ligand and mouse receptor; bone marrow-derived dendritic cells [PMID:11714836].","localisation_and_range":"Ligand is flagged secreted [flag]; no range data in our evidence, so paracrine action is implied by the flag only.","caveats":"Abstract only; the binding assay itself is not described in the abstract, so the assay type is unclear. The Reactome records in the dossier are human complexes (beta-defensins 1, 4A, 103 with CCR6) and do not directly cover the mouse gene [DB:Reactome]. No affinity reported.","key_references":[{"PMID":"11714836","why":"Murine beta-defensin 2/3 bind murine CCR6"}],"covers":["LR003925"]},"LR002485":{"pair":"DEFB4B -> CCR2","headline":"Fc-fused human beta-defensin 2 binds CCR2 and induces chemotaxis; one full-text paper.","interaction_type":"direct binding","direction_and_effect":"hBD2:Ig bound CCR2-transfected HEK293 cells, induced CCR2-specific chemotaxis of HEK293 cells and human monocytes, and CCR2-deficient mouse cells failed to migrate toward it; CCL2/MCP-1 preincubation abolished hBD-induced migration and hBD2:Ig inhibited MCP-1 migration [PMID:20483750]. Curators label this agonist [PMID:20483750]. Reactome lists a bound complex [DB:Reactome].","molecular_requirements":"Not reported in our evidence; the ligand is a fusion protein in the key study, with no subunit or co-receptor requirement tested.","affinity_potency":[],"species_and_systems":"Human beta-defensin 2 and 3 Fc fusion proteins (hBD2:Ig, hBD3:Ig) and their mouse orthologs bound human CCR2 in HEK293 cells and acted on human monocytes and CCR2-deficient versus wild-type mouse peritoneal exudate cells [PMID:20483750]. Mouse orthologs bound human or mouse CCR2 [PMID:20483750].","localisation_and_range":"Ligand is flagged secreted [flag]; no range data in our evidence, so paracrine action is implied by the flag only.","caveats":"Single paper; the paper names hBD2 and does not distinguish the DEFB4A and DEFB4B loci, and Reactome cites the same paper [DB:Reactome]. Ligand is an Ig-Fc fusion. No Kd reported.","key_references":[{"PMID":"20483750","why":"hBD2/3 Ig fusions bind CCR2 and induce chemotaxis"}],"covers":["LR002485"]},"LR003934":{"pair":"DKK1 -> LRP5","headline":"No curator-verified paper; support is database records and UniProt statements only.","interaction_type":"database-asserted only","direction_and_effect":"UniProt states LRP5 interacts via beta-propeller regions 3 and 4 with DKK1, and DKK1 interacts via its C-terminal Cys-rich domain with LRP5 [DB:UniProt]. BioGRID records co-localization and IntAct records coimmunoprecipitation and tandem affinity purification [DB:BioGRID] [DB:IntAct].","molecular_requirements":"UniProt notes LRP5 complexed with KREMEN2 increases DKK1 effects [DB:UniProt]; other details not reported in our evidence.","affinity_potency":[],"species_and_systems":"Not reported in our evidence.","localisation_and_range":"DKK1 flagged secreted; LRP5 flagged receptor and transmembrane [flag].","caveats":"Judged papers were two different-entity rows, two review-only and one abstract-insufficient; none confirms the pair. Co-localization is a weak assay.","key_references":[],"covers":["LR000442","LR003934"]},"LR007372":{"pair":"DLK1 -> NOTCH2","headline":"DLK1-NOTCH2 rests only on an IntAct coimmunoprecipitation record; no verified paper.","interaction_type":"database-asserted only","direction_and_effect":"No curator-verified paper. IntAct records an association by anti-tag coimmunoprecipitation [DB:IntAct]. Direction and effect not reported in our evidence.","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Species and system not reported in our evidence beyond a human pair entry.","localisation_and_range":"DLK1 flagged secreted and transmembrane; NOTCH2 a transmembrane receptor [flag].","caveats":"Only a database record (PMID 33961781 as cited by IntAct); one review-only paper was judged and not used. Treat as unverified.","key_references":[],"covers":["LR007372"]},"LR003943":{"pair":"DLL4 -> NOTCH1","headline":"Well-supported membrane-bound agonist pair with several functional papers and Reactome complexes; no binding affinity in our evidence.","interaction_type":"functional only","direction_and_effect":"DLL4 acts as an agonist of NOTCH1: Dll4 overexpression in human endothelial cells induces HEY2 and is reversed by a gamma-secretase inhibitor [PMID:16219802]. DLL4 preferentially activates NOTCH1 over NOTCH2 [PMID:30289388]; without Fringes, DLL4-NOTCH1 activation was more than twice that of DLL4-NOTCH2 [PMID:32820046].","molecular_requirements":"Ectodomain selectivity lies in the region between the N-terminus and EGF repeat three [PMID:30289388]. Fringe enzymes modulate activity ligand-specifically [PMID:32820046]. Reactome lists a DLL4:NOTCH1 plasma-membrane complex [DB:Reactome].","affinity_potency":[],"species_and_systems":"Human cell assays (HUVECs, co-culture) [PMID:16219802][PMID:32820046]; mouse retroviral bone-marrow model [PMID:11739188]; both human and mouse records exist.","localisation_and_range":"Both partners are annotated transmembrane and DLL4 not secreted [flag], consistent with contact-dependent signalling.","caveats":"All papers read as abstracts. The mouse leukaemia paper only hedges that Dll4-Notch1 interaction 'may provide key signals' and shows an overexpression phenotype, so it is weak for this pair [PMID:11739188]. Downstream effect in endothelium can be inhibitory for VEGF-A responses [PMID:16219802].","key_references":[{"PMID":"30289388","why":"DLL4 vs DLL1 selectivity for NOTCH1/NOTCH2"},{"PMID":"32820046","why":"DLL/JAG x NOTCH1/NOTCH2 and Fringe effects"},{"PMID":"16219802","why":"Dll4 as Notch ligand in human endothelial cells"}],"covers":["LR000451","LR003943"]},"LR005761":{"pair":"DMP1 -> ITGB3","headline":"Supported by the same abstract-only study as ITGAV: DMP1 engages alphaVbeta3 integrin and activates FAK.","interaction_type":"functional only","direction_and_effect":"DMP1 interacts with alphaVbeta3 integrin and stimulates focal adhesion kinase phosphorylation; the effect is blocked by anti-alphaVbeta3 antibody [PMID:21642437].","molecular_requirements":"The paper implicates the alphaVbeta3 heterodimer; the chain-specific role of beta3 is not resolved [PMID:21642437].","affinity_potency":[],"species_and_systems":"Human mesenchymal stem cells and osteoblast-like cells [PMID:21642437].","localisation_and_range":"DMP1 annotated secreted [flag].","caveats":"Abstract only; antibody blockade, not binding. Same paper supports the ITGAV pair, so these are not independent.","key_references":[{"PMID":"21642437","why":"DMP1 signals via alphaVbeta3 integrin"}],"covers":["LR002493","LR005761"]},"LR002494":{"pair":"DRAXIN -> DCC","headline":"Direct structural evidence that Draxin binds the DCC N-terminal Ig domains; a single paper, read as an abstract.","interaction_type":"direct binding","direction_and_effect":"Draxin interacts with DCC through its N-terminal four immunoglobulin domains, shown by crystal structures [PMID:29503192]. Draxin captures Netrin-1 and tethers it to DCC, modulating Netrin-mediated fasciculation [PMID:29503192]. Listed effect is agonist.","molecular_requirements":"The Draxin C-terminal region binds DCC Ig1-Ig4 at a relatively weak site; Netrin-1 binds a separate adjacent Draxin site [PMID:29503192]. Netrin-1 is part of the proposed functional triad.","affinity_potency":[],"species_and_systems":"Recombinant proteins in crystallography and cell-based binding; the dossier labels species as human [PMID:29503192].","localisation_and_range":"Draxin annotated secreted, DCC transmembrane [flag]; the model has Draxin bridging axons decorated with DCC [PMID:29503192].","caveats":"Abstract plus excerpts only. The binding is described as relatively weak and no Kd is in our evidence. The paper's focus is the Netrin-1 axis.","key_references":[{"PMID":"29503192","why":"Crystal structures of Draxin/DCC and Draxin/Netrin-1"}],"covers":["LR002494","LR005762"]},"LR001783":{"pair":"DSC1 -> DSG1","headline":"Family-wide study finds all desmogleins bind all desmocollins; DSC1-DSG1 is within that set, plus database records.","interaction_type":"direct binding","direction_and_effect":"Solution biophysics and coated-bead aggregation showed that all Dsgs form adhesive dimers with all Dscs, with affinities characteristic of each pair, so DSC1:DSG1 falls inside this set [PMID:27298358]. BioGRID lists a DSG1-DSC1 reconstituted complex [DB:BioGRID]; IntAct lists pull-down and solid-phase assays [DB:IntAct].","molecular_requirements":"Binding is through ectodomain strand-swap; conserved charged residues disfavour Dsg:Dsg and Dsc:Dsc and favour Dsg:Dsc pairing [PMID:27298358]. UniProt notes the cytoplasmic regions interact [DB:UniProt].","affinity_potency":[],"species_and_systems":"Human ectodomains in recombinant assays [PMID:27298358].","localisation_and_range":"Both annotated transmembrane [flag]; adhesive trans-cellular binding between cells in desmosomes [PMID:27298358].","caveats":"Abstract read only; the dossier does not give a pair-specific affinity for DSC1:DSG1. Direction is arbitrary since the interaction is symmetric adhesion; the pair is one of 25 companion rows from one paper.","key_references":[{"PMID":"27298358","why":"Family-wise Dsg:Dsc heterophilic binding and structures"}],"covers":["LR001783"]},"LR001792":{"pair":"DSC3 -> DSG2","headline":"DSC3 -> DSG2: heterophilic desmosomal cadherin binding, supported by a single family-wide paper.","interaction_type":"direct binding","direction_and_effect":"The paper reports that all desmogleins form adhesive dimers with all desmocollins, with affinities characteristic of each Dsg:Dsc pair, so this pair is covered by the family-wise heterophilic result [PMID:27298358]. Binding is trans-cellular and heterodimers are called the fundamental adhesive unit of desmosomes [PMID:27298358].","molecular_requirements":"Ectodomains of one Dsg and one Dsc are sufficient for dimer formation in the reported solution biophysics and bead aggregation; binding uses a strand-swap mechanism with charge-based heterophilic preference [PMID:27298358]. No further subunits or co-receptors reported.","affinity_potency":[],"species_and_systems":"Experiments used human proteins (solution biophysics, SPR and coated-bead aggregation) [PMID:27298358]. Pair is recorded for: human, mouse (ortholog-projected). The mouse entry is projected from human evidence.","localisation_and_range":"Membrane-bound desmosomal cadherins acting in trans between adjacent cells (juxtacrine/contact) [PMID:27298358]; entity flags mark both as receptors and transmembrane where set [flag].","caveats":"Curators read only the abstract; the paper's family-wide statement is applied to this pair, one of 25 companion rows, and no pair-specific affinity is in our dossier. The crystal structures cited cover Dsg2, Dsg3, Dsc1 and Dsc2 only [PMID:27298358]. Database records also exist (IntAct), which are not independent of the evidence above. [DB:IntAct]","key_references":[{"PMID":"27298358","why":"Family-wise Dsg:Dsc heterophilic binding by biophysics, SPR, bead aggregation and crystal structures"}],"covers":["LR001792","LR005148"]},"LR005149":{"pair":"DSC3 -> DSG3","headline":"DSC3 -> DSG3: heterophilic desmosomal cadherin binding, supported by a single family-wide paper.","interaction_type":"direct binding","direction_and_effect":"The paper reports that all desmogleins form adhesive dimers with all desmocollins, with affinities characteristic of each Dsg:Dsc pair, so this pair is covered by the family-wise heterophilic result [PMID:27298358]. Binding is trans-cellular and heterodimers are called the fundamental adhesive unit of desmosomes [PMID:27298358].","molecular_requirements":"Ectodomains of one Dsg and one Dsc are sufficient for dimer formation in the reported solution biophysics and bead aggregation; binding uses a strand-swap mechanism with charge-based heterophilic preference [PMID:27298358]. No further subunits or co-receptors reported.","affinity_potency":[],"species_and_systems":"Experiments used human proteins (solution biophysics, SPR and coated-bead aggregation) [PMID:27298358]. Pair is recorded for: human, mouse (ortholog-projected). The mouse entry is projected from human evidence.","localisation_and_range":"Membrane-bound desmosomal cadherins acting in trans between adjacent cells (juxtacrine/contact) [PMID:27298358]; entity flags mark both as receptors and transmembrane where set [flag].","caveats":"Curators read only the abstract; the paper's family-wide statement is applied to this pair, one of 25 companion rows, and no pair-specific affinity is in our dossier. The crystal structures cited cover Dsg2, Dsg3, Dsc1 and Dsc2 only [PMID:27298358].","key_references":[{"PMID":"27298358","why":"Family-wise Dsg:Dsc heterophilic binding by biophysics, SPR, bead aggregation and crystal structures"}],"covers":["LR001793","LR005149"]},"LR005770":{"pair":"DSG2 -> DSG2","headline":"Homophilic DSG2 trans self-binding shown by cross-linking in human keratinocytes; abstract-level evidence only.","interaction_type":"direct binding","direction_and_effect":"DSG2 binds itself: extracellular cross-linking gave homophilic, isoform-specific adducts in HaCaT keratinocytes, consistent with trans (cell-cell) interaction [PMID:21098030]. No directional effect beyond a curator agonist-style label is reported.","molecular_requirements":"Trp-2 and Ala-80 mutation abolished Dsc2 binding specifically, not tested for DSG2 [PMID:21098030]. Other subunits or co-receptors: not reported in our evidence.","affinity_potency":[],"species_and_systems":"Human HaCaT keratinocytes (cross-linking, electron microscopy) [PMID:21098030]. Pair is recorded for human (ortholog-projected) and mouse; no mouse experiment is in our evidence.","localisation_and_range":"Membrane-bound desmosomal cadherin; trans cell-cell contact, adducts in the detergent-insoluble fraction and probably in desmosomes [PMID:21098030]. Entity flags mark it as a transmembrane receptor [flag].","caveats":"Only the abstract was read. The authors found no evidence for heterophilic or cis interaction (not fully excluded) [PMID:21098030]. No affinity reported, and no database record.","key_references":[{"PMID":"21098030","why":"Cross-linking evidence for homophilic, isoform-specific desmosomal cadherin binding"}],"covers":["LR002502","LR005770"]},"LR009721":{"pair":"DSPP -> ITGB1","headline":"Database-asserted only; the single record concerns the alphaVbeta1 complex, not ITGB1 alone.","interaction_type":"database-asserted only","direction_and_effect":"Reactome records DSPP(463-1301) binding integrin alphaVbeta1 [DB:Reactome R-HSA-4086132].","molecular_requirements":"The record is for the alphaV:beta1 heterodimer; a beta1-only requirement is not shown in our evidence.","affinity_potency":[],"species_and_systems":"Human; no experiments reported in our evidence.","localisation_and_range":"DSPP is flagged as secreted [flag].","caveats":"No confirmed paper: outcomes were review_only and abstract_insufficient. Chain-level assignment to ITGB1 is inferred from the complex record.","key_references":[],"covers":["LR009721"]},"LR003952":{"pair":"EDN1 -> EDNRB","headline":"Endothelin-1 binds and activates the ETB receptor; supported by binding papers read as abstracts plus structures.","interaction_type":"direct binding","direction_and_effect":"ET-1 is an agonist of ETB: iodinated ET-1 binds ETB-transfected cells and is internalised to lysosomes [PMID:12972292]; ET-1 and ET-3 had approximately equal potencies in displacing 125I-ET-1 and in eliciting [Ca2+]i transients [PMID:1713452]. Ligand effect is flagged Stimulatory in the interaction record.","molecular_requirements":"Not reported in our evidence beyond the single receptor; GtoPdb/Reactome-style complex records list EDN1, EDN3:EDNRB [DB:Reactome R-HSA-9825404].","affinity_potency":[],"species_and_systems":"Human cDNA expressed in COS cells and transfected cells [PMID:1713452][PMID:12972292]; the mouse pair is ortholog-inferred, not tested in our evidence. Structures with both chains exist [DB:PDB 5GLH][DB:PDB 8IY5]; an IntAct scintillation proximity assay is also listed [DB:IntAct].","localisation_and_range":"ET-1 is annotated secreted and ETB transmembrane [flag], so a paracrine/endocrine ligand acting on a membrane receptor.","caveats":"All three papers were read as abstracts only. One is mainly a receptor-trafficking study [PMID:12972292]. Endothelins are non-selective at ETB, so this receptor does not discriminate ET-1 from ET-3 [PMID:1713452].","key_references":[{"PMID":"1713452","why":"cloned human ETB, binding and Ca2+ response"},{"PMID":"2175397","why":"original cloning of the non-isopeptide-selective receptor"},{"PMID":"12972292","why":"ET-1 binding and lysosomal fate of ETB"}],"covers":["LR000461","LR003952"]},"LR000469":{"pair":"EFNA1 -> EPHA3","headline":"Database-asserted only: BioGRID and UniProt list EFNA1 as an EPHA3 ligand; no papers judged.","interaction_type":"database-asserted only","direction_and_effect":"UniProt states EFNA1 acts as a ligand for EPHA3 inhibiting epithelial-to-mesenchymal transition of cardiac cells [DB:UniProt PMID:12794130]; a BioGRID reconstituted complex is recorded [DB:BioGRID].","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Species of the supporting experiments not reported in our evidence; human pair is ortholog-inferred, mouse is not.","localisation_and_range":"Annotations flag EFNA1 secreted and transmembrane and EPHA3 secreted [flag]; no paper text on localisation.","caveats":"No curated paper evidence for this pair; support is database-only.","key_references":[],"covers":["LR000469","LR003960"]},"LR003961":{"pair":"EFNA1 -> EPHA4","headline":"Ephrin-A1 binds EphA4 in rat tissue and drives EphA4 signalling in human cells; plus database binding records.","interaction_type":"direct binding","direction_and_effect":"Ephrin-A1 and ephrin-A4 selectively bind EphA4 but not EphA7 in striatal lysates [PMID:10366629]; ephrin-A1 stimulation induces EphA4-mediated phosphorylation of Vsm-RhoGEF and RhoA activation [PMID:12775584]. Stimulatory.","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Rat striatal tissue binding [PMID:10366629]; human cells [PMID:12775584]. Human pair ortholog-inferred, mouse not. Database records: BioGRID affinity capture-western [DB:BioGRID], IntAct ELISA and surface plasmon resonance [DB:IntAct].","localisation_and_range":"EFNA1 annotated secreted and transmembrane, EPHA4 transmembrane [flag].","caveats":"Most papers read as abstracts only. A third paper reads B61 binding as decreasing across receptors but the EphA4 value is not in our excerpt [PMID:8755474]. No affinity values reported.","key_references":[{"PMID":"10366629","why":"ephrin-A1 binds EphA4 in rat striatum"},{"PMID":"12775584","why":"ephrin-A1 via EphA4 activates RhoA"}],"covers":["LR000470","LR003961"]},"LR000478":{"pair":"EFNA2 -> EPHA4","headline":"Database-only: crystal structure of the EphA4-ephrinA2 complex and a pull-down record; no papers judged.","interaction_type":"database-asserted only","direction_and_effect":"A crystal structure of the EphA4-ephrinA2 complex [DB:PDB 2WO3] and an IntAct pull-down [DB:IntAct]; UniProt lists EPHA4 as binder [DB:UniProt PMID:19836338]. Effect not reported in our evidence.","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Experimental species not reported in our evidence; human pair ortholog-inferred, mouse not.","localisation_and_range":"EFNA2 annotated transmembrane, EPHA4 transmembrane [flag].","caveats":"No curated paper evidence; support is database-only, though a structure is direct physical evidence.","key_references":[],"covers":["LR000478","LR003969"]},"LR003970":{"pair":"EFNA2 -> EPHA5","headline":"Ephrin-A2 and EphA5 are co-expressed in mouse hippocampus; no direct binding shown.","interaction_type":"functional only","direction_and_effect":"Both EphA5 and ephrin-A ligands (2 and 5) are expressed in adult mouse hippocampus; immunoadhesins targeting receptor or ligand sites were used with a behavioural readout [PMID:10531456]. UniProt lists EPHA5 as an EFNA2 binder [DB:UniProt].","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Adult mouse hippocampus, in vitro and behavioural [PMID:10531456].","localisation_and_range":"EFNA2 annotated transmembrane, EPHA5 transmembrane [flag].","caveats":"The shown evidence is co-expression and a protein-targeting study, not binding between this pair; abstract only.","key_references":[{"PMID":"10531456","why":"EphA5 and ephrin-A2/A5 in learning"}],"covers":["LR000479","LR003970"]},"LR000487":{"pair":"EFNA3 -> EPHA5","headline":"Ephrin-A3 binds EphA5 in ELISA and repels entorhinal neurites; support is moderate.","interaction_type":"direct binding","direction_and_effect":"Ephrin-A3 AP binds best to EphA3, EphA5 and EphA7 [PMID:22568954]. Entorhinal neurites, which express EphA5, were repelled by ephrin-A3 but not ephrin-A5 [PMID:10516308].","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"ELISA, species unspecified [PMID:22568954]; rat entorhinal neurites in a stripe assay [PMID:10516308]. The human pair is ortholog-inferred.","localisation_and_range":"Both are flagged membrane-bound [flag].","caveats":"The repulsion paper hedges with 'may interact' and did not assay physical binding separately; read as an abstract only [PMID:10516308]. The ELISA paper was a browser read with an unverifiable quote [PMID:22568954].","key_references":[{"PMID":"22568954","why":"ELISA binding ranking"},{"PMID":"10516308","why":"Ephrin-A3 repels EphA5-expressing neurites"}],"covers":["LR000487","LR003978"]},"LR000496":{"pair":"EFNA4 -> EPHA6","headline":"No verified paper; BioGRID and IntAct records only.","interaction_type":"database-asserted only","direction_and_effect":"BioGRID lists EFNA4-EPHA6 by affinity capture-MS [DB:BioGRID]; IntAct lists an anti-tag coimmunoprecipitation association [DB:IntAct]. Effect not reported in our evidence.","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Experimental species not reported in our evidence; the human pair is ortholog-inferred.","localisation_and_range":"EFNA4 flagged secreted and transmembrane; EPHA6 flagged membrane-bound [flag].","caveats":"All judged papers were review-only or abstract-insufficient; support is database records only.","key_references":[],"covers":["LR000496","LR003987"]},"LR005158":{"pair":"ENHO -> GPR19","headline":"Adropin (ENHO) activates GPR19 in one abstract-only paper that confirms an earlier report; GtoPdb lists it as agonist.","interaction_type":"functional only","direction_and_effect":"Adropin-mediated GPR19 activation activates MAPK/ERK1/2, which the paper reports as essential for E-cadherin upregulation in breast cancer cells; adropin is described as an endogenous ligand, agonist [PMID:28476646][DB:GtoPdb].","molecular_requirements":"Subunits or co-receptors: not reported in our evidence.","affinity_potency":[],"species_and_systems":"Human ligand and receptor recorded [PMID:28476646]; the human pair is ortholog-inferred and a mouse pair is also listed. Overexpression in breast cancer cells.","localisation_and_range":"ENHO is flagged secreted and GPR19 as a receptor [flag]; range is not described in the paper text we hold.","caveats":"Abstract only; the paper confirms a previous report rather than showing binding, so evidence is functional. GtoPdb lists pEC50 as the affinity unit but no value is in our dossier [DB:GtoPdb].","key_references":[{"PMID":"28476646","why":"Confirms adropin as GPR19 ligand and shows ERK1/2 activation"}],"covers":["LR001802","LR005158"]},"LR005806":{"pair":"EPHA10 -> EFNA4","headline":"EPHA10-EFNA4 rests only on a UniProt function statement; no verified papers.","interaction_type":"database-asserted only","direction_and_effect":"UniProt states EPHA10 binds EFNA3, EFNA4 and EFNA5 [DB:UniProt]. Effect: not reported in our evidence.","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Experiment species not reported in our evidence.","localisation_and_range":"EPHA10 is flagged secreted in our annotation [flag], unusual for an Eph receptor; EFNA4 flags are secreted and transmembrane [flag]. The pair is oriented Eph -> ephrin in our records; the evidence describes Eph-ephrin binding without establishing which partner acts as ligand here.","caveats":"Two review-only rows; support is a single database sentence. No affinity data.","key_references":[],"covers":["LR002538","LR005806"]},"LR002539":{"pair":"EPHA10 -> EFNA5","headline":"EPHA10-EFNA5 rests only on a UniProt function statement; no verified papers.","interaction_type":"database-asserted only","direction_and_effect":"UniProt states EPHA10 binds EFNA3, EFNA4 and EFNA5 [DB:UniProt]. Effect: not reported in our evidence.","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Experiment species not reported in our evidence.","localisation_and_range":"EPHA10 is flagged secreted in our annotation [flag], unusual for an Eph receptor; EFNA5 flags are non-secreted [flag]. The pair is oriented Eph -> ephrin in our records; the evidence describes Eph-ephrin binding without establishing which partner acts as ligand here.","caveats":"Two review-only rows; support is a single database sentence. No affinity data.","key_references":[],"covers":["LR002539","LR005807"]},"LR005815":{"pair":"EPHA3 -> EFNA3","headline":"EPHA3-EFNA3: one abstract-only colorectal cancer paper reports binding and reverse signalling; BioGRID reconstituted complex.","interaction_type":"direct binding","direction_and_effect":"EphA3 was confirmed to bind EFNA3 by co-immunoprecipitation in CRC cells, and EphA3/EFNA3 reverse signalling (into the EFNA3 cell) promoted EMT through ERK1/2 and metastasis [PMID:40928719]. BioGRID lists a reconstituted complex [DB:BioGRID].","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Colorectal cancer cells and nude-mouse models were used in the paper [PMID:40928719]; species of the cells is not stated in the abstract we hold. Human and mouse pairs are both ortholog-inferred.","localisation_and_range":"EPHA3 is flagged secreted, EFNA3 non-secreted [flag].","caveats":"One paper, abstract only; the ephrin-side (reverse) signalling is a functional claim in cancer cells. No affinity data. Eight other rows were review-only or abstract-insufficient.","key_references":[{"PMID":"40928719","why":"EphA3 binds EFNA3 by co-IP; reverse signalling drives EMT via ERK"}],"covers":["LR002547","LR005815"]},"LR002548":{"pair":"EPHA3 -> EFNA4","headline":"EPHA3-EFNA4 rests on a BioGRID reconstituted complex; no verified papers.","interaction_type":"database-asserted only","direction_and_effect":"BioGRID lists EPHA3-EFNA4 as a reconstituted complex [DB:BioGRID]. Effect: not reported in our evidence.","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Experiment species not reported in our evidence.","localisation_and_range":"Both partners are flagged secreted [flag]. The pair is oriented Eph -> ephrin in our records; the evidence describes Eph-ephrin binding without establishing which partner acts as ligand here.","caveats":"Eight judged rows were review-only or abstract-insufficient; single database record, no affinity data.","key_references":[],"covers":["LR002548","LR005816"]},"LR005824":{"pair":"EPHA4 -> EFNB3","headline":"EPHA4-EFNB3 is supported by a crystal structure and BioGRID/IntAct records; no verified papers.","interaction_type":"direct binding","direction_and_effect":"A crystal structure of the human EphA4 ectodomain with human ephrinB3 is recorded [DB:PDB 4BKF]; BioGRID lists a reconstituted complex [DB:BioGRID]; IntAct lists ELISA and coimmunoprecipitation associations [DB:IntAct]. UniProt states EphA4 is highly promiscuous [DB:UniProt].","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Human proteins in PDB 4BKF [DB:PDB 4BKF]; both pair versions are ortholog-inferred.","localisation_and_range":"Neither partner is flagged secreted [flag]. The pair is oriented Eph -> ephrin in our records; the evidence describes Eph-ephrin binding without establishing which partner acts as ligand here.","caveats":"Database evidence only; two review-only rows. No affinity values in our dossier.","key_references":[],"covers":["LR002556","LR005824"]},"LR002557":{"pair":"EPHA5 -> EFNA1","headline":"EPHA5-EFNA1 rests on a single UniProt statement; no verified papers.","interaction_type":"database-asserted only","direction_and_effect":"UniProt states EFNA1 binds EPHA2, EPHA3, EPHA4, EPHA5, EPHA6 and EPHA7 [DB:UniProt]. Effect: not reported in our evidence.","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Experiment species not reported in our evidence; both pairs are ortholog-inferred.","localisation_and_range":"EFNA1 is flagged secreted, EPHA5 non-secreted [flag]. The pair is oriented Eph -> ephrin in our records; the evidence describes Eph-ephrin binding without establishing which partner acts as ligand here.","caveats":"Two review-only rows; one database sentence only, no affinity data.","key_references":[],"covers":["LR002557","LR005825"]},"LR005833":{"pair":"EPHA6 -> EFNA4","headline":"Database-only pair: BioGRID affinity capture-MS and one IntAct co-immunoprecipitation; no verified paper.","interaction_type":"database-asserted only","direction_and_effect":"Direction and effect are not reported. Both partners carry the receptor annotation flag [flag], so ligand/receptor direction is not established by our evidence.","molecular_requirements":"Requirements: not reported in our evidence.","affinity_potency":[],"species_and_systems":"No paper was verified for this pair; species and experimental system of the database records are not reported in our evidence.","localisation_and_range":"EFNA4 carries both secreted and transmembrane flags [flag]; EPHA6 is receptor-flagged only. Range is unclear from our evidence.","caveats":"No curator-verified paper; support is database records only. Records are an Affinity Capture-MS entry [DB:BioGRID 3648313] and an anti-tag coimmunoprecipitation [DB:IntAct EBI-54500804]; these show association in a cell system, not defined direct binding. Affinity not reported in our evidence.","key_references":[],"covers":["LR002565","LR005833"]},"LR002566":{"pair":"EPHA6 -> EFNA5","headline":"Database-only pair: a single IntAct co-immunoprecipitation record; no verified paper.","interaction_type":"database-asserted only","direction_and_effect":"Direction and effect are not reported. Both partners carry the receptor annotation flag [flag], so ligand/receptor direction is not established by our evidence.","molecular_requirements":"Requirements: not reported in our evidence.","affinity_potency":[],"species_and_systems":"No paper was verified for this pair; species and experimental system of the database records are not reported in our evidence.","localisation_and_range":"Both partners are annotated as transmembrane [flag], so any interaction would be juxtacrine (cell contact); this comes from annotation flags only.","caveats":"No curator-verified paper; support is database records only. Only an anti-tag coimmunoprecipitation record exists [DB:IntAct EBI-54501476], which does not establish direct binding. Affinity not reported in our evidence.","key_references":[],"covers":["LR002566","LR005834"]},"LR002575":{"pair":"EPHA8 -> EFNA4","headline":"Database-only pair: a single IntAct co-immunoprecipitation record; no verified paper.","interaction_type":"database-asserted only","direction_and_effect":"Direction and effect are not reported. Both partners carry the receptor annotation flag [flag], so ligand/receptor direction is not established by our evidence.","molecular_requirements":"Requirements: not reported in our evidence.","affinity_potency":[],"species_and_systems":"No paper was verified for this pair; species and experimental system of the database records are not reported in our evidence.","localisation_and_range":"EPHA8 is transmembrane-flagged; EFNA4 carries secreted and transmembrane flags [flag]; range is unclear.","caveats":"No curator-verified paper; support is database records only. The IntAct record is an anti-tag coimmunoprecipitation [DB:IntAct EBI-54500804], which does not establish direct binding. Affinity not reported in our evidence.","key_references":[],"covers":["LR002575","LR005843"]},"LR005860":{"pair":"EPHB3 -> EFNB2","headline":"EPHB3-hFc binds EFNB2-expressing cells in one henipavirus paper where it served as an expression control; other support is database records.","interaction_type":"direct binding","direction_and_effect":"Soluble EPHB3 (1,210-0.4 nM, fivefold dilution) stained cells expressing EFNB2 or EFNB3 and was used to validate receptor expression; no agonist or antagonist effect was reported [PMID:38426726]. UniProt states forward and reverse signalling through the EFNB2/EPHB3 complex regulate migration and adhesion of cells that tubularize the urethra and septate the cloaca [DB:UniProt].","molecular_requirements":"Not reported beyond the two partners.","affinity_potency":[],"species_and_systems":"Flow cytometry on cell lines expressing EFNB2 or EFNB3 with soluble human-Fc-tagged EPHB3; the species of the cell lines and of EPHB3 is not reported in our excerpts [PMID:38426726].","localisation_and_range":"Both partners transmembrane-flagged [flag]; binding was shown with soluble EPHB3-hFc to cell-surface ephrin [PMID:38426726].","caveats":"The paper's focus is Nipah and related virus receptor-binding proteins; EPHB3 binding is described as a cognate receptor 'previously reported' and was used as a control, with no EPHB3 Kd reported in our excerpts. The Kd values quoted in the excerpts (1.45 nM, 0.34 nM) are for a Hendra virus protein with EFNB3 and EFNB2, not EPHB3. IntAct co-immunoprecipitations also exist [DB:IntAct EBI-21582984], [DB:IntAct EBI-54556805].","key_references":[{"PMID":"38426726","why":"Soluble EPHB3-hFc binding to EFNB2- and EFNB3-expressing cells, used as a validation control in a henipavirus study."}],"covers":["LR002592","LR005860"]},"LR002593":{"pair":"EPHB3 -> EFNB3","headline":"EPHB3-hFc binds EFNB3-expressing cells in one henipavirus paper where it served as an expression control; a BioGRID reconstituted complex also exists.","interaction_type":"direct binding","direction_and_effect":"Soluble EPHB3 (1,210-0.4 nM, fivefold dilution) stained cells expressing wild-type EFNB3 and an EFNB3-Y120F mutant to validate their expression [PMID:38426726]. No agonist or antagonist effect was reported.","molecular_requirements":"Not reported beyond the two partners.","affinity_potency":[],"species_and_systems":"Flow cytometry on cell lines expressing EFNB2 or EFNB3 with soluble human-Fc-tagged EPHB3; the species of the cell lines and of EPHB3 is not reported in our excerpts [PMID:38426726].","localisation_and_range":"Both partners transmembrane-flagged [flag]; binding was shown with soluble EPHB3-hFc to cell-surface ephrin [PMID:38426726].","caveats":"The paper's focus is Nipah virus use of EFNB3; EPHB3 binding is described as 'previously reported' and was used as a control; no EPHB3 Kd is reported in our excerpts. The Kd values in the excerpts (1.45 nM, 0.34 nM) are for a Hendra virus protein, not EPHB3. BioGRID lists a Reconstituted Complex [DB:BioGRID 287713]. Two papers were abstract-insufficient.","key_references":[{"PMID":"38426726","why":"Soluble EPHB3-hFc binding to EFNB2- and EFNB3-expressing cells, used as a validation control in a henipavirus study."}],"covers":["LR002593","LR005861"]},"LR008722":{"pair":"EREG -> ERBB2","headline":"No paper evidence; only a PDB structure of the EREG-bound EGFR/HER2 ectodomain complex supports EREG with ERBB2.","interaction_type":"database-asserted only","direction_and_effect":"Not reported in our evidence beyond a database structure [DB:PDB 8HGP].","molecular_requirements":"PDB 8HGP is an electron microscopy structure of the EREG-bound EGFR/HER2 ectodomain complex, so ERBB2 is seen with EGFR present [DB:PDB 8HGP].","affinity_potency":[],"species_and_systems":"Species and cell system not reported in our evidence.","localisation_and_range":"Both annotated as transmembrane or receptor [flag].","caveats":"No curator-verified paper; the only judged row is review_only. A structure of the ternary complex does not show whether EREG contacts ERBB2 directly.","key_references":[],"covers":["LR008722"]},"LR007066":{"pair":"F2 -> ITGAV:ITGB3","headline":"Prothrombin as an integrin alphaVbeta3 ligand rests on a single UniProt functional statement.","interaction_type":"database-asserted only","direction_and_effect":"UniProt states that integrin alpha-V/beta-3 is a receptor for prothrombin among other ligands [DB:UniProt P05106].","molecular_requirements":"The ITGAV:ITGB3 heterodimer is named as the receptor [DB:UniProt P05106].","affinity_potency":[],"species_and_systems":"Species and system: not reported in our evidence.","localisation_and_range":"Complex annotated transmembrane [flag].","caveats":"Database assertion only, no papers, no binding data or effect direction in our evidence.","key_references":[],"covers":["LR007066"]},"LR000559":{"pair":"FBN1 -> ITGAV","headline":"Fibrillin-1 binds alphaV integrins; direct binding measured for alphaVbeta6 (K(d) approximately 0.45 mum) and functional support for alphaVbeta3.","interaction_type":"direct binding","direction_and_effect":"Integrin alphaVbeta6 is identified as a novel receptor for fibrillin-1 with a K(d) of approximately 0.45 mum, by surface plasmon resonance [PMID:17158881]. Fibroblast adhesion to fibrillin-1 was mediated by alpha 5 beta 1 with alpha v beta 3 contributing [PMID:12807887], and PF14 signaling in HUVECs used alpha v beta 3 [PMID:20686071].","molecular_requirements":"AlphaV needs a beta partner (beta3 or beta6 shown). Module requirements for alphaVbeta6 activation differ from those of alphaVbeta3 [PMID:17158881]. The RGD loop in TB4 mediates adhesion via alphaVbeta3 [PMID:17158881].","affinity_potency":[{"value":"K(d) approximately 0.45 mum","assay":"surface plasmon resonance with recombinant fibrillin fragments (alphaVbeta6)","system":"human fibrillin-1","cite":"PMID:17158881"}],"species_and_systems":"Human proteins and cells in all three papers [PMID:17158881] [PMID:12807887] [PMID:20686071]; the mouse pair is ortholog-inferred. Reactome and UniProt records cover alphaVbeta3 [DB:Reactome] [DB:UniProt].","localisation_and_range":"FBN1 is flagged secreted, not transmembrane [flag]; assembled microfibrils are matrix [PMID:12807887].","caveats":"The affinity applies to alphaVbeta6, not ITGAV with the beta3 partner. All papers abstract only. Entity ITGAV is annotated as integrin alphaV beta3.","key_references":[{"PMID":"17158881","why":"Binding of fibrillin-1 to alphaVbeta6, with Kd."},{"PMID":"12807887","why":"Cell adhesion via alpha5beta1 and alphaVbeta3."},{"PMID":"20686071","why":"Endothelial signaling by fibrillin-1 fragment."}],"covers":["LR000559","LR004050"]},"LR008191":{"pair":"FBN1 -> ITGAV:ITGB3","headline":"Fibrillin-1 signals through integrin alphaVbeta3 in endothelial cells; database records also support the complex.","interaction_type":"functional only","direction_and_effect":"Fibrillin-1 fragment PF14 acted in HUVECs via alpha v beta 3 and alpha 5 beta 1 integrins, with calcium rise, proliferation and migration [PMID:20686071]. Reactome describes interaction of integrin alphaVbeta3 with fibrillin [DB:Reactome]. UniProt says ITGAV:ITGB3 acts as a fibrillin-1 receptor mediating RGD-dependent adhesion [DB:UniProt].","molecular_requirements":"Complex of ITGAV and ITGB3 [flag]; alpha 5 beta 1 was also implicated, so alphaVbeta3 may not be the only receptor [PMID:20686071].","affinity_potency":[],"species_and_systems":"Human umbilical venous endothelial cells, with bovine aortic endothelial cells as confirmation [PMID:20686071].","localisation_and_range":"FBN1 is flagged secreted, not transmembrane [flag]; extracellular microfibrils [PMID:20686071].","caveats":"One paper, abstract only, using inhibition rather than direct binding; database records are additional support. No affinity reported in our evidence.","key_references":[{"PMID":"20686071","why":"Fibrillin-1 fragment signals via alphaVbeta3."}],"covers":["LR008191"]},"LR008218":{"pair":"FCER2 -> CD47:ITGAV:ITGB3","headline":"Soluble CD23 appears to use the alphaV beta3/CD47 vitronectin receptor complex; binding data point to alphaV rather than CD47 or beta3.","interaction_type":"functional only","direction_and_effect":"Anti-CD47 and anti-beta3 mAbs and vitronectin (not fibronectin) inhibited sCD23-induced TNF-alpha, IL-12 and IFN-gamma release, suggesting the VnR/CD47 complex is a functional sCD23 receptor [PMID:10037797]. Binding appears to be mediated by alphaV: sCD23 bound purified alphav protein and a single human alphav chain CHO transfectant [PMID:10037797].","molecular_requirements":"Anti-CD47 and anti-beta3 mAbs did not block sCD23 binding to alphav+beta3+ T cell lines, whereas vitronectin and an anti-alphav mAb (AMF7) did. sCD23 directly bound alphav+beta3+/CD47(-) cell lines, but CD47 co-expression increased binding [PMID:10037797]. So CD47 is enhancing, not required, for binding; whether beta3 is needed is not established in our evidence.","affinity_potency":[],"species_and_systems":"Human monocytes, T cell lines and CHO transfectants; sCD23 used (human).","localisation_and_range":"CD23 is flagged secreted and transmembrane [flag]; the soluble form is the one tested [PMID:10037797].","caveats":"One paper (full text), cell-based. Inhibition by antibodies and ligands, not purified three-chain binding. The complex is a CD47/integrin association, so scoring by least-expressed subunit may be too strict for CD47.","key_references":[{"PMID":"10037797","why":"sCD23 function and binding via VnR/CD47 complex, alphav chain"}],"covers":["LR008218"]},"LR000568":{"pair":"FGA -> ITGAX","headline":"Fibrinogen Aalpha N-terminus and alphaEC domain engage alphaX-beta2 (CD11c/CD18); adhesion evidence, two abstract-level papers.","interaction_type":"functional only","direction_and_effect":"TNF-stimulated neutrophils adhered to fibrinogen via CD11c/CD18, blocked by anti-CD11c but not anti-CD11b antibodies [PMID:1671533]. Recombinant alphaEC supported adhesion of alphaXbeta2 cells [PMID:11588042].","molecular_requirements":"alphaX-beta2 heterodimer. The Aalpha N-terminal region (Gly-Pro-Arg, amino acids 17-19) and fragment E were implicated [PMID:1671533]; alphaX I domain binds alphaEC [PMID:11588042].","affinity_potency":[],"species_and_systems":"Human neutrophils [PMID:1671533, species not recorded in fields]; U937, THP-1 and transfectants [PMID:11588042].","localisation_and_range":"FGA flagged secreted; ITGAX not secreted [flag].","caveats":"Both abstract only; cell-adhesion assays, not purified binding. A third paper was abstract_insufficient.","key_references":[{"PMID":"1671533","why":"CD11c/CD18 recognises Aalpha N-terminal domain"},{"PMID":"11588042","why":"alphaEC binds alphaX and alphaM"}],"covers":["LR000568"]},"LR005167":{"pair":"FGB -> TLR4","headline":"Functional and database support for fibrinogen as an endogenous TLR4 ligand; no direct binding measurement in our evidence.","interaction_type":"functional only","direction_and_effect":"Fibrinogen exposure increased inflammatory cytokine production by monocytes from pre-eclamptic patients, not normotensive pregnant controls; the authors suggest a fibrinogen-TLR4 axis [PMID:24661950]. Reactome records that cleaved fibrinogen products bind TLR4:LY96 [DB:Reactome R-HSA-8870678].","molecular_requirements":"Reactome describes the receptor as the TLR4:LY96 complex and the ligand as cleaved fibrinogen products, so LY96 and the processed form may matter [DB:Reactome R-HSA-8870678].","affinity_potency":[],"species_and_systems":"Human monocytes from pre-eclamptic and normotensive pregnant patients [PMID:24661950]. Mouse record is ortholog-inferred.","localisation_and_range":"FGB is flagged secreted [flag]; plasma fibrinogen levels were higher in pre-eclamptic patients [PMID:24661950].","caveats":"Abstract only; the abstract does not show TLR4 dependence directly (no blocking result reported), and the effect was absent in normotensive monocytes [PMID:24661950]. A review-only paper was also judged. Fibrinogen here is the whole protein, not FGB specifically.","key_references":[{"PMID":"24661950","why":"Fibrinogen activates monocytes from pre-eclamptic patients, framed as TLR4 axis"}],"covers":["LR001812","LR005167"]},"LR004078":{"pair":"FGF1 -> FGFR1","headline":"Well-supported direct FGF1-FGFR1 binding, with structures, SPR and cell assays; FGF1 activates it, heparan sulfate required in some assays.","interaction_type":"direct binding","direction_and_effect":"FGF1 binds FGFR1 and activates it; in a study of FGFR1 and FGFR4, FGFR1 binds FGF-1 and FGF-2 equally [PMID:10336501]. FGF1 binds FGFR1 directly based on receptor presence and without KLB [PMID:22442730]. UniProt records FGF1 inducing FGFR1 phosphorylation [DB:UniProt]. A kinase-deficient FGFR1 variant binds FGF1 yet gives no autophosphorylation, proposed as a regulatory decoy [PMID:8756477].","molecular_requirements":"Heparan sulfate is a required co-factor for the binding specificity [PMID:10336501]; ternary FGF1-FGFR1c-perlecan heparan sulfate complexes form [PMID:24509440]. KLB is not needed [PMID:22442730]. FGFR1 variant lacking the kinase domain is inactive [PMID:8756477].","affinity_potency":[],"species_and_systems":"Human FGF1 and FGFR1 in recombinant, 293 cell and perlecan systems [PMID:22442730][PMID:24509440]; BaF3 mitogenic assays with species unspecified [PMID:16597617][PMID:8663044]. Human and mouse records both exist.","localisation_and_range":"FGF1 is flagged secreted and FGFR1 a transmembrane receptor [flag]; paracrine ligand, membrane receptor.","caveats":"A phage-display peptide study is indirect [PMID:11032250]. BaF3 papers were browser-read with quotes pending spot-check [PMID:16597617]. Many papers are abstract only. Structures and binding assays exist in databases [DB:PDB 1EVT][DB:PDB 3OJV][DB:BioGRID][DB:IntAct]. Affinity values not shown in our evidence.","key_references":[{"PMID":"22442730","why":"FGF1 binds FGFR1 directly, KLB-independent"},{"PMID":"10336501","why":"FGFR1 binds FGF-1 and FGF-2 equally; heparan sulfate needed"},{"PMID":"24509440","why":"Ternary FGF1-FGFR1c-perlecan complexes in full text"}],"covers":["LR000594","LR004078"]},"LR000595":{"pair":"FGF1 -> FGFR2","headline":"Well-supported direct FGF1-FGFR2 binding shown by crystal structures and functional assays in human proteins.","interaction_type":"direct binding","direction_and_effect":"Crystal structures show a complex of human FGF1 with a two-domain extracellular fragment of human FGFR2, and a dimeric FGFR2 ectodomain induced by FGF1 plus a heparin decasaccharide [PMID:10618369][PMID:11069186]. FGF1 is stated to activate all FGFRs in BaF3 assays [PMID:16597617], and full-length FGF1 stimulated FGFR2 phosphorylation more than truncated FGF1 [PMID:14732692].","molecular_requirements":"Structure is a 1:1 FGF1:FGFR2 complex arranged as a dimer [PMID:10618369]; heparin bridges two FGF1 and two receptor chains in the ternary assembly [PMID:11069186].","affinity_potency":[],"species_and_systems":"Human FGF1 and human FGFR2 fragments (crystallography) [PMID:10618369]; FGFR2 phosphorylation in RCS cells [PMID:14732692]. Mouse record is ortholog-inferred.","localisation_and_range":"FGF1 secreted and FGFR2 transmembrane receptor [flag].","caveats":"Two papers were browser-read with quotes pending spot-check [PMID:16597617][PMID:14732692]. No affinity values in our evidence. Two review-only papers were also judged. Database records include PDB [DB:PDB 1DJS], BioGRID, IntAct and Reactome [DB:Reactome R-HSA-8853189].","key_references":[{"PMID":"10618369","why":"Crystal structure of human FGF1 with FGFR2 fragment"},{"PMID":"11069186","why":"FGF1-FGFR2-heparin ternary structure"},{"PMID":"14732692","why":"FGF1 forms and FGFR2 phosphorylation"}],"covers":["LR000595","LR004079"]},"LR000577":{"pair":"FGF16 -> FGFR2","headline":"FGF16 activates FGFR2c in BaF3 cells, and genetic data suggest FGFR1/FGFR2 act redundantly for FGF signals in the heart.","interaction_type":"functional only","direction_and_effect":"FGF9, FGF16 and FGF20 activated FGFRc isoforms with high activity [PMID:16597617]. In mouse heart, endocardial and epicardial FGF signals are received by FGFR1 and FGFR2 acting redundantly in cardiomyoblasts [PMID:15621532]. Agonist.","molecular_requirements":"c-isoform specific in BaF3 [PMID:16597617]. In vivo, FGFR1 and FGFR2 are redundant [PMID:15621532].","affinity_potency":[],"species_and_systems":"BaF3 mitogenic panel [PMID:16597617]; species of FGFR constructs not reported. Mouse pair projected from human. The mouse knockout study used Fgf9/Fgf16/Fgf20 knockouts and heart organ culture [PMID:15621532].","localisation_and_range":"FGF16 flagged secreted [flag]; paracrine signalling from endo/epicardium to myocardium [PMID:15621532].","caveats":"The heart paper is genetic and acts on FGF9, FGF16 and FGF20 jointly, so FGF16-FGFR2 specificity is inferred, not measured; abstract-only [PMID:15621532]. Panel paper is functional only [PMID:16597617].","key_references":[{"PMID":"16597617","why":"BaF3 panel, FGFRc activation"},{"PMID":"15621532","why":"FGF9/16/20 signal via redundant FGFR1/2 in mouse heart"}],"covers":["LR000577","LR004061"]},"LR004069":{"pair":"FGF18 -> FGFR2","headline":"FGF18 activates FGFR2c in a BaF3 mitogenic panel; one functional paper.","interaction_type":"functional only","direction_and_effect":"FGF8, FGF17 and FGF18 specifically activated FGFR1c, 2c, 3c and the two Ig-like domain form of FGFR4 [PMID:16597617]. Agonist.","molecular_requirements":"c isoform [PMID:16597617].","affinity_potency":[],"species_and_systems":"BaF3 mitogenic panel [PMID:16597617]; species of FGFR constructs not reported. Mouse pair projected from human.","localisation_and_range":"FGF18 flagged secreted [flag].","caveats":"Mitogenic activity in BaF3 cells, not binding; browser-read full text, quote unverified; one abstract-insufficient paper not shown [PMID:16597617].","key_references":[{"PMID":"16597617","why":"BaF3 panel"}],"covers":["LR000585","LR004069"]},"LR000586":{"pair":"FGF18 -> FGFR3","headline":"FGF18 signals through FGFR3 to promote chondrogenesis, supported by mouse genetics and a BaF3 panel.","interaction_type":"functional only","direction_and_effect":"FGF18 was a selective ligand for FGFR3 in limb bud mesenchymal cells, where it suppressed proliferation and promoted differentiation and cartilage matrix production [PMID:15781473]. FGF18 also activated FGFR3c in BaF3 cells [PMID:16597617]. Agonist.","molecular_requirements":"c isoform of FGFR3 in BaF3 [PMID:16597617]; FGFR3-/- cultures had impaired response to FGF18 and altered FGFR1/FGFR2 expression [PMID:15781473].","affinity_potency":[],"species_and_systems":"Mouse limb bud mesenchymal cultures from FGFR3-/- vs +/+ [PMID:15781473]; BaF3 panel [PMID:16597617]. Human and mouse pairs listed, neither projected.","localisation_and_range":"FGF18 flagged secreted; paracrine action is inferred [flag].","caveats":"Evidence is genetic and functional, with no direct binding measurement in the dossier. FGF18 suppresses proliferation here, an unusual FGF effect. Abstract-only for the chondrogenesis paper [PMID:15781473].","key_references":[{"PMID":"15781473","why":"FGF18-FGFR3 in limb bud chondrogenesis"},{"PMID":"16597617","why":"BaF3 FGFR3c activation"}],"covers":["LR000586","LR004070"]},"LR002629":{"pair":"FGF2 -> CSPG4","headline":"NG2/CSPG4 binds FGF2 directly via its core protein and acts as an FGF co-receptor; one primary paper.","interaction_type":"direct binding","direction_and_effect":"FGF-2 bound NG2 in a glycosaminoglycan-independent, core-protein-mediated manner, and the proteoglycan alone retained FGF-2 on the cell membrane for receptor presentation [PMID:23124902]. NG2 loss reduced FGF-driven pericyte proliferation and corneal angiogenesis in mice, and decreased FGFR phosphorylation in human smooth-muscle-like cells [PMID:23124902].","molecular_requirements":"The NG2 ectodomain suffices; the cytoplasmic domain contributes little. NG2 also associated with FGFR1 and FGFR3 independent of ligand [PMID:23124902]. Effect is co-receptor, not a stand-alone receptor.","affinity_potency":[],"species_and_systems":"Recombinant protein binding, live cells, NG2-null mouse cells and corneas, and siRNA-treated human smooth-muscle-like cells [PMID:23124902]. BioGRID lists reconstituted complex, FRET and affinity capture [DB:BioGRID].","localisation_and_range":"Both annotated secreted and transmembrane-capable [flag]; NG2 is membrane-bound, so action is on or near the cell surface.","caveats":"One paper; no affinity value. The VEGF response was unaffected, so effects are FGF specific [PMID:23124902].","key_references":[{"PMID":"23124902","why":"FGF-2 binds NG2 core protein; NG2 required for FGF responses"}],"covers":["LR002629","LR005895"]},"LR004096":{"pair":"FGF2 -> FGFRL1","headline":"FGF2 binds FGFR5/FGFRL1 extracellular domains in one abstract-only study; likely a decoy receptor.","interaction_type":"direct binding","direction_and_effect":"Recombinant FGFR5 beta-Fc and gamma-Fc bound FGF-2 specifically, but not FGF-7 or EGF [PMID:11418238]. Affinity was lower than for FGFR2C [PMID:11418238].","molecular_requirements":"Only the extracellular domains were tested, both splice variants (three or fewer Ig domains) [PMID:11418238]. FGFRL1 lacks an intracellular tyrosine kinase domain per the curator note, so it cannot signal conventionally [PMID:11418238].","affinity_potency":[],"species_and_systems":"Recombinant Fc fusions; the abstract describes a murine FGFR5, though the dossier labels experiment species as human [PMID:11418238]. Human and mouse pairs are both ortholog-inferred.","localisation_and_range":"Not reported in our evidence.","caveats":"Single abstract-only paper; no affinity value and no signalling readout, so effect (decoy or regulator) is inferred, not shown. Species labelling may be wrong.","key_references":[{"PMID":"11418238","why":"Recombinant FGFR5-Fc binds FGF-2 specifically"}],"covers":["LR000612","LR004096"]},"LR001819":{"pair":"FGF22 -> FGFRL1","headline":"FGFRL1 binds FGF22 with high affinity but lacks a kinase domain and acts as a decoy that antagonizes FGF signaling.","interaction_type":"direct binding","direction_and_effect":"Soluble FGFRL1 ectodomain and the membrane-bound receptor bind FGF22 among other FGFs with high affinity, by ligand dot blot, cell-based binding and surface plasmon resonance [PMID:19920134]. FGFRL1 is proposed as a decoy receptor and antagonizes FGFR signaling in Xenopus embryos [PMID:19920134].","molecular_requirements":"The intracellular domain lacks the split tyrosine kinase domain needed for signal transduction [PMID:19920134]. The ectodomain is shed from C2C12 myoblasts and HEK293 cells [PMID:19920134].","affinity_potency":[],"species_and_systems":"Human reagents per curators; C2C12 and HEK293 cells and Xenopus embryos [PMID:19920134].","localisation_and_range":"Both shed soluble and membrane-bound forms bind FGF22, so action can be at the cell surface or at a distance [PMID:19920134].","caveats":"Abstract-only reading; no numeric affinity given for FGF22 specifically. Antagonism was shown for FGFR signaling generally, not FGF22 specifically [PMID:19920134]. Mouse pair is projected from human.","key_references":[{"PMID":"19920134","why":"Shed and membrane FGFRL1 bind FGF22; decoy function"}],"covers":["LR001819","LR005174"]},"LR004087":{"pair":"FGF23 -> FGFR1","headline":"FGF23 binds and activates FGFR1c; supported by SPR, mitogenesis, pull-downs and structures, with Klotho in the complex.","interaction_type":"direct binding","direction_and_effect":"FGF23 binds and activates the c splice isoforms of FGFR1-3 and FGFR4, but not the b isoforms [PMID:16081635, PMID:16597617]. Curated effect is stimulatory [PMID:16081635].","molecular_requirements":"c isoform only; highly sulfated, longer glycosaminoglycans promoted activity [PMID:16081635]. Reactome and PDB describe a complex of FGF23, Klotho and FGFR1c [DB:Reactome R-HSA-190218, DB:PDB 5W21].","affinity_potency":[],"species_and_systems":"Human reagents per curators (SPR and mitogenesis) with opossum kidney cells for signaling [PMID:16081635]; BaF3 screen with unspecified species [PMID:16597617]. Mouse pair is ortholog-inferred.","localisation_and_range":"FGF23 flagged secreted [flag]; the paper proposes it circulates to the kidney [PMID:16081635].","caveats":"The 2005 paper names FGFR1-3 collectively, not FGFR1 alone, and was read as an abstract only [PMID:16081635]. BioGRID and IntAct records add support [DB:BioGRID, DB:IntAct].","key_references":[{"PMID":"16081635","why":"SPR and mitogenesis of FGF23 on FGFR c isoforms"},{"PMID":"16597617","why":"BaF3 receptor-specificity screen"}],"covers":["LR000603","LR004087"]},"LR005176":{"pair":"FGF3 -> FGFRL1","headline":"FGFRL1 binds FGF3 with high affinity but lacks a kinase domain; proposed decoy receptor.","interaction_type":"direct binding","direction_and_effect":"Soluble and membrane-bound FGFRL1 bind FGF3 among other FGFs with high affinity by dot blot, cell binding and SPR [PMID:19920134]. FGFRL1 is proposed as a decoy and antagonizes FGFR signaling in Xenopus embryos [PMID:19920134].","molecular_requirements":"No split tyrosine kinase domain; ectodomain shed from cells [PMID:19920134].","affinity_potency":[],"species_and_systems":"C2C12, HEK293 cells and Xenopus embryos; human per curators [PMID:19920134].","localisation_and_range":"Both shed and membrane-bound forms bind [PMID:19920134].","caveats":"Abstract-only reading; no FGF3-specific affinity number. Antagonism is shown for FGFR signaling generally. Mouse pair is projected.","key_references":[{"PMID":"19920134","why":"FGFRL1 binds FGF3 and acts as decoy"}],"covers":["LR001821","LR005176"]},"LR002638":{"pair":"FGFR1 -> NRP1","headline":"FGFR1 interacts with NRP1 in a single biosensor study; receptor-receptor, not a classic ligand pair.","interaction_type":"direct binding","direction_and_effect":"FGF receptor 1 was among proteins able to interact with NRP1 immobilised on a sensor surface [PMID:15695515]. Direction and effect are not reported.","molecular_requirements":"Interactions were heparin-inhibited and ionic-strength dependent [PMID:15695515].","affinity_potency":[],"species_and_systems":"Optical biosensor with recombinant proteins; species not stated in the abstract [PMID:15695515]. Both species projected by ortholog inference.","localisation_and_range":"Both FGFR1 and NRP1 are flagged transmembrane [flag]; FGFR1 is flagged not secreted [flag].","caveats":"Abstract-only read for this row; one paper. Pair is membrane receptor to membrane receptor, so function is unclear. Heparin-binding sites may explain the interaction.","key_references":[{"PMID":"15695515","why":"Biosensor interaction of FGFR1 with NRP1"}],"covers":["LR002638","LR005904"]},"LR005905":{"pair":"FGG -> ITGAM","headline":"Eosinophil adhesion to fibrinogen depends on alphaMbeta2; one functional paper only.","interaction_type":"functional only","direction_and_effect":"Airway eosinophil adhesion to fibrinogen was alphaMbeta2-mediated and blocked by anti-alphaMbeta2 [PMID:16601240].","molecular_requirements":"The receptor is the alphaMbeta2 (ITGAM:ITGB2) heterodimer; the ligand assayed was whole fibrinogen, not the gamma chain alone [PMID:16601240].","affinity_potency":[],"species_and_systems":"Eosinophils from airway and blood (organism not stated in the dossier abstract) [PMID:16601240]. The mouse pair is ortholog-inferred.","localisation_and_range":"FGG is flagged secreted [flag].","caveats":"One paper, abstract only, adhesion not direct binding. Chain-level assignment to FGG is by this resource's encoding. No database records.","key_references":[{"PMID":"16601240","why":"Eosinophil adhesion to fibrinogen via alphaMbeta2"}],"covers":["LR002639","LR005905"]},"LR005914":{"pair":"FLRT2 -> ADGRL2","headline":"FLRT2 acts on LPHN2 (ADGRL2) in endothelial cells, but evidence is functional and from an abstract-level read.","interaction_type":"functional only","direction_and_effect":"In human endothelial cells, silencing endogenous FLRT2 increased ECM-elicited migration, and recombinant FLRT2 reduced it, with no response when LPHN2 was silenced; FLRT2 loss lowered cAMP and active Rap1 [PMID:34581723]. The paper describes FLRT2-activated LPHN2 inhibiting YAP/TAZ and focal adhesions [PMID:34581723]; the curated row labels it antagonist.","molecular_requirements":"A mouse Lphn2 lacking the olfactomedin domain (dOLF) did not rescue the phenotype, and is described as not binding FLRT2, so the OLF domain is required [PMID:34581723]. Uncleaved FLRT2 may also act in cell-cell contacts [PMID:34581723].","affinity_potency":[],"species_and_systems":"Human endothelial cells (siRNA, recombinant rhFLRT2), mouse Lphn2 constructs, and lphn2a-knockout zebrafish [PMID:34581723]. Pair listed for human and mouse (mouse ortholog-inferred).","localisation_and_range":"FLRT2 is flagged secreted and transmembrane [flag]; the paper describes autocrine/paracrine signalling and a soluble ~75 kD recombinant FLRT2 form [PMID:34581723].","caveats":"No direct binding measurement is shown in the excerpts; the OLF-mutant is said not to bind FLRT2. Curated read depth was abstract only.","key_references":[{"PMID":"34581723","why":"Endothelial FLRT2-LPHN2 signalling via OLF domain; siRNA, recombinant protein, zebrafish."}],"covers":["LR002648","LR005914"]},"LR002656":{"pair":"FLRT3 -> ADGRL1","headline":"FLRT3 binds latrophilin-1 (ADGRL1); supported by pull-down and a splicing study, but ADGRL1 evidence is secondary to ADGRL3.","interaction_type":"direct binding","direction_and_effect":"Ecto-FLRT3-Fc pulled down many LPHN1 and LPHN3 peptides, and ecto-LPHN1-Fc bound all FLRT isoforms in cell binding [PMID:22405201]. Latrophilin-1 binding to FLRT3 is not affected by its N-terminal alternative splicing, unlike teneurin binding [PMID:24273166]. Direction/effect: the curator-assigned effect is agonist [PMID:24273166], but our evidence does not show agonism.","molecular_requirements":"Teneurin and FLRT3 bind latrophilin-1 independently [PMID:24273166]. Subunit requirements otherwise not reported in our evidence.","affinity_potency":[],"species_and_systems":"Rat brain extract, rat/HEK293 cell assays and mass spectrometry [PMID:22405201]; the splicing paper was read as abstract only [PMID:24273166]. Dossier lists human and mouse interactions.","localisation_and_range":"FLRT3 is annotated secreted and transmembrane, ADGRL1 transmembrane [flag]; the high-affinity interaction was shown in trans [PMID:22405201].","caveats":"The 2014 paper cites FLRT3-LPHN1 as an established ligand rather than testing it as its main result [PMID:24273166]. Two further judged papers were abstract-insufficient. No affinity for ADGRL1 reported.","key_references":[{"PMID":"22405201","why":"FLRT family identified as latrophilin ligands; LPHN1 and LPHN3 pulled down by FLRT3"},{"PMID":"24273166","why":"LPHN1-FLRT3 binding unaffected by splicing"}],"covers":["LR002656","LR005922"]},"LR005923":{"pair":"FLRT3 -> ADGRL3","headline":"FLRT3 binds latrophilin-3 (ADGRL3) with high affinity in trans; well supported by binding, structure and function.","interaction_type":"direct binding","direction_and_effect":"FLRT3 and LPHN3 ectodomains interact with high affinity in trans; blocking with soluble LPHN3, or LPHN3 or FLRT3 shRNA, reduced excitatory synapse density in cultured neurons, and FLRT3 shRNA in vivo decreased afferent input strength and dendritic spine number in dentate granule cells [PMID:22405201]. An antibody (LK30) agonist of ADGRL3 broke the ADGRL3-teneurin interaction but not ADGRL3-FLRT3 [PMID:36746957].","molecular_requirements":"FLRT3 and ADGRL3 form a complex that also takes UNC5B or UNC5D [DB:UniProt]. LK30 binds ADGRL3 without displacing FLRT3, forming a trimeric FLRT3/ADGRL3/LK30 complex on SEC [PMID:36746957]. FLRT3 binding is via the Olf domain [PMID:36746957].","affinity_potency":[],"species_and_systems":"Rat brain extract, HEK293 cells, cultured neurons and mass spectrometry [PMID:22405201]; the 2016 structural paper mentions Lphn3 binds FLRT3 as background [PMID:27091502]; HEK293T and purified proteins [PMID:36746957]. Dossier covers human and mouse.","localisation_and_range":"FLRT3 annotated secreted and transmembrane, ADGRL3 transmembrane [flag]; interaction shown in trans between cells [PMID:22405201]. UniProt describes cell-cell adhesion via ADGRL3 on adjacent cells [DB:UniProt].","caveats":"No affinity value in our evidence. The 2016 sentence is a passing statement, not a new test [PMID:27091502]. Four further papers were abstract-insufficient, two review-only, one pending. Database records: PDB 5CMN structure [DB:PDB 5CMN], IntAct x-ray crystallography [DB:IntAct].","key_references":[{"PMID":"22405201","why":"FLRTs identified as latrophilin ligands; high-affinity trans interaction and synapse effects"},{"PMID":"36746957","why":"FLRT3 binding retained when teneurin binding is blocked"},{"PMID":"27091502","why":"Structural context of FLRT/Lphn3 complexes"}],"covers":["LR002657","LR005923"]},"LR000658":{"pair":"FN1 -> ITGA3","headline":"Fibronectin binding to integrin alpha3beta1 is supported by one SPR paper; ITGA3 evidence is for the alpha3beta1 dimer.","interaction_type":"direct binding","direction_and_effect":"Surface plasmon resonance was used to determine binding kinetics of integrin alpha3beta1 to Fn fragments, and binding depended on the ninth type III repeat [PMID:26318455]. BioGRID lists a reconstituted complex between FN1 and ITGA3 [DB:BioGRID].","molecular_requirements":"alpha3beta1 is the tested form; ITGA3 alone is not reported in our evidence. Dependence on the ninth type III repeat is reported in the paper title [PMID:26318455].","affinity_potency":[],"species_and_systems":"Recombinant Fn fragments; the abstract mentions epithelial cell responses; species not stated in our evidence.","localisation_and_range":"FN1 flagged secreted, ITGA3 flagged receptor [flag]; matrix-to-cell contact.","caveats":"Single paper read as an abstract; kinetic values are not in our evidence. 1 paper pending.","key_references":[{"PMID":"26318455","why":"SPR kinetics of alpha3beta1 binding fibronectin fragments"}],"covers":["LR000658","LR004142"]},"LR010684":{"pair":"FN1 -> ITGAV:ITGB8","headline":"No curated paper; only generic alphaV-integrin database records.","interaction_type":"database-asserted only","direction_and_effect":"Direction and effect not reported in our evidence.","molecular_requirements":"Not reported in our evidence for beta8 specifically.","affinity_potency":[],"species_and_systems":"Not reported in our evidence.","localisation_and_range":"FN1 is flagged secreted and as a receptor, not transmembrane [flag]; the dossier gives no range beyond that.","caveats":"Two papers were judged abstract-insufficient. The listed records (BioGRID ITGB3-FN1, PDB 4MMX alphaVbeta3, Reactome alphaIIbbeta3) do not concern ITGB8 [DB:BioGRID][DB:PDB 4MMX][DB:Reactome].","key_references":[],"covers":["LR010684"]},"LR000667":{"pair":"FN1 -> ITGB7","headline":"Fibronectin binds alpha4beta7 (via the CS-1 region) in mouse T lymphoma cells; one abstract-level paper.","interaction_type":"direct binding","direction_and_effect":"Mouse TK-1 cells adhered to intact fibronectin and a CS-1 fragment, blocked by anti-alpha4 antibodies, and alpha4beta7 bound the CS-1 region by affinity chromatography [PMID:1372909]. Adhesion was increased by brief PMA stimulation [PMID:1372909].","molecular_requirements":"The receptor is the alpha4-beta7 heterodimer; beta7 was the only subunit associated with alpha4 in these cells [PMID:1372909]. Cells did not adhere to the RGD-containing fragment [PMID:1372909].","affinity_potency":[],"species_and_systems":"Mouse TK-1 T lymphoma cells; human and mouse rows are ortholog-inferred [PMID:1372909].","localisation_and_range":"Fibronectin flagged secreted [flag]; adhesion of lymphocytes to matrix (contact), from paper text.","caveats":"One paper, read as abstract. No affinity reported. Experiments are in mouse; the human pair is inferred.","key_references":[{"PMID":"1372909","why":"alpha4beta7 binds fibronectin CS-1 in mouse TK-1 cells"}],"covers":["LR000667","LR004151"]},"LR009307":{"pair":"FN1 -> NT5E","headline":"Weak support: a one-sentence background statement that CD73 binds fibronectin.","interaction_type":"functional only","direction_and_effect":"The only paper states that CD73 binds laminin and fibronectin, as background in an immunohistochemical survey of 165 glioblastomas [PMID:10470109].","molecular_requirements":"not reported in our evidence.","affinity_potency":[],"species_and_systems":"Human glioblastoma tissue (IHC) [PMID:10470109].","localisation_and_range":"Fibronectin flagged secreted [flag]; CD73 is described as an ectoenzyme on glial plasma membranes [PMID:10470109].","caveats":"The binding claim is not this paper's own result. Two other papers were judged insufficient or unresolvable. No database record. Abstract only.","key_references":[{"PMID":"10470109","why":"Background statement on CD73 matrix binding"}],"covers":["LR009307"]},"LR002665":{"pair":"FN1 -> SDC4","headline":"Syndecan-4 binds the FNIII13 site of fibronectin; one abstract-level paper in human cells.","interaction_type":"direct binding","direction_and_effect":"FNIII13 was characterised as the syndecan-4 binding site in fibronectin; overexpression of syndecan-4, but not syndecan-1 or -2, reverted the tenascin-C-induced adhesion defect [PMID:11731446].","molecular_requirements":"The HepII/syndecan-4 site in FNIII13; tenascin-C competes by binding FNIII13 [PMID:11731446].","affinity_potency":[],"species_and_systems":"Human glioblastoma and breast carcinoma cells; mouse pair is inferred [PMID:11731446].","localisation_and_range":"Receptor flagged as receptor [flag]; fibronectin secreted [flag]; matrix-contact interaction (inferred).","caveats":"Abstract only; no affinity reported. Mouse row ortholog-inferred. Species of cells stated by dossier as human.","key_references":[{"PMID":"11731446","why":"FNIII13 as syndecan-4 binding site"}],"covers":["LR002665","LR005931"]},"LR010954":{"pair":"FRZB -> WNT3A","headline":"Weak: an association inferred from a transcriptomic network analysis in neonatal mouse ovary.","interaction_type":"functional only","direction_and_effect":"A mouse ovary study stated that FRZB interacts with WNT3A, a suppressor of primordial follicle activation, and may promote activation [PMID:34673933]. Inhibitory effect is only a dataset flag.","molecular_requirements":"not reported in our evidence.","affinity_potency":[],"species_and_systems":"Neonatal mouse ovary; granulosa cell transcriptomics and immunolocalisation [PMID:34673933].","localisation_and_range":"FRZB was seen in oocyte cytoplasm and granulosa cells [PMID:34673933]; entity flags not shown for secretion.","caveats":"The interaction came from pathway-analysis network (IPA) relationships, not a binding assay; abstract plus excerpts; one other row was judged a different entity. No database record.","key_references":[{"PMID":"34673933","why":"Network-based suggestion that FRZB interacts with WNT3A"}],"covers":["LR010954"]},"LR011935":{"pair":"FST -> INHBB","headline":"Database-level: follistatin interacts with INHBB (activin B) per UniProt and a structure.","interaction_type":"database-asserted only","direction_and_effect":"UniProt says INHBB interacts with FST and FSTL3 [DB:UniProt]; Reactome records follistatin binding activin [DB:Reactome R-HSA-2473184]. Inhibitory flag [flag].","molecular_requirements":"PDB 9Z3T contains chains of P19883 (FST) and P09529 (INHBB) [DB:PDB 9Z3T].","affinity_potency":[],"species_and_systems":"not reported in our evidence.","localisation_and_range":"not reported in our evidence.","caveats":"No verified papers (two pending). The Reactome record names activin generically. Affinity not reported.","key_references":[],"covers":["LR011935"]},"LR005932":{"pair":"FSTL1 -> CD14","headline":"FSTL1 interacts with CD14 and activates TLR4-dependent innate responses in human cells.","interaction_type":"direct binding","direction_and_effect":"Recombinant FSTL1 induced IL-6 or IL-8 in a CD14- and TLR4-dependent manner and induced tolerance to a second LPS stimulation; it acts as an endogenous TLR4 agonist [PMID:22265692]. Agonist.","molecular_requirements":"CD14 acts as a co-receptor for TLR4 signalling [PMID:22265692]; TLR4 is required [PMID:22265692].","affinity_potency":[],"species_and_systems":"Human cells with recombinant FSTL1 [PMID:22265692]; mouse pair inferred. IntAct lists SPR and FACS assays [DB:IntAct].","localisation_and_range":"Both entities flagged secreted [flag]; CD14 flagged receptor [flag].","caveats":"The binding itself is described as from a previous study (background); this paper adds functional evidence. Abstract only; no affinity reported in our evidence.","key_references":[{"PMID":"22265692","why":"FSTL1 evokes TLR4 responses via CD14"}],"covers":["LR002666","LR005932"]},"LR001828":{"pair":"FSTL1 -> DIP2A","headline":"DIP2A is identified as an FSTL1 receptor in endothelial cells and cardiac myocytes; co-IP plus knockdown evidence.","interaction_type":"direct binding","direction_and_effect":"DIP2A bound FSTL1 by co-immunoprecipitation; DIP2A siRNA reduced FSTL1 binding to cells, and reduced FSTL1-stimulated survival, migration, network formation and Akt phosphorylation [PMID:20054002]. In cardiac myocytes, DIP2A ablation reduced protection against hypoxia/reoxygenation apoptosis [PMID:20054002]. Agonist.","molecular_requirements":"not reported in our evidence.","affinity_potency":[],"species_and_systems":"Human endothelial cell membrane fraction and cultured cardiac myocytes; both human and mouse pairs are ortholog-inferred [PMID:20054002].","localisation_and_range":"DIP2A is on the endothelial cell surface; FSTL1 is flagged secreted [PMID:20054002, flag].","caveats":"One paper, abstract only; no affinity values. UniProt wording is that DIP2A 'may act' as a receptor [DB:UniProt]. IntAct also lists a competition binding and two-hybrid record [DB:IntAct].","key_references":[{"PMID":"20054002","why":"DIP2A identified as FSTL1 receptor"}],"covers":["LR001828","LR005183"]},"LR000676":{"pair":"GAL -> GALR1","headline":"Galanin is a well-supported agonist of GALR1, with direct binding in human cells and nanomolar-to-picomolar affinity.","interaction_type":"direct binding","direction_and_effect":"Galanin acts as an agonist: the cloned human receptor binds galanin with high affinity and mediates galanin inhibition of adenylate cyclase [PMID:7524088]. GtoPdb lists a full agonist action [DB:GtoPdb].","molecular_requirements":"Mutagenesis implicates His264, His267 (TM-VI), Phe282 (TM-VII) and Glu271 (extracellular loop III) of the receptor in galanin binding [PMID:8617199]. Subunit or co-receptor requirements are not reported in our evidence.","affinity_potency":[{"value":"Kd 0.07 nM","assay":"125I-galanin binding","system":"CHP-212 human neuroblastoma cells, galanin receptors like GALR1","cite":"PMID:9168941"},{"value":"<1 nM","assay":"binding affinity","system":"Bowes cells expressing hGalR1","cite":"PMID:11600206"},{"value":"Kd in the nanomolar range","assay":"radioligand binding","system":"COS cells expressing cloned receptor","cite":"PMID:7524088"}],"species_and_systems":"Binding studies used human receptor in cells (COS, Bowes, HEK-293E, CHP-212); an in vivo rat study supports GalR1 involvement in antiallodynic effects of high-dose galanin [PMID:11481429]. The mouse pair is projected from human evidence.","localisation_and_range":"Galanin is flagged as secreted and GALR1 as a transmembrane receptor [flag]; a secreted peptide acting at a distance is plausible but not directly tested in our evidence.","caveats":"Most papers were read as abstracts only. The rat in vivo assignment to GalR1 is pharmacological and inferential, not a binding measurement [PMID:11481429]. Two-state binding (picomolar high-affinity and nanomolar low-affinity) was reported in HEK-293E cells [PMID:9808667].","key_references":[{"PMID":"7524088","why":"Cloning of human GALR1 with high-affinity galanin binding"},{"PMID":"9168941","why":"Kd 0.07 nM galanin binding in CHP-212 cells"},{"PMID":"9808667","why":"Two-state affinity characterisation of human GALR1"}],"covers":["LR000676","LR004160"]},"LR004159":{"pair":"GALP -> GALR3","headline":"Human GALP binds GALR3 in transfected human cells (IC50 10 nM); a single abstract-level paper plus GtoPdb.","interaction_type":"direct binding","direction_and_effect":"GALP acts as an agonist at GALR3; competition binding in SH-SY5Y cells showed highest affinity of the three subtypes [PMID:15944009]. GtoPdb lists an agonist action [DB:GtoPdb].","molecular_requirements":"Subunit or co-receptor requirements are not reported in our evidence. GALP(3-32) is at least as potent as full-length GALP(1-60) in the same study [PMID:15944009].","affinity_potency":[{"value":"IC50 = 10 nM","assay":"competition ligand binding","system":"human neuroblastoma SH-SY5Y cells transfected with the receptor, human GALP(1-60)","cite":"PMID:15944009"}],"species_and_systems":"Human receptor in transfected human SH-SY5Y cells; the dossier lists the ligand species as porcine for the experiment. The mouse pair is projected from human evidence.","localisation_and_range":"GALP is flagged as secreted and the receptor as a transmembrane receptor [flag].","caveats":"Single paper, abstract only; other papers are pending. GALP shares its N-terminal 13 residues with galanin, so cross-reactivity with galanin receptors is expected, not specific [PMID:15944009].","key_references":[{"PMID":"15944009","why":"Ligand binding of human GALP(1-60) at GalR1, GalR2 and GalR3"}],"covers":["LR000675","LR004159"]},"LR010945":{"pair":"GCG -> GIPR","headline":"Database-asserted only: a single IntAct record; no confirmed paper.","interaction_type":"database-asserted only","direction_and_effect":"Direction and effect are not reported in our evidence.","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Human only; no experimental system described beyond an IntAct circular dichroism record [DB:IntAct].","localisation_and_range":"GCG is flagged secreted [flag]; receptor localisation is not reported in our evidence.","caveats":"No paper was confirmed: four were judged different_entity and three abstract_insufficient. Support is one IntAct record by circular dichroism [DB:IntAct].","key_references":[],"covers":["LR010945"]},"LR004168":{"pair":"GCG -> GLP1R","headline":"Glucagon acts on GLP1R as an agonist per databases, but most confirmed papers test GLP-1 rather than glucagon.","interaction_type":"direct binding","direction_and_effect":"GtoPdb lists glucagon as a full agonist at GLP1R [DB:GtoPdb]. In a GLP-1R/beta-arrestin-2 fusion, apparent affinity increased selectively for glucagon, not GLP-1 itself [PMID:15528268].","molecular_requirements":"Receptor N-terminal fragment binds GLP-1 with lower affinity than wild-type receptor, and the TM1-TM3 region is also needed [PMID:11116211]. Whether glucagon needs the same determinants is not reported in our evidence.","affinity_potency":[{"value":"IC50 5.2 nM","assay":"GLP-1 binding to wild-type GLP-1R (a GLP-1 result, not glucagon)","system":"receptor expressed in cells","cite":"PMID:11116211"}],"species_and_systems":"Human ligand and receptor recorded for most papers; the rat GLP-I receptor in CHO cells was used in PMID:7937318. The mouse pair is projected from human evidence.","localisation_and_range":"GCG is flagged secreted and GLP1R transmembrane [flag].","caveats":"Only PMID:15528268 involves glucagon, in a fusion-construct system that may not reflect native receptor. That paper's curated 9.2 pKi has no stated ligand and GtoPdb lists pKi 6.9-7.0, so it is not used. PMIDs 11116211 and 8404634 test GLP-1, and PMID:7937318 reports oxyntomodulin as a weak agonist. All abstract-only. Structures exist [DB:PDB 3IOL].","key_references":[{"PMID":"15528268","why":"Glucagon affinity at GLP-1R/beta-arrestin-2 fusion"},{"PMID":"7937318","why":"Rat GLP-1R pharmacology including oxyntomodulin"},{"PMID":"8404634","why":"Cloning of human GLP-1 receptor; ligand is GLP-1"}],"covers":["LR000684","LR004168"]},"LR000685":{"pair":"GCG -> GLP2R","headline":"The proglucagon product GLP-2 is a high-affinity GLP2R agonist; evidence concerns GLP-2, not glucagon itself.","interaction_type":"direct binding","direction_and_effect":"GLP-2 raised cAMP in GLP-2R-expressing cells, but GLP-1 and related peptides did not [PMID:9990065]. GLP-2(3-33) bound with 7.5% of the affinity of GLP-2(1-33) and was a weak partial agonist that shifted the GLP-2(1-33) dose-response to the right [PMID:11738243]. GtoPdb lists a full agonist [DB:GtoPdb].","molecular_requirements":"Not reported in our evidence beyond the single receptor.","affinity_potency":[{"value":"Kd 0.57 nM","assay":"saturable radioligand binding","system":"cells expressing GLP-2R","cite":"PMID:9990065"},{"value":"EC50 0.58 nM","assay":"cAMP production","system":"cells expressing GLP-2R","cite":"PMID:9990065"},{"value":"Ki 0.06 nM","assay":"displacement by synthetic rat GLP-2","system":"cells expressing GLP-2R","cite":"PMID:9990065"}],"species_and_systems":"Cloned rat and human GLP-2R [PMID:9990065]; transfected human receptor in vitro and mice in vivo [PMID:11738243]. The mouse pair is projected from human evidence.","localisation_and_range":"GCG is flagged secreted and GLP2R transmembrane [flag]. Reactome lists GLP2R with GCG(146-178) [DB:Reactome].","caveats":"Abstract-only. The ligand is the GLP-2 peptide from proglucagon, not glucagon; glucagon activity at GLP2R is not shown. One paper is pending.","key_references":[{"PMID":"9990065","why":"Cloning of GLP-2R with Kd, EC50 and Ki"},{"PMID":"11738243","why":"GLP-2(3-33) binding and activity at human GLP-2R"}],"covers":["LR000685","LR004169"]},"LR002674":{"pair":"GDF1 -> ACVR2B","headline":"Weak functional evidence only: a GDF3 paper cites GDF1 as using ActRIIB (ACVR2B); GtoPdb asserts agonism.","interaction_type":"functional only","direction_and_effect":"GtoPdb lists GDF1 as an agonist at this receptor [DB:GtoPdb]. The only paper states that GDF3 signalling, 'similar to GDF1', is mediated by ALK4, ActRIIA, ActRIIB and Cripto in Smad-dependent reporter assays [PMID:17936261].","molecular_requirements":"Type I ALK4, type II ActRIIA/ActRIIB and the co-receptor Cripto are named; native GDF1 was incapable of signalling in heterologous cells unless a heterologous prodomain, Furin or Nodal co-expression was used [PMID:17936261].","affinity_potency":[],"species_and_systems":"Mouse is the species with primary evidence; the human pair is ortholog-projected. The abstract does not state the cell species [PMID:17936261].","localisation_and_range":"GDF1 is flagged secreted [flag].","caveats":"Abstract-only. GDF1 receptor usage is background in a paper about GDF3, not its own result [PMID:17936261]. Native GDF1 is poorly processed, so potency is not reported in our evidence.","key_references":[{"PMID":"17936261","why":"GDF3 (and, by reference, GDF1) use ALK4, ActRIIA/B and Cripto"}],"covers":["LR002674","LR005939"]},"LR005941":{"pair":"GDF10 -> ACVR2A","headline":"Functional evidence only: GDF10 (BMP-3b) activity is facilitated by ActRIIA together with ALK-4 in mouse C2C12 cells.","interaction_type":"functional only","direction_and_effect":"BMP-3b directly activated Smad2/3 phosphorylation and PAI-1 expression but not Smad1/5/8, and opposed BMP-2 signalling [PMID:22155034]. GtoPdb lists agonist [DB:GtoPdb].","molecular_requirements":"Activity was facilitated by the combination of ALK-4 and ActRIIA; ActRIIA is paired with a type I chain, and ALK-2/-3/-6 were excluded [PMID:22155034].","affinity_potency":[],"species_and_systems":"Mouse myoblastic C2C12 cells per the abstract [PMID:22155034]; both human and mouse pairs are ortholog-inferred.","localisation_and_range":"GDF10 is flagged secreted and non-transmembrane [flag], so signalling would be paracrine or autocrine; range not studied in our evidence.","caveats":"One abstract-only paper (abstract truncated); inhibition by receptor extracellular-domain constructs, no direct binding or affinity.","key_references":[{"PMID":"22155034","why":"BMP-3b uses ALK-4/ActRIIA to activate Smad2/3"}],"covers":["LR002676","LR005941"]},"LR005185":{"pair":"GDF15 -> GFRAL","headline":"Well supported: GDF15 binds GFRAL with high affinity and acts through it to reduce food intake, shown in four papers and structures.","interaction_type":"direct binding","direction_and_effect":"GDF15 binds GFRAL; Gfral deletion abrogates GDF15 effects on food intake and body weight in mice [PMID:28846097][PMID:28846098][PMID:28846099]. Gfral-knockout mice are hyperphagic under stress and resistant to chemotherapy-induced anorexia [PMID:28953886]. GtoPdb lists agonist [DB:GtoPdb].","molecular_requirements":"GFRAL requires the coreceptor RET for intracellular signalling [PMID:28846099]; UniProt describes a 2:2:2 GDF15-GFRAL-RET complex [DB:UniProt].","affinity_potency":[],"species_and_systems":"Mice and nonhuman primates; Gfral expressed in area postrema and nucleus of the solitary tract in mice and humans [PMID:28846097]. PDB 5VZ4 and 6Q2J, IntAct entries [DB:PDB 5VZ4][DB:IntAct].","localisation_and_range":"GDF15 is a secreted 25-kDa dimer [PMID:28846097]; GFRAL is brainstem-restricted [PMID:28953886], so endocrine signalling to hindbrain neurons.","caveats":"All four papers read as abstracts. 'High affinity' is stated without a number in our evidence; GtoPdb gives pKd units but no value.","key_references":[{"PMID":"28846097","why":"GDF15 binds GFRAL; weight loss in mice and primates"},{"PMID":"28846098","why":"GFRAL required for GDF15 metabolic effects"},{"PMID":"28846099","why":"GFRAL needs RET to signal"}],"covers":["LR001830","LR005185"]},"LR004177":{"pair":"GDF2 -> ACVRL1","headline":"BMP9 is a high-affinity ligand of the type-I receptor ALK1, supported by crystal structures, binding and functional data.","interaction_type":"direct binding","direction_and_effect":"BMP9 is an agonist for ALK1 [PMID:22718755][PMID:32238803][DB:GtoPdb]. BMP9 activated an ID1-promoter reporter and Smad1/5/8 phosphorylation, abolished by ALK1 silencing or soluble ALK1 ectodomain [PMID:17068149]. Soluble ALK-1 blocked the activity of the BMP-9 pro-region complex [PMID:15851468].","molecular_requirements":"Type-II partners are needed: silencing both BMPRII and ActRIIA abolishes the response, and endoglin overexpression enhances it [PMID:17068149]. BMP-9 also bound endoglin with high affinity [PMID:17311849]. The BMP9:ALK1 ectodomain complex has 2:2 stoichiometry for BMP10 and a similar BMP9 assembly [PMID:32238803]. The pro-region does not interfere with ALK1 binding or signalling [PMID:15851468][PMID:32238803].","affinity_potency":[{"value":"EC50 = 45 +/- 27 pg/mL","assay":"ID1 BMP response element activation","system":"microvascular endothelial cells","cite":"PMID:17068149"}],"species_and_systems":"Human (ligand and receptor) in structural work [PMID:22718755][PMID:32238803]; transfected COS cells, endothelial cells and glioblastoma cells [PMID:17311849]; C2C12 cells [PMID:32238803]. Mouse pair is projected from human evidence.","localisation_and_range":"BMP-9 is flagged as secreted and non-transmembrane, the receptor as transmembrane [flag]; this implies paracrine/endocrine signalling to a cell-surface receptor (from annotation flags only).","caveats":"Several rows are abstract-only [PMID:22718755][PMID:15851468][PMID:17311849]. The 23029472 sentence uses ALK1-Fc only as a positive control in an RGM binding study, and 19956691 shows ALK1 ectodomain inhibition of BMP9 luciferase activity as a side result [PMID:23029472][PMID:19956691]. The affinity values are not given in the dossier.","key_references":[{"PMID":"15851468","why":"BIAcore and soluble ALK-1 blockade identify ALK-1 as a BMP-9 receptor"},{"PMID":"22718755","why":"Ternary BMP9-ALK1-ActRIIB structure"},{"PMID":"17068149","why":"BMP9 activates ALK1 signalling, EC50 = 45 +/- 27 pg/mL"}],"covers":["LR000693","LR004177"]},"LR007228":{"pair":"GDF2 -> ACVRL1:BMPR2","headline":"No curated papers; the ALK1/BMPRII complex rests on database records.","interaction_type":"database-asserted only","direction_and_effect":"GtoPdb lists agonist records for ACVRL1 and BMPR2 [DB:GtoPdb]. UniProt says BMP9 interacts with ACVRL1, BMPR2 and ACVR2B with high affinity in vitro and signals through ACVRL1 but not other Alks [DB:UniProt].","molecular_requirements":"Both ACVRL1 and BMPR2 are listed as members of the receptor complex [flag]; BioGRID records BMPR2-GDF2 reconstituted complexes [DB:BioGRID].","affinity_potency":[],"species_and_systems":"Not reported in our evidence.","localisation_and_range":"BMP-9 is flagged as secreted and non-transmembrane, the receptor as transmembrane [flag]; this implies paracrine/endocrine signalling to a cell-surface receptor (from annotation flags only).","caveats":"No papers were judged (four review_only rows not shown); support is from databases only [DB:BioGRID][DB:GtoPdb][DB:UniProt].","key_references":[{"PMID":"17311849","why":"BioGRID record for BMPR2-GDF2"},{"PMID":"22718755","why":"BioGRID record for BMPR2-GDF2"}],"covers":["LR007228"]},"LR000694":{"pair":"GDF2 -> BMPR2","headline":"BMP9 binds the type-II receptor BMPRII, with measured affinity, and needs it for signalling in endothelial cells.","interaction_type":"direct binding","direction_and_effect":"GtoPdb lists agonist [DB:GtoPdb]. BMPR-II and ACTR-IIA were both required for the response in endothelial cells [PMID:28646109]. The BMP-9 pro-region complex bound strongly to ALK-1 and BMPR-II by BIAcore [PMID:15851468].","molecular_requirements":"Type-II receptor partnered with a type-I receptor: ALK1 predominantly in endothelial cells, ALK2 in myoblasts [PMID:17311849]; ALK2 was the key type-I receptor for monocyte recruitment [PMID:28646109].","affinity_potency":[{"value":"KD 627.6 pm","assay":"SPR binding of BMP9 to BMPRII ECD","system":"recombinant proteins","cite":"PMID:22718755"},{"value":"KD of 21.6 pm","assay":"SPR binding of BMP9 to ActRIIB (comparator)","system":"recombinant proteins","cite":"PMID:22718755"}],"species_and_systems":"Recombinant SPR [PMID:22718755][PMID:15851468]; transfected COS cells [PMID:17311849]; human endothelial cells [PMID:28646109]. Mouse pair projected from human evidence.","localisation_and_range":"BMP-9 is flagged as secreted and non-transmembrane, the receptor as transmembrane [flag]; this implies paracrine/endocrine signalling to a cell-surface receptor (from annotation flags only).","caveats":"BMPRII binding alone is weak in COS cells [PMID:17311849] and about 30-fold weaker than ActRIIB [PMID:22718755]. Two binding sentences are unverified browser reads [PMID:15851468][PMID:22718755]; the 28646109 row is abstract only.","key_references":[{"PMID":"22718755","why":"SPR KD for BMP9-BMPRII versus ActRIIB"},{"PMID":"15851468","why":"BIAcore: pro-region complex binds BMPR-II"},{"PMID":"17311849","why":"Weak BMP-9 binding to BMPR-II in COS cells"}],"covers":["LR000694","LR004178"]},"LR002683":{"pair":"GDF3 -> ACVR1B","headline":"GDF3 signals through ALK4 (ACVR1B) in reporter assays with Cripto and type II receptors; binding itself is not shown.","interaction_type":"functional only","direction_and_effect":"GDF3 signalling can be mediated by ALK4 plus ActRIIA/ActRIIB and the co-receptor Cripto, activating Smad-dependent reporters [PMID:17936261]. Agonist [PMID:17936261][DB:GtoPdb].","molecular_requirements":"Needs type II receptors ActRIIA/ActRIIB and Cripto; native GDF3 precursor is poorly processed in heterologous cells and needs a heterologous prodomain, Furin or Nodal co-expression to signal [PMID:17936261].","affinity_potency":[],"species_and_systems":"Reporter assays in heterologous cells; curators label human ligand and receptor, though the abstract names no cell line [PMID:17936261]. The mouse pair is listed as direct and the human pair as ortholog-inferred.","localisation_and_range":"GDF3 is flagged secreted [flag]; range not reported otherwise in our evidence.","caveats":"Abstract only. No direct binding data. ALK4 effect is inseparable from type II receptors and Cripto.","key_references":[{"PMID":"17936261","why":"GDF3 signals via ALK4, ActRIIA/B and Cripto"}],"covers":["LR002683","LR005948"]},"LR005950":{"pair":"GDF3 -> ACVR2A","headline":"GDF3 signalling involves ActRIIA (with ALK4 and Cripto) in reporter assays; binding is not shown.","interaction_type":"functional only","direction_and_effect":"GDF3 signalling can be mediated by ALK4, type II receptors ActRIIA and ActRIIB, and Cripto, activating Smad-dependent reporters [PMID:17936261]. Agonist [PMID:17936261][DB:GtoPdb].","molecular_requirements":"The paper tests the full set (ALK4, ActRIIA, ActRIIB, Cripto), so the role of this receptor alone is not separated; native GDF3 needs a heterologous prodomain, Furin or Nodal to signal [PMID:17936261].","affinity_potency":[],"species_and_systems":"Heterologous cell reporter assays; curators label human [PMID:17936261]. The human pair is ortholog-inferred and the mouse pair listed as direct.","localisation_and_range":"GDF3 is flagged secreted [flag]; the receptor is flagged transmembrane [flag].","caveats":"Abstract only. No direct binding data; the paper treats the type II receptors as a group.","key_references":[{"PMID":"17936261","why":"GDF3 signals via ALK4, ActRIIA/B and Cripto"}],"covers":["LR002685","LR005950"]},"LR006805":{"pair":"GDF3 -> BMPR1A","headline":"Asserted only by a GtoPdb agonist record; no papers in our evidence.","interaction_type":"database-asserted only","direction_and_effect":"GtoPdb lists GDF3 as an agonist of BMPR1A [DB:GtoPdb].","molecular_requirements":"not reported in our evidence","affinity_potency":[],"species_and_systems":"Not reported in our evidence.","localisation_and_range":"GDF3 is flagged secreted [flag].","caveats":"No papers or other database records; no experimental evidence in our evidence.","key_references":[],"covers":["LR006805"]},"LR009343":{"pair":"GDF5 -> ACVR1","headline":"Only a verified negative: GDF-5 did not bind the other type I receptors, including ACVR1, when expressed alone.","interaction_type":"conflicting","direction_and_effect":"No positive effect reported. GDF-5 bound BMPR-IB but not other type I receptors when expressed alone in COS-1 cells [PMID:8702914].","molecular_requirements":"The abstract's binding with type II receptors present is cut off, so ACVR1 status in that setting is not reported in our evidence [PMID:8702914].","affinity_potency":[],"species_and_systems":"COS-1 transfectants and rat ROB-C26 cells [PMID:8702914].","localisation_and_range":"Not reported in our evidence.","caveats":"Abstract only; ACVR1 is inferred from the phrase 'other type I receptors'. Three other rows were abstract-insufficient. Database records shown concern BMPR1B and not ACVR1 [DB:BioGRID][DB:IntAct].","key_references":[{"PMID":"8702914","why":"Tested GDF-5 binding to type I and II receptors"}],"covers":["LR009343"]},"LR007237":{"pair":"GDF6 -> ACVR2B:BMPR1B","headline":"No paper confirms this combination; only database annotation of the chains, with no direct evidence for the complex.","interaction_type":"database-asserted only","direction_and_effect":"Not reported in any verified paper in our evidence. UniProt says GDF6 seems to positively regulate chondrogenic differentiation through BMPR1A, BMPR1B, BMPR2 and ACVR2A subunits, activating SMAD1-SMAD5-SMAD8 [DB:UniProt]. A BioGRID record concerns GDF6 with BMPR1B only [DB:BioGRID].","molecular_requirements":"Complex requirement is untested: no curator-verified paper covers ACVR2B and BMPR1B together.","affinity_potency":[],"species_and_systems":"Not reported in our evidence.","localisation_and_range":"Ligand is flagged secreted and not transmembrane [flag]; range beyond that is not reported in our evidence.","caveats":"All judged papers (4) were review_only. ACVR2B is not named in the UniProt note.","key_references":[],"covers":["LR007237"]},"LR007246":{"pair":"GDF9 -> BMPR2:TGFBR1","headline":"Functional support in human theca cells that GDF9 signals via a BMPRII-ALK5 receptor pair.","interaction_type":"functional only","direction_and_effect":"GDF9 activated the bone morphogenic protein-activated type II receptor-ALK5-SMAD2/3 pathway, reduced CYP17A1 and androgen production, and increased SMAD2/3 phosphorylation, which an ALK5 inhibitor blocked [PMID:39382269]. GtoPdb lists GDF9 agonist records for both BMPR2 and TGFBR1 individually [DB:GtoPdb].","molecular_requirements":"Both a type II (BMPRII) and a type I (ALK5/TGFBR1) chain are involved; the abstract reports the two receptors bound each other (coimmunoprecipitation) [PMID:39382269]. Whether either chain alone suffices is not reported in our evidence.","affinity_potency":[],"species_and_systems":"Primary cultured human theca cells from IVF patients [PMID:39382269].","localisation_and_range":"GDF9 is flagged as secreted and non-transmembrane [flag], so signalling is paracrine/autocrine; the receptor is flagged transmembrane [flag].","caveats":"Abstract only; the abstract is cut off and direct GDF9 binding to the pair is not shown [PMID:39382269]. Database records are per single chain, not for the complex [DB:BioGRID][DB:GtoPdb].","key_references":[{"PMID":"39382269","why":"Human theca cells: BMPRII-ALK5-SMAD2/3 activation by GDF9"}],"covers":["LR007246"]},"LR004195":{"pair":"GDNF -> GFRA2","headline":"Direct binding and Ret activation shown, but GFRA2 is a secondary GDNF receptor, preferring neurturin.","interaction_type":"direct binding","direction_and_effect":"GDNF can bind GFRalpha-2 and activate Ret in its presence [PMID:9407096]. TrnR2 (GFRA2) mediated GDNF signalling through Ret in vitro [PMID:9182803]. Reactome and BioGRID agree [DB:Reactome][DB:BioGRID].","molecular_requirements":"RET is needed as the signalling component [PMID:9407096][PMID:9182803]. GFRA2 is GPI-linked [PMID:9182803].","affinity_potency":[],"species_and_systems":"Transfected cells (NIH3T3-derived fibroblasts in [PMID:9182803]); curators record human ligand and receptor. Mouse pair is ortholog-inferred.","localisation_and_range":"GDNF is flagged secreted [flag]; GFRA2 is attached to the cell surface via GPI [PMID:9182803].","caveats":"Cells expressing GFRalpha-1 bind GDNF more efficiently than neurturin, and GFRalpha-2 prefers neurturin [PMID:9407096]. TrnR2-Ret fibroblasts are approximately 30-fold more sensitive to NTN than to GDNF [PMID:9182803]. No affinity values are in our evidence.","key_references":[{"PMID":"9407096","why":"GDNF binds GFRalpha-2; GFRalpha-1 is primary"},{"PMID":"9182803","why":"TrnR2-Ret mediates GDNF signalling, NTN-preferring"}],"covers":["LR000711","LR004195"]},"LR008236":{"pair":"GDNF -> GFRA2:RET","headline":"Functional support: the GFRA2-Ret complex mediates GDNF signalling in vitro, but less sensitively than NTN.","interaction_type":"functional only","direction_and_effect":"TrnR2 (GFRA2) with Ret can mediate GDNF signalling in vitro; PI-PLC treatment depleted Ret phosphorylation induced by NTN and GDNF [PMID:9182803].","molecular_requirements":"Both GFRA2 and RET are present in the responsive complex; fibroblasts with Ret alone were the control [PMID:9182803].","affinity_potency":[],"species_and_systems":"Fibroblasts stably expressing Ret and TrnR2; curators record human ligand and receptor [PMID:9182803].","localisation_and_range":"GFRA2 is GPI-linked at the cell surface [PMID:9182803]; GDNF is flagged secreted [flag].","caveats":"Fibroblasts expressing TrnR2 and Ret are approximately 30-fold more sensitive to NTN than to GDNF, so this is a non-preferred route [PMID:9182803]. Single paper; no binding affinity reported. Database records are for GFRA1/GFRA2 chains, not this complex [DB:Reactome].","key_references":[{"PMID":"9182803","why":"TrnR2-Ret complex mediates GDNF and NTN signalling"}],"covers":["LR008236"]},"LR002692":{"pair":"GDNF -> NCAM1","headline":"Direct binding and RET-independent signalling reported by one abstract; needs GFRA1.","interaction_type":"direct binding","direction_and_effect":"GDNF binds p140(NCAM) with high affinity, rapidly activating Fyn and FAK in RET-negative cells; it stimulates Schwann cell migration and axonal growth via NCAM and Fyn independently of RET [PMID:12837245].","molecular_requirements":"Association of NCAM with GFRalpha1 promotes high-affinity GDNF binding to p140(NCAM) and reduces NCAM-mediated adhesion [PMID:12837245].","affinity_potency":[],"species_and_systems":"Curators record human ligand and receptor; Schwann cells and hippocampal and cortical neurons were used; the human and mouse pair rows are ortholog-inferred [PMID:12837245].","localisation_and_range":"NCAM1 is a cell-adhesion molecule, giving a contact-mediated (juxtacrine) route alongside diffusible GDNF per the paper's framing [PMID:12837245]; GDNF is flagged secreted [flag].","caveats":"One paper, abstract only, no affinity value in our evidence. No database record supports the pair.","key_references":[{"PMID":"12837245","why":"NCAM as RET-independent GDNF receptor with GFRalpha1"}],"covers":["LR002692","LR005957"]},"LR010468":{"pair":"GLS:SLC1A1 -> GRIN1:GRIN2B","headline":"Protein-association records only; no paper confirms GLS:SLC1A1 -> GRIN1:GRIN2B as a ligand-receptor pair.","interaction_type":"database-asserted only","direction_and_effect":"Direction and effect not reported in our evidence. BioGRID lists affinity capture-Western records between SLC1A1 and NMDA receptor subunits (GRIN1 and GRIN2 chains) [DB:BioGRID][PMID:17459877].","molecular_requirements":"Only the SLC1A1 member of the ligand complex appears in the BioGRID records; the other ligand subunit (GLS/GLS2) is not covered in our evidence [DB:BioGRID].","affinity_potency":[],"species_and_systems":"Not reported in our evidence.","localisation_and_range":"Not reported in our evidence.","caveats":"No paper confirmed; judged papers were different_entity or abstract_insufficient. The records are transporter-receptor co-capture, not binding of a secreted ligand.","key_references":[],"covers":["LR010468"]},"LR009019":{"pair":"GNAI2 -> CXCR2","headline":"GNAI2-CXCR2 is supported only by database interaction records; no curator-confirmed paper.","interaction_type":"database-asserted only","direction_and_effect":"UniProt says GNAI2 interacts with CXCR1 and CXCR2 [DB:UniProt][PMID:8662698]. Direction and effect as a ligand-receptor pair not reported in our evidence.","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Not reported in our evidence.","localisation_and_range":"Receptor flagged transmembrane where annotated [flag]; otherwise not reported in our evidence.","caveats":"No paper confirmed; judged papers were different_entity, abstract_insufficient, unresolvable or review_only. The records describe protein association, not a ligand activating a receptor.","key_references":[],"covers":["LR009019"]},"LR009118":{"pair":"GNAS -> ADCY7","headline":"Database-asserted only: UniProt says ADCY7 is activated by GNAS (G(s) alpha); no curated paper confirmed it.","interaction_type":"database-asserted only","direction_and_effect":"Stimulatory: UniProt reports that ADCY7 is activated by G(s) G alpha protein (GNAS) [DB:UniProt][PMID:18541530]; the interaction annotation is 'Stimulatory' [flag].","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Species and assay not reported in our evidence; annotated human.","localisation_and_range":"Not reported in our evidence.","caveats":"No paper in our evidence supports this pair; it rests on database records alone. Curated judgements were 'review_only' and 'abstract_insufficient'. ADCY7 is an enzyme effector, not a receptor binding an extracellular ligand.","key_references":[],"covers":["LR009118"]},"LR008506":{"pair":"GNAS -> GLP1R","headline":"Database-asserted only: one BioGRID PCA record; curated papers were reviews or abstract-insufficient.","interaction_type":"database-asserted only","direction_and_effect":"Direction and effect not reported in our evidence [DB:BioGRID].","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"BioGRID lists a protein-fragment complementation (PCA) assay [PMID:26272612]; species not reported in our evidence.","localisation_and_range":"GLP1R is annotated as a transmembrane receptor [flag]; GNAS is intracellular.","caveats":"No paper in our evidence supports this pair; it rests on database records alone. Judged rows: 'review_only' (1) and 'abstract_insufficient' (2).","key_references":[],"covers":["LR008506"]},"LR000739":{"pair":"HCRT -> HCRTR1","headline":"Orexin-A (HCRT) is a well-supported agonist of OX1 (HCRTR1): binding and many functional assays, mostly human receptor in CHO cells.","interaction_type":"direct binding","direction_and_effect":"Orexin-A activates OX1: it raises [Ca2+]i in CHO cells expressing human OX1 [PMID:10498827][PMID:11250867], and the original de-orphanization paper reports that the orexin peptides bind and activate the receptors [PMID:9491897]. Orexin-A is about five-fold higher affinity than orexin-B in whole-cell competition [PMID:14691055]. GtoPdb lists it as a full agonist [DB:GtoPdb].","molecular_requirements":"Single receptor, no co-receptor reported in our evidence. Intact disulfide bonds of orexin-A are required for OX1 activation, and truncated or alanine-substituted analogues lose potency [PMID:11162621][PMID:12606634]. HCRT encodes both orexin-A and orexin-B; this pair concerns orexin-A. Coupling reported to Ca2+ influx, phospholipase C/D and G-protein classes including pertussis-toxin-insensitive ones [PMID:17115071][PMID:18488139][PMID:12702704].","affinity_potency":[{"value":"Ki 318 nM","assay":"whole-cell radioligand competition vs [3H]-SB-674042","system":"human OX1","cite":"PMID:14691055"},{"value":"EC50 0.068 nM","assay":"calcium mobilisation","system":"CHO-K1 cells expressing OX1R","cite":"PMID:11162621"},{"value":"pEC50 8.38","assay":"Ca2+ mobilisation (Fluo-3AM)","system":"CHO cells expressing human OX1","cite":"PMID:11250867"},{"value":"pEC50 8.03","assay":"FLIPR calcium","system":"CHO-OX1","cite":"PMID:10498827"}],"species_and_systems":"Experiments are almost all with recombinant human OX1 in CHO, Neuro-2a/PC12 or HEK cells [PMID:12208495][PMID:12702704]; the 1998 discovery paper localised orexin in rat brain and tested peptides in rats [PMID:9491897]. The mouse pair is ortholog-inferred, not experimentally shown here.","localisation_and_range":"Ligand flagged secreted and receptor transmembrane [flag], consistent with paracrine or neuronal signalling; not otherwise reported in our evidence.","caveats":"The two affinity readings differ widely (Ki 318 nM in one radioligand format versus sub-nanomolar to low-nanomolar EC50 elsewhere); the curators note this is assay-format dependent [PMID:14691055]. All papers were read as abstracts only.","key_references":[{"PMID":"9491897","why":"Original identification of orexin peptides as ligands of the two receptors"},{"PMID":"11162621","why":"Orexin-A EC50 at OX1R and disulfide requirement"},{"PMID":"14691055","why":"Direct competition binding, Ki for orexin-A"}],"covers":["LR000739","LR004221"]},"LR001837":{"pair":"HHLA2 -> TMIGD2","headline":"TMIGD2 reported as one HHLA2 receptor; one paper, mainly about HHLA2 expression in cancers, so binding detail is thin.","interaction_type":"direct binding","direction_and_effect":"TMIGD2 was identified as one of the receptors for HHLA2 using combined bioinformatics and immunologic approaches [PMID:25549724]. Effect on T cells is not clearly established in this paper's excerpts; the curator label was antagonist, and the text mentions T-cell coinhibition [PMID:25549724].","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Human proteins and human tissue samples; the binding experiment is not described in the excerpts [PMID:25549724].","localisation_and_range":"HHLA2 is annotated as not secreted [flag]; it was seen as membranous and cytoplasmic in tumour cells [PMID:25549724].","caveats":"The excerpts concern HHLA2 expression in normal organs and cancers, not the binding experiment.","key_references":[{"PMID":"25549724","why":"Identifies TMIGD2 as an HHLA2 receptor; HHLA2 expression in cancers"}],"covers":["LR001837"]},"LR000748":{"pair":"HLA-A -> LILRB1","headline":"Well supported direct binding: a crystal structure and several binding studies, all in human systems.","interaction_type":"direct binding","direction_and_effect":"LILRB1 (LIR-1/ILT2) is a receptor for HLA class I; ILT2-IgG1 bound HLA-A, -B and -G1 transfectants but not HLA-Cw3 [PMID:9382880]. A crystal structure of LIR-1 D1D2 with HLA-A2 shows contact with the conserved beta2-microglobulin and alpha3 domains [PMID:12897781]. The receptor is called inhibitory in the paper titles [PMID:9382880]; downstream signalling is not reported in our evidence beyond that.","molecular_requirements":"LIR-1 D1D2 domains were sufficient for the HLA-A2 complex in the structure [PMID:12897781]. Binding to a broad set of >90 HLA class I alleles was tested [PMID:21270408].","affinity_potency":[],"species_and_systems":"All experiments in human proteins or human cells (LIR-1-Fc expression cloning, ILT2-IgG1 on transfectants, recombinant structure) [PMID:9285411][PMID:9382880][PMID:12897781].","localisation_and_range":"Both partners are flagged membrane-bound receptors/transmembrane [flag], so signalling is by cell contact (juxtacrine).","caveats":"The binding site is the conserved region, so LILRB1 binds many HLA class I molecules, not HLA-A specifically [PMID:12897781][DB:UniProt]. Two papers were read as abstracts only [PMID:12897781][PMID:21270408]. One further paper was judged abstract-insufficient. UniProt records only a broad HLA-A/B/C/G/F recognition [DB:UniProt].","key_references":[{"PMID":"9382880","why":"ILT2-IgG1 binds HLA-A, -B, -G1 transfectants"},{"PMID":"12897781","why":"3.4-A crystal structure of LIR-1 with HLA-A2"},{"PMID":"9285411","why":"LIR-1-Fc expression cloning of HLA-A2 and HLA-B44"}],"covers":["LR000748"]},"LR002719":{"pair":"HLA-B -> CD8A","headline":"Direct binding of CD8 to HLA class I, including HLA-B, is supported by SPR and tetramer staining; affinity is weak.","interaction_type":"direct binding","direction_and_effect":"CD8 acts as a co-receptor for MHC class I. CD8alphaalpha bound classical MHC molecules including HLA-B*3501 [PMID:10809759]. Peptide-deficient HLA-B*35:01 tetramers preferentially bound CD8 on CD8+ T cells, and staining was blocked by anti-CD8 (clone SK1) [PMID:29741477].","molecular_requirements":"CD8alphaalpha (the homodimer) was the form measured by SPR [PMID:10809759]. Whether other chains are needed is not reported in our evidence.","affinity_potency":[{"value":"Kd 90-220 microm","assay":"surface plasmon resonance with CD8alphaalpha, over HLA-A*0201, -A*1101, -B*3501 and -C*0702","system":"species not reported in our evidence","cite":"PMID:10809759"}],"species_and_systems":"The tetramer work used human donor PBMCs, with B*35:01-positive and -negative donors [PMID:29741477]. Species for the SPR study is not recorded in our evidence [PMID:10809759].","localisation_and_range":"HLA-B is flagged transmembrane; CD8A carries a secreted flag as well as transmembrane [flag]. Interaction is presumably on cell surfaces, but this comes from the flags only.","caveats":"The Kd range is pooled over several alleles, not HLA-B alone. Empty (peptide-deficient) HLA-B conformers bound CD8 more strongly than peptide-filled ones [PMID:29741477]. Both papers were read as abstracts by curators.","key_references":[{"PMID":"10809759","why":"SPR Kd of CD8alphaalpha for classical MHC class I"},{"PMID":"29741477","why":"Peptide-deficient HLA-B*35:01 binds CD8 on T cells"}],"covers":["LR002719"]},"LR008335":{"pair":"HLA-C -> KIR2DS2","headline":"One 2017 paper reports direct recognition of viral peptides presented by HLA-C by activating KIR2DS2.","interaction_type":"direct binding","direction_and_effect":"Activating KIR2DS2 directly recognises conserved flaviviral-derived peptides in the context of HLA-C [PMID:28916719].","molecular_requirements":"Binding depends on the presented viral peptide; peptide-HLA tetramers were used [PMID:28916719].","affinity_potency":[],"species_and_systems":"Human NK cells and peptide-HLA tetramers [PMID:28916719].","localisation_and_range":"HLA-C is annotated transmembrane [flag]; contact-dependent.","caveats":"Single paper, abstract only; no affinity; recognition is of peptide-HLA-C, not HLA-C alone.","key_references":[{"PMID":"28916719","why":"KIR2DS2 recognises viral peptide-HLA-C"}],"covers":["LR008335"]},"LR000757":{"pair":"HLA-C -> KIR2DS4","headline":"Direct but weak, allele- and peptide-restricted binding of HLA-C to activating KIR2DS4, shown with recombinant proteins and human NK cells.","interaction_type":"direct binding","direction_and_effect":"HLA-C ligates the activating receptor KIR2DS4. HLA-C*05:01 carrying a peptide with Trp at position 8 was sufficient to activate primary KIR2DS4+ NK cells and trigger degranulation [PMID:31138701]. Binding is weak and restricted to certain HLA-C allotypes [PMID:15265913][PMID:19858347].","molecular_requirements":"KIR2DS4-Fc bound six HLA-C allotypes (C1: C*1601, C*0102, C*1402; C2: C*0501, C*0202, C*0401) [PMID:19858347]. With HLA-C*05:01, only peptides with Phe, Tyr or Trp at p8 gave binding; of 61 peptides tested, P2-AF, P2-AY and P2-AW conferred binding. HLA-C*08:02 did not bind with P2-AY, so the C2 epitope contributed [PMID:31138701]. Tetramer binding to cells needed KIR2DS4 plus DAP12 [PMID:31138701]. Other chains: not reported in our evidence.","affinity_potency":[{"value":"half-maximal activation 0.07 uM P2-AW; 1 uM P2-AY","assay":"NK cell degranulation vs peptide concentration (a potency, not a Kd)","system":"primary KIR2DS4+ NK cells with 221-C*05:01-ICP47 cells","cite":"PMID:31138701"}],"species_and_systems":"All experiments were human proteins and human cells: KIR2DS4-Fc on HLA-coated beads, HLA tetramers on transfected 293T cells and primary NK cells [PMID:19858347][PMID:31138701].","localisation_and_range":"Both partners are transmembrane per annotation flags [flag]; HLA-C is not flagged secreted, so signalling is by cell contact [flag].","caveats":"The earlier report called the HLA-Cw4 interaction weak and restricted to HLA-Cw4 only [PMID:15265913]. HLA-C binding without NKL cell activation (only HLA-A*1102 activated) [PMID:19858347]. In a bead assay KIR2DS4-Fc bound HLA-C complexes but not non-classical HLA, and gave no SPR binding to HLA-F [PMID:27455421]. [PMID:15265913], [PMID:19858347] and [PMID:9521070] were read as abstracts (the last is a functional cytotoxicity study naming receptor NKAT8).","key_references":[{"PMID":"31138701","why":"HLA-C*05:01 with p8-Trp peptide binds and activates KIR2DS4+ NK cells"},{"PMID":"19858347","why":"KIR2DS4-Fc binds subsets of C1+ and C2+ HLA-C; no NKL activation by HLA-C"},{"PMID":"15265913","why":"Background: weak, HLA-Cw4-restricted recognition"}],"covers":["LR000757"]},"LR002728":{"pair":"HLA-E -> CD8A","headline":"Direct but very weak binding of CD8 alpha-alpha to HLA-E by SPR; far weaker than for classical class I.","interaction_type":"direct binding","direction_and_effect":"CD8alphaalpha binds HLA-E only weakly [PMID:10809759]. CD8 acts as a co-receptor alongside the T-cell receptor [PMID:10809759].","molecular_requirements":"The CD8 alpha-alpha homodimer was tested; variation in affinity localised to the MHC alpha3 domain by mutagenesis [PMID:10809759].","affinity_potency":[{"value":"Kd >= 1 mM (HLA-E); 90-220 uM for classical HLA-A*0201, -A*1101, -B*3501, -C*0702","assay":"surface plasmon resonance","system":"recombinant human proteins","cite":"PMID:10809759"}],"species_and_systems":"Recombinant human proteins [PMID:10809759].","localisation_and_range":"Annotation flags mark both HLA-E and CD8A as secreted and transmembrane [flag]; the paper does not address this.","caveats":"Abstract only. Binding is at the weak limit; the abstract ties the lack of cell adhesion to HLA-A*6801 and B*4801, not HLA-E.","key_references":[{"PMID":"10809759","why":"SPR of CD8alphaalpha with class I MHC, including weak HLA-E"}],"covers":["LR002728"]},"LR000766":{"pair":"HLA-G -> LILRB1","headline":"Well-supported direct human HLA-G to LILRB1 (LIR-1/ILT2) binding with an inhibitory effect; low-micromolar affinity, though most papers were read as abstracts.","interaction_type":"direct binding","direction_and_effect":"HLA-G engages the inhibitory receptor LILRB1 (ILT2/LIR-1) on NK and other leukocytes and suppresses NK function [PMID:12874224][PMID:9933109][PMID:19841038]. A complex structure of LILRB1 with HLA-G1 is reported [PMID:31273318][PMID:31694909]. UniProt describes peptide-bound HLA-G-B2M as a ligand for LILRB1 [DB:UniProt].","molecular_requirements":"Binding depends on the HLA-G form. The beta2-microglobulin-free multimerized HLA-G1 dimer lacked detectable affinity for LILRB1, and LILRB1 keeps tight contacts with beta2m [PMID:31694909]. Cysteines 42 and 147 mediate cell-surface oligomers, and mutating them sharply reduced LIR-1 Ig binding [PMID:12874224]. The disulfide-linked dimer showed higher overall affinity than the monomer through avidity and enhanced LILRB1 signalling in a reporter assay [PMID:16455647]. D1D2 of LILRB1 binds HLA-I; D3D4 acts as a scaffold [PMID:31273318].","affinity_potency":[{"value":"Kd 2-45 microM (range across the MHC class I panel; ILT2 and ILT4 bound HLA-G with 3- to 4-fold higher affinity than classical MHCIs)","assay":"surface plasmon resonance","system":"soluble ILT2 (LILRB1) and MHC class I proteins","cite":"PMID:12853576"}],"species_and_systems":"All curated experiments were human: purified proteins, crystallography, transfectants and NK cells [PMID:12853576][PMID:12874224][PMID:9933109].","localisation_and_range":"HLA-G is flagged both secreted and transmembrane [flag]. Interaction occurs in cis and in trans [PMID:31273318]; the cell-surface evidence indicates contact-dependent signalling [PMID:12874224].","caveats":"Affinity is weak. Eight confirmed papers are mostly abstract-only. PMID:15718280 describes HLA-G structure without a receptor co-structure, and LIR-1 binding there is background. Isoform dependence is reported [PMID:31694909].","key_references":[{"PMID":"12853576","why":"SPR affinity of ILT2/ILT4 for HLA-G among MHC class I"},{"PMID":"31694909","why":"LILRB1/HLA-G1 complex structure and beta2m dependence"},{"PMID":"12874224","why":"HLA-G cysteine-mediated oligomers drive LIR-1 binding and NK inhibition"}],"covers":["LR000766"]},"LR002737":{"pair":"HMGB1 -> LRP1","headline":"Direct binding of HMGB1 to purified LRP1 reported in a chondrocyte ligandome study; abstract-only, no affinity value.","interaction_type":"direct binding","direction_and_effect":"HMGB1 is one of ten ligands whose direct LRP1 binding was confirmed. Affinity correlated with endocytosis rate, and LRP1 mediates endocytosis of these ligands in cartilage [PMID:36028175]. Direction is LRP1 uptake of HMGB1.","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Human chondrocytes, purified LRP1 binding assays, LRP1-deficient fibroblasts and a conditional Lrp1 knockout mouse [PMID:36028175]. The mouse pair is ortholog-inferred.","localisation_and_range":"HMGB1 is flagged secreted [flag]; LRP1 is a cell-surface endocytic receptor [PMID:36028175].","caveats":"Abstract only; HMGB1 is one of ten ligands in a large screen and no HMGB1-specific numbers are available. No database records.","key_references":[{"PMID":"36028175","why":"LRP1 ligandome in chondrocytes; direct HMGB1 binding"}],"covers":["LR002737","LR005985"]},"LR002746":{"pair":"HPX -> LRP1","headline":"LRP1/CD91 is the receptor for hemopexin-heme complexes; direct binding shown by Biacore, with Reactome support.","interaction_type":"direct binding","direction_and_effect":"Ligand-affinity purification identified LRP1/CD91 as the hemopexin-heme receptor; the complex is internalised, hemopexin is degraded in lysosomes and heme delivered, and LRP1-dependent heme-oxygenase-1 mRNA transcription follows in monocytes [PMID:15947085]. Reactome lists the LRP1:Hemopexin:heme complex [DB:Reactome].","molecular_requirements":"The hemopexin-heme complex, not hemopexin alone, gives high receptor affinity (Biacore) [PMID:15947085].","affinity_potency":[],"species_and_systems":"Human hemopexin; LRP1-expressing COS cells and monocytes [PMID:15947085]. The mouse pair is ortholog-inferred.","localisation_and_range":"HPX is flagged as secreted [flag]; plasma and cerebrospinal fluid ligand [PMID:15947085].","caveats":"Abstract-only reading; the affinity value is not given in our evidence. One further row was judged review_only.","key_references":[{"PMID":"15947085","why":"Ligand-affinity purification and Biacore: LRP1 is the hemopexin-heme receptor"}],"covers":["LR002746","LR005994"]},"LR009190":{"pair":"HSP90AA1 -> CFTR","headline":"Database records only; no curator-verified paper supports this pair as a ligand-receptor interaction.","interaction_type":"database-asserted only","direction_and_effect":"Direction and effect are not reported in our evidence.","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"BioGRID lists 5 records, including a reconstituted complex and affinity-capture assays [DB:BioGRID]; IntAct lists a pull-down association [DB:IntAct]. Species of the experiments is not reported in our evidence beyond the human entities.","localisation_and_range":"The ligand carries no secreted flag [flag]; localisation of the interaction is not reported in our evidence.","caveats":"No verified paper; the judged row was different_entity.","key_references":[],"covers":["LR009190"]},"LR000775":{"pair":"HSPA1A -> TLR4","headline":"Human HSPA1A activates neutrophils through TLR4 (with TLR2) in a single functional paper; binding shown only by flow cytometry blockade.","interaction_type":"functional only","direction_and_effect":"Tumour-derived HspA1A engaging TLR2 and TLR4 on neutrophils increased reactive oxygen species production; curators label it an agonist [PMID:22528050]. Blocking TLR2/TLR4 antibodies reduced hrHspA1A binding to neutrophils by flow cytometry, and an IRAK1/4 inhibitor protected neutrophils from the priming effect of hrHspA1A [PMID:22528050].","molecular_requirements":"TLR2 and TLR4 are both implicated; the paper does not separate TLR4 from TLR2 contributions, and co-receptors such as MD-2 are not reported in our evidence [PMID:22528050].","affinity_potency":[],"species_and_systems":"Human ovarian cancer cells, cancer-patient neutrophils and recombinant human HspA1A, in vitro [PMID:22528050].","localisation_and_range":"HSPA1A is flagged secreted [flag]; the paper reports HspA1A both released from and membrane-expressed on cancer cells, so signalling may be paracrine or by contact [PMID:22528050].","caveats":"Single paper. Evidence is antibody blockade and a functional readout, not purified-protein binding or affinity. Companion TLR2 pair is inseparable here.","key_references":[{"PMID":"22528050","why":"Neutrophil activation by cancer-cell HspA1A via TLR2/TLR4; blocking-antibody and recombinant-protein experiments"}],"covers":["LR000775"]},"LR002755":{"pair":"HSPG2 -> CSPG4","headline":"Human melanoma-cell evidence that CSPG4 forms a complex with perlecan via protein-protein interactions; abstract only.","interaction_type":"direct binding","direction_and_effect":"CSPG4 immunopurified from melanoma lines formed a complex with perlecan made by the same cells, and the interaction supported cell adhesion and actin polymerization [PMID:29462330].","molecular_requirements":"Binding was via hydrophobic protein-protein interactions at multiple sites on perlecan, including the C-terminal region [PMID:29462330]. Chondroitin sulphate decoration of CSPG4 differed between cell lines [PMID:29462330].","affinity_potency":[],"species_and_systems":"Human melanoma cell lines MM200 and Me1007, immunopurification and adhesion assays [PMID:29462330]. Mouse pair is ortholog-inferred.","localisation_and_range":"CSPG4 is flagged transmembrane and also secreted [flag]; it is on the cell surface and shed into conditioned medium [PMID:29462330]. Perlecan is a matrix partner, so interaction is contact or matrix-mediated.","caveats":"Abstract only; no affinity. Co-purification does not alone prove direct binding, though the abstract reports mechanistic studies. The curator's 'agonist' label has no signalling evidence behind it in the abstract.","key_references":[{"PMID":"29462330","why":"CSPG4-perlecan complex in melanoma cells; hydrophobic multi-site binding"}],"covers":["LR002755","LR006002"]},"LR008830":{"pair":"ICAM1 -> EGFR","headline":"Only proteomic co-purification records; no curated paper supports ICAM1 acting as a ligand for EGFR.","interaction_type":"database-asserted only","direction_and_effect":"BioGRID lists EGFR-ICAM1 as affinity capture-MS and IntAct as anti-bait coimmunoprecipitation [DB:BioGRID] [DB:IntAct]. Direction and effect are not reported in our evidence.","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Human; cell system not reported in our evidence.","localisation_and_range":"ICAM1 is flagged secreted and the entity is flagged protein [flag]; no paper text.","caveats":"The one judged row was different_entity (the paper concerned another entity). Co-purification does not show direct binding or ligand-receptor signalling.","key_references":[],"covers":["LR008830"]},"LR000784":{"pair":"ICAM1 -> ITGAL","headline":"Well supported direct binding of ICAM-1 to the alphaL (LFA-1) I domain, with structures and affinity data; ITGAL acts in the ITGAL:ITGB2 integrin.","interaction_type":"direct binding","direction_and_effect":"ICAM-1 is the ligand of the integrin alphaLbeta2 [PMID:15728350]. The alphaL I domain locked open bound ICAM-1 with a 9,000-fold affinity increase, reversed by disulfide reduction [PMID:11353828]. Engineered ICAM-1 mutants raised affinity for LFA-1 I domains 19-fold and 22-fold [PMID:16354667]. Effect is adhesive and stimulatory.","molecular_requirements":"The I domain of alphaL is the binding domain; in vivo the receptor is the alphaLbeta2 integrin [PMID:15728350]. The I domain alone was sufficient for full-affinity binding in the locked-open form [PMID:11353828]. Binding depends on integrin activation state and Mg2+ [PMID:11353828].","affinity_potency":[{"value":"9,000-fold increase over wild type","assay":"I domain locked open by disulfide, ICAM-1 binding kinetics","system":"recombinant protein","cite":"PMID:11353828"},{"value":"19-fold and 22-fold","assay":"improved ICAM-1 mutant vs wild type, intermediate- and high-affinity LFA-1 I domains","system":"recombinant human proteins","cite":"PMID:16354667"}],"species_and_systems":"Human recombinant proteins and cells; the structure used the ICAM-3 D1 domain, not ICAM-1 [PMID:15728350]. Mouse pair is ortholog-inferred.","localisation_and_range":"ICAM1 and ITGAL are flagged transmembrane or cell-surface [flag]; contact-dependent. Reactome shows the complex at the plasma membrane [DB:Reactome].","caveats":"All papers were abstract-only. The crystal structure is with ICAM-3, which only supports a shared docking mode [PMID:15728350]. Some affinity data use isolated I domains or mutants. Three other papers were abstract_insufficient.","key_references":[{"PMID":"11353828","why":"I domain affinity for ICAM-1 and sufficiency"},{"PMID":"16354667","why":"ICAM-1 variants with higher LFA-1 affinity"},{"PMID":"15728350","why":"Structure of ICAM-3 with alphaL I domain, ICAM-1/2/3 off-rates"}],"covers":["LR000784","LR004242"]},"LR005194":{"pair":"ICAM1 -> SPN","headline":"ICAM-1 reported as a ligand for CD43 (sialophorin) in a single 1991 abstract-level paper; thin evidence.","interaction_type":"direct binding","direction_and_effect":"ICAM-1 was identified as a ligand for CD43; Daudi cells bound immobilised CD43, and CD43 expression in a murine T-cell hybridoma enhanced antigen-specific response to Daudi cells [PMID:1683685]. Effect direction is not reported in our evidence.","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Human CD43 expressed in a murine HLA-DR-specific T-cell hybridoma, with human Daudi cells and purified immobilised CD43 [PMID:1683685]. Mouse pair is ortholog-inferred.","localisation_and_range":"Both partners are membrane-bound (cell-cell contact) in the experiment [PMID:1683685]; ICAM1 also carries a secreted flag [flag].","caveats":"Abstract only; no affinity. IntAct lists a solid-phase assay for this pair (PMID 35922511) [DB:IntAct], but no detail beyond that.","key_references":[{"PMID":"1683685","why":"Original report of ICAM-1 as a CD43 ligand"}],"covers":["LR001845","LR005194"]},"LR001846":{"pair":"ICAM3 -> CD209","headline":"ICAM-3 binds DC-SIGN in vitro, but the one paper judges the affinity as submicromolar and comparable to nonspecific glycoprotein interactions.","interaction_type":"conflicting","direction_and_effect":"Reconstituted DC-SIGN/DC-SIGNR receptors bound ICAM-3 with submicromolar affinity similar to FcgammaRIIb and FcgammaRIII, and oligomerisation of DC-SIGNR did not raise ICAM-3 binding affinity [PMID:15795245]. UniProt and Reactome record DC-SIGN as an ICAM-3 receptor requiring Ca2+ [DB:UniProt][DB:Reactome].","molecular_requirements":"Receptor oligomer state: the DC-SIGNR oligomerisation gave no increase in ICAM-3 affinity [PMID:15795245]; Ca(2+) is required per UniProt [DB:UniProt].","affinity_potency":[],"species_and_systems":"Human, recombinant reconstituted proteins [PMID:15795245]; UniProt notes a role between dendritic cells and resting T cells [DB:UniProt].","localisation_and_range":"Membrane lectin on dendritic cells binding membrane ICAM-3 on T cells: contact-dependent [DB:UniProt].","caveats":"Abstract only. The paper's conclusion argues against a specific adhesion role for this interaction [PMID:15795245]. IntAct lists a solid-phase assay [DB:IntAct]. No numeric affinity given in our evidence.","key_references":[{"PMID":"15795245","why":"Submicromolar ICAM-3 binding, similar to nonspecific interactions"}],"covers":["LR001846"]},"LR000793":{"pair":"ICAM3 -> ITGAL","headline":"ICAM-3 is an LFA-1 ligand with structural, binding and functional evidence including a crystal structure.","interaction_type":"direct binding","direction_and_effect":"ICAM-3 is a constitutively expressed LFA-1 ligand, with its binding site in the N-terminal two Ig domains and a domain-1 cluster (Glu37, Leu66, Ser68, Gln75) dominant [PMID:7822326]. Purified ICAM-3 supported LFA-1-dependent adhesion and gave a costimulatory signal for resting T cell proliferation [PMID:7905020]. Affinity order was ICAM-1 > ICAM-2 > ICAM-3 [PMID:11353828].","molecular_requirements":"Crystal structure is of ICAM-3 D1 with the alphaL inserted domain [PMID:15728350][DB:PDB 1T0P]; UniProt gives the receptor as ITGAL/ITGB2 [DB:UniProt].","affinity_potency":[],"species_and_systems":"Human proteins and cells [PMID:7822326][PMID:7905020]; crystal structure of ICAM-3 D1 with alphaL I domain [PMID:15728350].","localisation_and_range":"Membrane-bound; contact-dependent adhesion; ICAM-3 is highly expressed by resting leukocytes [PMID:7822326].","caveats":"Most papers abstract-only; full-text excerpts for PMID:7905020 are not informative on the pair. No numeric affinity in our evidence.","key_references":[{"PMID":"15728350","why":"Crystal structure and kinetics of ICAM-3 D1 with alphaL I domain"},{"PMID":"7822326","why":"Mapping of LFA-1 binding site on ICAM-3"},{"PMID":"11353828","why":"Affinity ranking of ICAMs for alphaL I domain"}],"covers":["LR000793"]},"LR004249":{"pair":"ICAM4 -> ITGA2B","headline":"Direct binding of ICAM-4-Fc to activated alphaIIbbeta3 (platelet integrin) in one transfectant study; the human pair is ortholog-inferred.","interaction_type":"direct binding","direction_and_effect":"Activated alphaIIbbeta3 binds recombinant ICAM-4-Fc specifically and dose dependently; curated as stimulatory [PMID:15355350]. UniProt describes ICAM4 as a ligand of ITGA2B:ITGB3 in erythrocyte-activated platelet adhesion [DB:UniProt].","molecular_requirements":"The receptor is the alphaIIb/beta3 heterodimer, and only the activated form bound. The alphaIIbbeta3 contact site is the ABED face of domain D1 with an extension in the C'-E loop of D2 [PMID:15355350].","affinity_potency":[],"species_and_systems":"Human ICAM-4-Fc and integrin cell transfectants [PMID:15355350]. Both listed interactions (human, mouse) are ortholog-inferred.","localisation_and_range":"ICAM4 carries both secreted and transmembrane flags [flag], so range is unclear; the papers used recombinant ICAM-4-Fc and cell-surface ICAM-4, consistent with contact-dependent adhesion. UniProt describes heterotypic erythrocyte-platelet adhesion [DB:UniProt].","caveats":"One paper, abstract only. Affinity not reported in our evidence. No mouse experiments.","key_references":[{"PMID":"15355350","why":"Integrin specificity for ICAM-4; alphaIIbbeta3 binding residues"}],"covers":["LR000795","LR004249"]},"LR004258":{"pair":"ICAM5 -> ITGB2","headline":"beta2 (LFA-1) binding to ICAM-5 is supported by two human studies, a structure record and UniProt.","interaction_type":"direct binding","direction_and_effect":"ICAM-5 domain 1 supports CD11a/CD18 interaction [PMID:10741396]; LFA-1-mediated HL-60 adhesion to recombinant telencephalin, curated as agonist [PMID:8995416]. UniProt names ITGAX:ITGB2 as an ICAM5 receptor ensuring neuron-leukocyte adhesion [DB:UniProt].","molecular_requirements":"Evidence is for beta2 pairs (CD11a/CD18 and, per UniProt, CD11c/CD18) rather than beta2 alone. TLN-LFA-1 binding was divalent-cation- and PMA-independent [PMID:8995416].","affinity_potency":[{"value":"50 nM","assay":"lowest soluble ICAM-5 domain 1 concentration that inhibited T-cell binding to immobilized ICAM-5","system":"human T cells, immobilized ICAM-5","cite":"PMID:10741396"}],"species_and_systems":"Human proteins; human T cells on rat hippocampal neurons [PMID:10741396]; HL-60 cells [PMID:8995416]. Mouse pair ortholog-inferred.","localisation_and_range":"ICAM5 carries a secreted flag only [flag]; the cloning paper reports a transmembrane region [PMID:8995416]; neuron-leukocyte adhesion is described in UniProt [DB:UniProt].","caveats":"Both papers abstract only; two more confirmed rows and one pending row not shown. The 50 nM figure is an inhibition concentration.","key_references":[{"PMID":"10741396","why":"ICAM-5 domain 1 and CD11a/CD18"},{"PMID":"8995416","why":"LFA-1-mediated adhesion to telencephalin"}],"covers":["LR000804","LR004258"]},"LR008443":{"pair":"IFNA13 -> IFNAR1","headline":"Chain-level binding of human alpha-IFNs to IFNAR1, applied to IFNA13 by class statements; thin.","interaction_type":"direct binding","direction_and_effect":"GtoPdb lists IFNA13 as an agonist of IFNAR1 [DB:GtoPdb]; the interaction is stimulatory in the record.","molecular_requirements":"Alpha-IFNs bind isolated IFNAR1 chain; competitive 1:1 binding to ifnar1-EC and ifnar2-EC for all IFNs tested [PMID:17174979].","affinity_potency":[{"value":"0.5-5 \u03bcM","assay":"binding to isolated receptor chain","system":"alpha-IFN subtypes","cite":"PMID:21856167"}],"species_and_systems":"Human recombinant/purified subunits [PMID:21856167] [PMID:17174979].","localisation_and_range":"Not reported in our evidence (no annotation flags for IFNA13).","caveats":"Both papers are abstract only and do not name IFNA13. Mouse pair is ortholog-inferred.","key_references":[{"PMID":"21856167","why":"Class-wide affinities"},{"PMID":"17174979","why":"Receptor subunit affinities for several IFNs"}],"covers":["LR008443","LR004263"]},"LR002764":{"pair":"IFNA2 -> CR2","headline":"IFNA2 binds CR2 (CD21) in vitro by SPR and ELISA; a single abstract-level study supports it.","interaction_type":"direct binding","direction_and_effect":"IFN-alpha, including IFN-alpha2, binds CR2 by surface plasmon resonance and ELISA in the same affinity range as C3d/iC3b, EBV-gp350 and CD23. The anti-CR2 mAb 171 diminished induction of IFN-alpha-responsive genes in purified human B cells, suggesting CR2 contributes to IFN-alpha signalling [PMID:16785534].","molecular_requirements":"IFN-alpha interacts with CR2 short consensus repeat domains 1 and 2, the same region that binds the other three ligands [PMID:16785534].","affinity_potency":[],"species_and_systems":"Human proteins and purified human peripheral blood B cells [PMID:16785534].","localisation_and_range":"Ligand carries a secreted flag [flag]; range otherwise not reported in our evidence.","caveats":"Single paper, read as abstract only. The abstract states the affinity is in the same range as other CR2 ligands but gives no value. IFN-alpha is not resolved to subtype in the abstract beyond 'including IFN-alpha2'. CR2 versus IFNAR contribution is not resolved in our evidence.","key_references":[{"PMID":"16785534","why":"SPR/ELISA binding of IFN-alpha to CR2 SCR1-2 and antibody blockade."}],"covers":["LR002764"]},"LR007273":{"pair":"IFNA2 -> IFNAR1:IFNAR2","headline":"IFNA2 engages the IFNAR1:IFNAR2 receptor; IFNAR2 binding is well shown, IFNAR1 contact rests on structural database records.","interaction_type":"direct binding","direction_and_effect":"IFNA2 binds IFNAR2-EC 1:1 with KD 10 nM, and the soluble ectodomain inhibits IFNalpha2 antiviral activity [PMID:10339405]. NMR maps the binding site on IFNAR2-EC in complex with IFN-alpha2 [PMID:11888273]. GtoPdb lists agonist action at both chains [DB:GtoPdb].","molecular_requirements":"IFNAR2 is the nanomolar-affinity subunit [PMID:11888273]. Papers here characterise only IFNAR2 or an undifferentiated receptor [PMID:10339405, PMID:1834641]; IFNAR1 is not part of the NMR complex [PMID:11888273]. IntAct and PDB records list IFNA2 with IFNAR1 and IFNAR2 by x-ray crystallography [DB:IntAct, PMID:21854986].","affinity_potency":[{"value":"10 nM","assay":"binding of refolded ifnar2 extracellular domain to IFNalpha2 (BIAcore SPR and fluorescence de-quenching)","system":"purified human proteins","cite":"PMID:10339405"}],"species_and_systems":"Human ligand and receptor; purified recombinant domains, NMR in solution, and human cells [PMID:10339405, PMID:11888273, PMID:1834641].","localisation_and_range":"Ligand carries a secreted flag [flag]; range otherwise not reported in our evidence.","caveats":"All papers read as abstracts only; one further row was review only. No verified paper in the dossier measures IFNAR1 and IFNAR2 together as a complex; PMID:1834641 does not resolve chains.","key_references":[{"PMID":"10339405","why":"IFNAR2-EC binds IFNalpha2 1:1 at KD 10 nM."},{"PMID":"11888273","why":"NMR of IFNAR2-EC with IFN-alpha2."},{"PMID":"1834641","why":"Competition binding; chains unresolved."}],"covers":["LR007273"]},"LR011719":{"pair":"IFNA5 -> IFNA2:IFNAR1:IFNAR2","headline":"IFNA5 to the IFNA2:IFNAR1:IFNAR2 entry is supported only by database records; no verified paper.","interaction_type":"database-asserted only","direction_and_effect":"GtoPdb lists IFNA5 as agonist at IFNAR1 and IFNAR2 [DB:GtoPdb]. IntAct records co-immunoprecipitation associations from anti-tag pulldowns [DB:IntAct, PMID:28514442, PMID:33961781]; the partners in those records are not specified in our evidence.","molecular_requirements":"The receptor entry lists IFNA2, IFNAR1 and IFNAR2 together; requirements not reported in our evidence.","affinity_potency":[],"species_and_systems":"Human pair. Species and system of the database experiments are not reported in our evidence.","localisation_and_range":"Ligand carries a secreted flag [flag]; range otherwise not reported in our evidence.","caveats":"No paper row was verified for this complex (pending only). Support rests on database records.","key_references":[],"covers":["LR011719"]},"LR004267":{"pair":"IFNA6 -> IFNAR1","headline":"IFNA6 binds IFNAR1 as a type I interferon agonist; support is a class-wide binding study plus GtoPdb.","interaction_type":"direct binding","direction_and_effect":"IFNA6 acts as an agonist on the type I interferon receptor; the curator-verified study reports binding of human alpha-IFN subtypes to isolated receptor chains [PMID:21856167]. GtoPdb lists this as an agonist interaction with no affinity units [DB:GtoPdb].","molecular_requirements":"IFNAR2 is the tight-binding chain (0.4-5 nM) and IFNAR1 the weak one (0.5-5 \u03bcM) for alpha-IFNs [PMID:21856167]. Whether the pair needs both chains for signalling is not reported in our evidence beyond this binding comparison.","affinity_potency":[{"value":"0.5-5 \u03bcM","assay":"affinity and rate-constant determination, 12 human alpha-IFN subtypes collectively, isolated IFNAR1 chain","system":"human proteins","cite":"PMID:21856167"}],"species_and_systems":"Human ligand and human receptor chains, isolated recombinant chains (abstract-level reading) [PMID:21856167]. The mouse pair is projected from human evidence (ortholog-inferred); no mouse experiment is in our evidence.","localisation_and_range":"Ligand is flagged secreted and not transmembrane [flag], so it acts as a diffusible paracrine or endocrine signal.","caveats":"The affinity range is stated for 'Alpha-IFNs' as a class, not IFNA6 individually; only IFN-alpha1 (220 nM) is singled out as weaker, and the paper was read as an abstract only [PMID:21856167].","key_references":[{"PMID":"21856167","why":"binding of 12 human alpha-IFN subtypes to isolated IFNAR1 and IFNAR2"}],"covers":["LR000823","LR004267"]},"LR000829":{"pair":"IFNB1 -> IFNAR1","headline":"IFNB1 binds IFNAR1 directly, including an IFNAR2-independent mode, with nanomolar affinity; well supported.","interaction_type":"direct binding","direction_and_effect":"IFN-beta is an agonist at IFNAR1 [DB:GtoPdb]. IFN-beta can ligate IFNAR1 independently of IFNAR2, and the IFNAR1-IFN-\u03b2 complex signalled a distinct gene set independent of Jak-STAT [PMID:23872679]. All IFNs tested showed competitive 1:1 binding to ifnar1-EC and ifnar2-EC [PMID:17174979].","molecular_requirements":"IFNAR1 alone is sufficient for ligation per the structural study, though in the canonical receptor it pairs with IFNAR2 [PMID:23872679]. Deleting Pro335 of IFNAR1 reduced affinity for hIFN-\u03b2 [PMID:29311663].","affinity_potency":[{"value":"15.8 \u00b1 3.4 nM","assay":"affinity of hIFN-\u03b2 for wild-type IFNAR1 (n = 3)","system":"human proteins","cite":"PMID:29311663"},{"value":"28.1 \u00b1 3.1 nM","assay":"affinity for IFNAR1 with Pro335 deletion","system":"human proteins","cite":"PMID:29311663"}],"species_and_systems":"Human proteins in binding studies [PMID:17174979][PMID:29311663]; mouse Ifnar1-/- mice were protected from LPS-induced sepsis, Ifnar2-/- mice were not [PMID:23872679]. Both human and mouse pairs are listed, neither ortholog-inferred.","localisation_and_range":"Ligand is flagged secreted and not transmembrane [flag], so it acts as a diffusible paracrine or endocrine signal.","caveats":"One paper (PMID:1834641) is recorded as pair_absent: its abstract concerns IFN-omega competing with labelled IFN-alpha for the receptor, and IFN-beta also blocked binding, so it does not show absence. Two of three binding papers are abstract-level. Affinity values come from the full-text paper only.","key_references":[{"PMID":"23872679","why":"IFN-\u03b2 ligates IFNAR1 independently of IFNAR2; structure"},{"PMID":"29311663","why":"IFN-\u03b2 affinity for wild-type and Pro335-deleted IFNAR1"},{"PMID":"17174979","why":"real-time binding of type I IFNs to ifnar1-EC and ifnar2-EC"}],"covers":["LR000829","LR004269"]},"LR007282":{"pair":"IFNG -> IFNGR1:IFNGR2","headline":"IFN-gamma signals through an IFNGR1:IFNGR2 complex; structural and reconstituted-cell evidence, read from abstracts.","interaction_type":"direct binding","direction_and_effect":"IFN-gamma is an agonist; GtoPdb lists Agonist for IFNG-IFNGR1 and IFNG-IFNGR2 [DB:GtoPdb]. Only cells expressing both chains were responsive: Jak1, Jak2 and Stat1 alpha were activated, and IFNGR1 was phosphorylated, only in cells expressing both IFN-gamma R1 and R2 [PMID:7673114].","molecular_requirements":"Both chains are needed for signalling. IFNGR1 is the binding subunit and IFNGR2 the transmembrane accessory factor necessary for signal transduction; cells with IFNGR1 alone were unresponsive, and a truncated IFNGR2 lacking residues 286-337 failed to signal [PMID:7673114]. An IFN-gamma R2:IFN-gamma cross-linked complex was seen in cells expressing both chains [PMID:7673114]. Ordered assembly: IFN-gamma binds IFNGR1 bivalently (1:2), then two second-chain receptors join to give 1:2:2 [PMID:11250200]. A 3:1 crystal complex was also seen [PMID:10986460].","affinity_potency":[],"species_and_systems":"Human; crystal structures [PMID:10986460, PMID:11250200] and reconstituted cell lines expressing cloned human receptor components [PMID:7673114].","localisation_and_range":"IFNG is flagged secreted and non-transmembrane [flag], so it is expected to act at a distance (paracrine/endocrine); the receptor is flagged transmembrane [flag].","caveats":"All three confirming papers were read as abstracts only. The 10986460 evidence sentence describes the complex generically; the crystal contained IFNGR1 ectodomain only. Reactome, PDB and UniProt records also support the complex [DB:UniProt].","key_references":[{"PMID":"7673114","why":"reconstituted cells show both chains are needed"},{"PMID":"11250200","why":"ordered 1:2:2 assembly"},{"PMID":"10986460","why":"crystal structure of the receptor complex"}],"covers":["LR007282"]},"LR001855":{"pair":"IFNL4 -> IFNLR1","headline":"IFN-lambda4 to IFNLR1: supported only by a database structure record.","interaction_type":"database-asserted only","direction_and_effect":"No effect direction is stated in our evidence. The class is Ligand-Receptor.","molecular_requirements":"A PDB entry 9BPU (electron microscopy) of the IFN-lambda4/IFN-lambdaR1/IL-10Rbeta receptor complex is recorded, so the ternary complex includes IL-10Rbeta [DB:PDB 9BPU].","affinity_potency":[],"species_and_systems":"Not reported in our evidence.","localisation_and_range":"IFNL4 is flagged secreted (transmembrane not annotated) [flag].","caveats":"No papers verified; the one attached row was abstract_insufficient. Support is a database structure record (cited paper PMID:39827213 was not judged).","key_references":[],"covers":["LR001855"]},"LR011728":{"pair":"IFNW1 -> IFNA2:IFNAR1:IFNAR2","headline":"IFN-omega to a complex listing IFNA2, IFNAR1 and IFNAR2: no verified paper, database records only.","interaction_type":"database-asserted only","direction_and_effect":"GtoPdb lists IFNW1-IFNAR1 and IFNW1-IFNAR2 as Agonist [DB:GtoPdb]. All three attached papers are pending.","molecular_requirements":"A human IFN-omega ternary complex structure exists (PDB 3SE4, X-ray diffraction) with IFNAR chains [DB:PDB 3SE4]; IntAct records the same [DB:IntAct]. The complex lists IFNA2 as a member, which is not supported here.","affinity_potency":[],"species_and_systems":"Not reported in our evidence beyond the human structure record.","localisation_and_range":"IFNW1 is flagged secreted and non-transmembrane [flag].","caveats":"No papers were verified for this row; support is from databases.","key_references":[],"covers":["LR011728"]},"LR000838":{"pair":"IFNW1 -> IFNAR1","headline":"IFN-omega binds IFNAR1; binding kinetics and competition data support it.","interaction_type":"direct binding","direction_and_effect":"IFN-omega is an agonist of the type I receptor; GtoPdb lists Agonist [DB:GtoPdb]. Hu-IFN-omega blocked binding of 32P-labeled Hu-IFN-alpha A to human cells, indicating it binds the alpha/beta receptor [PMID:1834641].","molecular_requirements":"Competitive 1:1 interaction with both ifnar1-EC and ifnar2-EC was shown for all IFNs tested including human IFNomega; rate and affinity constants differed over several orders of magnitude across IFNs for both subunits [PMID:17174979].","affinity_potency":[],"species_and_systems":"Human proteins; recombinant ectodomains on solid-supported membranes [PMID:17174979]; human cells [PMID:1834641].","localisation_and_range":"IFNW1 is flagged secreted and non-transmembrane [flag].","caveats":"Both papers read as abstracts only. The 1991 paper refers to an undifferentiated alpha/beta receptor, so assignment to IFNAR1 specifically cannot be verified from it. No numeric constants are in the abstract.","key_references":[{"PMID":"17174979","why":"IFNomega binds ifnar1-EC and ifnar2-EC"},{"PMID":"1834641","why":"IFN-omega competes for the alpha/beta receptor"}],"covers":["LR000838"]},"LR007264":{"pair":"IGF1 -> GPC3:IGF1R","headline":"No paper supports IGF1 acting on the GPC3:IGF1R complex; the one paper judged concerns IGF-II, so support is database-only for the IGF1-IGF1R part.","interaction_type":"database-asserted only","direction_and_effect":"The only judged paper found IGF-II, not IGF1, binding GPC3 and IGF-1R, with GPC3 enhancing IGF-II-dependent IGF-1R phosphorylation [PMID:18413366]. It was marked as a verified negative for this IGF1 pair. GtoPdb lists IGF1 as an agonist of IGF1R [DB:GtoPdb].","molecular_requirements":"The GPC3:IGF1R complex is not supported by any IGF1 evidence in our evidence. In the paper, GPC3 bound IGF-II and IGF-1R, and convertase-processed GPC3 was needed for IGF-II binding [PMID:18413366]. IGF1 binding to IGF1R alone is recorded in structures and interaction databases [DB:PDB 4XSS] [DB:BioGRID] [DB:IntAct].","affinity_potency":[],"species_and_systems":"The paper used GST pull-down and co-immunoprecipitation in HEK293T cells and IGF-II treatment of HEK293 and NIH3T3 cells; species is not stated in the excerpts [PMID:18413366].","localisation_and_range":"IGF1 is flagged as secreted; the complex is flagged transmembrane [flag].","caveats":"Do not treat the GPC3 co-receptor role as shown for IGF1; the evidence concerns IGF2. The paper was read in full text but never mentions IGF1 as a ligand for this complex [PMID:18413366]. Other database records concern IGF1-IGF1R alone.","key_references":[{"PMID":"18413366","why":"Negative: shows the GPC3/IGF1R link is IGF-II dependent, not IGF1"}],"covers":["LR007264"]},"LR002773":{"pair":"IGF2 -> M6PR","headline":"IGF-II binds the cation-independent mannose 6-phosphate receptor with sub-nanomolar Kd in a single radioligand study (abstract only).","interaction_type":"direct binding","direction_and_effect":"IGF-II binds the receptor, which the study concludes is the same protein as the IGF-II receptor; binding was unaffected by mannose 6-phosphate, so the two ligand types use different sites [PMID:2963812]. Downstream effect is not reported in our evidence.","molecular_requirements":"The cation-independent receptor bound 0.95 mol IGF-II per mol receptor; IGF-II did not bind the cation-dependent mannose 6-phosphate receptor [PMID:2963812]. Co-receptors: not reported.","affinity_potency":[{"value":"Kd 0.2 nM","assay":"equilibrium radioligand binding, IGF-II to affinity-purified CI-MPR","system":"purified receptor","cite":"PMID:2963812"},{"value":"Kd 0.4 microM","assay":"IGF-I binding to the same receptor (comparison)","system":"purified receptor","cite":"PMID:2963812"}],"species_and_systems":"Curator note says human IGF-II; the abstract mentions bovine CI-MPR and the human IGF-II receptor, and the exact receptor source used in the binding assay is not stated [PMID:2963812]. The dossier lists only a human pair, marked as projected from other evidence.","localisation_and_range":"IGF-II is annotated as secreted [flag]. Receptor localisation is not reported in our evidence.","caveats":"One paper, read as abstract only; no mouse or cell-based functional data; M6PR has no database record in the dossier. IGF-I bound far more weakly and insulin binding was not detected [PMID:2963812].","key_references":[{"PMID":"2963812","why":"Equilibrium binding of IGF-II to purified CI-MPR, Kd 0.2 nM"}],"covers":["LR002773"]},"LR004276":{"pair":"IGFBP4 -> FZD8","headline":"One abstract-level study: IGFBP-4 co-immunoprecipitates with Frizzled 8 and blocks Wnt3A binding; inhibitory.","interaction_type":"direct binding","direction_and_effect":"IGFBP-4 physically interacted with Frizzled 8 and inhibited binding of Wnt3A to it, inhibiting canonical Wnt signalling [PMID:18528331]. Curator effect: antagonist.","molecular_requirements":"The same study reports interaction with the co-receptor LRP6 too [PMID:18528331]; whether Frizzled 8 alone is sufficient is not reported in our evidence.","affinity_potency":[],"species_and_systems":"Curator note describes a mouse model (Igfbp4 knockdown, cardiomyogenesis); the dossier lists a mouse pair and a human pair projected from it [PMID:18528331]. Assays: co-immunoprecipitation and Wnt3A competition.","localisation_and_range":"IGFBP4 is annotated as secreted and FZD8 as a receptor [flag].","caveats":"Abstract-only read; the interaction assay is co-immunoprecipitation, not a quantified binding measurement. No affinity reported. Cardiogenic effect was independent of IGF binding but attenuated by IGFs through IGFBP-4 sequestration [PMID:18528331].","key_references":[{"PMID":"18528331","why":"IGFBP-4 binds Frizzled 8 and LRP6, blocks Wnt3A binding"}],"covers":["LR000844","LR004276"]},"LR010972":{"pair":"IGFBP5 -> IGF2","headline":"Database-supported IGFBP5-IGF2 binding, classed as ligand-ligand; no curated paper.","interaction_type":"database-asserted only","direction_and_effect":"Annotated as inhibitory, class Ligand-Ligand; Reactome lists an IGF:IGFBP5:ALS complex [DB:Reactome].","molecular_requirements":"ALS is part of the Reactome complex [DB:Reactome]; no other requirements reported.","affinity_potency":[],"species_and_systems":"Human only; BioGRID lists a reconstituted complex and IntAct an anti-tag co-immunoprecipitation [DB:BioGRID][DB:IntAct].","localisation_and_range":"Both partners are annotated as secreted [flag].","caveats":"No curator-verified paper (three candidates judged as a different entity, one review only). Database records only; no affinity.","key_references":[],"covers":["LR010972"]},"LR000847":{"pair":"IGFL3 -> IGFLR1","headline":"IGFL3 tightly binds IGFLR1 by SPR in a full-text study; no value in the excerpts.","interaction_type":"direct binding","direction_and_effect":"IGFL3 also tightly bound the receptor in an SPR assay of human IGFL paralogues against immobilized IGFLR1-Fc [PMID:21454693]. Effect: not reported in our evidence.","molecular_requirements":"No requirements reported.","affinity_potency":[],"species_and_systems":"Human FLAG-tagged IGFL3 and IGFLR1-Fc, SPR [PMID:21454693].","localisation_and_range":"IGFL3 is annotated as secreted and IGFLR1 as transmembrane [flag].","caveats":"The curator note mentions a quantified affinity but the dossier gives none, so it is not reported here. Only one paper; IntAct record is from the same study [DB:IntAct].","key_references":[{"PMID":"21454693","why":"SPR shows IGFL3 tight binding to IGFLR1"}],"covers":["LR000847"]},"LR002782":{"pair":"IGSF8 -> KIR3DL2","headline":"Tumour IGSF8 suppresses NK cells through KIR3DL2 in CRISPR-screen and blocking-antibody work; abstract only, binding not shown directly.","interaction_type":"functional only","direction_and_effect":"Tumour-expressed IGSF8 suppresses NK cell function by interacting with human KIR3DL2 and mouse Klra9 on NK cells [PMID:38657602]. An antibody blocking the IGSF8-NK receptor interaction enhances NK killing in vitro and, in syngeneic tumour models, anti-IGSF8 alone or with anti-PD1 inhibits tumour growth [PMID:38657602]. The receptor acts as an inhibitory checkpoint.","molecular_requirements":"Co-receptors or subunits are not reported in our evidence.","affinity_potency":[],"species_and_systems":"Human KIR3DL2 and mouse Klra9 are both named; the in vivo work used syngeneic mouse models [PMID:38657602]. The curator recorded human for both ligand and receptor species.","localisation_and_range":"IGSF8 is flagged non-secreted and KIR3DL2 a transmembrane receptor [flag], consistent with contact signalling from tumour cells to NK cells; range from annotation only.","caveats":"Abstract only. The abstract says 'interacting' and does not report a binding assay or affinity, so direct physical binding is not established in our evidence.","key_references":[{"PMID":"38657602","why":"IGSF8 as an innate immune checkpoint acting through KIR3DL2"}],"covers":["LR002782"]},"LR007255":{"pair":"IHH -> BOC:PTCH1","headline":"Only a computational endometrium scRNA-seq prediction supports the BOC:PTCH1 complex; structural BOC binding is under the single-chain pair.","interaction_type":"functional only","direction_and_effect":"A CellChat-style analysis of human endometrial scRNA-seq predicts IHH from C2 epithelial progenitors-1 interacting with the Hedgehog co-receptor BOC in C12 basalis stromal fibroblasts and C8 late secretory stroma [PMID:42276064]. The paper states IHH is one of three ligands binding PTCH1/PTCH2 and relieves PTCH inhibition of SMO [PMID:42276064].","molecular_requirements":"The complex pairs BOC with PTCH1. The paper's own result names BOC only; PTCH1 as part of the same complex is not tested there [PMID:42276064]. PDB 3N1M and 3N1P show IHH with BOC [DB:PDB 3N1M]; UniProt names PTCH1 as a hedgehog receptor [DB:UniProt].","affinity_potency":[],"species_and_systems":"Human endometrium, computational prediction with BOC/SSEA1 immunolocalisation [PMID:42276064].","localisation_and_range":"IHH is flagged secreted and transmembrane; BOC and PTCH1 are flagged as receptors [flag].","caveats":"Prediction only; it is not binding evidence. The complex form is not tested in the paper; binding to BOC alone is supported by structure at the single-chain pair [DB:PDB 3N1M].","key_references":[{"PMID":"42276064","why":"scRNA-seq prediction of IHH-BOC signalling in endometrium"}],"covers":["LR007255"]},"LR007291":{"pair":"IL10 -> IL10RA:IL10RB","headline":"IL-10 signals through IL10RA plus IL10RB; IL10RA binds ligand and IL10RB is needed for signalling.","interaction_type":"direct binding","direction_and_effect":"Human IL-10 binds the IL-10R1 chain in hamster cells but does not induce signalling; co-expressing CRFB4 (IL10RB) makes cells IL-10 sensitive [PMID:9312047]. IL-10R1 co-immunoprecipitated with an anti-CRF antibody in IL-10-treated PBMCs [PMID:9312047]. Reactome and UniProt describe a heterotetrameric IL10RA/IL10RB receptor [DB:Reactome] [DB:UniProt].","molecular_requirements":"IL10RB is an accessory chain essential for the active receptor and signalling [PMID:9312047]. The structures contain IL-10R1 only, and IL-10R2 is recruited afterwards [PMID:11485736]. Both chains are needed for signalling.","affinity_potency":[{"value":"approximately 70 pM","assay":"binding on Ba/F3 transfectants","system":"mouse IL-10R (IL10RA) in Ba/F3 cells","cite":"PMID:8248239"}],"species_and_systems":"Human proteins for the structure and signalling [PMID:11485736] [PMID:9312047]; mouse cells for 70 pM [PMID:8248239]; hamster cells for reconstitution [PMID:9312047].","localisation_and_range":"IL10 is flagged secreted and the complex transmembrane [flag].","caveats":"Four of six papers are structures or binding of IL10RA alone, so complex-level evidence is a single paper [PMID:9312047]. All are abstract only. The 70 pM value is for the IL10RA chain.","key_references":[{"PMID":"9312047","why":"IL10RB is essential for IL-10 signalling"},{"PMID":"11485736","why":"Structure of IL-10 with IL-10R1"},{"PMID":"7759550","why":"IL-10 binds the alpha chain alone"}],"covers":["LR007291"]},"LR004285":{"pair":"Il11 -> Il11ra1","headline":"Mouse Il11-Il11ra1 binding is shown by SPR and Ba/F3 binding; most other support is human or abstract-only.","interaction_type":"direct binding","direction_and_effect":"IL-11 acts as agonist: expression of the receptor with gp130 was needed for Ba/F3 proliferation and M1 macrophage differentiation in response to IL-11 [PMID:7957045].","molecular_requirements":"High-affinity binding appeared to require coexpression of both NR1 (Il11ra1) and gp130; NR1 alone gave low-affinity binding [PMID:7957045]. Multiple copies of IL-11, IL-11R and gp130 are in the receptor complex [PMID:10948192].","affinity_potency":[{"value":"KD of 72 nM","assay":"surface plasmon resonance, rhIL11 to mouse IL11RA1","system":"recombinant proteins","cite":"PMID:34108253"},{"value":"94 nM","assay":"SPR, rmIL11 to mIL11RA1","system":"recombinant proteins","cite":"PMID:34108253"},{"value":"50 nM","assay":"SPR, rhIL11 to hIL11RA, reconfirmed","system":"recombinant proteins","cite":"PMID:34108253"},{"value":"Kd approximately 10 nM","assay":"low-affinity binding to NR1 alone","system":"mouse NR1 in Ba/F3 cells","cite":"PMID:7957045"},{"value":"Kd = 300-800 pM","assay":"high-affinity binding with gp130","system":"mouse, Ba/F3 cells","cite":"PMID:7957045"}],"species_and_systems":"Mouse receptor in Ba/F3 cells [PMID:7957045]; SPR with human and mouse IL11 on mouse receptor [PMID:34108253]. Two other papers used human IL-11 (mutagenesis) or unspecified species (co-IP) [PMID:10504396][PMID:10948192].","localisation_and_range":"IL-11 is flagged secreted [flag].","caveats":"The SPR sentence comes from a browser-read of the full text and its quote is marked unverified, spot-check pending [PMID:34108253]. The other three papers were abstract-only reads. The 10504396 row is noted as human data placed on the mouse row.","key_references":[{"PMID":"34108253","why":"SPR KD values for IL11 to mouse IL11RA1"},{"PMID":"7957045","why":"cloning of murine receptor and affinities"},{"PMID":"10948192","why":"co-IP of the complex"}],"covers":["LR004285"]},"LR000856":{"pair":"IL11 -> IL6ST","headline":"IL-11 contacts gp130 directly within an IL-11R-containing complex; gp130 alone is not shown sufficient.","interaction_type":"direct binding","direction_and_effect":"IL-11 sites II and III are independent gp130-binding epitopes, both essential for gp130 dimerization [PMID:10948192]. GtoPdb lists IL11 as agonist at IL6ST [DB:GtoPdb].","molecular_requirements":"IL-11R is also required: a stable IL-11/IL-11R/gp130 complex forms, proposed as 2:2:2 [PMID:10948192]. High-affinity IL-11 binding appeared to require both NR1 (IL-11Ralpha) and gp130 [PMID:7957045]. Treat this as a complex-dependent pair, not a standalone IL11-IL6ST interaction.","affinity_potency":[{"value":"Kd = 300-800 pM","assay":"high-affinity IL-11 binding needing NR1 plus gp130","system":"mouse, Ba/F3 cells","cite":"PMID:7957045"}],"species_and_systems":"Co-IP and native PAGE used tagged ligand and soluble receptors [PMID:10948192]. Cloning and binding were in mouse Ba/F3 cells [PMID:7957045]. The human pair is ortholog-inferred; the mouse pair is not.","localisation_and_range":"IL6ST is flagged transmembrane, IL-11 secreted [flag].","caveats":"Both papers are abstract-only. The 7957045 evidence is about the NR1 plus gp130 requirement, not a direct IL-11 to gp130 contact, and the dossier labels the species as human although the paper is murine.","key_references":[{"PMID":"10948192","why":"IL-11 gp130-binding epitopes in a hexameric complex"},{"PMID":"7957045","why":"high-affinity binding needs gp130 with NR1"}],"covers":["LR000856","LR004286"]},"LR004294":{"pair":"Il13 -> Il4ra","headline":"Mouse pair projected from human; its only support is a human genetic association paper, so evidence is very weak.","interaction_type":"database-asserted only","direction_and_effect":"The paper states IL13 or IL4 binding to IL4R induces Th2 polarization as background [PMID:11709756]. UniProt: IL4R interacts with the IL13/IL13RA1 complex to form a type II receptor [DB:UniProt].","molecular_requirements":"IL4R forms a type II receptor with IL13RA1 and IL13 [DB:UniProt]; not shown for IL4R alone.","affinity_potency":[],"species_and_systems":"The cited experiments are in human families, not mouse [PMID:11709756]; mouse pair is ortholog-inferred.","localisation_and_range":"Not reported in our evidence.","caveats":"Genetic association study, not binding evidence [PMID:11709756]. Mouse relevance rests on orthology only.","key_references":[{"PMID":"11709756","why":"Human genetic association only"}],"covers":["LR004294"]},"LR000865":{"pair":"IL15 -> IL15RA","headline":"IL15 binds IL15RA with high affinity, shown in mouse cloning and human soluble-receptor work; well supported.","interaction_type":"direct binding","direction_and_effect":"IL-15R alpha alone binds IL-15 with affinity equal to that of the heterotrimeric IL-2R for IL-2 [PMID:7641685]. Soluble full ectodomain sIL-15R alpha is a high-affinity IL-15 antagonist [PMID:15265897], while the recombinant sushi domain acts as an agonist through IL-15R beta/gamma [PMID:16284400].","molecular_requirements":"IL15RA is the private alpha chain; the IL15 high-affinity receptor combines it with IL-2R beta and gamma [PMID:15265897]. The sushi domain bears most of the binding affinity [PMID:16284400]. Sushi does not affect function of the tripartite membrane receptor [PMID:16284400].","affinity_potency":[],"species_and_systems":"Murine IL-15R alpha cloned and expressed [PMID:7641685]; human cell lines and COS-7 for shedding [PMID:15265897].","localisation_and_range":"IL15 flagged secreted [flag]. Receptor shed as 42 kDa soluble form [PMID:15265897]; IL15 expressed with IL15RA on producer cells (trans-presentation) per UniProt [DB:UniProt].","caveats":"All abstracts only. Soluble forms can antagonize or agonize depending on domain used, which matters for shed-receptor interpretation. Numeric affinity not reported in our evidence.","key_references":[{"PMID":"7641685","why":"Cloning of murine IL-15R alpha; binding"},{"PMID":"15265897","why":"Soluble human sIL-15R alpha as antagonist"},{"PMID":"16284400","why":"Sushi domain as agonist"}],"covers":["LR000865","LR004295"]},"LR006814":{"pair":"IL17B -> IL17RA","headline":"IL-17B to IL-17RA rests only on a GtoPdb agonist record; the papers judged were insufficient or about other entities.","interaction_type":"database-asserted only","direction_and_effect":"GtoPdb lists an agonist interaction [DB:GtoPdb]; no paper in our evidence shows it.","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Not reported in our evidence.","localisation_and_range":"IL-17B annotated as secreted and IL-17RA as a receptor [flag].","caveats":"No verified paper. Judged rows were abstract_insufficient (2), review_only (1) and different_entity (2). Do not treat as validated.","key_references":[],"covers":["LR006814"]},"LR000874":{"pair":"IL18 -> IL18R1","headline":"IL-18 binds IL18R1 directly; supported by a co-crystal structure, binding assays and a Kd, all in human systems.","interaction_type":"direct binding","direction_and_effect":"IL-18 binds IL-18R alpha (IL18R1) and acts as an agonist: IL-1Rrp (IL18R1) conferred IL-18 binding and signal transduction on COS-1 cells [PMID:9325300], and GtoPdb lists IL18-IL18R1 as agonist [DB:GtoPdb].","molecular_requirements":"IL18R1 is the ligand-binding chain; a co-crystal structure shows IL-18 with both IL-18R alpha and beta ectodomains in a ternary complex [PMID:25500532], and IL-18R beta is needed for high affinity binding in cotransfected cells [PMID:11046021]. UniProt says IL18R1 binds IL18 but not IL1A or IL1B [DB:UniProt]. One paper reports CD48 associating with IL-18R alpha in KG-1 cells [PMID:15760905].","affinity_potency":[{"value":"Kd 18.5 nM","assay":"125I-IL-18 binding","system":"human L428 Hodgkin's line","cite":"PMID:9325300"},{"value":"Kd 11 nM (low affinity site)","assay":"binding after cotransfection with both receptor chains","system":"cotransfected cells; species human per curator","cite":"PMID:11046021"},{"value":"Kd 0.4 nM (high affinity site)","assay":"binding after cotransfection with both receptor chains","system":"cotransfected cells; species human per curator","cite":"PMID:11046021"}],"species_and_systems":"Experiments used human proteins and cells; the mouse pair is projected from human evidence (ortholog inferred) and not tested in our evidence.","localisation_and_range":"Ligand carries the secreted annotation flag [flag], which implies paracrine/endocrine range; receptor localisation beyond the receptor flag is not reported in our evidence.","caveats":"All four papers were read as abstracts (the structure paper also has full-text excerpts). Binding was inhibited by IL-18 but not IL-1beta [PMID:9325300]. The high affinity site needs the second chain, so IL18R1 alone is a lower-affinity receptor [PMID:11046021].","key_references":[{"PMID":"25500532","why":"Crystal structure of human IL-18 with both receptor ectodomains"},{"PMID":"9325300","why":"Receptor purification, Kd 18.5 nM, IL-18 binding in COS-1 cells"},{"PMID":"11046021","why":"Both chains needed for high affinity binding"}],"covers":["LR000874","LR004304"]},"LR000883":{"pair":"IL1B -> IL1RAP","headline":"IL1RAP is an accessory chain needed for IL-1beta signalling and high-affinity binding; evidence is abstract-level plus database structures.","interaction_type":"direct binding","direction_and_effect":"IL-1 agonists bound IL-1R AcP-deficient cells through type I IL-1R but failed to activate NF-kappaB or AP-1 signalling, so IL1RAP is an essential signal-transducing component [PMID:9820540]. GtoPdb lists the pair as agonist [DB:GtoPdb].","molecular_requirements":"IL1RAP acts with IL1R1 in a ternary complex; IL-1RAcP contacts the back of IL-1R(I) wrapped around IL-1beta rather than binding IL-1beta alone (modelling) [PMID:11418113]. Reactome has IL1R1:IL1:IL1RAP [DB:Reactome]. PDB 3O4O and 4DEP contain IL1B and IL1RAP chains [DB:PDB 3O4O].","affinity_potency":[{"value":"70-fold reduced murine IL-1beta affinity without IL-1R AcP","assay":"binding to knockout fibroblasts","system":"IL-1R AcP-deficient mouse fibroblasts","cite":"PMID:9820540"}],"species_and_systems":"Fibroblasts and mice from IL-1R AcP-deficient animals with murine IL-1beta [PMID:9820540]; the abstract does not name the species for the other ligands beyond murine IL-1alpha and human IL-1Ra. Curated labels say human; the pair also exists for mouse.","localisation_and_range":"IL1B is flagged secreted and IL1RAP is flagged transmembrane (and secreted) [flag]; signalling is by a membrane receptor complex.","caveats":"Both papers were read as abstracts only. The 2001 paper is purely computational [PMID:11418113]. IL1RAP is a co-receptor, not a stand-alone receptor; IL-1alpha and IL-1Ra bound with only moderately reduced affinity without it [PMID:9820540].","key_references":[{"PMID":"9820540","why":"Knockout shows IL1RAP essential for signalling and for high-affinity IL-1beta binding"},{"PMID":"11418113","why":"Computational model of IL-1RAcP contacting the IL-1beta/IL-1R(I) complex"}],"covers":["LR000883","LR004313"]},"LR002791":{"pair":"IL1B -> ITGB1","headline":"IL-1beta binds integrin alpha5beta1 directly according to one abstract-level paper; UniProt repeats that paper.","interaction_type":"direct binding","direction_and_effect":"IL-1beta specifically bound integrins alphavbeta3 and alpha5beta1, and the authors propose this binding is primarily important for agonistic IL-1beta signalling [PMID:29030430]. Agonist direction is the curators' label.","molecular_requirements":"The integrin heterodimer is the binding unit named in the paper (integrin alpha5beta1); this pair record is for one subunit only, and which subunit contacts IL-1beta is not reported in our evidence [PMID:29030430]. UniProt: ITGA5:ITGB1 is a receptor for IL1B and binding is essential for IL1B signaling [DB:UniProt].","affinity_potency":[],"species_and_systems":"Human IL-1beta and human integrins in binding and signalling assays; the mouse pair is inferred from human evidence [PMID:29030430].","localisation_and_range":"IL1B is flagged secreted [flag]; the integrin is a membrane receptor, so ligand acts at the cell surface.","caveats":"Read as abstract only. The E128K mutation in the IL1R-binding site enhanced integrin binding, and Lys-to-Glu substitutions reduced but did not abolish agonistic action, so integrin binding is not the only route [PMID:29030430]. No affinity reported. UniProt support derives from the same paper.","key_references":[{"PMID":"29030430","why":"IL-1beta binds alphavbeta3 and alpha5beta1; role in agonism"}],"covers":["LR002791","LR006034"]},"LR011737":{"pair":"IL1RN -> IL1B:IL1R2:IL1RAP","headline":"Complex pair supported by database records only; no paper confirmed.","interaction_type":"database-asserted only","direction_and_effect":"GtoPdb lists IL1RN-IL1RAP as antagonist [DB:GtoPdb]. Reactome records IL1R1:IL1R2:IL1RN and IL1 receptor antagonist binding IL1 receptors [DB:Reactome]; BioGRID has IL1R2-IL1RN affinity capture-western [DB:BioGRID].","molecular_requirements":"The receptor entry is a three-member complex (IL1B:IL1R2:IL1RAP); the records support individual members, not this complex as a unit.","affinity_potency":[],"species_and_systems":"Species and system not reported in our evidence.","localisation_and_range":"IL1RN is flagged secreted [flag].","caveats":"Three papers are pending and none verified. Database records name pairs of members, not this complex, so the complex-level claim is an assembly.","key_references":[],"covers":["LR011737"]},"LR007309":{"pair":"IL1RN -> IL1R2:IL1RAP","headline":"No paper verifies this complex pairing; support is from GtoPdb, UniProt and BioGRID records for the individual chains.","interaction_type":"database-asserted only","direction_and_effect":"GtoPdb records IL1RN-IL1RAP as Antagonist [DB:GtoPdb]. UniProt describes IL1R2 as a non-signaling receptor for IL1A, IL1B and IL1RN [DB:UniProt].","molecular_requirements":"The IL1R2:IL1RAP complex is not tested with IL1RN in our evidence. Reactome lists a complex IL1R1:IL1R2:IL1RN, not IL1RAP [DB:Reactome].","affinity_potency":[],"species_and_systems":"Human only; no experimental system reported in our evidence.","localisation_and_range":"IL1RN secreted, complex flagged transmembrane [flag].","caveats":"No curator-verified paper for the complex (one paper judged abstract_insufficient). The BioGRID record concerns IL1R2-IL1RN only [DB:BioGRID]. The GtoPdb record is for IL1RAP alone. Whether IL1RAP adds to IL1RN binding is not reported in our evidence.","key_references":[],"covers":["LR007309"]},"LR000892":{"pair":"IL22 -> IL10RB","headline":"IL-22 signals through a receptor that includes IL10RB (CRF2-4) as the shared second chain; one abstract-level paper plus databases.","interaction_type":"functional only","direction_and_effect":"IL-22 is a ligand for CRF2-4 and, together with IL-22R, enables IL-22 signalling with STAT1, STAT3 and STAT5 activation [PMID:10875937]. GtoPdb lists an agonist (pEC50) [DB:GtoPdb]. No numeric value is given in our evidence.","molecular_requirements":"IL10RB works with IL22RA1; IL-22 signals through a heterodimer of IL22RA1 and shared IL10RB [DB:UniProt][PMID:10875937]. IL10RB alone is not shown sufficient.","affinity_potency":[],"species_and_systems":"Human, cell lines responsive to IL-22 [PMID:10875937]. Mouse pair is ortholog-inferred.","localisation_and_range":"IL-22 is flagged secreted [flag].","caveats":"The abstract asserts ligand status but reports no binding constant [PMID:10875937]. IntAct lists ELISA and SPR records [DB:IntAct]. Abstract only.","key_references":[{"PMID":"10875937","why":"IL-22 is a ligand for CRF2-4 (IL10RB)"}],"covers":["LR000892","LR004322"]},"LR007318":{"pair":"IL25 -> IL17RA:IL17RB","headline":"IL-25 acts through IL17RB with IL17RA also required; one weak SPR measurement for IL17RA, otherwise functional evidence.","interaction_type":"direct binding","direction_and_effect":"IL-25 is an agonist at this receptor in GtoPdb for both chains [DB:GtoPdb]. Intranasal IL-25 drives eosinophilic lung inflammation in mice, and IL-17RB or IL-17RA knockout, or blocking antibodies to either, abolished the response [PMID:18768888]. IL-17E induced NF-kappaB activation and IL-8 production [PMID:11058597].","molecular_requirements":"Both chains are needed functionally: splenocytes from IL-17RB KO or IL-17RA KO mice made no IL-5 or IL-13 in response to IL-25 [PMID:18768888]. By SPR, IL-25 bound IL-17RB, IL-17RA had no apparent affinity for IL-25 alone, and IL-17RA bound only the IL-17RB-IL-25 complex [PMID:19838198]. Reactome lists an IL25 dimer:IL17RA:IL17RB complex [DB:Reactome].","affinity_potency":[{"value":"14.1\u00b12.4 \u03bcM","assay":"SPR sequential capture: IL-17RA binding to the IL-17RB-IL-25 complex","system":"recombinant proteins","cite":"PMID:19838198"}],"species_and_systems":"Binding work used recombinant protein (species not stated beyond the pair being human) [PMID:19838198]; knockout and antibody work was in mice, with a blocking anti-human IL-17RA antibody also blocking IL-25 activity in a primary human cell assay [PMID:18768888]. Structures 7UWJ, 7UWK and 7UWL contain both chains [DB:PDB 7UWJ].","localisation_and_range":"IL-25 is flagged secreted and non-transmembrane; the receptor complex is flagged transmembrane [flag].","caveats":"Most papers were read as abstracts only. The IL-17RA contribution in vitro is low affinity (micromolar) and conditional on IL-17RB. PMID:40451110 only shows reduced IL-25 with raised Il17ra expression in HDM mice, and PMID:40074948 concerns IL-17RB; neither tests the heterodimer. PMID:25204502 found IL-25 knockout mice were not protected in endotoxin shock.","key_references":[{"PMID":"18768888","why":"Knockout and antibody blockade show both IL-17RB and IL-17RA are needed for IL-25 activity in mice."},{"PMID":"19838198","why":"SPR: IL-17RA binds the IL-17RB-IL-25 complex at 14.1\u00b12.4 \u03bcM, not IL-25 alone."},{"PMID":"11058597","why":"First report of IL-17E as ligand of IL-17BR/IL-17Rh1."}],"covers":["LR007318"]},"LR001864":{"pair":"IL36A -> IL1RL2","headline":"IL36A activates IL1RL2 (IL-36R) in functional assays; supported by two abstract-only papers.","interaction_type":"functional only","direction_and_effect":"IL-1F6/F8/F9 activate NF-kappaB in an IL-1Rrp2 (IL1RL2)-dependent manner and anti-IL-1Rrp2 antibodies block it [PMID:14734551]. IL36R activation of mouse and human fibroblasts induced fibrosis-related genes including collagen type VI [PMID:30452921]. GtoPdb: Agonist [DB:GtoPdb].","molecular_requirements":"Signalling needs IL-1RAcP as well as IL1RL2 per the companion evidence; single IL1RL2 rows inherit complex-level evidence [PMID:14734551].","affinity_potency":[],"species_and_systems":"Human and mouse cell lines [PMID:14734551]; mouse and human fibroblasts and human intestinal tissue [PMID:30452921].","localisation_and_range":"Ligand annotated as secreted [flag]; receptor-side localisation not otherwise reported.","caveats":"Both papers abstract-only. No binding measurement or affinity. 14734551 names IL-1F6/F8/F9 rather than IL36A.","key_references":[{"PMID":"14734551","why":"IL-1Rrp2-dependent NF-kappaB activation"},{"PMID":"30452921","why":"IL36R activation in fibroblasts"}],"covers":["LR001864","LR005209"]},"LR004339":{"pair":"IL4 -> IL13RA1","headline":"IL-4 engages IL-13Ralpha1 as second chain with IL-4Ralpha, weakly alone; supported by SPR and mouse knockout.","interaction_type":"direct binding","direction_and_effect":"IL-13Ralpha1 is required for IL-4-induced airway resistance, mucus, TGF-beta and eotaxin(s) in Il13ra1-/- mice [PMID:18480254]. GtoPdb: Agonist [DB:GtoPdb].","molecular_requirements":"IL-13Ralpha1 is a second chain in the type II complex with IL-4Ralpha [PMID:23103943]. IL-4 on its own binds IL-13Ralpha1 with KD >1 uM [PMID:23103943].","affinity_potency":[{"value":"KD 4200 nM","assay":"SPR, IL-4/IL-4Ralpha complex binding IL-13Ralpha1","system":"recombinant human","cite":"PMID:23103943"}],"species_and_systems":"Recombinant human IL-4 [PMID:23103943]; mouse Il13ra1-/- allergen model [PMID:18480254]. Mouse pair is ortholog-inferred.","localisation_and_range":"IL-4 flagged secreted [flag].","caveats":"Paper 23103943 is partly an engineering study; excerpts used. 18480254 is dependence, not binding.","key_references":[{"PMID":"23103943","why":"SPR of IL-4 variants with IL-13Ralpha1"},{"PMID":"18480254","why":"IL-13Ralpha1 role in IL-4 responses in mice"}],"covers":["LR000911","LR004339"]},"LR007327":{"pair":"IL4 -> IL13RA1:IL4R","headline":"IL4 engages the type II receptor (IL4R with IL13RA1); support is one abstract-only binding paper plus database records, with no direct IL4-IL13RA1 binding data.","interaction_type":"functional only","direction_and_effect":"Database records list IL4 as an agonist at IL4R and IL13RA1 [DB:GtoPdb]. Dupilumab (REGN668) blockade of IL4R-alpha in ex vivo mycosis fungoides skin explants reduced proliferation and immunosuppressive pathways, consistent with an IL4/IL13 receptor-dependent axis [PMID:42350047].","molecular_requirements":"The receptor needs IL4R plus IL13RA1 (type 2 complex) [DB:UniProt]. The IL13RA1 D1 domain is the binding unit for IL-13 but none of the D1 mutations affected IL-4 binding [PMID:19586918]; a structure and ITC data exist for IL4R with IL13RA1 (P78552) [DB:PDB 3BPN].","affinity_potency":[],"species_and_systems":"Human ligand and receptor in both papers: receptor domain mutants in binding assays [PMID:19586918]; ex vivo patient skin explants with single-cell transcriptomics [PMID:42350047].","localisation_and_range":"IL4 is flagged secreted and non-transmembrane [flag], so it acts as a diffusible ligand on receptor-bearing cells; the receptor is flagged as a transmembrane receptor [flag].","caveats":"Both papers were read as abstracts only (the second with some full-text excerpts). Neither measures IL4 binding to IL13RA1 directly; the 2026 paper blocks IL4R-alpha, and the curator notes IL13RA1 is not named individually [PMID:42350047]. Affinity not reported in our evidence.","key_references":[{"PMID":"19586918","why":"Mutational dissection of IL13RA1 D1 domain; IL-4 binding unaffected"},{"PMID":"42350047","why":"IL4R-alpha blockade in human MF explants"}],"covers":["LR007327"]},"LR002809":{"pair":"IL6 -> CD5","headline":"A single 2016 paper reports IL-6 directly binding CD5 on B cells; uncorroborated by other sources.","interaction_type":"direct binding","direction_and_effect":"IL-6 directly bound CD5, activating STAT3 via gp130 and JAK2 (agonist); CD5+ B cells responded to IL-6 without IL-6Ralpha [PMID:27096320].","molecular_requirements":"gp130 and JAK2 are downstream of CD5; the effect appeared in IL-6Ralpha-negative cells and was not explained by soluble IL-6Ralpha, which was not detectable by ELISA [PMID:27096320].","affinity_potency":[],"species_and_systems":"Mouse splenic B cells and tumour models (CD5+ B cells promoted tumour growth); human tumour tissues show STAT3 activation. The curated row lists human ligand and receptor, while the excerpts describe mouse cells [PMID:27096320].","localisation_and_range":"CD5 is flagged secreted and as a receptor [flag], which is unusual; membrane versus soluble form is not stated in our evidence.","caveats":"Single paper; no database support. Binding assay details are not given in the abstract. A second confirmed row is not shown.","key_references":[{"PMID":"27096320","why":"IL-6 binds CD5 and activates STAT3 in B cells"}],"covers":["LR002809","LR006049"]},"LR006049":{"pair":"IL6 -> CD5","headline":"A single 2016 paper reports IL-6 directly binding CD5 on B cells; uncorroborated by other sources.","interaction_type":"direct binding","direction_and_effect":"IL-6 directly bound CD5, activating STAT3 via gp130 and JAK2 (agonist); CD5+ B cells responded to IL-6 without IL-6Ralpha [PMID:27096320].","molecular_requirements":"gp130 and JAK2 are downstream of CD5; the effect appeared in IL-6Ralpha-negative cells and was not explained by soluble IL-6Ralpha, which was not detectable by ELISA [PMID:27096320].","affinity_potency":[],"species_and_systems":"Mouse splenic B cells and tumour models (CD5+ B cells promoted tumour growth); human tumour tissues show STAT3 activation. The curated row lists human ligand and receptor, while the excerpts describe mouse cells [PMID:27096320].","localisation_and_range":"CD5 is flagged secreted and as a receptor [flag], which is unusual; membrane versus soluble form is not stated in our evidence.","caveats":"Single paper; no database support. Binding assay details are not given in the abstract. A second confirmed row is not shown.","key_references":[{"PMID":"27096320","why":"IL-6 binds CD5 and activates STAT3 in B cells"}],"covers":["LR002809","LR006049"]},"LR000919":{"pair":"IL7 -> IL2RG","headline":"IL2RG is a functional IL-7 receptor component, shown by cross-linking and antibodies; supporting chain, not a standalone receptor.","interaction_type":"direct binding","direction_and_effect":"IL-2R gamma was physically associated with the IL-7 receptor by chemical cross-linking [PMID:8266077]; antibodies show gamma participates in high-affinity IL-7 receptor complexes [PMID:8128231]. GtoPdb: agonist [DB:GtoPdb].","molecular_requirements":"IL2RG is a shared subunit that augments IL-7 binding affinity and internalization [PMID:8266077]; it works with the IL-7Ralpha chain [PMID:7522165]. IL2RG alone is not shown to bind IL-7 in our evidence.","affinity_potency":[],"species_and_systems":"Mouse for PMID:8266077; human for PMID:7522165; species of PMID:8128231 not reported in our evidence. Co-immunoprecipitation in IntAct [DB:IntAct].","localisation_and_range":"Secreted ligand [flag].","caveats":"Chain-only pair: the receptor is IL2RG without IL7R. Abstracts only; the PMID:7522165 paper mentions the gamma chain as background and its result concerns IL7R alpha.","key_references":[{"PMID":"8266077","why":"Cross-linking shows IL-2Rgamma associated with IL-7R"},{"PMID":"8128231","why":"Antibodies show gamma chain in IL-7 receptor complexes"}],"covers":["LR000919","LR004347"]},"LR004348":{"pair":"IL7 -> IL7R","headline":"IL7 to IL7R supported by one confirmed functional paper plus databases; abstract-level.","interaction_type":"functional only","direction_and_effect":"IL-7 causes p85 of PtdIns 3-kinase to associate with IL-7R via phosphorylation of Tyr449 in the alpha chain [PMID:7522165]. GtoPdb: agonist [DB:GtoPdb].","molecular_requirements":"IL7R alpha chain acts with the common gamma chain [PMID:7522165]; the paper's result concerns the alpha chain only.","affinity_potency":[],"species_and_systems":"Human; mouse pair ortholog-inferred [PMID:7522165].","localisation_and_range":"IL6/IL7/IL9 are flagged secreted [flag], so signalling is paracrine or endocrine; the receptor is flagged transmembrane [flag].","caveats":"One confirmed paper, read as abstract only, shows downstream signalling not binding. Four other papers were abstract_insufficient.","key_references":[{"PMID":"7522165","why":"IL-7-induced p85 association with IL-7R alpha, Tyr449"}],"covers":["LR000920","LR004348"]},"LR007921":{"pair":"INHA -> ACVR1B:ACVR2A","headline":"INHA on ACVR1B plus ACVR2A: database-asserted only; the type II receptor is the likely contact, no curated paper.","interaction_type":"database-asserted only","direction_and_effect":"GtoPdb lists INHA with the type II receptor as agonist [DB:GtoPdb]; BioGRID has ACVR2A-INHA affinity capture-western [DB:BioGRID 275207] and Reactome has an inhibin-A:TGFBR3:ACVR2A complex [DB:Reactome]. Effect is stimulatory by annotation only.","molecular_requirements":"Type II chain ACVR2A carries the database evidence; the type I chain is not specifically evidenced in our evidence. Reactome places betaglycan (TGFBR3) in the inhibin-A:ACVR2A complex [DB:Reactome].","affinity_potency":[],"species_and_systems":"Species of database experiments not reported in our evidence.","localisation_and_range":"Secreted ligand [flag]; receptor complex transmembrane [flag].","caveats":"No paper evidence supports this pair; it rests on database records. Both judged papers were review_only. GtoPdb calls INHA an agonist, whereas related papers on other INHA pairs describe inhibin as competing with activin and BMPs.","key_references":[],"covers":["LR007921"]},"LR000928":{"pair":"INHA -> ACVR2A","headline":"Inhibin competes with BMPs for type II activin receptors; one confirmed paper but a conflicting verified negative.","interaction_type":"conflicting","direction_and_effect":"Inhibin competes with BMPs for type II activin receptors, blocking BMP-Smad signalling [PMID:12493742]. A pair_absent judgement on the same paper says the ACVR2A-INHA mention was not a positive finding [PMID:12493742]. GtoPdb: agonist [DB:GtoPdb].","molecular_requirements":"The curators' note says inhibin is an INHA-containing complex acting on type II activin receptors (ACVR2A/ACVR2B) [PMID:12493742].","affinity_potency":[],"species_and_systems":"Species and cells not reported beyond BMP-responsive cell types [PMID:12493742]. Mouse and human pairs are ortholog-inferred. BioGRID: ACVR2A-INHA affinity capture-western [DB:BioGRID 275207].","localisation_and_range":"Secreted ligand [flag].","caveats":"Confirmed and pair_absent rows coexist for the same paper; the absent row was an automated propagation from a text mention. Evidence is inhibin as a complex, not INHA alone. Two papers abstract_insufficient.","key_references":[{"PMID":"12493742","why":"Inhibin competes with BMPs for type II activin receptors"}],"covers":["LR000928","LR004351"]},"LR007930":{"pair":"INHA:INHBA -> ACVR1C:ACVR2B","headline":"Inhibin A to ACVR1C:ACVR2B is supported only by database records for individual chains; no verified paper.","interaction_type":"database-asserted only","direction_and_effect":"No curator-verified paper; GtoPdb lists the component pairs as agonist [DB:GtoPdb]. BioGRID records INHBA-ACVR2B binding (Affinity Capture-Western, Reconstituted Complex) [DB:BioGRID]; PDB 7OLY holds activin A with an ActRIIB-Alk4 fusion [DB:PDB 7OLY]; UniProt says type-2 receptors bind activin-A/INHBA and inhibin-A [DB:UniProt].","molecular_requirements":"Receptor is a type I (ACVR1C) plus type II (ACVR2B) pair; UniProt says INHBA signals through type I and type II receptors [DB:UniProt]. Whether inhibin A (INHA:INHBA) engages this exact complex is not reported in our evidence.","affinity_potency":[],"species_and_systems":"Human pair; no experimental species reported in our evidence (no verified papers).","localisation_and_range":"Ligand carries a secreted flag and receptor a transmembrane flag [flag]; suggests endocrine or paracrine action on membrane receptors.","caveats":"Rests on databases alone; the two papers judged were review_only, so none confirms this pair. Database records concern individual subunits or related complexes, not necessarily this exact combination. Reactome describes activin binding to ACVR2A,B:ACVR1B, not ACVR1C [DB:Reactome].","key_references":[],"covers":["LR007930"]},"LR004357":{"pair":"INHBA -> ACVR2B","headline":"Binding of activin A to ACVR2B is supported by a verified competition study and a structure.","interaction_type":"direct binding","direction_and_effect":"Labelled activin was displaced by inhibin from the activin type II receptors, especially type IIB [PMID:9202237]. GtoPdb lists agonist [DB:GtoPdb].","molecular_requirements":"Type II receptor binds activin directly; UniProt says type-2 receptors act as primary activin receptors [DB:UniProt]. PDB 7OLY holds activin A with an ActRIIB-Alk4 fusion [DB:PDB 7OLY].","affinity_potency":[],"species_and_systems":"Chinese hamster ovary cells; species of ligand and receptor not stated in our evidence [PMID:9202237].","localisation_and_range":"Ligand secreted flag, receptor transmembrane flag [flag].","caveats":"The paper concerns inhibin displacing activin, so it supports ACVR2B binding of activin only indirectly; abstract only; no affinity.","key_references":[{"PMID":"9202237","why":"Competition binding shows activin and inhibin use type II receptors, especially IIB."}],"covers":["LR000934","LR004357"]},"LR010981":{"pair":"INHBC -> ACVR1B:ACVR2B","headline":"INHBC drives ACVR2B-Smad2 signalling in liver cancer cells; abstract-only functional evidence for the ACVR1B:ACVR2B complex.","interaction_type":"functional only","direction_and_effect":"INHBC activates ACVR2B-Smad2 signalling to drive hepatocellular carcinoma cell proliferation and invasion; the ACVR2B antibody bimagrumab reduced xenograft growth by ~42% (P = 0.008) [PMID:41298802].","molecular_requirements":"Only ACVR2B is implicated; ACVR1B is not mentioned in our evidence [PMID:41298802].","affinity_potency":[],"species_and_systems":"Human hepatocellular carcinoma cells and a mouse xenograft; Mendelian randomization of human plasma proteins [PMID:41298802].","localisation_and_range":"Ligand is flagged secreted [flag], so likely paracrine/endocrine; receptor is flagged transmembrane [flag].","caveats":"Abstract only; binding not shown. Abstract-insufficient and different-entity rows were also judged.","key_references":[{"PMID":"41298802","why":"INHBC-ACVR2B axis in liver cancer"}],"covers":["LR010981"]},"LR004366":{"pair":"INHBC -> ACVR2B","headline":"Activin C reported to bind ACVR2B and antagonise activin A signalling; one abstract-level paper.","interaction_type":"direct binding","direction_and_effect":"Activin-C acts as an activin-A antagonist by binding activin receptor subunits IIA and IIB and modulating canonical Smad signalling [PMID:25180271]. The database-style effect label is Stimulatory, which differs from this antagonist reading.","molecular_requirements":"Type II receptor subunit binding only; a type I partner is not reported in our evidence.","affinity_potency":[],"species_and_systems":"Human granulosa cell line and human gonadal/adrenal cancer tissue [PMID:25180271]. Mouse pair is projected from human evidence (ortholog inferred).","localisation_and_range":"Ligand is flagged secreted [flag].","caveats":"Single paper, read as abstract only; binding method not stated in the abstract. Two confirmed rows are counted but one paper is shown; one other row was review-only and one abstract-insufficient.","key_references":[{"PMID":"25180271","why":"Activin-C binds ActRIIA/IIB and antagonises activin A in human gonadal/adrenal cancer settings"}],"covers":["LR000943","LR004366"]},"LR002818":{"pair":"INSL3 -> RXFP1","headline":"INSL3 to RXFP1 rests on a GtoPdb agonist record; no curator-confirmed paper.","interaction_type":"database-asserted only","direction_and_effect":"GtoPdb lists INSL3 as a full agonist at RXFP1, with affinity expressed as pKi (no value given) [DB:GtoPdb PMID:23303914].","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Not reported in our evidence.","localisation_and_range":"Ligand is flagged secreted [flag].","caveats":"No paper was confirmed: four rows were judged a different entity, three review-only and four abstract-insufficient. Treat as unverified.","key_references":[],"covers":["LR002818","LR006058"]},"LR006058":{"pair":"INSL3 -> RXFP1","headline":"INSL3 to RXFP1 rests on a GtoPdb agonist record; no curator-confirmed paper.","interaction_type":"database-asserted only","direction_and_effect":"GtoPdb lists INSL3 as a full agonist at RXFP1, with affinity expressed as pKi (no value given) [DB:GtoPdb PMID:23303914].","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Not reported in our evidence.","localisation_and_range":"Ligand is flagged secreted [flag].","caveats":"No paper was confirmed: four rows were judged a different entity, three review-only and four abstract-insufficient. Treat as unverified.","key_references":[],"covers":["LR002818","LR006058"]},"LR009712":{"pair":"IRAK4 -> TLR7","headline":"IRAK4 to TLR7 lacks any verified paper; only UniProt describes IRAK4 in a signalling complex.","interaction_type":"database-asserted only","direction_and_effect":"UniProt describes IRAK4 as part of the Myddosome signalling complex with IRAK1, TRAF6 and TRAF3, leading to NF-kappa-B and IRF7 activation [DB:UniProt].","molecular_requirements":"Myddosome membership is described, not binding to TLR7 itself.","affinity_potency":[],"species_and_systems":"Not reported in our evidence.","localisation_and_range":"Not reported in our evidence.","caveats":"One review-only and three abstract-insufficient rows; no confirmed paper.","key_references":[],"covers":["LR009712"]},"LR002827":{"pair":"ITGB2 -> AGER","headline":"RAGE interacts directly with Mac-1 (alphaMbeta2); ITGB2 row inherits heterodimer evidence from knockout and binding work.","interaction_type":"direct binding","direction_and_effect":"RAGE acts as an adhesion counter-receptor: leukocyte adhesion to RAGE was blocked by an anti-Mac-1 antibody but not an anti-LFA-1 antibody [PMID:14623906]. RAGE-deficient mice had reduced neutrophil recruitment [PMID:14623906].","molecular_requirements":"Specific to Mac-1; p150,95 weaker; LFA-1 and beta1-integrins did not bind [PMID:14623906]. So beta2 alone is not enough.","affinity_potency":[],"species_and_systems":"Mouse peritonitis models, human cell lines (THP-1, U937) and CHO transfectants [PMID:14623906].","localisation_and_range":"Membrane adhesion between leukocytes and endothelium [PMID:14623906].","caveats":"Abstract plus full-text excerpts; the evidence is complex-level. No affinity reported.","key_references":[{"PMID":"14623906","why":"Mac-1 as RAGE counter-receptor with knockout evidence"}],"covers":["LR002827","LR006065"]},"LR006067":{"pair":"ITGB3 -> THY1","headline":"Thy-1 and alphavbeta3 integrin interact, with slip-bond kinetics measured by optical tweezers; abstract only.","interaction_type":"direct binding","direction_and_effect":"Thy-1/alphavbeta3 interactions stimulate astrocyte migration and retraction of neuronal prolongations; both partners signal [PMID:29212879].","molecular_requirements":"Alphavbeta3 as Fc fusion with nonpurified integrin; ITGB3 chain-only row [PMID:29212879].","affinity_potency":[],"species_and_systems":"Recombinant Thy-1-Fc and alphavbeta3-Fc, human per record; pair projected by orthology to both species [PMID:29212879].","localisation_and_range":"Trans interaction between neurons and astrocytes [PMID:29212879].","caveats":"Force accelerated dissociation (slip bond) [PMID:29212879]; no rate or Kd values in the dossier. Nonspecific events were detected even with purified proteins [PMID:29212879]. Both interactions listed are ortholog-inferred.","key_references":[{"PMID":"29212879","why":"Single-molecule force measurement of Thy-1/alphavbeta3 binding"}],"covers":["LR002830","LR006067"]},"LR004375":{"pair":"JAG1 -> NOTCH1","headline":"Canonical Notch ligand-receptor pair with direct binding and functional support, plus extensive database records.","interaction_type":"direct binding","direction_and_effect":"Soluble Notch1 extracellular protein bound JAG1 directly in solid-phase assays, Ca2+-dependent [PMID:11006133]. In cell-based assays JAG1 activated NOTCH1 [PMID:32820046]. Blocking Jagged1 or Notch1 with antibodies inhibited Treg suppressor function in vitro [PMID:18292500]. The interaction is annotated as stimulatory.","molecular_requirements":"Binding required Ca2+ [PMID:11006133]. Fringe enzymes modulate activity in a ligand- and receptor-specific way, though the abstract does not give JAG1-NOTCH1 specifics [PMID:32820046]. UniProt also notes interaction with NOTCH1 in the presence of calcium ions [DB:UniProt].","affinity_potency":[],"species_and_systems":"Human proteins in the binding and signalling papers [PMID:11006133][PMID:32820046]; species unspecified for the Treg study [PMID:18292500]. The mouse pair is a separate record, and the human pair is ortholog-inferred.","localisation_and_range":"JAG1 is flagged as transmembrane [flag], so signalling is likely contact-dependent; the papers do not state this.","caveats":"All three papers were read as abstracts only. The Treg paper is indirect (antibody blockade) [PMID:18292500]. Affinities were said to differ between DSL proteins but are not given in our evidence [PMID:11006133]. Database support includes BioGRID, IntAct, Reactome [DB:BioGRID][DB:IntAct][DB:Reactome].","key_references":[{"PMID":"11006133","why":"Direct solid-phase binding"},{"PMID":"32820046","why":"Cell-based NOTCH1 activation by JAG1"},{"PMID":"18292500","why":"Blocking antibodies in Treg function"}],"covers":["LR000952","LR004375"]},"LR000955":{"pair":"JAG1 -> NOTCH4","headline":"Functional in vivo and cell evidence that JAG1 activates NOTCH4 under disturbed flow; no direct binding in our evidence.","interaction_type":"functional only","direction_and_effect":"Disturbed flow activated JAG1-NOTCH4 signalling in porcine and murine arteries and cultured human coronary artery endothelial cells [PMID:36044575]. Endothelial Jag1 deletion reduced atherosclerosis at disturbed-flow sites [PMID:36044575]. In cells under low oscillatory shear stress, N4ICD activation fell when JAG1 was blocked, but not when DLL4 was blocked [PMID:36044575]. Effect labelled agonist.","molecular_requirements":"Not reported in our evidence beyond JAG1 being the dominant ligand and NOTCH4 the dominant receptor in these cells [PMID:36044575].","affinity_potency":[],"species_and_systems":"Porcine and mouse arteries, human coronary artery endothelial cells [PMID:36044575]. The mouse pair is a separate record; the human pair is ortholog-inferred.","localisation_and_range":"JAG1 is flagged as transmembrane [flag]; this is an endothelial context.","caveats":"Only one paper, with no binding assay in the excerpts. A Reactome complex record exists [DB:Reactome]. The curator row was read as abstract although full text was available.","key_references":[{"PMID":"36044575","why":"JAG1-NOTCH4 mechanosensing in atherosclerosis"}],"covers":["LR000955","LR004378"]},"LR002836":{"pair":"JAM3 -> JAM3","headline":"JAM-C homophilic binding shown with purified protein and adhesion assays in human cells; mapped to the D1 Ig domain.","interaction_type":"direct binding","direction_and_effect":"Soluble JAM-C bound immobilised JAM-C in a purified system, JAM-C-transfected CHO cells adhered to immobilised JAM-C, and this mediated lung carcinoma NCI-H522 cell adhesion to JAM-C and to endothelial cells, blocked by soluble JAM-C or isolated D1 [PMID:16118203].","molecular_requirements":"Homophilic binding is mediated by the amino-terminal Ig domain D1, not D2; the E66R mutation in the Arg64-Ile65-Glu66 motif abolished it [PMID:16118203].","affinity_potency":[],"species_and_systems":"Human JAM-C; purified proteins, CHO transfectants, NCI-H522 cells and endothelial cells; abstract-only read. The mouse entry is ortholog-inferred.","localisation_and_range":"Contact-dependent between adjacent cells (tumour-endothelial); the entity flag marks JAM3 secreted [flag], not supported by the paper.","caveats":"Single paper, read as abstract. IntAct (protein array, solid phase assay) and Reactome (JAM3 dimerises) records agree [DB:IntAct, DB:Reactome]. A homodimer means ligand and receptor are the same chain. No affinity reported.","key_references":[{"PMID":"16118203","why":"Homophilic JAM-C binding and D1/E66 mapping"}],"covers":["LR002836","LR006073"]},"LR010819":{"pair":"KL -> FGFR4","headline":"Klotho engages FGFR4 as part of an FGF23 co-receptor complex; one structural paper (abstract) plus a PDB record.","interaction_type":"direct binding","direction_and_effect":"Klotho co-receptors simultaneously engage FGF hormones and their cognate FGFRs, stabilising the complex; the structure includes FGFR4 [PMID:37286607].","molecular_requirements":"Heparan sulfate proteoglycan is an additional required coreceptor for dimerisation/activation. The structure is a 1:2:1:1 FGF23-FGFR-alphaKlotho-heparan sulfate complex, and alphaKlotho does not directly recruit the secondary receptor [PMID:37286607].","affinity_potency":[],"species_and_systems":"Human proteins, cryo-EM structure with cell-based complementation experiments [PMID:37286607]. PDB 7YSW has KL and FGFR4 chains [DB:PDB 7YSW].","localisation_and_range":"Klotho is flagged as a receptor itself [flag]; membrane or shed form not distinguished in this dossier.","caveats":"Abstract only. The signalling ligand is FGF23 and KL is a co-receptor, so this is not a stand-alone ligand-receptor pair. No affinity reported in our evidence.","key_references":[{"PMID":"37286607","why":"Cryo-EM structure of FGF23-FGFR-alphaKlotho-heparan sulfate complexes"}],"covers":["LR010819"]},"LR006076":{"pair":"KLRG1 -> CDH1","headline":"KLRG1 binds E-cadherin and inhibits NK cytotoxicity; direct binding in mouse and human, plus a structure.","interaction_type":"direct binding","direction_and_effect":"KLRG1 is an inhibitory receptor; E-cadherin binding of KLRG1 prevented lysis of E-cadherin-expressing targets by KLRG1+ NK cells [PMID:16461340]. KLRG1 engagement inhibited cadherin-dependent adhesion and influenced dendritic cell cytokine secretion, and induced cadherin tyrosine phosphorylation, so signalling goes both ways [PMID:19855082].","molecular_requirements":"The first two extracellular domains of cadherin are sufficient to initiate KLRG1-dependent signalling [PMID:19855082].","affinity_potency":[],"species_and_systems":"Mouse KLRG1 tetramer expression cloning identified human E-cadherin as a xenogeneic ligand, and mouse E-cadherin as a syngeneic ligand, in BW5147 cells and reporter cells [PMID:16461340]. The human pair is ortholog-inferred and the mouse pair is direct [flag]. Species of the second paper are not reported in the abstract [PMID:19855082]. PDB 3FF7 and Reactome list the complex [DB:PDB 3FF7][DB:Reactome].","localisation_and_range":"Both are membrane proteins [flag]; interaction is by cell contact.","caveats":"No affinity in our evidence. The first paper is read in part from full text, the second as an abstract only. Binding was shown with a mouse probe, so the human-human interaction is inferred.","key_references":[{"PMID":"16461340","why":"Expression cloning of E-cadherin as KLRG1 ligand"},{"PMID":"19855082","why":"Bidirectional KLRG1-cadherin signalling"}],"covers":["LR002841","LR006076"]},"LR001873":{"pair":"KMT2E -> NCR2","headline":"NKp44L, a cell-surface MLL5 isoform, is reported as a ligand for NKp44; one abstract-read paper plus IntAct.","interaction_type":"direct binding","direction_and_effect":"NKp44L is identified as a cellular ligand for NKp44; anti-NKp44L antibodies sharply decreased NK lysis [PMID:23958951].","molecular_requirements":"The ligand is a novel isoform of the mixed-lineage leukemia-5 protein (NKp44L), not the canonical nuclear protein; surface localisation is associated with a specific C-terminal motif [PMID:23958951].","affinity_potency":[],"species_and_systems":"Human NK cells and tumor and transformed cells [PMID:23958951]. IntAct lists far western blotting and fluorescence microscopy [DB:IntAct].","localisation_and_range":"Cell-surface expressed unlike other MLL members, found on tumor and transformed cells and not on circulating cells from healthy individuals [PMID:23958951].","caveats":"Abstract only. The acting form is an isoform, so expression of canonical KMT2E would not indicate the ligand. No affinity reported.","key_references":[{"PMID":"23958951","why":"NKp44L isoform as NKp44 ligand"}],"covers":["LR001873"]},"LR004384":{"pair":"KNG1 -> BDKRB1","headline":"Kininogen-derived kinins activate B1R; structure and radioligand work, but the active ligand is a kinin peptide, not KNG1.","interaction_type":"direct binding","direction_and_effect":"Des-Arg10-kallidin activates B1R, and a G protein-coupled complex structure of human B1R bound to des-Arg10-kallidin is reported [PMID:34518695]. GtoPdb lists a full agonist [DB:GtoPdb].","molecular_requirements":"The acting ligand is a processed kinin peptide released from kininogen; the intact KNG1 protein as the ligand is not tested in our evidence [PMID:34518695][PMID:10422787].","affinity_potency":[{"value":"pKi 9.6-10.0","assay":"GtoPdb full agonist record","system":"not specified in dossier","cite":"PMID:10422787"}],"species_and_systems":"Human B1R in the structure [PMID:34518695]. Cloned rat and human B1R in COS-7 cells with [3H]des-Arg10-kallidin binding [PMID:10422787]. PDB 7EIB [DB:PDB 7EIB].","localisation_and_range":"KNG1 is secreted [flag]; kinins act as peptide hormones at a membrane GPCR [PMID:34518695].","caveats":"KNG1 itself is a precursor, so expression of KNG1 only indicates potential kinin supply after proteolysis. Four papers were abstract_insufficient and four pending. The pKi range is from GtoPdb, not from a paper in our dossier text.","key_references":[{"PMID":"34518695","why":"B1R structure with des-Arg10-kallidin"},{"PMID":"10422787","why":"Rat and human B1R pharmacology"}],"covers":["LR000962","LR004384"]},"LR000964":{"pair":"KNG1 -> GP1BA","headline":"Kininogen is reported to bind the platelet GP Ib-IX-V complex and restrict thrombin binding; one abstract-read paper.","interaction_type":"direct binding","direction_and_effect":"Kininogen did not inhibit thrombin-induced aggregation of Bernard-Soulier platelets, which lack GP Ib-IX-V, consistent with kininogen interacting with that complex and limiting thrombin access; this is an inhibition of thrombin binding, not a classic receptor activation [PMID:9269768].","molecular_requirements":"The binding site is in kininogen domain 3 (K270-G292); a heptapeptide L271-A277 is the minimal effective sequence [PMID:9269768]. The receptor is the whole GP Ib-IX-V complex, and GP1BA alone is not tested in our evidence.","affinity_potency":[],"species_and_systems":"Platelets, with recombinant K270-G292 polypeptide and a synthetic peptide [PMID:9269768]; species not reported in our evidence.","localisation_and_range":"KNG1 is secreted [flag]; platelet-surface receptor.","caveats":"Abstract only (partly truncated). The abstract says kininogen interacts 'either directly or indirectly' with the complex, so direct binding to GP1BA is not shown. Receptor complex subunits GP1BB, GP9 and GP5 are not examined.","key_references":[{"PMID":"9269768","why":"Kininogen and the platelet GP Ib-IX-V complex"}],"covers":["LR000964","LR004386"]},"LR004393":{"pair":"L1CAM -> ERBB2","headline":"Reciprocal co-IP in HEK293 cells shows L1CAM-erbB2 association; one paper, brain co-IP also positive.","interaction_type":"direct binding","direction_and_effect":"L1CAM co-immunoprecipitated with erbB2 and the reverse IP pulled down L1CAM, in HEK293 cells [PMID:22815787]. L1CAM binding to erbB enhances the response to neuregulins; effect labelled agonist [PMID:22815787].","molecular_requirements":"Different Ig-like domains of L1CAM can support erbB interaction [PMID:22815787]. Heterodimer partners of ERBB2 are not reported in our evidence.","affinity_potency":[],"species_and_systems":"Human L1CAM and erbB2 in HEK293 cells; L1CAM also co-IPs with erbB2 from brain extracts; mouse and rat tissue used [PMID:22815787]. Mouse pair is ortholog-inferred. BioGRID lists Affinity Capture-Western [DB:BioGRID].","localisation_and_range":"Cell-surface proteins in cis in axons [PMID:22815787]; L1CAM flagged secreted too [flag].","caveats":"Single paper; non-quantitative co-IP, no affinity; abstract-level label but full text excerpted.","key_references":[{"PMID":"22815787","why":"Co-IP of L1CAM with erbB2"}],"covers":["LR000971","LR004393"]},"LR002845":{"pair":"L1CAM -> ITGA2B","headline":"Direct heterophilic binding of L1 Ig6 (RGD) to alphaIIbbeta3 supports platelet adhesion; ITGA2B alone is a chain of that heterodimer.","interaction_type":"direct binding","direction_and_effect":"The sixth Ig-like domain of human L1 (L1-Ig6) functions as a heterophilic ligand for integrins including alphaIIbbeta3, supporting rapid attachment of activated human platelets [PMID:9396761]. Adhesion-promoting (agonist-like).","molecular_requirements":"Binding needs the single RGD motif in L1-Ig6; mutation abrogated it, and a RGD peptide blocked it. Evidence concerns the alphaIIbbeta3 heterodimer, so ITGA2B alone is chain-level only; ITGB3 is also required [PMID:9396761].","affinity_potency":[],"species_and_systems":"Human L1-Ig6 and human integrins, cell adhesion assays with human platelets; abstract read, though dossier lists full text [PMID:9396761]. Mouse pair is ortholog-inferred.","localisation_and_range":"Cell-contact adhesion; L1 de novo expression on blood vessels in neoplastic and inflammatory disease is noted by the curator [PMID:9396761]. ITGA2B has no secreted flag [flag].","caveats":"Single paper, no affinity; use the ITGA2B:ITGB3 complex row for scoring.","key_references":[{"PMID":"9396761","why":"L1-Ig6 RGD binds alphaIIbbeta3"}],"covers":["LR002845","LR006080"]},"LR007048":{"pair":"L1CAM -> ITGA2B:ITGB3","headline":"One paper shows L1-Ig6 RGD-dependent binding of alphaIIbbeta3 and platelet adhesion.","interaction_type":"direct binding","direction_and_effect":"L1-Ig6 acts as a heterophilic ligand for alphaIIbbeta3; the interaction supported rapid attachment of activated human platelets [PMID:9396761].","molecular_requirements":"RGD-dependent: mutating the single RGD in L1-Ig6 abrogated binding; beta3 integrin binding occurred with Ca2+, Mg2+ or Mn2+ [PMID:9396761]. Both ITGA2B and ITGB3 form the receptor.","affinity_potency":[],"species_and_systems":"Human L1-Ig6 and integrins; activated human platelets [PMID:9396761].","localisation_and_range":"Cell-contact adhesion with platelets [PMID:9396761].","caveats":"Single paper, abstract-level read; no affinity; hierarchy suggests alphaIIbbeta3 binds when active.","key_references":[{"PMID":"9396761","why":"Integrin hierarchy and platelet adhesion to L1-Ig6"}],"covers":["LR007048"]},"LR000973":{"pair":"L1CAM -> ITGA5","headline":"Direct L1-alpha5beta1 binding shown in ELISA with purified integrins (FN3) and RGD-dependent Ig6 adhesion; supported across three papers.","interaction_type":"direct binding","direction_and_effect":"Purified alphaVbeta3 and alpha5beta1 bound L1 FN3 directly in ELISA [PMID:10871287]. VLA-5 (alpha5beta1) bound murine L1 in cell aggregation and binding assays [PMID:8557754]. L1-Ig6 supported alpha5beta1-mediated adhesion; effect labelled agonist [PMID:9396761].","molecular_requirements":"Two sites: RGD-independent FN3 binding requiring FN3 multimers [PMID:10871287], and RGD-dependent Ig6 binding, beta1 integrins needing Mn2+ and inhibited by Ca2+ [PMID:9396761]. alpha5 pairs with beta1 here.","affinity_potency":[],"species_and_systems":"Purified human/unspecified proteins in ELISA [PMID:10871287]; mouse L1 on mouse and human cells and platelets [PMID:8557754]; human L1-Ig6 [PMID:9396761]. Mouse pair is ortholog-inferred.","localisation_and_range":"Cell-contact adhesion; thymocyte and platelet binding assays [PMID:8557754].","caveats":"Hierarchy alphavbeta3 or active alphaIIbbeta3 > alphavbeta1 > alpha5beta1 suggests weakest of the three [PMID:9396761]. 8557754 and 9396761 were abstract only; no affinity values.","key_references":[{"PMID":"10871287","why":"ELISA direct binding of purified alpha5beta1 to L1 FN3"},{"PMID":"8557754","why":"VLA-5 binds murine L1"},{"PMID":"9396761","why":"L1-Ig6 RGD-dependent integrin binding"}],"covers":["LR000973","LR004395"]},"LR006085":{"pair":"L1CAM -> NRP1","headline":"Specific trans binding of L1 to neuropilin-1 mapped to L1 Ig domain 1; one abstract-only paper plus database records.","interaction_type":"direct binding","direction_and_effect":"L1 binds NP-1 in trans, not L1 or other Ig CAMs, converting Sema3A-induced repulsion to attraction and activating the NO/cGMP pathway [PMID:12456642]. Soluble L1 acts as a modulator of the Sema3A receptor.","molecular_requirements":"Binding site is a restricted sequence of L1 Ig domain 1; a pathological L1 missense mutation disrupts L1-NP-1 complex formation and Sema3A reversion [PMID:12456642]. Reactome lists L1:NRP1 and a binding reaction [DB:Reactome R-HSA-374580]; BioGRID lists Reconstituted Complex [DB:BioGRID].","affinity_potency":[],"species_and_systems":"Axon guidance assays with L1 constructs; species not reported in our evidence [PMID:12456642]. Mouse pair is ortholog-inferred.","localisation_and_range":"Trans binding at the membrane; soluble L1 also acts [PMID:12456642]; L1CAM flagged secreted [flag].","caveats":"Abstract only; no affinity values.","key_references":[{"PMID":"12456642","why":"Trans binding of L1 to NP-1 and site mapping"}],"covers":["LR002850","LR006085"]},"LR010792":{"pair":"LAMA1 -> ITGA7:ITGB1","headline":"Alpha7beta1 is described as a laminin-1 receptor, supported by functional adhesion and migration work; abstract-only.","interaction_type":"functional only","direction_and_effect":"Alpha7 transfectants gained motility on laminin-1/E8, and deleting the alpha7 cytoplasmic domain preserved adhesion but abolished motility and lamellipodia formation [PMID:11278916].","molecular_requirements":"Complex receptor ITGA7:ITGB1; the alpha7 cytoplasmic domain is needed for migration signalling but not adhesion or heterodimer assembly [PMID:11278916].","affinity_potency":[],"species_and_systems":"Human HEK293 alpha7 transfectants and myoblasts [PMID:11278916].","localisation_and_range":"Ligand flagged secreted [flag]; complex flagged transmembrane [flag].","caveats":"Abstract only; laminin-1 is a heterotrimer so the assay cannot isolate LAMA1. The receptor-identity statement is background. A BioGRID record concerns LAMA1-ITGB1 only [DB:BioGRID 315221].","key_references":[{"PMID":"11278916","why":"Adhesion and migration on laminin-1/E8 via alpha7beta1"}],"covers":["LR010792"]},"LR000982":{"pair":"LAMA1 -> ITGB8","headline":"Beta8-containing integrins mediate chick neuron interaction with laminin-1; functional, abstract-only, and by homology.","interaction_type":"functional only","direction_and_effect":"An anti-beta8 extracellular domain antibody blocked chick sensory neuron interactions with laminin-1, collagen IV and fibronectin, identifying the first ligands for beta8 integrins [PMID:7542940]. Record labelled Stimulatory [flag].","molecular_requirements":"Beta8-containing heterodimers mediate the interaction; the alpha partner is not specified in our evidence [PMID:7542940].","affinity_potency":[],"species_and_systems":"Chick embryonic sensory neurons; the human and mouse pairs are ortholog-inferred [PMID:7542940].","localisation_and_range":"Ligand flagged secreted [flag]; matrix ligand.","caveats":"Abstract only; laminin-1 is a heterotrimer, so LAMA1 cannot be separated from its partner chains, and the integrin was stored per subunit instead of as a complex. No binding affinity reported.","key_references":[{"PMID":"7542940","why":"Beta8 integrins mediate neuron interaction with laminin-1"}],"covers":["LR000982","LR004403"]},"LR002854":{"pair":"LAMA3 -> ITGA3","headline":"Recombinant alpha3beta1 binds laminin-332 with Kd 14 nM; one full-text paper.","interaction_type":"direct binding","direction_and_effect":"Recombinant alpha3beta1 binds laminin-332 in solid-phase assay [PMID:16413178]. Labelled Stimulatory [flag].","molecular_requirements":"The receptor is the alpha3beta1 heterodimer; laminin-332 was recognised by alpha3- and alpha6-containing integrins but not alpha7-containing ones [PMID:16413178].","affinity_potency":[{"value":"Kd 14 nM","assay":"solid-phase saturation binding","system":"recombinant human alpha3beta1 ectodomain with laminin-332","cite":"PMID:16413178"}],"species_and_systems":"Human recombinant integrins [PMID:16413178]; mouse is listed as a separate non-inferred pair.","localisation_and_range":"Ligand flagged secreted; matrix ligand.","caveats":"Evidence is for the assembled laminin heterotrimer, not the single alpha chain alone [PMID:16413178]. Five other papers were abstract_insufficient.","key_references":[{"PMID":"16413178","why":"Kd 14 nM for alpha3beta1 and laminin-332"}],"covers":["LR002854","LR006088"]},"LR000991":{"pair":"LAMA4 -> ITGA6","headline":"Antibody-blocking adhesion data implicate alpha6 integrin in cell adhesion to laminin-8 and LAMA4; functional only.","interaction_type":"functional only","direction_and_effect":"Platelet adhesion to purified platelet laminin-8 (alpha4beta1gamma1) was largely inhibited by antibodies to beta1 and alpha6 integrin chains [PMID:10585296]. Endothelial adhesion to the alpha4 G domain was blocked by combined anti-alpha3 and alpha6 antibodies [PMID:12454288]. Stimulatory per interaction record [flag].","molecular_requirements":"alpha6beta1 is implicated as a pair; alpha3 and alpha6 act together in the endothelial assay [PMID:10585296][PMID:12454288].","affinity_potency":[],"species_and_systems":"Human platelets and endothelial cells [PMID:10585296][PMID:12454288]","localisation_and_range":"LAMA4 flagged secreted [flag]; laminin-8 is released by activated platelets [PMID:10585296].","caveats":"Antibody blocking is indirect; Both papers were read from abstracts only. In the 12454288 abstract, alpha6beta1 is said to function cooperatively, not to bind with measured high affinity. One paper was review-only.","key_references":[{"PMID":"10585296","why":"Platelet adhesion to laminin-8 blocked by anti-alpha6"},{"PMID":"12454288","why":"alpha3/alpha6 antibodies block adhesion to alpha4 G domain"}],"covers":["LR000991","LR004410"]},"LR006094":{"pair":"LAMA4 -> ITGB3","headline":"Recombinant laminin alpha4 G domain binds integrin alphavbeta3 with high affinity; one abstract-level paper.","interaction_type":"direct binding","direction_and_effect":"alphavbeta3 integrin bound with high affinity to G(919-1207) of laminin alpha4, and function-blocking antibodies to alphavbeta3 reduced endothelial attachment [PMID:12454288].","molecular_requirements":"Receptor tested is the alphavbeta3 heterodimer, so ITGB3 alone is not shown to suffice; ligand is a G-domain fragment [PMID:12454288].","affinity_potency":[{"value":"half-maximal at 1.4 nM","assay":"endothelial cell adhesion to G(919-1207) (adhesion, not Kd)","system":"endothelial cells","cite":"PMID:12454288"}],"species_and_systems":"Endothelial cells and recombinant protein [PMID:12454288].","localisation_and_range":"LAMA4 flagged secreted; ITGB3 not secreted [flag].","caveats":"Abstract only; no binding Kd quoted.","key_references":[{"PMID":"12454288","why":"alphavbeta3 binds alpha4 G domain"}],"covers":["LR002860","LR006094"]},"LR002863":{"pair":"LAMA5 -> ITGA7","headline":"Laminin alpha5 (as laminin-511/521) binds integrin alpha7X1beta1 with Kd 1.2 nM in one recombinant-binding study.","interaction_type":"direct binding","direction_and_effect":"Laminin-511/521 bound recombinant integrin alpha7X1beta1 [PMID:16413178]. Effect annotation is not given for this row.","molecular_requirements":"Heterotrimer ligand and alpha7beta1 heterodimer receptor were used; single chains were not tested [PMID:16413178]. The alpha7X2beta1 splice variant did not give a determinable Kd with laminin-511/521 in the table (ND(+)) [PMID:16413178].","affinity_potency":[{"value":"Kd 1.2 nM","assay":"solid-phase saturation binding, recombinant integrin ectodomain to purified laminin isoforms (laminin-511/521 vs alpha7X1beta1)","system":"human recombinant proteins","cite":"PMID:16413178"}],"species_and_systems":"Human recombinant proteins [PMID:16413178]; mouse pair ortholog-inferred.","localisation_and_range":"LAMA5 is flagged secreted [flag] and ITGA7 is flagged as a receptor [flag]; beyond these annotation flags, range is not reported in our evidence.","caveats":"A single paper supports this pair, and the Kd applies to the alpha7X1 splice variant with the beta1 partner.","key_references":[{"PMID":"16413178","why":"Recombinant alpha7beta1 binding to laminin-511/521"}],"covers":["LR002863","LR006097"]},"LR011395":{"pair":"LAMB3 -> ITGA7:ITGB1","headline":"No paper verifies LAMB3 with ITGA7:ITGB1; the only database record concerns alpha2beta1.","interaction_type":"database-asserted only","direction_and_effect":"Only Reactome integrin alpha2beta1 binding laminin-332 is recorded [DB:Reactome R-HSA-349626]; it does not name alpha7beta1.","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Species and system not reported in our evidence.","localisation_and_range":"Ligand is annotated as secreted [flag]; the receptor is annotated as a receptor [flag]. Matrix versus soluble range is not reported in our evidence.","caveats":"No paper in our evidence verifies this pair as listed; support rests on the database record alone. Two papers were abstract_insufficient, one pending, one different_entity.","key_references":[],"covers":["LR011395"]},"LR004429":{"pair":"LAMC1 -> ITGA7","headline":"LAMC1 (in laminin-211/221 and laminin-1/2) binds integrin alpha7 with Kd 0.64 nM; assembled-laminin evidence.","interaction_type":"direct binding","direction_and_effect":"Laminin-211/221 bound recombinant alpha7X1beta1 in solid-phase assays [PMID:16413178]. Alpha7beta1 is described as a receptor for laminin-1 and -2 mediating myoblast migration on laminin [PMID:11278916]. Annotated effect is Stimulatory [flag].","molecular_requirements":"Binder is the alpha7beta1 heterodimer and ligand the assembled heterotrimer; single chains were not tested [PMID:16413178]. For PMID:11278916 the curator notes the assay cannot separate the chains of laminin-1 and -2.","affinity_potency":[{"value":"Kd 0.64 nM","assay":"solid-phase saturation binding, recombinant integrin ectodomain to purified laminin isoform; alpha7X1beta1 vs laminin-211/221","system":"recombinant human integrin, purified laminin","cite":"PMID:16413178"}],"species_and_systems":"Recombinant human proteins [PMID:16413178]; transfected HEK293 cells in PMID:11278916 (abstract only). Mouse pair is projected from human.","localisation_and_range":"Ligand is annotated as secreted [flag]; the receptor is annotated as a receptor [flag]. Matrix versus soluble range is not reported in our evidence.","caveats":"Kd values are for the whole laminin heterotrimer, not the single chain. The second paper was read as abstract only and is largely about alpha7 cytoplasmic-domain signalling.","key_references":[{"PMID":"16413178","why":"Kd for alpha7X1beta1 vs laminin-211/221"},{"PMID":"11278916","why":"alpha7beta1 as laminin-1/-2 receptor in myoblast motility, abstract only"}],"covers":["LR001011","LR004429"]},"LR002872":{"pair":"LAMC1 -> PTPRF","headline":"Laminin-nidogen complex binds the PTPRF (LAR) FnIII domain 5 in GST pulldowns; LAMC1 is a chain-level proxy.","interaction_type":"direct binding","direction_and_effect":"Laminin-nidogen was identified as a ligand for LAR-FnIII domain 5 [PMID:9647658]. Cross-linking LAR with antibody inhibited laminin-nidogen-induced cell processes in HeLa cells by 97% [PMID:9647658].","molecular_requirements":"Binding needs the Fn5 domain without the alternatively spliced exon 13 (Fn5-); inclusion of the exon disrupted binding, though some low-affinity binding of Fn5+ was seen at high concentration [PMID:9647658]. Purified laminin-nidogen bound Fn5- dose-dependently; the authors say they cannot specify the binding site on the complex or whether laminin binds directly, rather than through a bridge, from the conditioned-media experiments alone [PMID:9647658].","affinity_potency":[],"species_and_systems":"GST-LAR fusion proteins with media from human U373 MG cells or purified laminin-nidogen; functional readout in human HeLa cells [PMID:9647658].","localisation_and_range":"PTPRF is flagged transmembrane and LAMC1 secreted [flag]; the ligand acts as an extracellular matrix complex.","caveats":"The evidence is for the laminin-nidogen complex, not LAMC1 alone; no affinity reported; abstract was the curated read though full text is available.","key_references":[{"PMID":"9647658","why":"Laminin-nidogen binds LAR-FnIII domain 5, splice-regulated"}],"covers":["LR002872","LR006106"]},"LR004438":{"pair":"LEFTY2 -> ACVR2B","headline":"Lefty2 antagonism via ActRIIB rests on a mouse genetic interaction and a rescue experiment, read from an abstract only.","interaction_type":"functional only","direction_and_effect":"Antagonist of Nodal signalling; Lefty inhibition was rescued by excess ActRIIA or ActRIIB, and a genetic interaction between lefty2 and ActRIIB was shown in mouse [PMID:11952836].","molecular_requirements":"ActRIIA or ActRIIB can act as the type II receptor, with ALK4 as type I and Cripto as membrane-bound co-receptor for Nodal [PMID:11952836].","affinity_potency":[],"species_and_systems":"Frog animal caps, mouse genetics, chick embryos. The human pair is ortholog-inferred [PMID:11952836].","localisation_and_range":"Ligand flagged secreted, receptor transmembrane [flag]. Lefty diffused faster than Nodal in chick embryos [PMID:11952836].","caveats":"No direct binding is shown; competitive binding is the authors' suggestion. Abstract-only read; no database records. The pair record carries a Stimulatory modulatory effect, which conflicts with the antagonist direction in the paper.","key_references":[{"PMID":"11952836","why":"Genetic interaction lefty2/ActRIIB in mouse; competitive-binding model"}],"covers":["LR001020","LR004438"]},"LR002881":{"pair":"LGALS3 -> ENG","headline":"Galectin-3 co-immunoprecipitates and co-localises with endoglin; identified in a protein microarray screen, abstract read only.","interaction_type":"direct binding","direction_and_effect":"Soluble endoglin bound galectin-3 with high affinity in a microarray of more than 9000 human proteins; endoglin co-immunoprecipitated and co-localised with galectin-3 in endothelial and CHO cells [PMID:31540324]. Functional effect not reported in our evidence.","molecular_requirements":"Soluble endoglin used as bait; whether the membrane form or co-receptors matter is not reported in our evidence [PMID:31540324].","affinity_potency":[],"species_and_systems":"Human endothelial cells and Chinese hamster ovary cells; recombinant soluble endoglin [PMID:31540324]. Mouse pair ortholog-inferred.","localisation_and_range":"Galectin-3 flagged secreted; endoglin proteolytically released as soluble form per the paper [PMID:31540324].","caveats":"No affinity number or direction reported; co-IP and co-localisation do not prove direct contact; abstract-only read.","key_references":[{"PMID":"31540324","why":"Endoglin interactome screen identifies galectin-3 as binder"}],"covers":["LR002881","LR006115"]},"LR002890":{"pair":"LGALS3 -> TYRO3","headline":"Exogenous galectin-3 stimulates TYRO3 phosphorylation in human cancer cells, but not AXL; one paper, evidence is functional.","interaction_type":"functional only","direction_and_effect":"Exogenous Gal-3 rapidly stimulated Tyro3 phosphorylation to the same extent as ProS1, but not Axl; it also activated Erk and Akt, protected from staurosporine-induced apoptosis and stimulated migration (agonist) [PMID:32664510].","molecular_requirements":"Selective for TYRO3 over AXL in cells; no co-receptor requirement reported in our evidence [PMID:32664510].","affinity_potency":[],"species_and_systems":"Human cancer lines SCC-25 (Tyro3 and Axl) and MGH-U3 (Tyro3 only) [PMID:32664510]. Mouse pair is ortholog-inferred.","localisation_and_range":"Galectin-3 has a secreted flag [flag]; added as exogenous protein to cells [PMID:32664510].","caveats":"Curated as direct binding, but the abstract reports receptor phosphorylation, not a binding measurement; the full text was available but excerpts are not shown here. Gal-3 was previously reported as a MerTK ligand (background). No affinity reported.","key_references":[{"PMID":"32664510","why":"Gal-3 stimulates Tyro3 phosphorylation and Erk signalling in human cancer cells"}],"covers":["LR002890","LR006124"]},"LR001882":{"pair":"LGALS9 -> HAVCR2","headline":"Galectin-9 reported as the Tim-3 ligand, with functional evidence and database support, but one UniProt entry notes a challenge.","interaction_type":"conflicting","direction_and_effect":"Galectin-9 induced Tim-3-dependent calcium flux, aggregation and death of Th1 cells in vitro, and in vivo administration selectively depleted IFN-gamma-producing cells and suppressed Th1 autoimmunity; curator labels it agonist [PMID:16286920]. Reactome lists the HAVCR2:LGALS9 complex at the plasma membrane [DB:Reactome].","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Human labelled for both partners by the curator; the abstract also reports in vivo administration, with species not stated in our evidence [PMID:16286920]. Mouse pair is separate and not ortholog-inferred.","localisation_and_range":"Galectin-9 flagged secreted, Tim-3 flagged transmembrane [flag]; Reactome places the complex at the plasma membrane [DB:Reactome].","caveats":"The paper is functional (Tim-3-dependent) and was read as abstract only. A UniProt entry on the HAVCR2 side-record says the function of Q8TDQ0 as a receptor for LGALS9 has been challenged [DB:UniProt]; note this accession is not identified in our evidence as HAVCR2. Two further rows were review-only.","key_references":[{"PMID":"16286920","why":"Identifies galectin-9 as the Tim-3 ligand"}],"covers":["LR001882","LR005224"]},"LR002908":{"pair":"LGALS9 -> PTPRC","headline":"Galectin-9 reported to engage CD45 within an inhibitory IgM-BCR complex in B cells; one abstract-only paper, indirect for CD45.","interaction_type":"functional only","direction_and_effect":"Galectin-9 relocalises IgM-BCR together with inhibitory CD45 and CD22, and exogenous galectin-9 nearly completely abolishes BCR signalling; curator labels it antagonist [PMID:30120235]. Excerpts say a pull-down with recombinant galectin-9 followed by mass spectrometry was used to find binders, under a heading 'Galectin-9 binds IgM-BCR and CD45' [PMID:30120235].","molecular_requirements":"Acts alongside IgM-BCR and CD22 in the complex [PMID:30120235].","affinity_potency":[],"species_and_systems":"B cells; excerpts mention mouse strains including Lgals9 knockout, though curator labels human [PMID:30120235]. Human pair is ortholog-inferred.","localisation_and_range":"Galectin-9 flagged secreted and found on the B-cell surface; CD45 flagged transmembrane [flag][PMID:30120235].","caveats":"Same paper as the IgM row; the cited evidence sentence concerns IgM-BCR, not CD45, and the abstract only mentions CD45 as relocalised. No affinity; no database support.","key_references":[{"PMID":"30120235","why":"Galectin-9 relocalises BCR with CD45/CD22, suppressing signalling"}],"covers":["LR002908","LR006135"]},"LR001891":{"pair":"LGI4 -> ADAM11","headline":"LGI4 binds ADAM11 moderately in cell-ELISA; ADAM22 is its strongest partner. Two confirming papers.","interaction_type":"direct binding","direction_and_effect":"LGI4 interacts with ADAM11 as well as ADAM22 and ADAM23 in cell-based binding assays [PMID:18974846]. Functional effect on ADAM11 is not reported in our evidence; the authors speculate ADAM11 may be supportive or a negative regulator and note ADAM11-deficient mice lacked myelination defects [PMID:18974846].","molecular_requirements":"Binding was measured with ADAM-expressing cells; no co-receptor requirement for ADAM11 is reported in our evidence. Reactome lists an LGI4:ADAM22,11,23 complex at the plasma membrane [DB:Reactome].","affinity_potency":[],"species_and_systems":"Cell-ELISA with mouse LGI4 and mouse ADAMs [PMID:18974846]; the dossier lists the experiment species as human. The human pair is ortholog-inferred, the mouse pair is not.","localisation_and_range":"LGI4 is secreted and ADAM11 is not flagged secreted [flag]; ADAM11 is a cell-surface receptor in the ADAM family.","caveats":"Binding to ADAM11 was moderate, weaker than to ADAM22 [PMID:18974846]. The main paper was read as an abstract plus full-text excerpts; the second is an unverified browser-read sentence [PMID:20220021]. No affinity value is reported.","key_references":[{"PMID":"18974846","why":"Cell-ELISA showing LGI4 binds ADAM11, ADAM22 and ADAM23"},{"PMID":"20220021","why":"Reports Lgi4 binding to Adam11 and Adam23 in addition to Adam22 (browser-read)"}],"covers":["LR001891","LR005233"]},"LR004447":{"pair":"LPL -> LRP2","headline":"LPL binds purified human and rat gp330/LRP2 with nanomolar affinity in one abstract-only paper.","interaction_type":"direct binding","direction_and_effect":"Purified gp330 bound LPL with high affinity; binding was saturable, divalent-cation dependent and inhibited by heparin or RAP [PMID:7686151]. LPL promoted in vitro binding of 125I-lipoproteins to gp330 [PMID:7686151].","molecular_requirements":"Not reported in our evidence beyond cation dependence and inhibition by heparin or RAP [PMID:7686151].","affinity_potency":[{"value":"Kd = 6.1 nM","assay":"in vitro binding to purified receptor","system":"human gp330","cite":"PMID:7686151"},{"value":"2.7 nM","assay":"in vitro binding to purified receptor","system":"rat gp330","cite":"PMID:7686151"}],"species_and_systems":"Purified human and rat gp330 in vitro [PMID:7686151]. The mouse pair is ortholog-inferred.","localisation_and_range":"LPL is annotated secreted [flag]. gp330 is a cell-surface protein in clathrin-coated pits [PMID:7686151].","caveats":"Single paper, abstract only. Binding to purified protein; cellular function not shown in our evidence. gp330 did not bind alpha2-macroglobulin-protease complex or Pseudomonas exotoxin A [PMID:7686151].","key_references":[{"PMID":"7686151","why":"gp330 binds LPL with Kd 6.1 nM (human) and 2.7 nM (rat)"}],"covers":["LR001033","LR004447"]},"LR006139":{"pair":"LRFN4 -> PTPRD","headline":"LRFN4 (SALM3) binds LAR-family RPTPs including PTPRD in a splice-dependent trans-synaptic interaction; one paper, plus Reactome.","interaction_type":"direct binding","direction_and_effect":"SALM3 interacts with and requires all three LAR-RPTPs (LAR, PTP-sigma, PTP-delta) for presynaptic differentiation [PMID:26321637]. The interaction needs the mini-exon B insert in the LAR-RPTP [PMID:26321637]. Reactome lists SALM3 binding LAR-RPTP [DB:Reactome].","molecular_requirements":"LAR-RPTPs containing meB alone bound SALM3, those with only meA or neither did not; adding meA to meB increased binding. Ig1-3 domains of PTP-delta were sufficient [PMID:26321637].","affinity_potency":[],"species_and_systems":"Paper reports mouse SALM3 and mouse PTP-delta in its assays; dossier species fields say human and the mouse pair is ortholog-inferred [PMID:26321637]. Cell-binding and co-culture assays, plus Salm3 knockout mice [PMID:26321637].","localisation_and_range":"Both flagged transmembrane for the pair, so contact-dependent trans-synaptic adhesion [flag][PMID:26321637].","caveats":"Evidence is family-level for all LAR-RPTPs; pair-specific data for PTPRD are not separated in our evidence. Evidence names PTP-delta explicitly in the notes and excerpts. Affinity not reported in our evidence.","key_references":[{"PMID":"26321637","why":"SALM3 binds LAR-RPTPs in a meB-dependent manner"}],"covers":["LR002914","LR006139"]},"LR002917":{"pair":"LRFN5 -> PTPRD","headline":"LRFN5 (SALM5) binds LAR-RPTPs including PTPRD via Ig domains; one paper, with 8.96 nM Kd measured for LAR.","interaction_type":"direct binding","direction_and_effect":"SALM5 interacts with the Ig domains of LAR-RPTPs (LAR, PTP-delta, PTP-sigma) [PMID:27225731]. PTP-delta and PTP-sigma interacted with SALM5 in cell aggregation assays [PMID:27225731]. Assay detail reports a stimulatory effect on presynaptic differentiation in contacting axons, with the interaction strongly inhibited by splice insert B [PMID:27225731].","molecular_requirements":"The three LAR Ig domains were sufficient for SALM5 binding; the FNIII region did not bind. The interaction was calcium-insensitive [PMID:27225731]. Other SALMs did not interact with LAR in cell aggregation assays [PMID:27225731].","affinity_potency":[{"value":"Kd 8.96 \u00b1 0.92 nM","assay":"Scatchard analysis of LAR-Ecto-Fc binding","system":"SALM5-expressing HEK293T cells; measured for LAR, not PTPRD","cite":"PMID:27225731"}],"species_and_systems":"HEK293T cell aggregation and soluble-binding assays, cocultured hippocampal neurons [PMID:27225731].","localisation_and_range":"Both partners flagged not secreted; transmembrane, so trans-synaptic contact adhesion [flag][PMID:27225731].","caveats":"Affinity was measured for LAR only; PTPRD was shown by cell aggregation only [PMID:27225731]. Record is labelled abstract-only although full-text excerpts exist.","key_references":[{"PMID":"27225731","why":"SALM5 binds LAR-RPTP Ig domains; Kd for LAR 8.96 nM"}],"covers":["LR002917","LR006142"]},"LR006148":{"pair":"LRIG2 -> PDGFRB","headline":"LRIG2 co-immunoprecipitates with PDGFR-beta and enhances its signalling in glioblastoma cells; a single paper plus one IntAct record.","interaction_type":"direct binding","direction_and_effect":"LRIG2 physically interacts with PDGFR-beta, promoting its total expression and activation and enhancing Akt and STAT3 signalling and cell-cycle effectors [PMID:30015847]. Curators label the effect agonist [PMID:30015847].","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Human glioblastoma cells, in vitro and in vivo, with PDGF-BB stimulation [PMID:30015847]. IntAct lists an anti-bait co-IP from the same paper [DB:IntAct]. The mouse pair is ortholog-inferred.","localisation_and_range":"LRIG2 is annotated non-secreted [flag]; PDGFR-beta is annotated transmembrane [flag]. Range is not discussed in our excerpts.","caveats":"The paper itself notes that Lrig2 had no effect on PDGFR levels or phosphorylation in mouse embryonic fibroblasts, so the effect may be tumour-cell specific [PMID:30015847]. Evidence is co-IP in cells, not purified-protein binding, and the sole IntAct record cites the same paper.","key_references":[{"PMID":"30015847","why":"LRIG2-PDGFR-beta interaction and enhanced signalling in GBM cells"}],"covers":["LR002923","LR006148"]},"LR005239":{"pair":"LRRC4B -> PTPRF","headline":"NGL-3 (LRRC4B) binds LAR (PTPRF) trans-synaptically to drive bidirectional synapse formation; supported by three papers and Reactome.","interaction_type":"direct binding","direction_and_effect":"NGL-3 and LAR in heterologous cells induced pre- and postsynaptic differentiation in contacting rat hippocampal neurons; NGL-3 knockdown reduced excitatory synapse number and function, and soluble LAR reduced NGL-3-induced presynaptic differentiation [PMID:19252495]. Curators label it agonist [PMID:19252495].","molecular_requirements":"The NGL-3 LRR domain (nine LRRs) binds the first two FNIII domains of LAR, and Gln-96 in the first LRR is critical for LAR binding and presynaptic induction [PMID:20139422]. In a cell aggregation assay, NGL-3 cells adhered strongly to LAR cells [PMID:23345436].","affinity_potency":[],"species_and_systems":"Rat hippocampal neurons and heterologous cells [PMID:19252495]; mouse L-cells for aggregation [PMID:23345436]. Reactome lists the complex [DB:Reactome]. The human pair is not ortholog-inferred; mouse is.","localisation_and_range":"Membrane-bound, contact-dependent trans-synaptic adhesion; LRRC4B is flagged non-secreted [flag].","caveats":"No affinity in our evidence. 23345436 was read via browser and its quote is marked unverifiable pending spot-check; it cites the earlier work as consistent. Two further judged papers were review_only and one abstract_insufficient.","key_references":[{"PMID":"19252495","why":"Discovery of trans-synaptic NGL-3-LAR interaction with functional assays"},{"PMID":"20139422","why":"Maps LRR/FNIII interface and Gln-96"},{"PMID":"23345436","why":"Cell aggregation confirms NGL-3 adhesion to LAR"}],"covers":["LR001897","LR005239"]},"LR002926":{"pair":"LRRC4C -> NTNG1","headline":"NGL-1 (LRRC4C) binds netrin-G1 through its LRR region; supported by binding, structural database records and mouse genetics, direction is conventional.","interaction_type":"direct binding","direction_and_effect":"NGL-1 specifically interacts with netrin-G1 through its LRR region [PMID:14595443]. Surface-bound NGL-1 stimulates, but soluble NGL-1 disrupts, growth of embryonic thalamic axons [PMID:14595443]. Netrin-G1/NGL1 interactions specify excitatory synapses in mouse hippocampus, and NGL-KO phenocopies netrin-G-KO plasticity phenotypes [PMID:25411505]. Trans-synaptic adhesion between presynaptic netrin-G1 and postsynaptic NGL-1 induces a cis interaction of netrin-G1 with LAR and promotes presynaptic differentiation [PMID:23986473].","molecular_requirements":"The LRR region of NGL-1 mediates netrin-G1 binding [PMID:14595443]. In synapses a tripartite NGL-1, netrin-G1 and LAR complex is described [PMID:23986473].","affinity_potency":[],"species_and_systems":"Human NGL-1 was identified, with netrin-G1 expression studied in mouse thalamic axons [PMID:14595443]. Other papers used neurons or mouse hippocampus with knockout mice [PMID:23986473, PMID:25411505]. Database records include BioGRID Affinity Capture-Western, Reconstituted Complex and Co-crystal Structure, IntAct SPR, and PDB 3ZYJ [DB:BioGRID, DB:IntAct, DB:PDB 3ZYJ].","localisation_and_range":"LRRC4C is flagged transmembrane and NTNG1 secreted [flag]; the papers describe netrin-G1 as lipid-anchored and membrane-bound, and the interaction as trans-synaptic adhesion [PMID:14595443, PMID:23986473].","caveats":"Ligand/receptor direction is a naming convention; the curator notes NGL-1 is functionally the signal-receiving partner. All three papers were read as abstracts only. No affinity value is reported in our evidence.","key_references":[{"PMID":"14595443","why":"identifies NGL-1 as netrin-G1 binding partner via LRR region"},{"PMID":"25411505","why":"in vivo KO evidence for netrin-G1/NGL1 synaptic specificity"},{"PMID":"23986473","why":"trans-synaptic adhesion and cis LAR interaction"}],"covers":["LR002926","LR006151"]},"LR006157":{"pair":"LRRTM2 -> NRXN3","headline":"LRRTM2 is reported to bind neurexin-3 lacking the S4 insert; support is one abstract-level paper's general statement.","interaction_type":"direct binding","direction_and_effect":"LRRTM2 binds neurexins 1, 2 and 3 alpha and beta variants specifically lacking an insert at splice site 4 [PMID:20519524].","molecular_requirements":"Neurexin must lack the S4 insert [PMID:20519524].","affinity_potency":[],"species_and_systems":"One paper, abstract only; species not specified. Orthology-projected mouse pair. No database records.","localisation_and_range":"Both partners flagged transmembrane [flag].","caveats":"The paper's evidence sentence names neurexin-1beta; NRXN3 rests on a general statement. Single abstract-read paper, no affinity reported.","key_references":[{"PMID":"20519524","why":"LRRTM2 binds neurexins 1-3 lacking S4"}],"covers":["LR002932","LR006157"]},"LR002935":{"pair":"LRRTM4 -> GPC3","headline":"LRRTM4 binds glypicans in a heparan sulfate-dependent manner, with GPC3 covered by a class-level result; one paper, mouse glypicans in HEK293T.","interaction_type":"direct binding","direction_and_effect":"Glypican binds LRRTM4, but not LRRTM2, in an HS-dependent manner [PMID:23911103]. LRRTM4-Fc strongly bound all glypican isoforms tested, and GPC1 and GPC3-6 were detected in the LRRTM4-Fc sample [PMID:23911103].","molecular_requirements":"Heparan sulfate on the glypican is required for binding [PMID:23911103]. Whether the core protein alone suffices is not reported in our evidence.","affinity_potency":[],"species_and_systems":"Cell surface binding used HA-tagged mouse glypican cDNAs in HEK293T cells; proteomics used rat brain [PMID:23911103]. Human and mouse pairs are orthology-projected. No database records.","localisation_and_range":"Glypican is described as a GPI-anchored HSPG [PMID:23911103]; GPC4 and LRRTM4 localise to pre- and postsynaptic membranes of excitatory synapses [PMID:23911103]. Annotation flag for GPC3 says not secreted [flag].","caveats":"Only one paper, read as abstract with excerpts. The curator notes the abstract names glypican generically, but the excerpts cover this paralog. No affinity reported.","key_references":[{"PMID":"23911103","why":"unbiased proteomics identifying glypican as LRRTM4 receptor"}],"covers":["LR002935","LR006160"]},"LR007345":{"pair":"LRRTM4 -> NRXN3","headline":"Rests on a single IntAct co-immunoprecipitation record only; no curator-verified paper.","interaction_type":"database-asserted only","direction_and_effect":"No curator-verified paper. The only record is an IntAct association detected by anti-tag coimmunoprecipitation [DB:IntAct].","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Not reported in our evidence beyond the IntAct record [DB:IntAct].","localisation_and_range":"Both partners flagged membrane-bound [flag].","caveats":"Support is one database record (curator outcome review_only, no judged papers). Coimmunoprecipitation does not show direct binding. Isoform or splice dependence is not reported.","key_references":[],"covers":["LR007345"]},"LR006166":{"pair":"LSR -> ACE2","headline":"LSR interacts with ACE2 in cis and trans and blocks Spike binding; one paper, functional and co-IP evidence.","interaction_type":"functional only","direction_and_effect":"LSR interacts with ACE2 in cis and in trans, preventing its binding to S protein and inhibiting viral entry and S protein-mediated cell-cell fusion; this makes it an antagonist of Spike-ACE2 binding rather than an activator [PMID:39443717]. Loss of LSR enhanced infection and exogenous LSR protected [PMID:39443717].","molecular_requirements":"Six LSR variants, CRD mutants and N- and C-terminal deletions were co-expressed with ACE2 in co-IP assays; which of them bind is not reported in our excerpts [PMID:39443717]. A small LSR-derived peptide blocked S-ACE2 binding in vitro [PMID:39443717].","affinity_potency":[],"species_and_systems":"Human cell lines (HEK293, Caco-2), intestinal organoids, ex vivo tissue and a humanized ACE2 mouse model [PMID:39443717]. BioGRID lists affinity capture-western [DB:BioGRID].","localisation_and_range":"Both flagged without a secretion flag [flag]; trans interaction was tested by co-culturing LSR and ACE2 cells, so cell-contact binding is supported [PMID:39443717].","caveats":"Direct binding between purified proteins is not reported; evidence is co-IP and pulldown in cells. Only one paper; the abstract was the curated read.","key_references":[{"PMID":"39443717","why":"LSR-ACE2 cis/trans interaction blocking Spike binding"}],"covers":["LR002941","LR006166"]},"LR011962":{"pair":"LTBP1 -> TGFB3","headline":"Database-only association of LTBP1 with TGF-beta-3 latent complex; no verified evidence.","interaction_type":"database-asserted only","direction_and_effect":"No verified paper (two pending). Reactome lists LTBP1,LTBP3:TGFB3:LAP3 in the extracellular region [DB:Reactome]. UniProt says LTBP1 regulates TGF-beta activation by maintaining it in an inactive state (text truncated) [DB:UniProt]. Annotated Inhibitory.","molecular_requirements":"Complex includes LAP3 [DB:Reactome]; further requirements not reported.","affinity_potency":[],"species_and_systems":"Not reported in our evidence.","localisation_and_range":"Both flagged secreted [flag]; TGFB3 also flagged transmembrane [flag].","caveats":"No papers verified; the pair is a latent-complex association, not receptor binding.","key_references":[],"covers":["LR011962"]},"LR002944":{"pair":"LY6H -> CD36","headline":"LY6H binds CD36 on cells in a CRISPRa screen follow-up; one full-text paper.","interaction_type":"direct binding","direction_and_effect":"Tetramerized LY6H (400 nM) stained CD36-transfected cells by flow cytometry, identifying CD36 as a receptor in a cell-based CRISPR activation screen [PMID:36178190]. Effect not reported in our evidence.","molecular_requirements":"Full-length CD36 transfected cells were used; other ligands including NRN1, VWC2L and SCRG1 also bound CD36 [PMID:36178190]. Subunit requirements not reported.","affinity_potency":[],"species_and_systems":"Cell-surface staining of CD36-transfected cells with SA-647 tetramerized ligand; species of the constructs labelled human [PMID:36178190].","localisation_and_range":"LY6H flagged not secreted, CD36 transmembrane [flag]; the screen used multimerized ligands.","caveats":"Evidence is cell staining, not purified-protein binding or affinity in our excerpts. Scavenger receptor CD36 binds multiple ligands [PMID:36178190], so specificity is a concern.","key_references":[{"PMID":"36178190","why":"CRISPRa screen identifies CD36 binding LY6H"}],"covers":["LR002944","LR006169"]},"LR010639":{"pair":"LY86 -> CD180","headline":"MD-1 (LY86) physically associates with RP105 (CD180); support is co-IP in mouse B cells and human cells.","interaction_type":"direct binding","direction_and_effect":"Mouse MD-1 is secreted but tethered to the cell surface by coexpressed RP105, confirmed by immunoprecipitation [PMID:9686597]. Human MD-1 is also associated with human RP105 and has an important role in cell surface expression of RP105 [PMID:9763566].","molecular_requirements":"MD-1 coexpression increased RP105-positive cells more than twice, and stable MD-1 expression gave about sevenfold more surface RP105 [PMID:9686597]. MD-1 is an accessory partner, not a signalling agonist.","affinity_potency":[],"species_and_systems":"Mouse B cells and transfected cells [PMID:9686597]; human MD-1 cDNA and human RP105 [PMID:9763566]. Curator species label for 9763566 is mouse. Structure available [DB:PDB 3B2D]; Reactome lists RP105:MD1 complex [DB:Reactome].","localisation_and_range":"MD-1 is secreted but tethered at the cell surface by RP105 [PMID:9686597].","caveats":"Abstracts only; co-IP shows association, not direct binding. No affinity. One row was unresolvable. UniProt says RP105 with MD-1 interacts with the TLR4 complex [DB:UniProt].","key_references":[{"PMID":"9686597","why":"Mouse MD-1 associates with RP105"},{"PMID":"9763566","why":"Human MD-1 associates with RP105"}],"covers":["LR010639"]},"LR004465":{"pair":"MATN1 -> ITGB1","headline":"Matrilin-1 adhesion is blocked by anti-beta1 antibody; functional evidence only, from one abstract-only paper.","interaction_type":"functional only","direction_and_effect":"Monoclonal antibody to integrin beta1 abolished CMP (matrilin-1)-induced cell adhesion and spreading [PMID:10196235].","molecular_requirements":"Beta1 is the likely partner of alpha1 (alpha1beta1); the alpha1 subunit co-precipitated labeled CMP, not beta1 [PMID:10196235].","affinity_potency":[],"species_and_systems":"Rabbit and human chondrocytes and fibroblasts on CMP-coated dishes [PMID:10196235]. Human and mouse pairs are ortholog-inferred.","localisation_and_range":"MATN1 is flagged secreted; ITGB1 flagged not secreted [flag]. Matrix adhesion.","caveats":"No direct binding to beta1 shown; antibody blockade only, abstract only, single paper. No database records.","key_references":[{"PMID":"10196235","why":"anti-beta1 blocks matrilin-1-induced adhesion"}],"covers":["LR001052","LR004465"]},"LR004474":{"pair":"MDK -> SDC1","headline":"Midkine binds syndecan-1 through its heparan sulfate and chondroitin sulfate chains; two abstract-only papers.","interaction_type":"direct binding","direction_and_effect":"Midkine bound both HS and CS chains of syndecan-1 by BIAcore [PMID:15226297]. Syndecan-1 isolated from 10-day rat fetus bound midkine strongly [PMID:9089390].","molecular_requirements":"Binding is glycosaminoglycan-mediated; the core protein also contributes for syndecan-1 [PMID:15226297]. CS removal changed association and dissociation rates, suggesting simultaneous HS and CS engagement [PMID:15226297].","affinity_potency":[],"species_and_systems":"Murine mammary epithelial cell syndecans with midkine (BIAcore) [PMID:15226297]; rat fetal syndecan-1 [PMID:9089390]. Curators record human ligand/receptor species, but the abstracts describe murine and rat material. Both species pairs are ortholog-inferred.","localisation_and_range":"Syndecan-1 is flagged secreted and transmembrane [flag]; the papers describe an ectodomain proteoglycan, so shed or membrane forms are both possible.","caveats":"Abstract-only reads. Syndecan-1 binding is a proteoglycan chain interaction and not a classic protein receptor; syndecan-3 and -4 bind similarly. No affinity reported.","key_references":[{"PMID":"15226297","why":"BIAcore: midkine binds HS and CS chains of syndecan-1"},{"PMID":"9089390","why":"Fetal rat syndecan-1 binds midkine"}],"covers":["LR001061","LR004474"]},"LR006175":{"pair":"MFAP5 -> NOTCH2","headline":"Bladder cancer paper reports CAF-derived MFAP5 directly interacting with NOTCH2 and activating it; abstract only.","interaction_type":"direct binding","direction_and_effect":"CAF-derived MFAP5 activated NOTCH2/HEY1 signalling through direct interaction with NOTCH2, stimulating N2ICD release; NOTCH2 knockdown or inactivating antibody NRR2Mab reversed MFAP5 effects in vitro and in vivo [PMID:32293074].","molecular_requirements":"Not reported beyond NOTCH2; MFAP5-mediated PI3K-AKT signalling activated a DLL4/NOTCH2 axis [PMID:32293074].","affinity_potency":[],"species_and_systems":"Human bladder cancer cells and cancer-associated fibroblasts, with in vivo tests [PMID:32293074]. Mouse pair is ortholog-inferred.","localisation_and_range":"MFAP5 is secreted by CAFs, paracrine to tumour cells [PMID:32293074].","caveats":"The abstract states 'direct interaction' without naming the assay; abstract only, no affinity. Possible involvement of DLL4 confounds ligand attribution.","key_references":[{"PMID":"32293074","why":"CAF-derived MFAP5 activates NOTCH2 via direct interaction"}],"covers":["LR002950","LR006175"]},"LR002953":{"pair":"MFGE8 -> ITGB5","headline":"Mouse RPE evidence that MFG-E8 ligates alphavbeta5 to drive rhythmic phagocytosis; abstract only.","interaction_type":"functional only","direction_and_effect":"MFG-E8 stimulates rhythmic POS phagocytosis by ligating apical alphavbeta5 receptors of the RPE [PMID:17620600]. Loss of MFG-E8, like loss of alphavbeta5, eliminated alphavbeta5 downstream signalling via MerTK [PMID:17620600].","molecular_requirements":"Acts through the alphavbeta5 heterodimer [PMID:17620600].","affinity_potency":[],"species_and_systems":"Mouse retinal pigment epithelium, MFG-E8-deficient mice [PMID:17620600]. Human pair is ortholog-inferred.","localisation_and_range":"Mfge8 is flagged secreted [flag]; alphavbeta5 sits on RPE apical microvilli [PMID:17620600].","caveats":"Functional (knockout) evidence, abstract only; retinal adhesion was only minimally reduced without MFG-E8.","key_references":[{"PMID":"17620600","why":"MFG-E8-alphavbeta5 signalling in RPE phagocytosis"}],"covers":["LR002953","LR006178"]},"LR009325":{"pair":"MFGE8 -> PDGFRB","headline":"MFG-E8 co-immunoprecipitates with PDGFRbeta after PDGF-BB in pericyte-like cells; likely indirect, one full-text paper.","interaction_type":"direct binding","direction_and_effect":"Coimmunoprecipitation showed transient MFG-E8 association with PDGFRbeta in PDGF-BB-treated 10T1/2 cells; MFG-E8 depletion enhanced PDGF-BB-dependent PDGFRbeta degradation and attenuated signalling [PMID:21868707]. BioGRID records Affinity Capture-Western [DB:BioGRID].","molecular_requirements":"MFG-E8 binding to cells depended on RGD and alphav; PDGFRbeta colocalisation was enhanced by PDGF-BB [PMID:21868707]. MFG-E8 modulates a PDGF-BB:PDGFRbeta signal, so PDGF-BB is required.","affinity_potency":[],"species_and_systems":"10T1/2 pericyte-like cells (siRNA and co-IP) [PMID:21868707]; curator species fields say human.","localisation_and_range":"MFG-E8 is flagged secreted and PDGFRB transmembrane [flag].","caveats":"Co-IP does not show direct binding; association is PDGF-BB-induced and probably runs through alphav integrin, so this is a modulator rather than a ligand.","key_references":[{"PMID":"21868707","why":"MFG-E8-PDGFRbeta co-IP and signalling modulation"}],"covers":["LR009325"]},"LR004483":{"pair":"MFNG -> NOTCH2","headline":"Manic fringe modifies Notch2 and reduces Jagged1 binding and signalling; enzyme-substrate, not a classic ligand.","interaction_type":"functional only","direction_and_effect":"Manic fringe decreased Jagged1 binding to Notch2 and Jagged1-triggered signalling, more than lunatic fringe, with no effect on Delta1 [PMID:11346656].","molecular_requirements":"Fringe is a glycosyltransferase acting on Notch2 EGF-repeat O-fucose; the two fringes act on different sites of the Notch2 extracellular region [PMID:11346656].","affinity_potency":[],"species_and_systems":"Human proteins in cell assays [PMID:11346656]. Human pair ortholog-inferred.","localisation_and_range":"MFNG is flagged secreted [flag]; it acts on the Notch ectodomain.","caveats":"Abstract only. It modulates Jagged1-Notch2 and is not itself an activating ligand, so it shouldn't be scored as a ligand-receptor pair in CCC tools.","key_references":[{"PMID":"11346656","why":"Manic fringe reduces Jagged1-Notch2 binding and signalling"}],"covers":["LR001070","LR004483"]},"LR006184":{"pair":"Mmp1a -> Lrp1","headline":"MMP-1 binds LRP1 with nanomolar affinity by SPR in two independent papers; binding is much stronger with TIMP complex; mouse pair projected from human.","interaction_type":"direct binding","direction_and_effect":"MMP-1 was identified as a new LRP1 ligand by SPR [PMID:32694578][PMID:32702237]. Binding was inhibited by RAP, indicating LRP1-specific binding, and uptake of MMP-1 by cells occurred only when complexed with TIMP-3 [PMID:32702237][PMID:32694578]. LRP1 acts as an endocytic scavenger receptor.","molecular_requirements":"Affinity depends on form: MMP-1 with TIMP-3 or TIMP-1 binds better than free MMP-1. MMP-1\u0394C alone had no detectable affinity, but bound with TIMP-3 (KD of 6.42 nM) [PMID:32694578]. Lysine residues on MMP-1 and TIMP-1 are required for LRP1 binding [PMID:32702237].","affinity_potency":[{"value":"KD 34.6 nM","assay":"SPR, free MMP-1","system":"purified proteins","cite":"PMID:32694578"},{"value":"KD 4.96 nM","assay":"SPR, MMP-1/TIMP-3 complex","system":"purified proteins","cite":"PMID:32694578"},{"value":"KD 19 \u00b1 1 nM","assay":"SPR bivalent model, proMMP-1","system":"purified proteins","cite":"PMID:32702237"},{"value":"KD 25 \u00b1 2 nM","assay":"SPR bivalent model, active MMP-1","system":"purified proteins","cite":"PMID:32702237"},{"value":"KD 0.6 \u00b1 0.2 nM","assay":"SPR bivalent model, MMP-1/TIMP-1 complex","system":"purified proteins","cite":"PMID:32702237"}],"species_and_systems":"Purified proteins by SPR, plus uptake in HTB94 chondrosarcoma-like cells [PMID:32694578]. The species of the proteins is not stated in the excerpts. No mouse experiment; the mouse pair is ortholog-inferred.","localisation_and_range":"Mmp1a is flagged as secreted [flag]; LRP1 mediates endocytosis of extracellular MMP-1.","caveats":"Both curator rows were read as abstract only, with full-text excerpts used here. Free MMP-1 binds with weaker affinity, so the physiological ligand may be the MMP-1/TIMP complex. Mouse pair is projected from human.","key_references":[{"PMID":"32702237","why":"SPR for proMMP-1, active MMP-1 and MMP-1/TIMP-1 binding to LRP1"},{"PMID":"32694578","why":"SPR and cell uptake: TIMP-3 bridges MMP-1 to LRP1"}],"covers":["LR006184"]},"LR002962":{"pair":"MMP2 -> PECAM1","headline":"MMP-2 co-immunoprecipitates with PECAM-1 in rat retinal endothelial cells, where MMP-2 treatment lowers PECAM-1; one paper, mainly cleavage.","interaction_type":"functional only","direction_and_effect":"MMP-2 treatment (50 to 400 ng/ml) significantly decreased PECAM-1 in rat retinal microvascular endothelial cells, and GM6001 restored PECAM-1 under high glucose [PMID:30793207]. This is an antagonist-type (loss of receptor) effect rather than signalling.","molecular_requirements":"Three possible MMP-2 cleavage sites on PECAM-1 were predicted in silico (PROSPER); the interaction was seen by immunoprecipitation [PMID:30793207].","affinity_potency":[],"species_and_systems":"Primary rat retinal microvascular endothelial cells and streptozotocin-diabetic rats; the pair is ortholog-inferred for human and mouse [PMID:30793207].","localisation_and_range":"MMP-2 is annotated as secreted and PECAM1 as transmembrane [flag]; the effect is on an endothelial junction protein.","caveats":"Co-IP is the only interaction evidence and was in cell lysates, so direct binding is not established. Cleavage sites were predicted in silico, not mapped experimentally. Human and mouse rows are inferred from rat data.","key_references":[{"PMID":"30793207","why":"Co-IP of PECAM-1/MMP-2 and MMP-2-induced PECAM-1 loss in rat retinal cells"}],"covers":["LR002962","LR006187"]},"LR005248":{"pair":"MMRN2 -> CD93","headline":"MMRN2 is a direct ligand for CD93, shown in two independent papers with domain and residue mapping.","interaction_type":"direct binding","direction_and_effect":"MMRN2 is a specific ligand for CD93 [PMID:28912033]; disrupting the interaction reduced endothelial adhesion and migration [PMID:28912033]. CD93 and MMRN2 co-immunoprecipitated in HUVEC lysates [PMID:28671670]. UniProt describes MMRN2 as a CD93 ligand [DB:UniProt]; BioGRID lists co-localisation and reconstituted complex [DB:BioGRID].","molecular_requirements":"CD93 and CLEC14A bind the same non-glycosylated coiled-coil region of MMRN2 [PMID:28671670]. The CD93 C-type lectin domain is needed, and F238 of CD93 engages the MMRN2 coiled-coil domain [PMID:28912033].","affinity_potency":[],"species_and_systems":"Human proteins; HUVEC lysates and human tumour vessels [PMID:28671670][PMID:28912033]. The mouse pair is ortholog-inferred.","localisation_and_range":"MMRN2 is a secreted ECM protein [flag]; CD93 is a transmembrane receptor [flag].","caveats":"Both curator rows were read as abstract only (full-text excerpts for one). Affinity is not reported in our evidence. Mapping relies on docking models and mutagenesis [PMID:28912033].","key_references":[{"PMID":"28912033","why":"Identifies MMRN2 as a CD93 ligand with mutagenesis mapping"},{"PMID":"28671670","why":"Family-wide MMRN2 binding and shared coiled-coil region"}],"covers":["LR001908","LR005248"]},"LR001909":{"pair":"MMRN2 -> CLEC14A","headline":"MMRN2 binds CLEC14A directly; supported by one full-text paper with binding mapping.","interaction_type":"direct binding","direction_and_effect":"CLEC14A directly binds MMRN2; recorded as agonist, and an MMRN2 peptide spanning the binding region blocks CLEC14A extracellular domain binding to endothelial cells [PMID:28671670].","molecular_requirements":"The CLEC14A C-type lectin domain is required; chimeras lacking it failed to bind. CLEC14A and CD93 bind the same non-glycosylated coiled-coil region of MMRN2, while CD248 binds a distinct region [PMID:28671670].","affinity_potency":[],"species_and_systems":"Human proteins and cells (HUVEC, HEK293T); mouse CLEC14A-ECD-Fc also bound the corresponding mouse MMRN2 region by far western [PMID:28671670].","localisation_and_range":"MMRN2 is an endothelial extracellular matrix protein and carries a secreted flag [flag]; CLEC14A is a membrane receptor, so signalling is by matrix contact.","caveats":"Single paper. Full-length MMRN2 behaved inconsistently in far western under some conditions. No affinity reported in our evidence.","key_references":[{"PMID":"28671670","why":"Direct binding, domain mapping, blocking peptide"}],"covers":["LR001909","LR005249"]},"LR006193":{"pair":"MSTN -> ACVR1B","headline":"Myostatin signals via ActRIIB with ALK4 as one possible type I partner; one abstract-only paper.","interaction_type":"direct binding","direction_and_effect":"Myostatin binds the type II receptor ActRIIB, then partners with ALK4 or ALK5 to phosphorylate Smad2/Smad3 [PMID:14517293].","molecular_requirements":"ACVR1B (ALK4) is a type I chain recruited after ActRIIB; ALK5 can substitute, so ALK4 is not obligate [PMID:14517293].","affinity_potency":[],"species_and_systems":"Cell-based signalling and receptor binding experiments; species labelled human; mouse pair is ortholog-inferred [PMID:14517293].","localisation_and_range":"Myostatin is secreted [flag]; paracrine or endocrine.","caveats":"Abstract only. ALK4 is a downstream partner of the type II receptor, not shown as a direct binder alone.","key_references":[{"PMID":"14517293","why":"Myostatin to ActRIIB then ALK4/ALK5"}],"covers":["LR002968","LR006193"]},"LR004492":{"pair":"MSTN -> ACVR2B","headline":"Myostatin binds ACVR2B (ActRIIB) as its primary type II receptor, backed by three papers.","interaction_type":"direct binding","direction_and_effect":"Purified myostatin dimer binds ActRIIB [PMID:11459935]; myostatin binds ActRIIB first and then recruits ALK4 or ALK5 to phosphorylate Smad2/Smad3 [PMID:14517293]. In human granulosa cells GDF8 suppressed PTX3 via SMAD2/3 [PMID:25641196].","molecular_requirements":"Needs a type I partner, ALK4 or ALK5 [PMID:14517293]. Myostatin competes with BMP7 for ActRIIB [PMID:14517293].","affinity_potency":[],"species_and_systems":"Purified proteins [PMID:11459935]; cell-based assays [PMID:14517293]; human granulosa cells [PMID:25641196]; mouse pair ortholog-inferred. IntAct SPR and BioGRID records also listed [DB:IntAct][DB:BioGRID 297250].","localisation_and_range":"Myostatin is secreted [flag].","caveats":"All abstracts only; one further paper is pending.","key_references":[{"PMID":"11459935","why":"Binding of myostatin to ActRIIB"},{"PMID":"14517293","why":"ActRIIB then ALK4/ALK5 signalling"},{"PMID":"25641196","why":"ACVR2A/2B knockdown in granulosa cells"}],"covers":["LR001080","LR004492"]},"LR002971":{"pair":"MUC1 -> ICAM1","headline":"Adhesion-type MUC1:ICAM-1 interaction supported by one full-text in vitro paper.","interaction_type":"functional only","direction_and_effect":"MUC1 on cancer cells bound ICAM-1; ZR-75-1 cells showed stronger ICAM-1 binding than MCF7 cells, and slow E-selectin rolling led to MUC1:ICAM-1 firm adhesion [PMID:22866263].","molecular_requirements":"E-selectin engagement slows rolling before ICAM-1 contact; underglycosylated MUC1 core epitope is involved [PMID:22866263].","affinity_potency":[],"species_and_systems":"Human breast cancer cell lines and recombinant ICAM-1 in flow microtubes [PMID:22866263]; mouse pair ortholog-inferred.","localisation_and_range":"Both annotated secreted and membrane flags [flag]; the paper concerns cell-surface adhesion.","caveats":"Single paper; cell-line level correlation rather than purified binding; no affinity.","key_references":[{"PMID":"22866263","why":"MUC1:ICAM-1 adhesion in rolling assays"}],"covers":["LR002971","LR006196"]},"LR002980":{"pair":"NCAN -> L1CAM","headline":"L1 binds neurocan with high affinity; binding site mapped to the first Ig domain of human L1; abstract-only.","interaction_type":"direct binding","direction_and_effect":"L1 can bind with high affinity to neurocan, and neurocan can block homophilic L1 binding [PMID:10934197].","molecular_requirements":"The neurocan-binding site is in the first Ig-like domain of human L1, mapped by fusion proteins, mutagenesis and peptide blocking [PMID:10934197].","affinity_potency":[],"species_and_systems":"Human L1 fusion proteins in vitro; mouse pair is ortholog-inferred [PMID:10934197].","localisation_and_range":"Neurocan flagged secreted and L1 transmembrane [flag]; Reactome lists an L1:Neurocan plasma membrane complex [DB:Reactome R-HSA-443646].","caveats":"Abstract only; no affinity value in our evidence. The inhibition of homophilic binding was reported as prior literature in the abstract ('It has been reported'). BioGRID also lists a reconstituted complex [DB:BioGRID].","key_references":[{"PMID":"10934197","why":"Neurocan-binding site mapped on L1 Ig1"}],"covers":["LR002980","LR006205"]},"LR008146":{"pair":"NDP -> FZD4:LRP5","headline":"Norrin acts through a FZD4-LRP5 receptor complex, but the three papers support it only indirectly.","interaction_type":"functional only","direction_and_effect":"Norrin triggers FZD4 ubiquitination and internalisation of the NDP receptor complex [PMID:28675177]. UniProt states norrin binds the FZD4-LRP5 complex to trigger beta-catenin signalling [DB:UniProt].","molecular_requirements":"FZD4 was essential for NDP surface binding and internalisation, while LRP5 and TSPAN12 alone were not sufficient [PMID:28675177]. Co-IP in the 2026 variant paper showed FZD4 with LRP5 and NDP, not TSPAN12 [PMID:41526591]. A quaternary Norrin-FZD4-LRP5/6-Tspan12 model is proposed [PMID:42155446].","affinity_potency":[],"species_and_systems":"Human cells (HeLa, mutant FZD4 p.Y250C) in 41526591 and endocytosis work in HeLa and mice in 28675177; Tspan12 structure was cryo-EM of Norrin-Tspan12 LEL at 3.78 Angstrom [PMID:42155446][PMID:41526591][PMID:28675177].","localisation_and_range":"Norrin is flagged secreted [flag]; the receptor is a membrane complex.","caveats":"All three papers were read as abstracts (excerpts for two). None measures NDP binding to the intact FZD4:LRP5 complex: the structure covers Norrin-Tspan12 and the co-IP covers FZD4-LRP5. The LRP5 chain is not named in the 28675177 abstract.","key_references":[{"PMID":"28675177","why":"NDP-induced FZD4 endocytosis of the receptor complex"},{"PMID":"41526591","why":"FZD4-LRP5-NDP co-IP and reporter assays"},{"PMID":"42155446","why":"Cryo-EM Norrin-Tspan12, quaternary model"}],"covers":["LR008146"]},"LR001918":{"pair":"NECTIN1 -> NECTIN3","headline":"Nectin-1 binds nectin-3 in trans with a KD of 1 nM, the tightest nectin-1 interaction.","interaction_type":"direct binding","direction_and_effect":"Nectin-3/nectin-1 trans-heterointeraction was confirmed [PMID:11544254], with affinity measured later [PMID:12011057]. Reactome lists a trans heterodimer [DB:Reactome].","molecular_requirements":"The trans-interaction is V-to-V domain, with C domains raising affinity; nectin3 and nectin4 share a binding region in the nectin1 V domain [PMID:12011057][PMID:11544254].","affinity_potency":[{"value":"KD 1 nM","assay":"trans-interaction affinity","system":"nectin1 with nectin3, human","cite":"PMID:12011057"}],"species_and_systems":"Human nectins; the mouse row is ortholog-inferred [PMID:12011057].","localisation_and_range":"Membrane adhesion molecules acting in trans at cell-cell junctions [PMID:12011057].","caveats":"11544254 is confirmatory of earlier work and gives no new data on this pair beyond confirmation. Both papers abstract only. The ligand and receptor roles are arbitrary; the pair is symmetric.","key_references":[{"PMID":"11544254","why":"Nectin1-nectin3 trans-interaction"},{"PMID":"12011057","why":"KD measurement and V domain mapping"}],"covers":["LR001918","LR005257"]},"LR005257":{"pair":"NECTIN1 -> NECTIN3","headline":"Nectin-1 binds nectin-3 in trans with a KD of 1 nM, the tightest nectin-1 interaction.","interaction_type":"direct binding","direction_and_effect":"Nectin-3/nectin-1 trans-heterointeraction was confirmed [PMID:11544254], with affinity measured later [PMID:12011057]. Reactome lists a trans heterodimer [DB:Reactome].","molecular_requirements":"The trans-interaction is V-to-V domain, with C domains raising affinity; nectin3 and nectin4 share a binding region in the nectin1 V domain [PMID:12011057][PMID:11544254].","affinity_potency":[{"value":"KD 1 nM","assay":"trans-interaction affinity","system":"nectin1 with nectin3, human","cite":"PMID:12011057"}],"species_and_systems":"Human nectins; the mouse row is ortholog-inferred [PMID:12011057].","localisation_and_range":"Membrane adhesion molecules acting in trans at cell-cell junctions [PMID:12011057].","caveats":"11544254 is confirmatory of earlier work and gives no new data on this pair beyond confirmation. Both papers abstract only. The ligand and receptor roles are arbitrary; the pair is symmetric.","key_references":[{"PMID":"11544254","why":"Nectin1-nectin3 trans-interaction"},{"PMID":"12011057","why":"KD measurement and V domain mapping"}],"covers":["LR001918","LR005257"]},"LR007354":{"pair":"NECTIN3 -> TIGIT","headline":"Weak interaction asserted by databases only; no verified paper.","interaction_type":"database-asserted only","direction_and_effect":"UniProt states TIGIT binds NECTIN3 with lower affinity than other ligands, and NECTIN3 binds TIGIT with low affinity [DB:UniProt]. The entry is labelled Stimulatory [flag], but no effect is shown in our evidence.","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Human records; IntAct lists protein array and solid phase assays [DB:IntAct].","localisation_and_range":"Transmembrane proteins by flags [flag]; contact-dependent presumed from flags only.","caveats":"Two candidate papers were judged to concern a different entity and one was review-only. Only low-affinity statements and high-throughput assays support the pair.","key_references":[],"covers":["LR007354"]},"LR011179":{"pair":"NGFR -> NTRK2","headline":"Receptor-receptor association: p75NTR co-precipitates with TrkB in co-transfected cells, with domain mapping done on trkB.","interaction_type":"direct binding","direction_and_effect":"p75NTR was co-precipitated with trkB in doubly transfected cells; co-expression with trkB increased the specificity of trkB activation by BDNF over neurotrophin-3 and neurotrophin-4/5 [PMID:9927421].","molecular_requirements":"Both extracellular and intracellular domains of trkB and p75NTR contribute; blocking trkB autophosphorylation reduced interaction for constructs with the intracellular domain only [PMID:9927421].","affinity_potency":[],"species_and_systems":"Co-immunoprecipitation in doubly transfected cells; species not reported in our evidence; abstract only [PMID:9927421]. BioGRID lists affinity capture-western records [DB:BioGRID].","localisation_and_range":"Both membrane receptors, in close proximity within cell membranes [PMID:9927421].","caveats":"Receptor-receptor pair, not a ligand-receptor one; co-IP may be indirect. Two other papers were abstract-insufficient.","key_references":[{"PMID":"9927421","why":"p75NTR-trkB co-precipitation and domain mapping"}],"covers":["LR011179"]},"LR001099":{"pair":"NID1 -> ITGB3","headline":"Entactin RGD recognised by alphaVbeta3 in attachment assays on recombinant and native entactin; abstract-level papers only.","interaction_type":"functional only","direction_and_effect":"The RGD sequence in entactin is recognised by alpha v beta 3 in attachment assays [PMID:7797588]; human mesangial cells use alpha v beta 3 and a beta 1-containing integrin for native entactin [PMID:9686320].","molecular_requirements":"Beta3 acts with alphaV; a second RGD-independent site is recognised by a beta 1 integrin [PMID:7797588].","affinity_potency":[],"species_and_systems":"Cell attachment assays with mutant recombinant entactin and cultured human kidney mesangial cells; both abstract only [PMID:7797588][PMID:9686320]. Human pair is listed and mouse pair is ortholog-inferred.","localisation_and_range":"Entactin is a basement-membrane glycoprotein; NID1 is annotated secreted [flag].","caveats":"Functional attachment and antibody inhibition, not purified binding. Three other papers were abstract-insufficient and one is pending.","key_references":[{"PMID":"7797588","why":"RGD deletion mutants show alpha v beta 3 recognition of entactin"},{"PMID":"9686320","why":"Antibody inhibition shows alpha v beta 3 use on mesangial cells"}],"covers":["LR001099","LR004510"]},"LR004519":{"pair":"NLGN3 -> NRXN1","headline":"Neuroligin-3 binding to neurexin-1beta is supported by rat full-text affinity chromatography and an SPR paper covering neuroligins 1-4.","interaction_type":"direct binding","direction_and_effect":"All three neuroligins bind neurexin 1beta in a Ca2+-dependent manner [PMID:8576240]. Neuroligins 1-4 bind neurexin-1beta with affinities spanning more than 2 orders of magnitude [PMID:17042500]; the curator note says NL3 appears only via a review as lower affinity.","molecular_requirements":"Neuroligin extracellular domains sediment as dimers, beta-neurexins as monomers, with a 2:2 complex suggested; splice insert 4 modulates association [PMID:17042500].","affinity_potency":[],"species_and_systems":"Rat brain proteins [PMID:8576240]; species unspecified in 17042500 though ranking is said to be conserved across mammals. Mouse and human pairs are ortholog-projected.","localisation_and_range":"Neither partner is secreted; both carry transmembrane flags [flag], so this is a membrane-bound, contact-dependent (trans-synaptic) pair. BioGRID lists a reconstituted complex and an affinity capture-western record [DB:BioGRID].","caveats":"17042500 abstract covers neuroligins collectively without naming NL3; the 8576240 full-text quote is a browser read with spot-check pending. No NL3-specific affinity value. One paper unresolvable, others abstract-insufficient.","key_references":[{"PMID":"8576240","why":"Neuroligins bind neurexin 1beta, Ca2+ dependent"},{"PMID":"17042500","why":"SPR of neuroligins 1-4 against neurexin-1beta"}],"covers":["LR001108","LR004519"]},"LR005266":{"pair":"Nlgn4l -> Nrxn1","headline":"Supported by a 2.6 A structure of the neurexin-1beta-neuroligin-4 complex; mapping to Nlgn4l is by ortholog projection.","interaction_type":"direct binding","direction_and_effect":"A 2.6 A crystal structure of soluble neurexin-1beta bound to neuroligin-4 describes a Ca2+-coordinated interface and NL4-specific rearrangements [PMID:20543817].","molecular_requirements":"The soluble Nrx1beta-NL4 complex; the interface is Ca2+-coordinated [PMID:20543817].","affinity_potency":[],"species_and_systems":"Experimental species not reported in our evidence; the mouse pair is ortholog-projected [PMID:20543817].","localisation_and_range":"Flags show both partners as not secreted [flag]; receptor flag only on Nrxn1.","caveats":"Abstract only. The paper concerns neuroligin-4, not stated to be Nlgn4l. No affinity.","key_references":[{"PMID":"20543817","why":"Crystal structure of Nrx1beta-NL4 complex"}],"covers":["LR005266"]},"LR001927":{"pair":"NLGN4X -> NRXN1","headline":"Structurally supported: 2.6 A crystal structure of the NRXN1beta-neuroligin-4 complex, plus UniProt interaction annotation.","interaction_type":"direct binding","direction_and_effect":"A 2.6 A crystal structure of the soluble neurexin-1beta-neuroligin-4 complex shows a Ca2+-coordinated interface, with SPR on structure-guided mutants (curator note) [PMID:20543817]. UniProt states NLGN4X interacts with NRXN1 in a calcium-dependent manner [DB:UniProt].","molecular_requirements":"Soluble neurexin-1beta; calcium required [PMID:20543817][DB:UniProt].","affinity_potency":[],"species_and_systems":"Experimental species not reported in our evidence; pair is human, not ortholog-projected.","localisation_and_range":"Both partners carry transmembrane flags [flag]; contact-dependent synaptic adhesion setting.","caveats":"Abstract only; no affinity values. Which neuroligin-4 gene was crystallised is not stated in our evidence. One further paper was review-only.","key_references":[{"PMID":"20543817","why":"Crystal structure of the complex"}],"covers":["LR001927"]},"LR004528":{"pair":"NODAL -> ACVR1B","headline":"Functional support for ALK4 (ACVR1B) as a Nodal type I receptor, but only with Cripto, and mainly from Xenopus and mouse experiments.","interaction_type":"functional only","direction_and_effect":"ALK4 mediates Nodal signalling in the presence of Cripto, and dominant-negative ALK4 blocks Nodal in frog animal caps [PMID:11485994][PMID:11952836]. Effect is signalling activation (agonist) [PMID:11952836].","molecular_requirements":"Type I receptor needs a type II partner (ActRIIA or ActRIIB) [PMID:11952836] and Cripto: membrane-bound Cripto is an obligatory co-receptor, while a soluble form binds Nodal but fails to signal [PMID:11952836]. Cripto interacts directly with ALK4 [PMID:11485994].","affinity_potency":[],"species_and_systems":"Mouse Nodal and Xenopus Nodal-related 1 in Xenopus embryos and cell reconstitution [PMID:11485994]; Xenopus animal caps [PMID:11952836]. The mouse pair is direct; the human pair is projected by orthology.","localisation_and_range":"Nodal flagged secreted [flag]; in the paper it signals via membrane-bound Cripto on receiving cells [PMID:11952836].","caveats":"Nodal-pathway rows differ by which type II receptor and co-receptor are included; CCC scoring by the weakest subunit makes the co-receptor requirement matter. Evidence is dominant-negative loss of function, not binding, for ALK4 [PMID:11952836]. Both papers read as abstract only. PMID:11485994 is mainly about ALK7, and dominant-negative ALK4 is not Nodal-specific.","key_references":[{"PMID":"11485994","why":"Reconstitution: ALK4 mediates Nodal signalling only with Cripto"},{"PMID":"11952836","why":"ALK4 and ActRIIA/B as Nodal receptors; membrane Cripto is obligatory"}],"covers":["LR001117","LR004528"]},"LR008254":{"pair":"NODAL -> ACVR1B:ACVR2B","headline":"Complex row without Cripto; the only verified paper stresses Cripto-1 dependence and does not name ACVR2B.","interaction_type":"functional only","direction_and_effect":"Nodal bound to the type II receptor uses Cripto-1 to recruit ALK4 for SMAD2/3 activation [PMID:39840816].","molecular_requirements":"Cripto-1 is required [PMID:39840816]; this row lacks it. ACVR2B is not named in the abstract.","affinity_potency":[],"species_and_systems":"NTERA-2 cells, SPR, AlphaFold3; species not stated [PMID:39840816].","localisation_and_range":"Nodal flagged secreted [flag].","caveats":"Abstract only; one further paper review-only. BioGRID lists NODAL-ACVR2B reconstituted complex [DB:BioGRID].","key_references":[{"PMID":"39840816","why":"Cripto-1 recruits ALK4 to Nodal-type II receptor"}],"covers":["LR008254"]},"LR008272":{"pair":"NODAL -> ACVR1C:ACVR2A","headline":"No verified paper; support is from UniProt and BioGRID.","interaction_type":"database-asserted only","direction_and_effect":"UniProt states ACVR1C is a receptor for activin AB, activin B, activin E and NODAL [DB:UniProt]; BioGRID lists a NODAL-ACVR2A reconstituted complex [DB:BioGRID].","molecular_requirements":"Row lists ACVR1C with ACVR2A; no Cripto/EGF-CFC co-receptor is included.","affinity_potency":[],"species_and_systems":"Not reported in our evidence.","localisation_and_range":"Nodal flagged secreted [flag].","caveats":"The single judged paper was review-only; no primary experiment is verified for this exact complex.","key_references":[],"covers":["LR008272"]},"LR008551":{"pair":"NOG -> BMP2","headline":"Noggin binds BMP2 as an antagonist; supported by SPR and a crystal structure in databases, no curated paper.","interaction_type":"database-asserted only","direction_and_effect":"Interaction is annotated Inhibitory [flag]; PDB 7AG0 is titled as a complex between BMP2 and its antagonist Noggin [DB:PDB 7AG0, PMID:36642181].","molecular_requirements":"Not reported in our evidence beyond a Noggin chain and a BMP2 chain in the structure [DB:PDB 7AG0].","affinity_potency":[],"species_and_systems":"IntAct lists surface plasmon resonance [DB:IntAct, PMID:19804412]; species and system not reported in our evidence.","localisation_and_range":"BMP2 is flagged secreted and non-transmembrane [flag]; Noggin acts as a secreted antagonist binding the ligand, not a membrane receptor.","caveats":"No papers were judged for this pair (five were rated as concerning a different entity). Rests on IntAct and PDB records alone. Noggin is a ligand-binding antagonist, not a signalling receptor, so CCC tools treat it as inhibitor.","key_references":[{"PMID":"36642181","why":"Crystal structure of BMP2 with Noggin (PDB 7AG0)"}],"covers":["LR008551"]},"LR004537":{"pair":"NPNT -> ITGB1","headline":"Nephronectin binds integrin alpha8beta1, so ITGB1 is supported only as the beta chain of that heterodimer.","interaction_type":"direct binding","direction_and_effect":"The paper shows binding of an alpha8beta1 heterodimer probe to nephronectin and in vivo complex formation [PMID:11470831]; binding was RGD-inhibitable [PMID:11470831].","molecular_requirements":"ITGB1 acts as a subunit with ITGA8; Reactome lists NPNT:ITGA8:ITGB1 [DB:Reactome]. The evidence does not test ITGB1 alone, and ITGB1 pairs with other alpha chains: not reported in our evidence.","affinity_potency":[],"species_and_systems":"Mouse tissue and recombinant probes [PMID:11470831]; human pair is ortholog-inferred.","localisation_and_range":"Nephronectin is an extracellular matrix protein, no transmembrane region [PMID:11470831].","caveats":"Chain-only evidence: the single paper used the alpha8beta1 heterodimer, not ITGB1 separately. Abstract-level judgement, though full text excerpts support RGD-dependent binding [PMID:11470831].","key_references":[{"PMID":"11470831","why":"alpha8beta1 binding to nephronectin"}],"covers":["LR001127","LR004537"]},"LR004546":{"pair":"NPVF -> NPFFR1","headline":"NPVF peptides bind NPFFR1 (FF1) with nanomolar affinity; two abstract-level papers plus GtoPdb full-agonist records.","interaction_type":"direct binding","direction_and_effect":"NPVF-derived peptides showed higher affinity for FF1 than NPFF-derived peptides [PMID:11481330]. In human NPFF1 cells the peptides act as agonists; GtoPdb lists a full agonist [PMID:12242085][DB:GtoPdb].","molecular_requirements":"Single receptor chain; no co-receptor or complex requirement reported in our evidence.","affinity_potency":[{"value":"pKi 9.2-9.3","assay":"GtoPdb agonist record","system":"not reported in our evidence","cite":"PMID:12242085"}],"species_and_systems":"Radioligand binding on human NPFF1 in CHO cells, human peptides [PMID:12242085]; the first paper does not state species [PMID:11481330]. Mouse pair is projected from human.","localisation_and_range":"NPVF is flagged secreted and NPFFR1 a transmembrane receptor [flag]; paracrine/neuroendocrine range is inferred only from these flags.","caveats":"Both papers were read as abstracts only. The peptides bind both NPFF receptors, with only a slight preference for FF1 [PMID:12242085]. Affinity is given as a range in GtoPdb, not per peptide.","key_references":[{"PMID":"11481330","why":"Identifies NPVF peptides; higher affinity for FF1 than NPFF peptides"},{"PMID":"12242085","why":"Human NPFF1/NPFF2 binding in CHO cells, nanomolar affinity"}],"covers":["LR001136","LR004546"]},"LR004555":{"pair":"NRG1 -> ERBB2","headline":"NRG1 binds ERBB2 only weakly on its own: ERBB3 is needed; evidence includes a pM-range binding claim and structures.","interaction_type":"conflicting","direction_and_effect":"Heregulin-alpha induced p185erbB2 phosphorylation, and recombinant HRG showed one high-affinity binding site on erbB2-expressing breast tumour cells [PMID:1350381]. Cross-linking showed direct heregulin contact with erbB2 and erbB3 [PMID:7514177].","molecular_requirements":"ERBB3 appears needed: not all erbB2-expressing cells respond, and erbB3 plus erbB2 reconstitutes a higher-affinity, signalling receptor [PMID:7514177]. Reactome lists NRG1:ERBB3:ERBB2 complexes [DB:Reactome R-HSA-1247502].","affinity_potency":[{"value":"Kd 105 pM","assay":"Scatchard analysis of recombinant HRG","system":"breast tumour cell line expressing p185erbB2","cite":"PMID:1350381"}],"species_and_systems":"Human ligand and receptor, tumour cell lines and transfected cells [PMID:1350381][PMID:7514177]. Mouse pair is projected from human.","localisation_and_range":"NRG1 is flagged secreted and transmembrane, ERBB2 transmembrane [flag]; membrane-bound or processed ligand forms are not distinguished in our evidence.","caveats":"Both papers are abstract only. The Kd was measured on cells that may express other ErbB receptors, so it cannot show ERBB2-alone binding. The dossier curator notes later work places ErbB2 as a heterodimer partner rather than a ligand binder; this is not in the papers shown. BioGRID and IntAct records exist [DB:IntAct].","key_references":[{"PMID":"1350381","why":"Heregulin-alpha purification and Kd 105 pM on erbB2 cells"},{"PMID":"7514177","why":"Heregulin cross-links erbB2 and erbB3; erbB3 needed for high affinity"}],"covers":["LR001146","LR004555"]},"LR006229":{"pair":"NRG1 -> ITGAV","headline":"Single abstract-level report that NRG1 binds integrin alphaV (ITGAV); one paper, stored per subunit, not the dimer.","interaction_type":"direct binding","direction_and_effect":"NRG1 (isolated EGF-like domain or native multi-domain form) binds integrins; Lys-to-Glu mutants suppressed integrin binding and ErbB3 phosphorylation, so integrin binding appears to support NRG1-ErbB3 signalling [PMID:20682778]. UniProt states this binding is essential for NRG1-ERBB signalling [DB:UniProt].","molecular_requirements":"NRG1 binds the integrin heterodimers alphavbeta3 and alpha6beta4; the dossier stores them per subunit [PMID:20682778]. alpha6beta4 was functionally dominant for forming the integrin-NRG1-ErbB3 ternary complex [PMID:20682778]. A UniProt record says the ternary complex includes ERBB3 [DB:UniProt]. This row names only one chain; the evidence concerns the heterodimer.","affinity_potency":[{"value":"KD 136 nM (1.36 x 10(-7) m), to alphavbeta3","assay":"direct binding","system":"purified integrins","cite":"PMID:20682778"}],"species_and_systems":"Human ligand and human receptor, purified proteins; the mouse pair is projected from human evidence [PMID:20682778].","localisation_and_range":"NRG1 is flagged both secreted and transmembrane [flag]; range not addressed in the paper text we have.","caveats":"Only one paper, read as abstract only. The KD is for alphavbeta3, not for this individual chain. Chain-only row for a heterodimeric receptor; the integrin dimer should be the unit scored.","key_references":[{"PMID":"20682778","why":"Direct NRG1-integrin binding and integrin-NRG1-ErbB3 ternary complex"}],"covers":["LR003005","LR006229"]},"LR004564":{"pair":"NRTN -> RET","headline":"Well supported: cryo-EM structure plus cell assays show neurturin activates RET, but only through a GFRA2 co-receptor.","interaction_type":"direct binding","direction_and_effect":"NRTN acts as an agonist: with GFRA2 it induces RET tyrosine phosphorylation, and the three proteins form a physical complex on the cell surface [PMID:9192898]. Fibroblasts expressing TrnR2 (GFRA2) and Ret are ~30-fold more sensitive to NTN than to GDNF [PMID:9182803].","molecular_requirements":"RET needs a GFR-alpha co-receptor. A cryo-EM structure of the NRTN-GFRalpha2-RET extracellular complex shows NRTN dimer contacting the RET cysteine-rich domain, with GFRalpha2 contacting RET via a calcium-binding site [PMID:31392261]. Reactome lists the reaction as GDNF,NRTN binding RET:GFRA1,GFRA2 [DB:Reactome]. RET alone with NRTN was not tested in our evidence; the structural paper reports no RET binding signal to NRTN or GFRalpha2 surfaces when RET was injected alone [PMID:31392261].","affinity_potency":[{"value":"Kd ~10 pM","assay":"NTN binding to NTNR-alpha (GFRA2), the co-receptor, not RET itself","system":"human","cite":"PMID:9192898"}],"species_and_systems":"Recombinant human proteins and fibroblast cells; the cryo-EM used reconstituted extracellular proteins at 5.7-Angstrom resolution [PMID:31392261]. Mouse pair is projected from human evidence (ortholog-inferred).","localisation_and_range":"NRTN is flagged secreted [flag]; RET is a transmembrane receptor with a GPI-linked co-receptor, so signalling is paracrine/juxtacrine at the receiving cell [PMID:9182803].","caveats":"The high-affinity value belongs to NRTN-GFRA2, not NRTN-RET. 31392261 and 9192898 were read as abstracts for the curator judgement. PDB structures (6GL7, 6Q2O, 6Q2R) are RET-GFRA2-type complexes [DB:PDB 6GL7].","key_references":[{"PMID":"31392261","why":"cryo-EM structure of NRTN-GFRalpha2-RET extracellular complex"},{"PMID":"9192898","why":"NTN/NTNRalpha/Ret form a physical complex and Ret phosphorylation; Kd ~10 pM"},{"PMID":"9182803","why":"GFRA2-Ret mediates NTN signalling, ~30-fold preferential to NTN"}],"covers":["LR001155","LR004564"]},"LR006238":{"pair":"NRXN1 -> ADGRL1","headline":"Direct high-affinity binding of neurexin ectodomains to latrophilin-1 shown for neurexins in general; one paper, NRXN1 not named in our evidence.","interaction_type":"direct binding","direction_and_effect":"CL1 (ADGRL1) and neurexins bind directly through their extracellular domains, and CL1 competed with neuroligin-1 for neurexin binding [PMID:22262843]. Cells expressing each partner formed a stable intercellular adhesion complex, so the interaction can act in trans [PMID:22262843]. Which partner is ligand or receptor is not defined; both are membrane proteins.","molecular_requirements":"Neurexins lacking an insert at splice site 4 (SS4) bind CL1 with nanomolar affinity; neurexins with an SS4 insert do not bind. The olfactomedin-like domain of CL1 mediates binding by deletion mapping [PMID:22262843].","affinity_potency":[],"species_and_systems":"Purified ectodomains and cell adhesion assays; species listed as human in the curation, mouse pair is ortholog-inferred, and the abstract does not specify NRXN1.","localisation_and_range":"Both are transmembrane proteins [flag]; trans-cellular, contact-dependent adhesion, with CL1 possibly postsynaptic [PMID:22262843].","caveats":"Evidence is stated for neurexins as a class; the abstract does not name NRXN1 specifically and no numeric affinity is in our evidence. Evidence sentence in the dossier is truncated.","key_references":[{"PMID":"22262843","why":"direct neurexin-CL1 binding, SS4-regulated, produces an adhesion complex"}],"covers":["LR003014","LR006238"]},"LR006247":{"pair":"NRXN1 -> NLGN2","headline":"Direct binding of beta-neurexin-1 to neuroligins measured by SPR; NLGN2 affinity not separately reported in our evidence.","interaction_type":"direct binding","direction_and_effect":"Neuroligins 1-4 are postsynaptic proteins that initiate presynaptic maturation via beta-neurexin, and individual neuroligins were tested against beta-neurexin-1 by surface plasmon resonance and affinity chromatography [PMID:17042500].","molecular_requirements":"Neuroligin and beta-neurexin form a 2:2 complex; splice insert 4 in beta-neurexin acts as a modulator [PMID:17042500]. BioGRID lists a reconstituted complex [DB:BioGRID].","affinity_potency":[],"species_and_systems":"Recombinant ectodomains; species unspecified. Human and mouse pairs are ortholog-inferred.","localisation_and_range":"Both transmembrane [flag]; trans-synaptic.","caveats":"Abstract only; the abstract reports affinities spanning more than 2 orders of magnitude across neuroligins but gives no NLGN2 value.","key_references":[{"PMID":"17042500","why":"SPR and affinity chromatography of neuroligin-beta-neurexin-1 recognition code"}],"covers":["LR003023","LR006247"]},"LR006256":{"pair":"NTM -> NTM","headline":"Neurotrimin homophilic interaction is supported by structural, proteomic and adhesion data.","interaction_type":"direct binding","direction_and_effect":"Ntm mediates homophilic adhesion shown by reaggregation of transfected cells and binding of an Ntm-Fc chimera [PMID:9801370]. IgLONs interact as homo- and heterodimers [PMID:30956130].","molecular_requirements":"Dimerization occurs through the first Ig domain of each monomer and is Ca2+ independent; IgLONs keep an extended conformation [PMID:30956130]. Cross-linking shows noncovalent homodimers and multimers [PMID:9801370].","affinity_potency":[],"species_and_systems":"Human rows per curator; transfected cells [PMID:9801370]; crystal structures of NTRI and other IgLONs, cell aggregation for NTRI and NEGR1 [PMID:30956130]. IntAct lists a protein array record [DB:IntAct].","localisation_and_range":"Neither partner flagged secreted or transmembrane [flag]; Ntm is described as GPI-anchored at the cell surface [PMID:9801370], so trans, contact-mediated adhesion.","caveats":"Self-interaction: ligand and receptor are the same protein, so scoring in CCC tools is homotypic. Abstracts only; the crystal structures cover NTRI, IgLON5 and NEGR1/IgLON5 per the abstract.","key_references":[{"PMID":"9801370","why":"Ntm homophilic adhesion and Ntm-Fc binding"},{"PMID":"30956130","why":"IgLON homo- and heterodimer structures"}],"covers":["LR003032","LR006256"]},"LR004573":{"pair":"NTN1 -> NEO1","headline":"Functional evidence only: neogenin mediates netrin-1-dependent cell clustering in mammary gland; direct binding is not shown in this dossier.","interaction_type":"functional only","direction_and_effect":"Neogenin mediates netrin-1-dependent cell clustering in cell aggregation assays; netrin-1 appears to act locally through neogenin to stabilise cap cells [PMID:12636918]. The effect is adhesive rather than guidance [PMID:12636918].","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Mouse mammary gland: loss of either gene disorganises terminal end buds [PMID:12636918]. The human pair is ortholog-inferred.","localisation_and_range":"Netrin-1 is secreted [flag]. In the mammary study netrin-1 is expressed in prelumenal cells and neogenin in adjacent cap cells [PMID:12636918].","caveats":"Paper read as abstract only and shows no direct binding. IntAct lists a co-immunoprecipitation [DB:IntAct] and Reactome a complex [DB:Reactome], but without details. One further paper is pending and not shown.","key_references":[{"PMID":"12636918","why":"Netrin-1/neogenin clustering and mouse mammary gland genetics"}],"covers":["LR001164","LR004573"]},"LR006265":{"pair":"NTN4 -> NEO1","headline":"Netrin-4 binds neogenin directly (abstract-only), and antiangiogenic function requires neogenin plus Unc5B recruitment.","interaction_type":"direct binding","direction_and_effect":"Netrin-4 bound neogenin but not Unc5B or Unc5C in endothelial cells; blocking antibodies to neogenin abolished its chemotactic effect [PMID:18719102]. Netrin-4 acts as an antiangiogenic factor [PMID:18719102].","molecular_requirements":"Silencing either neogenin or Unc5B abolished the netrin-4 inhibitory effect on endothelial migration; netrin-4 increased the association between Unc5B and neogenin [PMID:18719102].","affinity_potency":[],"species_and_systems":"Human endothelial cells; Matrigel and laser-induced choroidal neovascularization models and a xenograft [PMID:18719102]. IntAct records a co-immunoprecipitation [DB:IntAct].","localisation_and_range":"Netrin-4 is secreted [flag].","caveats":"Abstract only, no affinity reported.","key_references":[{"PMID":"18719102","why":"Netrin-4 binds neogenin and recruits Unc5B in endothelial cells"}],"covers":["LR003041","LR006265"]},"LR004582":{"pair":"NTNG2 -> LRRC4","headline":"Netrin-G2 and its ligand (LRRC4/NGL-2) bind at about 2.5 nM, with matching mouse loss-of-function phenotypes and a co-crystal structure.","interaction_type":"direct binding","direction_and_effect":"Netrin-G2 and netrin-G2 ligand act in the same pathway: genetic inhibition of either gives no acoustic startle with auditory brainstem responses present [PMID:17973922].","molecular_requirements":"Not reported in our evidence.","affinity_potency":[{"value":"2.5 nM","assay":"affinity as stated in abstract; assay not specified","system":"netrin-G2 with netrin-G2 ligand","cite":"PMID:17973922"},{"value":"2.3 nM","assay":"comparison pair, assay not specified","system":"netrin-G1 with netrin-G1 ligand","cite":"PMID:17973922"}],"species_and_systems":"Mouse [PMID:17973922]. Records: BioGRID co-crystal, IntAct SPR and PDB 3ZYI [DB:PDB 3ZYI][DB:BioGRID][DB:IntAct]. Human pair is ortholog-inferred.","localisation_and_range":"Both partners are flagged not secreted [flag], consistent with membrane-anchored, contact-based signalling.","caveats":"Abstract only; assay format is not given. One further row is pending.","key_references":[{"PMID":"17973922","why":"About 2.5 nM affinity and matching knockout phenotypes"}],"covers":["LR001173","LR004582"]},"LR004591":{"pair":"OMG -> LINGO1","headline":"OMgp acts with a NgR1/p75/LINGO-1 complex; LINGO-1 is a co-receptor component, and direct OMgp-LINGO-1 binding is not shown.","interaction_type":"functional only","direction_and_effect":"In non-neuronal cells, coexpression of human NgR1, p75 and LINGO-1 conferred responsiveness to oligodendrocyte myelin glycoprotein, measured as RhoA activation [PMID:14966521]. Dominant-negative LINGO-1 attenuated myelin inhibition in primary neurons, and LINGO-1-Fc did similarly [PMID:14966521].","molecular_requirements":"LINGO-1 binds NgR1 and p75 and is an additional functional component of the NgR1/p75 signalling complex; NgR1 and p75 alone could not activate RhoA [PMID:14966521]. So the effective receptor is a multi-subunit complex.","affinity_potency":[],"species_and_systems":"Reconstitution in non-neuronal cells with human proteins, plus primary neuronal cultures [PMID:14966521]. Mouse pair is ortholog-inferred.","localisation_and_range":"OMG is flagged membrane-bound (not secreted) [flag]; LINGO-1 is a nervous system-specific transmembrane protein [PMID:14966521].","caveats":"Single abstract-only paper. LINGO-1 is shown to bind NgR1 and p75, not OMgp; the pair is therefore a co-receptor relationship, not demonstrated direct ligand binding. No affinity reported.","key_references":[{"PMID":"14966521","why":"LINGO-1 as a functional component of the NgR1/p75 complex for OMgp"}],"covers":["LR001182","LR004591"]},"LR007381":{"pair":"OSM -> IL6ST:LIFR","headline":"OSM signals through the gp130:LIFR complex (type I OSM receptor), with direct binding and functional evidence.","interaction_type":"direct binding","direction_and_effect":"OSM binds the high-affinity LIF receptor but not the low-affinity form, while LIF cannot bind OSM receptors [PMID:1536831]. Co-expressing gp130 with the low-affinity LIFR confers high-affinity binding of both LIF and OSM [PMID:1542794]. Human OSM acts through LIFR, mouse OSM does not [PMID:10854424]. GtoPdb lists OSM as agonist of both IL6ST and LIFR [DB:GtoPdb].","molecular_requirements":"Both chains are needed for high-affinity binding: gp130 is the converting subunit for the LIFR, and gp130 alone confers only low-affinity OSM binding in COS-7 cells [PMID:1542794]. UniProt names type I OSM receptor as LIFR plus IL6ST [DB:UniProt].","affinity_potency":[],"species_and_systems":"Human cell lines and COS-7 transfectants [PMID:1536831][PMID:1542794]; rat hepatoma cells with human and mouse OSM [PMID:10854424]. Only the human pair is listed.","localisation_and_range":"OSM is flagged secreted [flag]; complex is flagged transmembrane receptor [flag]. Secreted, acting on cells carrying both chains.","caveats":"All papers read as abstracts only. Species restriction: mouse OSM does not act through LIFR [PMID:10854424], so projecting to mouse would be risky. Two review-only and one abstract-insufficient rows are not shown. No affinity values in our evidence.","key_references":[{"PMID":"1542794","why":"gp130 as affinity converter for LIFR, binds OSM and LIF"},{"PMID":"1536831","why":"OSM, not LIF, binds the high-affinity LIF receptor"},{"PMID":"10854424","why":"Human but not mouse OSM uses LIFR"}],"covers":["LR007381"]},"LR001189":{"pair":"OSTN -> NPR3","headline":"OSTN binds NPR3 (NPR-C) as a competitive ligand, with a Kd of approximately 5 nM in mouse work; abstract-level evidence.","interaction_type":"direct binding","direction_and_effect":"Osteocrin binds specifically and saturably to NPR-C with a Kd of approximately 5 nM, with no binding to GC-A or GC-B [PMID:17951249]. It augments CNP-stimulated cGMP production, consistent with blocking NPR-C-mediated clearance, so it acts as an antagonist of NPR3 clearance [PMID:17951249]. OSTN competitively bound NPR3 with atrial NP [PMID:29326144]. GtoPdb lists OSTN as an antagonist of NPR3 [DB:GtoPdb].","molecular_requirements":"NPR3 alone is enough in the reported binding; residues important for NP binding to NPR-C are needed for Ostn binding [PMID:17951249].","affinity_potency":[{"value":"Kd approximately 5 nM","assay":"saturable binding to NPR-C","system":"mouse","cite":"PMID:17951249"}],"species_and_systems":"Mouse for Kd and transgenic work [PMID:17951249]; the second paper is labelled human but uses mouse infarct models [PMID:29326144]. Both human and mouse pairs are ortholog-inferred.","localisation_and_range":"OSTN is flagged secreted [flag]; NPR3 is a flagged receptor [flag]. Secreted ligand acting by competition for clearance.","caveats":"All evidence is from abstracts. Effect is indirect: it raises NP levels rather than signalling through NPR3. A pending paper is not shown. The musclin paper [PMID:19244276] concerns musclin, a paralog name, and its species is unspecified in the dossier.","key_references":[{"PMID":"17951249","why":"Kd approximately 5 nM; NPR-C specificity"},{"PMID":"29326144","why":"Competitive NPR3 binding with atrial NP"}],"covers":["LR001189","LR004598"]},"LR006292":{"pair":"PCDHGA3 -> PCDHGA3","headline":"Mouse Pcdhga3 is a well-established homophilic adhesion molecule in K562 assays; used as a positive control.","interaction_type":"direct binding","direction_and_effect":"Two K562 cell populations each transfected with murine PCDHGA3 adhered strongly [PMID:27068704], and \u03b3-Pcdh isoform A3 showed strict homophily [PMID:20679223].","molecular_requirements":"Clustered protocadherin trans interaction is homophilic and isoform-specific; cis multimers with other isoforms may form the actual cell-surface unit, so one isoform alone may not reproduce the interface.","affinity_potency":[],"species_and_systems":"Mouse PCDHGA3 expressed in human K562 cells [PMID:27068704]; mouse isoforms [PMID:20679223]. Human pair is ortholog-inferred.","localisation_and_range":"Membrane-bound cell-adhesion molecule; trans homophilic contact between cells (juxtacrine), not secreted [flag].","caveats":"Cell aggregation only, no affinity. In PMID:27068704 PCDHGA3 served as a control, not the main subject. PMID:20679223 was browser-read and unverified. Paralogs are not interchangeable.","key_references":[{"PMID":"20679223","why":"strict homophily of gamma-Pcdh isoforms"},{"PMID":"27068704","why":"PCDHGA3 homophilic adhesion as control"}],"covers":["LR003069","LR006292"]},"LR001198":{"pair":"PDGFC -> PDGFRA","headline":"PDGFC (cleaved growth factor domain) binds and activates PDGFRA; two papers read as abstracts plus database binding records.","interaction_type":"direct binding","direction_and_effect":"PDGF-C binds to and activates the PDGF alpha-receptor and is activated by proteolysis [PMID:10806482]. Recombinant growth factor domain (PDGF-CC) showed high affinity binding to PDGF receptor-alpha homodimers and alpha/beta heterodimers in competition binding and immunoprecipitation; mitogenic on mesenchymal cells [PMID:11297552].","molecular_requirements":"Proteolytic release of the growth factor domain from the CUB domain is needed for activity [PMID:11297552][PMID:10806482]. PDGFRA homodimers and alpha/beta heterodimers bind [PMID:11297552].","affinity_potency":[],"species_and_systems":"Mouse in vivo: transgenic overexpression drives fibroblast proliferation and Pdgfra-null embryonic kidneys lose mesenchymal cells near PDGF-C expression [PMID:10806482]. Second paper used cells bearing both receptors, recombinant protein, species unspecified, and a diabetic mouse wound model [PMID:11297552]. BioGRID and IntAct binding records exist [DB:BioGRID][DB:IntAct].","localisation_and_range":"PDGFC flagged secreted [flag]; acts as a released growth factor domain after cleavage [PMID:11297552].","caveats":"Both papers read as abstracts only. No numeric affinity in our evidence ('high affinity' only). Mouse pair is ortholog-inferred.","key_references":[{"PMID":"10806482","why":"PDGF-C binds and activates PDGFRA; mouse in vivo support"},{"PMID":"11297552","why":"Competition binding of PDGF-CC to PDGFRA homodimers and alpha/beta heterodimers"}],"covers":["LR001198","LR004607"]},"LR004609":{"pair":"PDGFD -> PDGFRB","headline":"PDGFD, once proteolytically activated, is an agonistic ligand specific for PDGFRB.","interaction_type":"direct binding","direction_and_effect":"Upon limited proteolysis, PDGF-DD is activated and becomes a specific agonistic ligand for PDGFR-beta; it is described as the first known PDGFR-beta-specific ligand [PMID:11331881]. UniProt: PDGFD interacts with PDGFRB homodimers and PDGFRA:PDGFRB heterodimers [DB:UniProt].","molecular_requirements":"Active ligand is the disulphide-linked PDGF-DD homodimer after proteolytic activation [PMID:11331881].","affinity_potency":[],"species_and_systems":"Abstract only; species and system details not reported in our evidence [PMID:11331881]. UniProt records exist for both partners [DB:UniProt]. The project record lists human and mouse interactions, mouse not ortholog-inferred.","localisation_and_range":"PDGFD flagged secreted; PDGFRB transmembrane [flag]; secreted dimer after proteolysis [PMID:11331881].","caveats":"One paper, abstract only; the evidence sentence is functional-agonist wording and no numbers are reported.","key_references":[{"PMID":"11331881","why":"Identifies activated PDGF-DD as a PDGFR-beta-specific agonist"}],"covers":["LR001200","LR004609"]},"LR003088":{"pair":"PDPN -> CD177","headline":"Human PDPN binds CD177 directly with micromolar affinity, and CD177 acts as a functional antagonist in fibroblasts.","interaction_type":"direct binding","direction_and_effect":"Screening identified CD177 as a PDPN binding partner; cellular assays show CD177 is a functional antagonist, recapitulating the phenotype of PDPN-deficient cancer-associated fibroblasts [PMID:34879110].","molecular_requirements":"Binding was measured with recombinant ectodomains; no co-receptor requirement reported in our evidence [PMID:34879110].","affinity_potency":[{"value":"KD = 3.3 \u00b1 0.7 \u03bcM","assay":"surface plasmon resonance, recombinant PDPN ectodomain","system":"human proteins","cite":"PMID:34879110"}],"species_and_systems":"Human proteins and primary human CAFs from colorectal cancer [PMID:34879110]. No binding between mouse CD177 and mouse PDPN was detected, so the interaction may be human-specific [PMID:34879110].","localisation_and_range":"Both are membrane proteins in the paper's setting (CD177 on neutrophils); the secreted flag on CD177 comes from an annotation flag [flag]. Contact-dependent use is likely but the soluble Fc ectodomain was used as stimulus [PMID:34879110].","caveats":"Affinity is 10-fold weaker than CLEC-2 (KD = 210 \u00b1 0.3 nM) [PMID:34879110]. Mouse pair is ortholog-inferred but the paper reports no mouse binding.","key_references":[{"PMID":"34879110","why":"Interactome screen, SPR KD and antagonist phenotype in CAFs"}],"covers":["LR003088","LR006311"]},"LR001936":{"pair":"PF4V1 -> CXCR3","headline":"CXCL4L1 induces chemotaxis in CXCR3A-transfected cells; one abstract-only functional paper, no binding data.","interaction_type":"functional only","direction_and_effect":"Both CXCL4L1 isoforms induced migration of CXCR3A-transfected cells from 125 ng/ml onward; the curator labels it agonist [PMID:28859966].","molecular_requirements":"Not reported in our evidence beyond CXCR3A. N-terminal extension (-4-70) did not change activity [PMID:28859966].","affinity_potency":[],"species_and_systems":"CXCR3A-transfected cells in chemotaxis assays; platelet-derived human isoforms [PMID:28859966].","localisation_and_range":"PF4V1 is flagged secreted [flag].","caveats":"Abstract only. Direct binding not shown; CXCL4L1 is described as angiostatic, and only the transfectant chemotaxis supports this pair. No database records.","key_references":[{"PMID":"28859966","why":"CXCL4L1 isoforms induce CXCR3A chemotaxis"}],"covers":["LR001936"]},"LR004618":{"pair":"PGF -> FLT1","headline":"PlGF binds FLT1 (VEGFR1): crystal structure, mutagenesis and binding papers, plus PDB 1RV6.","interaction_type":"direct binding","direction_and_effect":"PlGF binds FLT1 with high affinity but not Flk-1/KDR [PMID:7929268]; the curator labels it agonist. PlGF binds the same VEGFR1 interface as VEGF [PMID:14684734].","molecular_requirements":"VEGFR1 Ig-like domain 2 carries the binding determinants; Glu137, Lys171, His223 and Arg224 affect PlGF but not VEGF binding [PMID:9452434] [PMID:14684734].","affinity_potency":[],"species_and_systems":"Human proteins; crystal structure at 2.5 A [PMID:14684734] and cell and soluble-receptor binding [PMID:7929268]. Mouse pair is ortholog-inferred.","localisation_and_range":"PGF is flagged secreted [flag]; PlGF152 binds heparin and PlGF131 does not [PMID:7929268].","caveats":"All abstract only. PlGF alone showed little direct mitogenic activity but potentiated VEGF [PMID:7929268]. Structure 1RV6 [DB:PDB 1RV6]; BioGRID and IntAct agree [DB:BioGRID] [DB:IntAct].","key_references":[{"PMID":"14684734","why":"Crystal structure of PlGF bound to VEGFR1 domain 2"},{"PMID":"7929268","why":"PlGF binds Flt-1 but not KDR"},{"PMID":"9452434","why":"Alanine scanning of Flt-1 domains"}],"covers":["LR001215","LR004618"]},"LR003097":{"pair":"PGLYRP1 -> CCR5","headline":"Evidence argues against: PGLYRP1 alone does not bind CCR5; only S100A4/Mts1 binds.","interaction_type":"conflicting","direction_and_effect":"Verified negative: the abstract says only Mts1 binds the CCR5 extracellular domain, excluding Tag7 (PGLYRP1) [PMID:30713770].","molecular_requirements":"The Tag7-Mts1 complex induces lymphocyte migration while neither protein does alone; UniProt says the complex is a ligand of CCR5 [PMID:30713770] [DB:UniProt].","affinity_potency":[],"species_and_systems":"Human PBM lymphocytes [PMID:30713770]. Mouse pair is ortholog-inferred.","localisation_and_range":"PGLYRP1 is flagged secreted [flag].","caveats":"Abstract only. Support for PGLYRP1 as a CCR5 ligand exists only as a complex annotation in UniProt [DB:UniProt].","key_references":[{"PMID":"30713770","why":"Only Mts1 of the Tag7-Mts1 complex binds CCR5"}],"covers":["LR003097","LR006319"]},"LR006319":{"pair":"PGLYRP1 -> CCR5","headline":"Evidence argues against: PGLYRP1 alone does not bind CCR5; only S100A4/Mts1 binds.","interaction_type":"conflicting","direction_and_effect":"Verified negative: the abstract says only Mts1 binds the CCR5 extracellular domain, excluding Tag7 (PGLYRP1) [PMID:30713770].","molecular_requirements":"The Tag7-Mts1 complex induces lymphocyte migration while neither protein does alone; UniProt says the complex is a ligand of CCR5 [PMID:30713770] [DB:UniProt].","affinity_potency":[],"species_and_systems":"Human PBM lymphocytes [PMID:30713770]. Mouse pair is ortholog-inferred.","localisation_and_range":"PGLYRP1 is flagged secreted [flag].","caveats":"Abstract only. Support for PGLYRP1 as a CCR5 ligand exists only as a complex annotation in UniProt [DB:UniProt].","key_references":[{"PMID":"30713770","why":"Only Mts1 of the Tag7-Mts1 complex binds CCR5"}],"covers":["LR003097","LR006319"]},"LR005275":{"pair":"PLA2G2A -> ITGA4","headline":"sPLA2-IIA binds and activates integrin alpha4beta1; alpha4 is listed as one subunit of the heterodimer.","interaction_type":"direct binding","direction_and_effect":"sPLA2-IIA bound alpha4beta1, competed with VCAM-1 for binding, and bound a site close to those for VCAM-1 and CS-1 in the alpha4 subunit [PMID:18635536]. It activated alpha4beta1 in a site 2-mediated manner, agonist effect [PMID:25398877]. Signalling was independent of catalytic activity [PMID:18635536]. UniProt records the site 2 binding [DB:UniProt P13612].","molecular_requirements":"The heterodimer alpha4beta1 binds; a site 2 peptide from integrin beta1 blocked sPLA2-IIA effects [PMID:25398877], so the beta1 chain contributes. A separate complex entry exists.","affinity_potency":[],"species_and_systems":"Human ligand and human receptor; integrin binding and cell assays [PMID:18635536][PMID:25398877]. Mouse pair is ortholog-inferred.","localisation_and_range":"Secreted, from the PLA2G2A secreted flag [flag].","caveats":"Abstract-level reading for both papers; one paper's full-text read is marked unverified. Binding Kd given in [PMID:18635536] was for alphavbeta3, not alpha4beta1. Not reported in our evidence for alpha4 alone.","key_references":[{"PMID":"18635536","why":"sPLA2-IIA binds alphavbeta3 and alpha4beta1, competes with VCAM-1"},{"PMID":"25398877","why":"Site 2 activation of alpha4beta1, alphavbeta3, alpha5beta1"}],"covers":["LR001938","LR005275"]},"LR007084":{"pair":"PLA2G2A -> ITGA5:ITGB1","headline":"Complex entry for sPLA2-IIA and alpha5beta1; no curated papers, supported by UniProt and IntAct.","interaction_type":"database-asserted only","direction_and_effect":"UniProt states ITGA5:ITGB1 binds PLA2G2A via site 2, inducing integrin conformational changes and enhanced ligand binding to site 1 [DB:UniProt P05556]. UniProt also states the integrin beta1 entry binds to and activates ITGAV:ITGB3, ITGA4:ITGB1 and ITGA5:ITGB1 [DB:UniProt P14555]. IntAct lists an ELISA record [DB:IntAct P05556-P14555].","molecular_requirements":"Alpha5:beta1 heterodimer as a unit; chain-only evidence: not reported in our evidence.","affinity_potency":[],"species_and_systems":"Human, per the records; no papers judged under this entry.","localisation_and_range":"Secreted ligand, from the PLA2G2A flag [flag].","caveats":"No papers judged; database annotation only [DB:UniProt P05556].","key_references":[],"covers":["LR007084"]},"LR006328":{"pair":"PLAT -> ANXA2","headline":"tPA's protease-independent NF-kB signalling in macrophages requires annexin A2; one abstract-only paper plus BioGRID.","interaction_type":"functional only","direction_and_effect":"The protease-independent action of tPA required its membrane receptor annexin A2 in macrophage NF-kB activation [PMID:22677557]. BioGRID lists a reconstituted complex [DB:BioGRID 278617].","molecular_requirements":"tPA induced annexin A2 aggregation and interaction with CD11b; CD11b ablation abolished the effect [PMID:22677557], so the effect needs a co-partner beyond ANXA2.","affinity_potency":[],"species_and_systems":"Experimental species not recorded; abstract mentions tPA-knockout mice and macrophages [PMID:22677557]. Both human and mouse pairs are ortholog-inferred.","localisation_and_range":"tPA secreted per flag [flag]; annexin A2 acting at the membrane per the abstract [PMID:22677557].","caveats":"Abstract only; physical binding is not described in the abstract, which says 'required its membrane receptor' [PMID:22677557]. Binding rests on a BioGRID record not linked to a dossier paper.","key_references":[{"PMID":"22677557","why":"tPA activates macrophage NF-kB via annexin A2/CD11b and ILK"}],"covers":["LR003107","LR006328"]},"LR004627":{"pair":"PLAU -> LRP2","headline":"uPA:PAI-1 complexes bind LRP2 (gp330) with Kd about 0.8 nM and are endocytosed; two abstract-only papers.","interaction_type":"direct binding","direction_and_effect":"Affinity-purified gp330 bound PAI-1 complexed with uPA, calcium-dependently, inhibited by RAP and tPA-PAI-1 complexes [PMID:8344937]. In type II pneumocytes, endocytosis of uPA:PAI-1 complexes was demonstrated and RAP blocked internalisation and degradation [PMID:7673355]. Clearance receptor function, not signalling.","molecular_requirements":"The binding unit is the uPA:PAI-1 complex; anti-gp330 antibodies inhibited 30-50% and anti-LRP antibodies partially inhibited the rest, so gp330 acts with LRP [PMID:7673355].","affinity_potency":[{"value":"Kd about 0.8 nM","assay":"binding of uPA.PAI-1 complexes to affinity-purified gp330, 4 degrees C","system":"rabbit renal cortex gp330","cite":"PMID:8344937"}],"species_and_systems":"Rabbit renal cortex gp330 and rabbit proximal tubules [PMID:8344937]; immortalized rat type II pneumocytes [PMID:7673355]. No human experiment shown, though curated as human.","localisation_and_range":"LRP2 binding is at the apical part of proximal tubules [PMID:8344937]; uPA secreted per flag [flag].","caveats":"Abstract only; free uPA binding is not the tested species. Human and mouse pairs are ortholog-inferred.","key_references":[{"PMID":"8344937","why":"Kd about 0.8 nM for uPA.PAI-1 binding to gp330"},{"PMID":"7673355","why":"gp330-mediated endocytosis of uPA:PAI-1 in pneumocytes"}],"covers":["LR001224","LR004627"]},"LR006337":{"pair":"PLAUR -> LRP1","headline":"Only functional, complex-level evidence for PLAUR with LRP1; no direct binding measured in the judged papers.","interaction_type":"functional only","direction_and_effect":"Interfering with LRP binding to the [uPAR:uPA:PAI-1] complex markedly decreased human myogenic cell motility [PMID:10896774]. Database records (BioGRID affinity-capture and reconstituted complex; UniProt) also assert PLAUR-LRP1 interaction [DB:BioGRID][DB:UniProt].","molecular_requirements":"LRP binds the assembled uPAR:uPA:PAI-1 complex, not uPAR alone [PMID:10896774]. UniProt says the interaction leads to PLAUR internalisation and is impaired by SORL1 [DB:UniProt].","affinity_potency":[],"species_and_systems":"Human myogenic cells; abstract only [PMID:10896774].","localisation_and_range":"Ligand flagged secreted [flag].","caveats":"Evidence is interference, not binding. A second paper was abstract-insufficient.","key_references":[{"PMID":"10896774","why":"LRP involvement in uPAR:uPA:PAI-1 complex-dependent motility"}],"covers":["LR003116","LR006337"]},"LR004636":{"pair":"PLTP -> ABCA1","headline":"PLTP cross-links to ABCA1, competing with apoA-I, and promotes lipid efflux; abstract-level evidence.","interaction_type":"direct binding","direction_and_effect":"PLTP and apoA-I were each covalently cross-linked to ABCA1 and blocked each other's cross-linking; both stabilised ABCA1 protein [PMID:14559902]. PLTP promoted cholesterol and phospholipid efflux, most with HDL present [PMID:14559902].","molecular_requirements":"Shared or overlapping ABCA1 binding site with apoA-I [PMID:14559902].","affinity_potency":[],"species_and_systems":"Human proteins; murine macrophages and ABCA1-transfected BHK cells [PMID:14559902].","localisation_and_range":"Ligand flagged secreted; ABCA1 membrane transporter [flag].","caveats":"Abstract only. PLTP acts as an intermediary transferring lipid to HDL. ABCA1 is a transporter, not a classical signalling receptor. One more row not shown.","key_references":[{"PMID":"14559902","why":"PLTP interacts with ABCA1 and enhances efflux"}],"covers":["LR001233","LR004636"]},"LR009037":{"pair":"PLXNA1 -> SEMA6D","headline":"Functional in vivo evidence in chick that Plexin-A1 is the Sema6D receptor; stored reversed and abstract-only.","interaction_type":"functional only","direction_and_effect":"Sema6D exerts region-specific effects on chick heart; Plexin-A1 mediates these as the major Sema6D-binding receptor [PMID:14977921]. Migration was promoted in conotruncal cells and inhibited in ventricle cells [PMID:14977921].","molecular_requirements":"Plexin-A1 partners with VEGFR2 in conotruncal segment or with Off-track in the ventricle [PMID:14977921]. Reactome has a SEMA6D:PLXNA1:TREM2:DAP12 complex [DB:Reactome R-HSA-416720].","affinity_potency":[],"species_and_systems":"Chicken embryo and explants [PMID:14977921]; human database records.","localisation_and_range":"Both partners are membrane-associated per flags [flag]; range not reported otherwise.","caveats":"Abstract only; the row is stored in reverse orientation (Sema6D is the ligand). No affinity.","key_references":[{"PMID":"14977921","why":"Sema6D signals via Plexin-A1 in chick heart"}],"covers":["LR009037"]},"LR004645":{"pair":"POMC -> MC5R","headline":"POMC-derived peptides bind and activate MC5R in transfected cells; abstract-level evidence with several peptides.","interaction_type":"direct binding","direction_and_effect":"POMC-derived peptides alpha-MSH, ACTH1-39, ACTH1-17, ACTH1-10 and ACTH4-10 increase cAMP in HEK293 cells with mouse MC5R, and alpha-MSH and ACTH1-17 are most potent [PMID:11785979]. MC5R has higher affinity for alpha-MSH than gamma-MSH and beta-MSH in COS cell binding [PMID:7774675]. GtoPdb lists agonist action [DB:GtoPdb]; a POMC-MC5R structure is in the PDB [DB:PDB 8INR].","molecular_requirements":"Not reported in our evidence.","affinity_potency":[{"value":"Kd 5.05 +/- 1.00 nmol/l","assay":"[125I][Nle4, D-Phe7]alpha-MSH binding","system":"COS cells; abstract text is ambiguous about which receptor this value belongs to","cite":"PMID:7774675"}],"species_and_systems":"Mouse MC5R in HEK293 cells with human ligand [PMID:11785979]; COS cells with species unspecified [PMID:7774675]. Both read as abstracts only.","localisation_and_range":"POMC flagged secreted, MC5R transmembrane [flag]; range not tested.","caveats":"The Kd value is ambiguous because the abstract labels two receptors as MC3 [PMID:7774675]. Distinct POMC products give different rank orders for cAMP and calcium, so a gene-level pair conflates peptides [PMID:11785979]. Ligand display name is beta-endorphin, not the peptides tested [flag].","key_references":[{"PMID":"11785979","why":"cAMP and calcium responses at mouse MC5R to POMC peptides"},{"PMID":"7774675","why":"Radioligand binding at MC5R"}],"covers":["LR001243","LR004645"]},"LR006346":{"pair":"POSTN -> ITGB3","headline":"Periostin-dependent cell adhesion is blocked by anti-alpha(V)beta(3) antibody, supporting ITGB3 as a periostin receptor; one abstract-level paper.","interaction_type":"functional only","direction_and_effect":"Purified recombinant periostin supports adhesion of ovarian epithelial cells, inhibited by monoclonal antibodies against alpha(V)beta(3) or alpha(V)beta(5), but not by anti-beta(1) antibody [PMID:12235007]. The curator notes alphaVbeta3 colocalises to focal adhesions on periostin [PMID:12235007].","molecular_requirements":"The evidence concerns the alphaV-beta heterodimers, so alphaV with ITGB3 is needed; ITGB3 alone is not tested [PMID:12235007].","affinity_potency":[],"species_and_systems":"Human ovarian epithelial cells, recombinant periostin; read as abstract only [PMID:12235007]. The mouse pair is ortholog-inferred.","localisation_and_range":"Periostin is flagged secreted [flag]; adhesion to purified protein suggests matrix-bound action, which is an inference.","caveats":"Antibody blocking is indirect; the abstract does not report binding or affinity. The same antibody result covers both beta chains and does not separate them. Only one paper confirmed in the shown dossier.","key_references":[{"PMID":"12235007","why":"Antibody-blocked adhesion to periostin via alphaV integrins"}],"covers":["LR003125","LR006346"]},"LR004654":{"pair":"PRLH -> PRLHR","headline":"Well supported agonist pair: PrRP binds GPR10 with sub-nM Kd and activates it in transfected cells; GtoPdb and PDB structures agree.","interaction_type":"direct binding","direction_and_effect":"Human and rat PrRP-20 and PrRP-31 are potent full agonists at GPR10, raising intracellular calcium without changing cAMP [PMID:11030716]. PrRP31 and PrRP20 promoted arachidonic acid metabolite release in receptor-expressing CHO cells but not mock cells [PMID:9607765]. GtoPdb lists a full agonist [DB:GtoPdb].","molecular_requirements":"Receptor alone sufficient in transfected cells. Both the 31- and 20-residue PrRP forms act [PMID:11030716].","affinity_potency":[{"value":"Kd 0.026 nM","assay":"[125I]-PrRP-20 saturation binding, high-affinity site","system":"HEK293 cells stably expressing human GPR10","cite":"PMID:11030716"},{"value":"Kd 0.57 nM","assay":"[125I]-PrRP-20 saturation binding, low-affinity site","system":"HEK293 cells stably expressing human GPR10","cite":"PMID:11030716"}],"species_and_systems":"Human GPR10 in HEK293 [PMID:11030716]; the 1998 identification used human receptor cDNA and rat pituitary cells, with a rat ortholog (UHR-1) in CHO cells [PMID:9607765]. Mouse pair is projected.","localisation_and_range":"PRLH is flagged secreted and PRLHR transmembrane [flag].","caveats":"The 9607765 evidence was browser-read and the curator's quote is unverified pending spot-check; the 11030716 paper was abstract-only. Structures exist [DB:PDB 8ZPS].","key_references":[{"PMID":"11030716","why":"Saturable PrRP binding to GPR10, Kd 0.026 nM"},{"PMID":"9607765","why":"Orphan receptor ligand identification of PrRP"}],"covers":["LR001253","LR004654"]},"LR006355":{"pair":"PRNP -> NCAM1","headline":"Co-crosslinking and binding-site mapping show PrP-NCAM1 complexes in mouse N2a cells, but a sibling row was judged pair_absent; conflicting curation.","interaction_type":"conflicting","direction_and_effect":"PrP(C) was found in complexes with N-CAM splice variants in mouse N2a cells by formaldehyde crosslinking and LC/MS/MS; the PrP-binding site maps to the FNIII modules of N-CAM [PMID:11743735]. N-CAM-/- mice still succumbed to scrapie, so N-CAM is not needed for PrP(Sc) replication [PMID:11743735].","molecular_requirements":"Glycans are not needed; the PrP face uses the N terminus, helix A and adjacent loop [PMID:11743735].","affinity_potency":[],"species_and_systems":"Mouse neuroblastoma N2a and ScN2a cells and N-CAM-/- mice [PMID:11743735].","localisation_and_range":"PRNP is flagged non-secreted; NCAM1 is flagged secreted and transmembrane [flag]. The complexes isolate with caveolae-like domains [PMID:11743735].","caveats":"Same paper has one row confirmed and one pair_absent (human row propagated from the mouse row); both are abstract-only. Complex formation is shown, not signalling or direction. BioGRID lists reconstituted complex, protein-peptide and co-crystal records from another paper [DB:BioGRID].","key_references":[{"PMID":"11743735","why":"In situ crosslinking identifies PrP-N-CAM complexes"}],"covers":["LR003134","LR006355"]},"LR001945":{"pair":"PROC -> TEK","headline":"Activated protein C reported to bind TEK (Tie2) directly with Kd ~3 nM and act as agonist; single abstract-only paper.","interaction_type":"direct binding","direction_and_effect":"APC bound Tie2 directly, competed with angiopoietins, and rapidly activated Tie2 to enhance endothelial barrier function; blocking Tie2 restricted the barrier effect, consistent with agonism [PMID:28005151].","molecular_requirements":"Not reported in our evidence beyond Tie2 itself; the paper names the activated form (APC) as the binder [PMID:28005151].","affinity_potency":[{"value":"Kd ~3 nM","assay":"binding assay, stronger than Ang2","system":"human APC and human Tie2","cite":"PMID:28005151"}],"species_and_systems":"Human ligand and receptor; binding assays, cell monolayer barrier assay and in vivo studies [PMID:28005151].","localisation_and_range":"PROC is flagged secreted and TEK transmembrane [flag], so signalling would be paracrine/endocrine onto membrane-bound receptor.","caveats":"Only one paper, read as abstract only; it is the sole support and no database records exist. Species of the in vivo work is not stated in the dossier.","key_references":[{"PMID":"28005151","why":"Direct binding (Kd ~3 nM) and Tie2 activation by APC."}],"covers":["LR001945"]},"LR004663":{"pair":"PSAP -> GPR37","headline":"Prosaptide, the active PSAP fragment, binds and activates GPR37 (pEC50 8.15); full-length prosaposin also stimulates; abstract-only.","interaction_type":"direct binding","direction_and_effect":"Prosaptide was the sole hit in an orphan-neuropeptide screen, promoted GPR37 endocytosis, bound it and activated signalling; it induced ERK phosphorylation, 35S-GTPgammaS binding and inhibited forskolin-stimulated cAMP [PMID:23690594]. GtoPdb lists agonist with pEC50 [DB:GtoPdb].","molecular_requirements":"Prosaptide is the active fragment; full-length prosaposin also stimulated GPR37 signalling [PMID:23690594]. Receptor is a single GPCR chain.","affinity_potency":[{"value":"pEC50 8.15","assay":"prosaptide agonist activity","system":"human prosaptide at human GPR37","cite":"PMID:23690594"}],"species_and_systems":"Human proteins in cells; primary astrocytes were protected from oxidative stress, attenuated by siRNA knockdown of GPR37/GPR37L1 [PMID:23690594]. Mouse pair is ortholog-inferred.","localisation_and_range":"PSAP flagged secreted and GPR37 transmembrane [flag]; paracrine.","caveats":"One paper, abstract-only; two further rows pending. Astrocyte knockdown targeted GPR37 and GPR37L1 together [PMID:23690594].","key_references":[{"PMID":"23690594","why":"Deorphanisation of GPR37 by prosaptide and prosaposin."}],"covers":["LR001263","LR004663"]},"LR008434":{"pair":"PSEN1 -> NOTCH1","headline":"Presenilin-1 associates with NOTCH1 per databases, as the gamma-secretase protease for a substrate; not a ligand-receptor pair.","interaction_type":"database-asserted only","direction_and_effect":"UniProt says PSEN1 associates with NOTCH1 via its transmembrane domain [DB:UniProt]. No signalling direction or effect shown in our evidence beyond a Stimulatory annotation.","molecular_requirements":"NOTCH1 transmembrane region interacts with PSEN1 [DB:UniProt].","affinity_potency":[],"species_and_systems":"Affinity capture-Western, FRET, co-IP and a PDB structure record [DB:BioGRID][DB:PDB 6IDF].","localisation_and_range":"Both membrane proteins [flag]; no range data.","caveats":"No curator-verified papers (all judged different_entity). Evidence is database only and reflects enzyme-substrate association.","key_references":[],"covers":["LR008434"]},"LR006364":{"pair":"PTH -> LRP6","headline":"PTH engages LRP6 indirectly through a PTH1R/LRP6 complex in one in vitro study.","interaction_type":"functional only","direction_and_effect":"PTH treatment induces endocytosis of a PTH1R/LRP6 complex that enhances Smad1 phosphorylation, an agonist effect [PMID:22589223].","molecular_requirements":"PTH1R is required; the effect was abrogated by PTH1R deletion, and LRP6 forms a complex with PTH1R [PMID:22589223].","affinity_potency":[],"species_and_systems":"Mesenchymal stromal cells in vitro and transplanted cells in vivo, curator lists human ligand and receptor [PMID:22589223].","localisation_and_range":"Ligand and receptor flagged secreted and transmembrane respectively [flag].","caveats":"No direct PTH-LRP6 binding shown; the curator notes the interaction is through complex formation with PTH1R. Abstract only.","key_references":[{"PMID":"22589223","why":"PTH1R/LRP6 endocytosis enhances BMP-Smad1 signalling."}],"covers":["LR003143","LR006364"]},"LR004672":{"pair":"PTHLH -> PTH2R","headline":"Our evidence points to no PTHrP activity at PTH2R; the one judged paper is a verified negative, while GtoPdb asserts an agonist.","interaction_type":"conflicting","direction_and_effect":"Native PTHrP responds poorly at the PTH2 receptor: the receptor responds potently to PTH but not to PTHrP [PMID:8702701]. Only after residues 5 and 23 were changed to the PTH residues did PTHrP bind and fully stimulate cAMP; [Trp23]hPTHrP-(1-36) was an antagonist at PTH2R [PMID:8702701]. GtoPdb nonetheless lists a full agonist [DB:GtoPdb].","molecular_requirements":"Residue 5 (His in PTHrP, Ile in PTH) determines signalling capability and residue 23 (Phe in PTHrP, Trp in PTH) determines binding affinity at PTH2R [PMID:8702701].","affinity_potency":[],"species_and_systems":"Human PTH-2 receptor with human hybrid peptides [PMID:8702701]. Human and mouse pairs are both ortholog-inferred.","localisation_and_range":"PTHLH is flagged as secreted and PTH2R as transmembrane [flag].","caveats":"The curated judgement is pair_absent (abstract only) [PMID:8702701]. Five other rows were abstract_insufficient and one was a different entity, so there is no positive primary evidence. GtoPdb agonist entries cite 11602681 and 8702701 [DB:GtoPdb], but the latter is the negative result.","key_references":[{"PMID":"8702701","why":"Shows PTH2R responds to PTH but not PTHrP"}],"covers":["LR001272","LR004672"]},"LR006373":{"pair":"PTN -> RNF167","headline":"Single SPR study reports PTN ectodomain binding to RNF167; no functional evidence.","interaction_type":"direct binding","direction_and_effect":"PTN ectodomain captured on sensors bound RNF167; RNF128 was the negative control and showed no binding [PMID:36178190]. Direction or functional effect is not reported in our evidence.","molecular_requirements":"Tested with the RNF167 extracellular domain; co-receptors or subunits not reported in our evidence.","affinity_potency":[],"species_and_systems":"Human proteins; surface plasmon resonance with recombinant ectodomains, found as a hit in a CRISPRa cell-based screen [PMID:36178190].","localisation_and_range":"PTN is flagged secreted [flag]. RNF167 has no secreted or transmembrane flag in the dossier; the paper describes it as a transmembrane PA-TM-RING E3 ligase [PMID:36178190].","caveats":"Only one paper, in vitro binding; no affinity reported; the paper notes E3 ligase interactions tend to have very weak affinity and fast kinetics [PMID:36178190]. Physiological signalling relevance not shown.","key_references":[{"PMID":"36178190","why":"SPR binding of PTN to RNF167 ectodomain"}],"covers":["LR003152","LR006373"]},"LR001279":{"pair":"PTN -> SDC3","headline":"Early affinity purification and solid-phase binding identify N-syndecan (SDC3) as a PTN (HB-GAM) receptor.","interaction_type":"direct binding","direction_and_effect":"A heparan-sulfate-bearing component isolated from perinatal rat brain on HB-GAM (PTN) affinity matrix was N-syndecan; anti-N-syndecan antibodies inhibited HB-GAM-induced neurite outgrowth (curator annotation: agonist) [PMID:8175719].","molecular_requirements":"Binding involves heparan sulfate chains on a 120-kDa core protein [PMID:8175719]; co-receptors not reported in our evidence.","affinity_potency":[{"value":"KD 0.6 nM","assay":"solid-phase binding assay","system":"N-syndecan from rat brain with HB-GAM","cite":"PMID:8175719"}],"species_and_systems":"Rat brain neurons and recombinant baculovirus HB-GAM [PMID:8175719]; dossier labels species human, which conflicts with the abstract. Human and mouse pairs are ortholog-inferred.","localisation_and_range":"PTN is flagged secreted [flag]; SDC3 carries no localisation flag. N-syndecan was seen at neurite and cell soma surface [PMID:8175719].","caveats":"Abstract only; one confirmed paper; glycan-dependent binding; other papers were judged review-only or pending and are not shown.","key_references":[{"PMID":"8175719","why":"N-syndecan isolated as HB-GAM receptor, KD 0.6 nM"}],"covers":["LR001279","LR004679"]},"LR005284":{"pair":"PTPRC -> MRC1","headline":"Mannose receptor binds CD45 glycans; one paper reports a functional effect on T cells, both abstract-level.","interaction_type":"direct binding","direction_and_effect":"MRC1 on dendritic cells interacts with CD45 on T cells, inhibiting its phosphatase activity, upregulating CTLA-4 and inducing T-cell tolerance [PMID:27601670]. The cysteine-rich domain of MRC1 (CR-Fc) bound CD45 isoforms in a sugar-dependent manner [PMID:10575006].","molecular_requirements":"Binding by the CR domain is glycan-dependent and specific to cell-specific glycoforms; two low molecular weight CD45 isoforms bound [PMID:10575006].","affinity_potency":[],"species_and_systems":"Mouse spleen and lymph node lysates and macrophages [PMID:10575006]; dendritic cell/T-cell cocultures in vitro and in vivo [PMID:27601670]; species of the latter not specified.","localisation_and_range":"Both flagged transmembrane [flag]; contact-dependent.","caveats":"Abstracts only; no affinity; binding depends on particular glycoforms so may not occur on every CD45-expressing cell. IntAct lists a solid-phase assay [DB:IntAct]. Mouse pair listed as not ortholog-inferred, but dossier experiment species fields conflict with each other.","key_references":[{"PMID":"27601670","why":"MRC1-CD45 interaction inhibits CD45 phosphatase on T cells"},{"PMID":"10575006","why":"CR domain of mannose receptor binds CD45 glycoforms"}],"covers":["LR001948","LR005284"]},"LR006382":{"pair":"PTPRD -> SLITRK2","headline":"Direct structural and cell-adhesion evidence that PTPRD and SLITRK2 bind; splicing-dependent.","interaction_type":"direct binding","direction_and_effect":"A crystal structure of the Slitrk2-PTP-delta trans-synaptic adhesion complex was reported, with mutational analysis showing splicing-dependent adhesion that induces synaptic differentiation [PMID:25989451]. Slitrk2-expressing L cells also aggregated with PTP-delta-expressing L cells [PMID:23345436].","molecular_requirements":"Binding depends on splicing of the type IIa RPTPs and Slitrks [PMID:25989451]. Single-chain sufficiency beyond the two domains crystallised is not reported in our evidence.","affinity_potency":[],"species_and_systems":"Structure paper read as abstract only; species of the proteins in it is not stated in the dossier [PMID:25989451]. Aggregation assay used mouse L cells [PMID:23345436]. Human and mouse pairs both listed, neither projected.","localisation_and_range":"Both flagged transmembrane [flag]; trans-synaptic adhesion indicates contact-dependent signalling [PMID:25989451].","caveats":"Structural paper was read only as abstract (curator notes were taken from it); the aggregation quote from the second paper is flagged unverifiable pending spot-check. Neither paper reports affinity in our evidence.","key_references":[{"PMID":"25989451","why":"Crystal structure of the Slitrk2-PTP-delta complex"},{"PMID":"23345436","why":"L-cell aggregation of Slitrk2 with PTP-delta cells"}],"covers":["LR003161","LR006382"]},"LR003169":{"pair":"PTPRS -> NTRK3","headline":"All TrkC isoforms bind PTP-sigma directly in trans with high affinity; postsynaptic TrkC and presynaptic PTP-sigma form a synaptic organising complex.","interaction_type":"direct binding","direction_and_effect":"All TrkC isoforms, but not TrkA or TrkB, function in excitatory synaptic adhesion through neurotrophin-independent high-affinity trans binding to axonal PTP-sigma; PTP-sigma triggers and TrkC mediates postsynaptic clustering, so organising signals run both ways [PMID:21262467].","molecular_requirements":"Noncatalytic TrkC isoforms also work, so the kinase domain is not needed for adhesion [PMID:21262467]. No further subunit requirements are reported in our evidence.","affinity_potency":[],"species_and_systems":"Hippocampal neuron-fibroblast coculture, a TrkC-neutralising antibody that blocks TrkC-PTP-sigma interaction, TrkC knockdown in culture and in vivo [PMID:21262467]. Human pair is ortholog-inferred; the mouse pair is not.","localisation_and_range":"Membrane-bound trans interaction across the synapse; PTPRS is also flagged secreted [flag] [PMID:21262467].","caveats":"Abstract-only read; no numeric affinity is reported in our evidence ('high-affinity' only). Reactome, BioGRID and UniProt also list the pair [DB:Reactome] [DB:UniProt].","key_references":[{"PMID":"21262467","why":"TrkC-PTP-sigma bidirectional synaptic organising complex"}],"covers":["LR003169","LR006390"]},"LR006391":{"pair":"PTPRS -> SLITRK1","headline":"Mouse cell-aggregation evidence that PTP-sigma and SLITRK1 adhere; single paper.","interaction_type":"functional only","direction_and_effect":"Slitrk1-expressing cells aggregated with PTP-sigma-expressing cells; the paper concludes PTP-sigma was specifically required for excitatory synaptic differentiation by Slitrks [PMID:23345436].","molecular_requirements":"Slitrks require distinct LAR-RPTP family members for synapse formation, in an isoform-dependent manner [PMID:23345436]. Subunit needs beyond that are not reported. A BioGRID reconstituted complex is listed [DB:BioGRID].","affinity_potency":[],"species_and_systems":"Mouse proteins in mouse L cells; the abstract also uses rat brain [PMID:23345436]. Human pair is direct; mouse pair is ortholog-inferred.","localisation_and_range":"Cell-cell aggregation implies contact-dependent action; PTPRS is flagged secreted [flag] [PMID:23345436].","caveats":"Evidence is one cell-adhesion assay (aggregation), not a measured binding; the paper's abstract-level result is that Slitrks need distinct LAR-RPTP members for synapse formation [PMID:23345436]. The curation note says the quote is unverifiable pending spot-check. BioGRID lists a reconstituted complex of SLITRK1 and PTPRS from PMID 25394468 [DB:BioGRID].","key_references":[{"PMID":"23345436","why":"Slitrk-PTP-sigma cell aggregation and synapse-formation requirement"}],"covers":["LR003170","LR006391"]},"LR001954":{"pair":"PVR -> TIGIT","headline":"PVR binds TIGIT, which inhibits human NK cytotoxicity; two papers read as abstracts, plus SPR and structure records.","interaction_type":"direct binding","direction_and_effect":"TIGIT binds PVR and PVRL2 but not PVRL3, and inhibits NK cytotoxicity directly through its ITIM; it protects normal cells from NK killing [PMID:19815499]. TIGIT is described as counterbalancing CD226, with CD96 also sharing PVR (CD155) [PMID:24658051]. Effect on the receptor-bearing cell is inhibitory.","molecular_requirements":"Not reported in our evidence beyond TIGIT's own ITIM being needed for inhibition [PMID:19815499]. PVR is shared with CD226 and CD96, which compete for it [PMID:24658051].","affinity_potency":[],"species_and_systems":"Human NK cells and human proteins [PMID:19815499]. The other paper used mouse knockouts for CD96 but the TIGIT statement is background there [PMID:24658051]. IntAct records include SPR and solid phase assay; a PDB structure with PVR and TIGIT chains exists [DB:IntAct][DB:PDB 3UDW].","localisation_and_range":"TIGIT is flagged as not secreted and PVR as secreted and transmembrane [flag]; NK inhibition shown with PVR on target cells [PMID:19815499].","caveats":"Both papers were judged on abstracts only. PMID:24658051 mainly concerns CD96 vs CD226; TIGIT-PVR is background there. No affinity value in our evidence. The entry's modulatory effect is labelled Stimulatory while the papers describe inhibition of NK cells.","key_references":[{"PMID":"19815499","why":"TIGIT binds PVR and PVRL2 and inhibits NK cells via its ITIM"},{"PMID":"24658051","why":"Places TIGIT with CD226 and CD96 competing for PVR"}],"covers":["LR001954","LR005290"]},"LR004681":{"pair":"PYY -> NPY2R","headline":"PYY binds and activates NPY2R (Y2) with high affinity in human and rat systems; three papers read as abstracts.","interaction_type":"direct binding","direction_and_effect":"PYY is an agonist: human PYY decreased cAMP and raised intracellular calcium in hY2-transfected 293 cells [PMID:7592910]. In rat, PYY inhibits cAMP and intestinal secretion through a Y2 receptor, reversed by antagonist BIIE0246 [PMID:11408607].","molecular_requirements":"Not reported in our evidence; single receptor chain.","affinity_potency":[{"value":"pKd 10.17","assay":"125I-PYY saturation binding","system":"human Y2 transiently expressed","cite":"PMID:7592910"},{"value":"pKi 9.47","assay":"displacement of 125I-PYY by PYY","system":"human Y2 transiently expressed","cite":"PMID:7592910"}],"species_and_systems":"Human Y2 cloned from hippocampus (293 cells) [PMID:7592910]; human brain Y2 cloned, high affinity for NPY, PYY and C-terminal fragments [PMID:8632753]; rat intestinal crypt membranes and rat Y2 in CHO cells [PMID:11408607].","localisation_and_range":"PYY is flagged secreted [flag]; the rat paper shows an endocrine/paracrine action on intestinal secretion [PMID:11408607].","caveats":"All three papers were abstract only. PMID:8632753 gives no number in our excerpt. NPY is similarly potent (pKi = 9.27), so PYY is not selective over NPY [PMID:7592910].","key_references":[{"PMID":"7592910","why":"Saturable PYY binding and cAMP/Ca2+ response at human Y2"},{"PMID":"11408607","why":"Rat peripheral Y2 as PYY receptor, binding and in vivo function"},{"PMID":"8632753","why":"Independent cloning of human brain Y2 with high PYY affinity"}],"covers":["LR001281","LR004681"]},"LR003178":{"pair":"QRFP -> NPFFR2","headline":"QRFP (26RFa) binds and activates human NPFFR2 in one full-text paper, as part of an RF-amide panel; cross-reactivity, not the cognate pair.","interaction_type":"direct binding","direction_and_effect":"RF-amide peptides including 26RFa bound NPFFR in radioligand competition and activated it in [35S]GTPgammaS and cAMP assays [PMID:23911743]. In mice, effects of the RF-amide peptides were antagonised by RF9, supporting direct NPFF receptor activation [PMID:23911743].","molecular_requirements":"Not reported in our evidence.","affinity_potency":[{"value":"Ki 0.1-10 nM","assay":"radioligand competition on membranes, whole peptide panel (not QRFP alone)","system":"CHO cells expressing human receptor","cite":"PMID:23911743"}],"species_and_systems":"Human receptor in CHO membranes; in vivo pain tests in mice with peptides given i.c.v. [PMID:23911743].","localisation_and_range":"QRFP is flagged secreted [flag]; mouse effects were by central injection.","caveats":"The Ki range covers all peptides, not QRFP specifically. The paper reports GPR103 as selective for its cognate ligand, so NPFF receptors are secondary targets. Mouse pair is projected.","key_references":[{"PMID":"23911743","why":"Systematic RF-amide peptide binding and activation of NPFF1/NPFF2"}],"covers":["LR003178","LR006398"]},"LR001288":{"pair":"RARRES2 -> CMKLR2","headline":"Chemerin binds and activates GPR1 (CMKLR2) with nanomolar affinity; supported by binding, arrestin and Tango assays, GtoPdb and PDB structures.","interaction_type":"direct binding","direction_and_effect":"Chemerin binds GPR1 with low nanomolar affinity but no significant G-protein activation was detected, whereas beta-arrestin recruitment and internalization occurred [PMID:27716822]. GPR1 shows ligand-induced arrestin3 recruitment and internalization, and also constitutive internalization, suggesting dual signaling and scavenging roles [PMID:34241650]. In a Tango assay GPR1 responded to chemerin [PMID:18165312]. GtoPdb lists a full agonist [DB:GtoPdb].","molecular_requirements":"The chemerin C-terminus folds into a loop and binds aromatic residues in GPR1 extracellular loops; chemerin-9 competed only at high concentrations (100-300 nM) for chemerin binding, suggesting a stronger C-terminal contribution [PMID:34241650, PMID:27716822].","affinity_potency":[{"value":"0.21 nM","assay":"saturation binding, [125I]-chemerin (0.21 nM refers to GPR1)","system":"CHO-K1 cells expressing human GPR1","cite":"PMID:27716822"},{"value":"240 pM","assay":"Tango assay, recombinant chemerin","system":"GPR1 reporter cells","cite":"PMID:18165312"},{"value":"EC50 = 2.1 nM","assay":"arrestin3 BRET recruitment, ChemS157","system":"GPR1 cells","cite":"PMID:34241650"}],"species_and_systems":"Human receptor and human chemerin in recombinant cell systems; mouse pair is inferred from human evidence.","localisation_and_range":"Chemerin is flagged secreted [flag].","caveats":"One paper (18165312) was read by browser and its quote is unverified (spot-check pending). Two further rows are pending and one is abstract_insufficient; one paper judged a different entity. The signaling mode (arrestin-biased, scavenging) differs from CMKLR1.","key_references":[{"PMID":"27716822","why":"Binding and signaling compared across three chemerin receptors"},{"PMID":"34241650","why":"GPR1 arrestin recruitment, internalization, scavenging role"},{"PMID":"18165312","why":"Tango assay identifies chemerin as GPR1 ligand"}],"covers":["LR001288","LR004687"]},"LR004690":{"pair":"RELN -> ITGB1","headline":"Reelin associates with alpha3beta1 integrin; the beta1-only attribution rests on one paper.","interaction_type":"direct binding","direction_and_effect":"Reelin was co-immunoprecipitated by beta1 integrin beads and its effect on migration depended on alpha3beta1 [PMID:10939329]. The annotation lists the effect as inhibitory [flag], matching the paper's inhibition of migration [PMID:10939329].","molecular_requirements":"Evidence is for alpha3beta1; beta1 alone is not shown to suffice, and alpha3beta1-deficient neurons lose the response [PMID:10939329].","affinity_potency":[],"species_and_systems":"Mouse and rat cortex and cultured cortical neurons; recombinant Reelin [PMID:10939329]. The human pair is ortholog-inferred.","localisation_and_range":"RELN is flagged secreted [flag].","caveats":"Single paper; chain-only (ITGB1) attribution of a heterodimer result; ITGB1 pairs with many alpha chains, not tested here beyond alpha3 [PMID:10939329].","key_references":[{"PMID":"10939329","why":"Reelin-alpha3beta1 integrin binding and migration inhibition"}],"covers":["LR001291","LR004690"]},"LR003187":{"pair":"RGMB -> CTLA4","headline":"RGMB is reported as a novel CTLA-4 binder that strengthens sCTLA-4 binding to CD80; one abstract-level paper.","interaction_type":"direct binding","direction_and_effect":"RGMB binds an extracellular domain of CTLA-4 and specifically strengthens binding of monomeric soluble CTLA-4 to CD80, enhancing its suppressive effect on co-stimulation [PMID:31061392].","molecular_requirements":"The enhancement applies to monomeric soluble CTLA-4 with CD80 [PMID:31061392].","affinity_potency":[],"species_and_systems":"Species not stated beyond curator's human entry; the mouse pair is ortholog-inferred [PMID:31061392].","localisation_and_range":"RGMB is not flagged secreted and CTLA4 is transmembrane [flag].","caveats":"Abstract-only; no affinity; mechanism is modulatory of a CTLA4-CD80 interaction, not a classical agonism; single paper.","key_references":[{"PMID":"31061392","why":"RGMB as a novel CTLA-4 binding partner"}],"covers":["LR003187","LR006407"]},"LR001297":{"pair":"RLN1 -> RXFP1","headline":"Relaxin acts via LGR7 (RXFP1) through cAMP in one abstract-level paper; GtoPdb lists it as full agonist.","interaction_type":"functional only","direction_and_effect":"LGR7 and LGR8 can mediate relaxin action through a cAMP-dependent pathway; soluble LGR7 ligand-binding region delayed parturition in antepartum mice [PMID:11809971]. GtoPdb records a full agonist action [DB:GtoPdb].","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Cell cAMP assays and mouse in vivo [PMID:11809971]; the human pair is not ortholog-inferred but the mouse pair is.","localisation_and_range":"RLN1 is flagged secreted and RXFP1 transmembrane [flag].","caveats":"Four papers were abstract_insufficient and one pending; the confirmed paper is functional, with no binding or affinity values in our evidence; the abstract says relaxin without specifying RLN1 [PMID:11809971].","key_references":[{"PMID":"11809971","why":"LGR7 and LGR8 mediate relaxin cAMP signalling"}],"covers":["LR001297","LR004696"]},"LR006409":{"pair":"RLN3 -> GPR135","headline":"Relaxin-3 binds and activates the receptor named GPCR135 with sub-nanomolar affinity in one abstract-level study.","interaction_type":"direct binding","direction_and_effect":"Recombinant human relaxin-3 stimulates GTPgammaS binding and inhibits cAMP accumulation in GPCR135-overexpressing cells, i.e. agonism [PMID:14522968]. Relaxin-3 is reported as the only insulin/relaxin superfamily member that activates it [PMID:14522968].","molecular_requirements":"Not reported in our evidence beyond the single receptor.","affinity_potency":[{"value":"Kd 0.31 nM","assay":"125I-relaxin-3 radioligand binding","system":"GPCR135-expressing cells","cite":"PMID:14522968"},{"value":"EC50 0.25 nM","assay":"GTPgammaS binding","system":"GPCR135-overexpressing cells","cite":"PMID:14522968"},{"value":"EC50 0.35 nM","assay":"cAMP accumulation inhibition","system":"GPCR135-overexpressing cells","cite":"PMID:14522968"}],"species_and_systems":"Recombinant human relaxin-3 in cell lines; ligand first isolated from porcine brain extracts, with rat brain extracts also active [PMID:14522968]. The mouse pair is projected from human evidence (ortholog inferred).","localisation_and_range":"Ligand flagged as secreted [flag]; receptor annotated only as a receptor, with no membrane flag given. Brain expression of both is described in situ [PMID:14522968].","caveats":"Single paper, read as abstract only. The mouse pair is inferred, not tested.","key_references":[{"PMID":"14522968","why":"Deorphanisation of GPCR135 by relaxin-3 with binding and functional data"}],"covers":["LR003189","LR006409"]},"LR012367":{"pair":"RNF43 -> FZD2:LRP6","headline":"RNF43 -> FZD2:LRP6 is supported only by database records; no paper confirmed it.","interaction_type":"database-asserted only","direction_and_effect":"Reactome lists a binding reaction in which ZNRF3 and RNF43 bind the FZD:LRP5/6 receptor complex [DB:Reactome]. Direction and effect are not reported in our evidence.","molecular_requirements":"Receptor is a FZD plus LRP complex; the Reactome record is generic for the FZD:LRP5/6 complex, not specific to this paralog combination, and which subunit RNF43 contacts is not reported in our evidence.","affinity_potency":[],"species_and_systems":"Human; experimental systems not reported in our evidence.","localisation_and_range":"Not reported in our evidence (no secreted or membrane flag given).","caveats":"No paper confirmed this pair (outcomes: abstract_insufficient 3). ","key_references":[],"covers":["LR012367"]},"LR003196":{"pair":"RSPO1 -> KREMEN1","headline":"RSPO1 interacts with KREMEN1 and blocks DKK1/Kremen-mediated LRP6 internalization; functional abstract-only evidence.","interaction_type":"functional only","direction_and_effect":"RSpo1 interferes with DKK1/Kremen-mediated internalization of LRP6 through an interaction with Kremen, raising LRP6 on the cell surface [PMID:17804805]. It does not directly activate LRP6, and its activity depends on canonical Wnt ligands and LRP6. The annotation notes antagonism of Kremen's role [PMID:17804805]; UniProt lists Kremen binding to DKK1 and RSPO1 via FU repeats [DB:UniProt].","molecular_requirements":"Requires canonical Wnt ligands and LRP6 for activity [PMID:17804805].","affinity_potency":[],"species_and_systems":"Human proteins in cell-based assays [PMID:17804805]; mouse pair ortholog-projected.","localisation_and_range":"RSPO1 is secreted per flag [flag].","caveats":"Abstract only; the assay class is functional and the interaction is stated, not measured. No affinity.","key_references":[{"PMID":"17804805","why":"RSpo1-Kremen interaction relieves LRP6 internalization"}],"covers":["LR003196","LR006416"]},"LR004708":{"pair":"RSPO1 -> ZNRF3","headline":"RSPO1 binds ZNRF3 with micromolar affinity by crystal structure; it inhibits ZNRF3 function.","interaction_type":"direct binding","direction_and_effect":"ZNRF3 binds RSPO1 and LGR5-RSPO1 with micromolar affinity via the RSPO1 Fu1 domain [PMID:24349440]. Annotated antagonist: RSPO1 blocks ZNRF3 and thereby enhances Wnt signalling [PMID:24349440].","molecular_requirements":"RSPO1 Fu1 domain mediates binding; the interface buries ~1,200 \u00c52 [PMID:24349440]. The ZNRF3 site overlaps trans-interactions of 2:2 LGR5-RSPO1 complexes.","affinity_potency":[],"species_and_systems":"Human proteins, crystal structures; mouse pair listed as not inferred [PMID:24349440].","localisation_and_range":"RSPO1 secreted per flag [flag].","caveats":"Abstract and excerpts are from a structural study; the affinity is stated only as micromolar, without a number. BioGRID and IntAct list FRET, SPR and reconstitution records [DB:BioGRID][DB:IntAct]. Receptor flag is generic.","key_references":[{"PMID":"24349440","why":"Crystal structure of ZNRF3-RSPO1 complex"}],"covers":["LR001311","LR004708"]},"LR005293":{"pair":"RSPO2 -> ZNRF3","headline":"RSPO2 is reported as a direct antagonistic ligand of ZNRF3, independent of LGR4/5/6; evidence is one abstract-only paper plus database records.","interaction_type":"direct binding","direction_and_effect":"RSPO2 acts as an antagonist of ZNRF3 (with RNF43); the authors state RSPO2, without LGR4/5/6, serves as a direct antagonistic ligand to RNF43 and ZNRF3 [PMID:29769720]. Reduced WNT potentiation correlated with RSPO2 mutant allele severity [PMID:29769720].","molecular_requirements":"No LGR4/5/6 needed for this action according to the paper [PMID:29769720]. Co-receptor or subunit requirements for ZNRF3 binding are not reported in our evidence.","affinity_potency":[],"species_and_systems":"Human RSPO2 mutations (tetra-amelia), triple Lgr4/5/6 knockout mice and cells, and rnf43/znrf3 deletion in Xenopus embryos [PMID:29769720]. Curators recorded human ligand and receptor.","localisation_and_range":"RSPO2 is flagged secreted and ZNRF3 is flagged as a receptor [flag]; BioGRID lists ZNRF3-RSPO2 FRET, reconstituted complex and affinity capture-Western records [DB:BioGRID], and PDB lists structures containing both chains [DB:PDB 8XFP].","caveats":"The paper was read as an abstract only, so binding details are not available. The abstract describes impaired binding of mutant RSPO2 to ZNRF3 rather than reporting a measured affinity [PMID:29769720]. Dossier covers human and mouse pairs, both with direct evidence.","key_references":[{"PMID":"29769720","why":"RSPO2 as LGR-independent direct antagonistic ligand of RNF43/ZNRF3"}],"covers":["LR001960","LR005293"]},"LR004717":{"pair":"RSPO3 -> SDC4","headline":"Rspo3 binds syndecan 4 and drives Wnt/PCP signalling in Xenopus; one abstract-only paper.","interaction_type":"direct binding","direction_and_effect":"Rspo3 binds Sdc4 and together they activate Wnt/PCP signalling; this works by inducing Sdc4-dependent clathrin-mediated endocytosis, which the authors say is essential for PCP signal transduction [PMID:21397842].","molecular_requirements":"In gastrulation, Rspo3/PCP signalling requires Wnt5a and is transduced via Fz7, Dvl and JNK [PMID:21397842].","affinity_potency":[],"species_and_systems":"Xenopus embryos for the functional work [PMID:21397842]; curators record human ligand and receptor. The mouse pair is ortholog-inferred.","localisation_and_range":"RSPO3 is flagged secreted [flag]; syndecan 4 is a membrane proteoglycan, though its localisation is not stated in our flags.","caveats":"Abstract only; binding assay and affinity are not reported in our evidence. No database records support this pair. The signal is Wnt/PCP, distinct from canonical beta-catenin signalling.","key_references":[{"PMID":"21397842","why":"Rspo3 binds Sdc4 and induces Wnt/PCP signalling via endocytosis"}],"covers":["LR001320","LR004717"]},"LR006418":{"pair":"RTN3 -> RTN4R","headline":"RTN3 binds NgR1 (RTN4R) with nanomolar affinity in a single biophysical mapping paper, read as abstract only.","interaction_type":"direct binding","direction_and_effect":"The paper reports novel nanomolar interactions of RTN2 and RTN3 with NgR1; effect on signalling is not reported in our evidence [PMID:17189258].","molecular_requirements":"Not reported for this pair; the abstract describes NgR1 mapping to the concave face of its leucine-rich-repeat domain [PMID:17189258].","affinity_potency":[],"species_and_systems":"Recombinant biophysical mapping across reticulon and NgR families; curators record human ligand and receptor. The human pair is ortholog-inferred [PMID:17189258].","localisation_and_range":"RTN4R is flagged transmembrane [flag]; RTN3 is a reticulon, typically intracellular, and its extracellular availability is not reported in our evidence.","caveats":"The exact affinity value is not in the abstract. The curator assay_class is direct_binding but the paper is abstract-only. Effect direction \"agonist\" is not stated in the abstract. No database records.","key_references":[{"PMID":"17189258","why":"Systematic mapping of reticulon-NgR interactions; RTN2/RTN3 bind NgR1"}],"covers":["LR003198","LR006418"]},"LR006427":{"pair":"S100A10 -> CFTR","headline":"One paper reports direct SPR binding of p11/S100A10 to the CFTR NBD1 domain; evidence is a single, domain-level in vitro result.","interaction_type":"direct binding","direction_and_effect":"p11 binds the NBD1 domain of CFTR; other tested proteins (ANXA1, cPLA2alpha/ANXA1 complex) did not bind NBD1 [PMID:19847291]. Functional data suggest CFTR restrains eicosanoid release by this complex, but this is inferred, not a ligand effect [PMID:19847291].","molecular_requirements":"Binding was shown to the isolated NBD1 domain of CFTR, not full-length channel; p11 is proposed as the link to a cPLA2alpha/ANXA1 complex [PMID:19847291].","affinity_potency":[],"species_and_systems":"SPR with human proteins in vitro; cell work in Calu-3 cells (human) [PMID:19847291]. Mouse pair is projected from human evidence.","localisation_and_range":"S100A10 is not flagged secreted in the entity annotation [flag]; the paper places the proteins in detergent-resistant membrane fractions [PMID:19847291]. Intracellular partner rather than a classic secreted ligand.","caveats":"Affinity not reported in our evidence. Curator read only the abstract, though full-text excerpts were available. Not a classic ligand-receptor relation; it is an intracellular adaptor interaction.","key_references":[{"PMID":"19847291","why":"SPR binding of p11 to CFTR NBD1"}],"covers":["LR003207","LR006427"]},"LR006436":{"pair":"S100A4 -> EMB","headline":"Embigin is reported as a new S100A4 receptor by pull-down in prostate cancer cells; one abstract-only curation.","interaction_type":"direct binding","direction_and_effect":"Extracellular S100A4 binding to embigin inhibits AMPK, activates NF-kappaB, MMP9 and mTORC1, inhibits autophagy and increases prostate cancer cell motility [PMID:30041429].","molecular_requirements":"Embigin's cytoplasmic tail matters for in vivo tumour growth; embigin also acts independently of S100A4 [PMID:30041429].","affinity_potency":[],"species_and_systems":"Human prostate cancer cells (DU145) and a mouse growth model [PMID:30041429].","localisation_and_range":"S100A4 is flagged secreted [flag]; the paper describes extracellular S100A4 binding embigin, a transmembrane glycoprotein [PMID:30041429].","caveats":"Binding shown by pull-down and immunoprecipitation; no affinity reported. Of S100 proteins tested only S100A4 bound embigin [PMID:30041429]. Abstract-level curation.","key_references":[{"PMID":"30041429","why":"Embigin as S100A4 receptor in prostate cancer"}],"covers":["LR003218","LR006436"]},"LR006445":{"pair":"S100A8 -> LY96","headline":"S100A8 binds the TLR4-MD2 complex (SPR, abstract-only); LY96 alone is not tested separately.","interaction_type":"direct binding","direction_and_effect":"Mrp8 (S100A8) specifically interacts with the TLR4-MD2 complex by surface plasmon resonance and in HEK293 cells transfected with TLR4, CD14 and MD2, acting as an endogenous TLR4 ligand that activates MyD88/IRAK-1/NF-kappaB and TNF-alpha [PMID:17767165]. Reactome lists S100A8:S100A9 binding TLR4:LY96 [DB:Reactome].","molecular_requirements":"The evidence is for the TLR4-MD2 complex; whether MD2 (LY96) itself contacts S100A8 is not reported in our evidence [PMID:17767165]. CD14 was co-expressed in the HEK293 system [PMID:17767165].","affinity_potency":[],"species_and_systems":"Mouse phagocytes and HEK293 cells transfected with TLR4, CD14 and MD2 (species of constructs not stated in the abstract); mouse pair is ortholog-inferred.","localisation_and_range":"Ligand flagged as secreted [flag]; secreted, so paracrine/endocrine range is plausible.","caveats":"Abstract only. Pair is a complex-level binding claim assigned to LY96; the receptor role of LY96 specifically is not isolated. Reactome rows cite the same and other papers (S100A8:S100A9 heterodimer).","key_references":[{"PMID":"17767165","why":"SPR and HEK293 evidence that Mrp8 binds TLR4-MD2"}],"covers":["LR003228","LR006445"]},"LR004726":{"pair":"S100A8 -> TLR4","headline":"S100A8 is an agonist of TLR4-MD2 with SPR, functional and in vivo knockout evidence; two papers, abstract-level binding.","interaction_type":"direct binding","direction_and_effect":"Mrp8 (S100A8) specifically interacts with the TLR4-MD2 complex by surface plasmon resonance, induces MyD88 translocation and IRAK-1/NF-kappaB activation and raises TNF-alpha; mice lacking Mrp8-Mrp14 were protected from endotoxin shock [PMID:17767165]. In the second paper, TLR4-deficient macrophages failed to respond to mMrp8 and an anti-TLR4 mAb almost completely blocked the hMrp8 TNF-alpha response [PMID:26329314]. Reactome records S100A8:S100A9 binding TLR4:LY96 [DB:Reactome]. The interaction record carries an Inhibitory modulatory flag, which conflicts with the agonist evidence.","molecular_requirements":"The binding evidence is for the TLR4-MD2 complex, and HEK293 reconstitution included CD14 [PMID:17767165]. Reactome models the S100A8:S100A9 heterodimer [DB:Reactome].","affinity_potency":[],"species_and_systems":"Mouse phagocytes and knockout mice [PMID:17767165]; murine macrophages, human monocytes and HEK293-hTLR4 cells [PMID:26329314]. Human and mouse pairs both have direct evidence in this dossier.","localisation_and_range":"Ligand flagged as secreted [flag]; secreted, so paracrine/endocrine range is plausible.","caveats":"Binding paper was read as abstract only. Mrp8 pre-stimulation also induces tolerance to later challenges [PMID:26329314]. Modulatory effect 'Inhibitory' on the interaction record disagrees with agonist evidence.","key_references":[{"PMID":"17767165","why":"SPR binding to TLR4-MD2 and knockout mouse protection"},{"PMID":"26329314","why":"TLR4-dependence of Mrp8 responses, full text"}],"covers":["LR001329","LR004726"]},"LR006454":{"pair":"S100A9 -> CD68","headline":"Recombinant rat S100A9 binds rat CD68 by ELISA and affinity chromatography; human and mouse pairs are ortholog-inferred.","interaction_type":"direct binding","direction_and_effect":"Recombinant rat S100A8 and S100A9 bound r-CD68 but not r-CD14 by ELISA and affinity chromatography, supported by flow cytometry; deglycosylation reduced binding and CD68 siRNA suppressed macrophage activation by r-S100A9 [PMID:27312849]. Agonist-like.","molecular_requirements":"Glycosylation of macrophages was needed for full binding; anti-TLR4 or anti-RAGE antibodies suppressed r-S100A9-stimulated IL-1beta mRNA, so CD68 may act with other receptors [PMID:27312849].","affinity_potency":[],"species_and_systems":"Rat recombinant proteins and rat macrophages; both the human and mouse pairs are projected by orthology, not tested [PMID:27312849].","localisation_and_range":"Ligand flagged as secreted [flag]; secreted, so paracrine/endocrine range is plausible. CD68 colocalized with S100A8/S100A9 in LPS-stimulated macrophages [PMID:27312849].","caveats":"Abstract only; rat-only evidence. Some cytokine regulation was not statistically significant. No affinity.","key_references":[{"PMID":"27312849","why":"Rat S100A9 binds CD68, glycosylation-dependent"}],"covers":["LR003238","LR006454"]},"LR006463":{"pair":"SCGB3A2 -> SDC1","headline":"SCGB3A2 binds syndecan-1 on cells and delivers LPS into the cytosol; moderately supported by one study.","interaction_type":"direct binding","direction_and_effect":"SCGB3A2 chaperones LPS to the cytosol through cell surface syndecan-1, driving caspase-11 pyroptosis [PMID:30526845]. SDC1 knockdown in LLC cells reduced SCGB3A2 binding, and ARH-77 cells expressing mouse SDC1 showed enhanced binding [PMID:30526845].","molecular_requirements":"Heparin inhibited binding, suggesting heparan sulfate chains on SDC1 contribute [PMID:30526845]. Effect is as LPS carrier rather than classical signalling.","affinity_potency":[],"species_and_systems":"Cell binding in mouse LLC, human ARH-77 (with mouse SDC1) and RAW264.7 cells, plus mouse xenografts [PMID:30526845].","localisation_and_range":"SCGB3A2 is flagged secreted; SDC1 is flagged transmembrane (and secreted) [flag].","caveats":"Binding was shown on cells, not with purified proteins, in our excerpts. Species labels in the dossier (human) differ from the mouse cell experiments. A second confirmed paper is not shown.","key_references":[{"PMID":"30526845","why":"SCGB3A2 binds SDC1 and delivers LPS to cytosol"}],"covers":["LR003247","LR006463"]},"LR001963":{"pair":"SDC2 -> PTPRJ","headline":"The syndecan-2 ectodomain is reported as a ligand of CD148 (PTPRJ), driving beta1-integrin adhesion; abstract-level evidence.","interaction_type":"direct binding","direction_and_effect":"The syndecan-2 extracellular domain (S2ED) is described as a novel ligand for CD148; CD148 siRNA reduced fibroblast adhesion to S2ED and CD148 transduces the signal to beta1-integrin adhesion via Src kinase [PMID:21813734].","molecular_requirements":"The region proximal to the transmembrane domain of syndecan-2 is the interaction site with CD148 [PMID:21813734]; the extracellular domain acts as the ligand.","affinity_potency":[],"species_and_systems":"Human WI38 lung fibroblasts, Jurkat and U937 cells; rat embryo fibroblasts in inhibitor experiments; siRNA and adhesion assays [PMID:21813734]. Pair is ortholog-inferred for human and mouse.","localisation_and_range":"SDC2 is flagged transmembrane and not secreted [flag]; the paper uses a soluble ectodomain, which implies shed or matrix-coated presentation, but this is not stated.","caveats":"Read as abstract plus excerpts; excerpts show adhesion and knockdown, and the direct binding evidence is not detailed in our excerpts. No affinity.","key_references":[{"PMID":"21813734","why":"S2ED as a CD148 ligand with siRNA and mapping of the interaction site"}],"covers":["LR001963","LR005295"]},"LR006472":{"pair":"SELE -> GLG1","headline":"Direct SPR binding of monomeric E-selectin to ESL-1 (GLG1), very low affinity; one abstract-only paper in mouse material plus database records.","interaction_type":"direct binding","direction_and_effect":"E-selectin binds ESL-1 (GLG1) as a ligand; surface plasmon resonance gave a fast dissociation rate (koff 4.6 s-1) and association rate (kon 7.4e4 M-1 s-1) [PMID:11404363]. Effect on signalling not reported in our evidence.","molecular_requirements":"Monomeric E-selectin was used. ESL-1 from mouse bone marrow cells and recombinant ESL-1 from alpha1,3-fucosyltransferase IV CHO cells both bound, so the fucosyltransferase appears sufficient for functional recombinant ESL-1 [PMID:11404363].","affinity_potency":[{"value":"Kd 62 uM","assay":"surface plasmon resonance, monomeric E-selectin","system":"ESL-1 from mouse bone marrow cells","cite":"PMID:11404363"},{"value":"Kd 66 uM","assay":"surface plasmon resonance","system":"recombinant ESL-1 from alpha1,3-fucosyltransferase IV CHO cells","cite":"PMID:11404363"}],"species_and_systems":"Both partners were mouse in the experiment (native mouse ESL-1, plus CHO-derived recombinant ESL-1); the human pair is ortholog-inferred and the mouse pair is not [PMID:11404363].","localisation_and_range":"Both are annotated as transmembrane [flag], so contact-dependent adhesion is implied; the paper describes tethering and rolling on endothelium [PMID:11404363].","caveats":"Affinity is very low with a fast off-rate, characteristic of rolling adhesion rather than stable binding. Paper read as abstract only. BioGRID lists the same paper as reconstituted complex [DB:BioGRID]; IntAct and Reactome also hold records [DB:IntAct] [DB:Reactome].","key_references":[{"PMID":"11404363","why":"SPR kinetics and Kd of E-selectin binding ESL-1"}],"covers":["LR003256","LR006472"]},"LR003259":{"pair":"SELENOP -> LRP8","headline":"LRP8 is the SELENOP receptor driving selenium uptake and ferroptosis protection in MYCN-amplified neuroblastoma; functional evidence, binding itself taken from prior work.","interaction_type":"functional only","direction_and_effect":"LRP8 overexpression conferred ferroptosis resistance and raised GPX4 protein; LRP8 loss caused ferroptosis, and SELENOP boosted GPX4 only in LRP8-proficient cells, so SELENOP signals through LRP8 as a selenium-supply receptor [PMID:37435859].","molecular_requirements":"Uptake supplies selenocysteine for GPX4 translation; low system Xc- activity makes cells dependent on LRP8. Other co-receptors not reported in our evidence [PMID:37435859].","affinity_potency":[],"species_and_systems":"Human neuroblastoma cells (SK-N-DZ) in vitro and orthotopic xenografts; mouse pair is ortholog-inferred [PMID:37435859].","localisation_and_range":"SELENOP is annotated secreted and LRP8 transmembrane [flag]; paracrine or endocrine uptake by receptor-mediated endocytosis is implied by the paper [PMID:37435859].","caveats":"This paper did not measure binding; it cites earlier studies for LRP2 and LRP8 being SELENOP receptors [PMID:37435859]. Abstract-level curation (full text excerpts available). No database records.","key_references":[{"PMID":"37435859","why":"LRP8-dependent SELENOP-derived selenium uptake and ferroptosis"}],"covers":["LR003259","LR006475"]},"LR008614":{"pair":"SELL -> CD34","headline":"L-selectin binds a glycoform of CD34 on high endothelial venules; carbohydrate-dependent, two abstract-only papers plus database records.","interaction_type":"direct binding","direction_and_effect":"Recombinant L-selectin stained lymph node high endothelial venules and bound sulfated carbohydrates on Sgp90, which was sequenced as CD34; an HEV glycoform of CD34 can act as an L-selectin ligand [PMID:7692600].","molecular_requirements":"Recognition depends on 6-sulfo sialyl Lewis x on the mucin domain, not a protein epitope [PMID:12889478]. Only the endothelial glycoform is a ligand [PMID:7692600].","affinity_potency":[],"species_and_systems":"First paper used recombinant L-selectin and murine lymph node HEV with polyclonal antiserum to murine CD34 [PMID:7692600]; curators record the species as human. The second paper is on endoglycan, with CD34 only as background [PMID:12889478].","localisation_and_range":"Both annotated transmembrane [flag]; contact-dependent (HEV leukocyte rolling) [PMID:12889478].","caveats":"Glycoform-restricted, so CD34 outside HEV is not shown to be a ligand. Papers read as abstracts. One further paper was abstract_insufficient. IntAct and Reactome records exist [DB:IntAct] [DB:Reactome].","key_references":[{"PMID":"7692600","why":"L-selectin binding to HEV CD34 glycoform"},{"PMID":"12889478","why":"CD34 family L-selectin ligands via 6-sulfo-sLex (CD34 as background)"}],"covers":["LR008614"]},"LR004735":{"pair":"SELPLG -> SELP","headline":"PSGL-1 binding to P-selectin is directly demonstrated, with an SPR affinity, structure and several database records.","interaction_type":"direct binding","direction_and_effect":"P-selectin binds PSGL-1; a sulfated, anionic amino-terminal segment of PSGL-1 is necessary for PSGL-1-mediated attachment to P- but not E-selectin [PMID:9128259]. In myeloma, blocking antibodies or PSGL-1 knockdown repressed macrophage-mediated drug resistance, and E-selectin-Fc was described as agonistic on PSGL-1, with Src/Erk1/2/c-myc activation [PMID:22996336].","molecular_requirements":"The first 19 amino acids of PSGL-1 suffice for attachment and rolling on P- and E-selectin, with a sialyl Lewis x glycan at Thr-16 important [PMID:9128259]. Covalent dimerisation of PSGL-1 is not required: monomeric Cys mutants bound P-selectin similarly, and a soluble approximately 25-kDa N-terminal fragment bound immobilized P-selectin [PMID:10713099]. Binding needed Ca2+ and sialidase-sensitive PSGL-1 [PMID:9829984].","affinity_potency":[{"value":"Kd 320 +/- 20 nM","assay":"surface plasmon resonance, soluble monomeric P-selectin to immobilized PSGL-1","system":"human P-selectin, PSGL-1 from human neutrophils","cite":"PMID:9829984"},{"value":"koff 1.4 +/- 0.1 s-1","assay":"surface plasmon resonance","system":"human","cite":"PMID:9829984"}],"species_and_systems":"Binding studies used human proteins and cells [PMID:9829984][PMID:10713099][PMID:9128259]. The myeloma study used human cells and a human myeloma-SCID mouse model [PMID:22996336]. The mouse pair is inferred from human evidence.","localisation_and_range":"Both partners are flagged membrane-bound [flag]; rolling and cell-contact adhesion between cells [PMID:9128259].","caveats":"Three of four shown papers were read as abstracts only. The myeloma paper concerns PSGL-1/selectins together, not P-selectin alone [PMID:22996336]. GtoPdb lists the affinity as pKd [DB:GtoPdb]. Structure and records available [DB:PDB 1G1S] [DB:BioGRID] [DB:IntAct] [DB:Reactome R-HSA-202724].","key_references":[{"PMID":"9829984","why":"SPR affinity and kinetics of P-selectin to PSGL-1"},{"PMID":"9128259","why":"Minimal PSGL-1 N-terminal determinants for P-selectin binding"},{"PMID":"10713099","why":"Monomeric PSGL-1 binds P-selectin"}],"covers":["LR001339","LR004735"]},"LR008029":{"pair":"SEMA3A -> NRP1:PLXNA1:PLXNA4","headline":"Plexin-A1 and plexin-A4 both required for Sema3A signalling; one abstract-only paper.","interaction_type":"functional only","direction_and_effect":"Plexin-A1 and plexin-A4 are required simultaneously for transduction of inhibitory sema3A signals and form complexes [PMID:21832283]. Effect is inhibitory [PMID:21832283].","molecular_requirements":"Both plexins are required together; plexin-A4 associates with neuropilins [PMID:21832283]. Whether NRP1 specifically is in the tested complex is not reported in our evidence.","affinity_potency":[],"species_and_systems":"Tumour cells and endothelial angiogenesis assays; labelled human [PMID:21832283].","localisation_and_range":"Sema3A is flagged secreted [flag]; receptor complex membrane-bound is not stated in our evidence.","caveats":"One paper, abstract only. No direct binding of Sema3A to the three-chain complex is shown. Database records concern the NRP1/PlexinA binding [DB:Reactome R-HSA-399933] [DB:BioGRID 2563623].","key_references":[{"PMID":"21832283","why":"Plexin-A1 and plexin-A4 needed together for sema3A signals"}],"covers":["LR008029"]},"LR006481":{"pair":"SEMA3B -> PLXNA4","headline":"Plexin-A4 is required, with plexin-A2 and a neuropilin, for Sema3B signalling (abstract only).","interaction_type":"functional only","direction_and_effect":"Sema3B signalling completely abolished by plexin-A2 silencing also required plexin-A4 and one of the two neuropilins [PMID:25335892]. Effect agonist.","molecular_requirements":"Part of a multi-component requirement: plexin-A2, plexin-A4 and NRP1 or NRP2 [PMID:25335892].","affinity_potency":[],"species_and_systems":"Endothelial and glioblastoma cells (labelled human) [PMID:25335892]; mouse pair is ortholog-inferred [flag].","localisation_and_range":"Sema3B is flagged secreted [flag].","caveats":"Single abstract-only paper; plexin-A4 requirement is stated in one sentence and no direct binding is shown.","key_references":[{"PMID":"25335892","why":"Sema3B signalling requires plexin-A4, plexin-A2 and a neuropilin"}],"covers":["LR003265","LR006481"]},"LR004744":{"pair":"SEMA3C -> NRP1","headline":"Several papers show SEMA3C (Sema E) acting through NRP1 in binding and functional work, mostly in mouse and mostly abstract-read.","interaction_type":"direct binding","direction_and_effect":"Neuropilin-1 binds Sema III, Sema E and Sema IV with high affinity [PMID:9331348]. Sympathetic axon responses to Sema E are mediated by neuropilin-1 and -2 as homo- or hetero-oligomers [PMID:9883722]. Sema3C signalled through Neuropilin-1 and PlexinD1 to inhibit retinal angiogenesis, abrogating VEGF-induced AKT, FAK and p38MAPK activation [PMID:26194913]. Neural crest SEMA3C activates NRP1 in outflow-tract endothelium [PMID:26053665].","molecular_requirements":"PlexinD1 is a co-receptor in the angiogenesis context [PMID:26194913]; NRP1 can act alone or with NRP2 in axons [PMID:9883722].","affinity_potency":[],"species_and_systems":"Dossier labels species as human for binding and angiogenesis papers [PMID:9331348][PMID:26194913], though the retina and sympathetic work involve mouse or neuron systems; mouse genetics for outflow tract [PMID:26053665].","localisation_and_range":"SEMA3C is flagged as secreted and not transmembrane [flag], so it acts as a diffusible paracrine cue on membrane receptors.","caveats":"All four shown papers were read as abstracts only. Effect is context dependent: antagonist of pathological angiogenesis [PMID:26194913] versus agonist in outflow-tract septation [PMID:26053665]. No affinity values reported in our evidence.","key_references":[{"PMID":"9331348","why":"NRP1 binds Sema III, Sema E and Sema IV with high affinity"},{"PMID":"26194913","why":"Sema3C via NRP1/PlexinD1 inhibits retinal angiogenesis"},{"PMID":"26053665","why":"Neural crest SEMA3C activates NRP1 in outflow tract"}],"covers":["LR001348","LR004744"]},"LR003268":{"pair":"SEMA3D -> NRP2","headline":"Zebrafish genetic evidence that Sema3D attraction involves Npn-1A/Npn-2B heterodimers; no binding data.","interaction_type":"functional only","direction_and_effect":"Sema3D appears attractive to telencephalic neurons forming the anterior commissure, and knockdown of Npn-2B phenocopied this defect [PMID:15456815].","molecular_requirements":"The authors propose that attraction is mediated by Npn-1A-Npn-2B heterodimers [PMID:15456815]; NRP2 acts with NRP1, not alone.","affinity_potency":[],"species_and_systems":"Zebrafish morpholino knockdown; the pair is ortholog-inferred for human and mouse [PMID:15456815].","localisation_and_range":"SEMA3D is annotated secreted and NRP2 transmembrane [flag].","caveats":"The supporting sentence is from a browser-read Discussion that is marked as an unverifiable quote with spot-check pending. No binding or affinity data; three other rows were abstract_insufficient.","key_references":[{"PMID":"15456815","why":"Zebrafish Sema3D attraction via Npn-1A and Npn-2B"}],"covers":["LR003268","LR006484"]},"LR004753":{"pair":"SEMA3G -> NRP2","headline":"SEMA3G binds NRP2 (not NRP1) in two direct-binding papers; supported in mouse and human-labelled systems.","interaction_type":"direct binding","direction_and_effect":"Sema3G binds Neuropilin-2 but not Neuropilin-1 and repels sympathetic but not dorsal root ganglion axons [PMID:16098142]. Sema3G binds Nrp2, which forms a complex with PlexinD1, and induces cell collapse [PMID:27880905].","molecular_requirements":"NRP2 partners with PlexinD1 for the collapse response [PMID:27880905]. Sema3G-AP bound Nrp2-expressing cells but not PlexinD1-expressing cells in the excerpts [PMID:27880905].","affinity_potency":[],"species_and_systems":"Murine Sema3G in the first paper [PMID:16098142]; the second paper is tagged human but uses mouse embryos and lymphatic endothelial cells [PMID:27880905]. Human pair is ortholog-inferred.","localisation_and_range":"SEMA3G is flagged secreted [flag].","caveats":"The 2005 paper was read as abstract only [PMID:16098142]. No affinity values reported.","key_references":[{"PMID":"16098142","why":"Sema3G binds NRP2 not NRP1; repels sympathetic axons"},{"PMID":"27880905","why":"Sema3G-AP binds Nrp2; NRP2/PlexinD1 complex needed for collapse"}],"covers":["LR001357","LR004753"]},"LR003277":{"pair":"SEMA4A -> PLXNB3","headline":"Sema4A binds Plexin-B3 in COS-7 transfection assays in one abstract-level paper; mouse pair is the direct one.","interaction_type":"direct binding","direction_and_effect":"Sema4A binds Plexin-B1, -B2 and -B3 in transfected COS-7 cells, and Rnd1 with these plexins induced cell contraction [PMID:20043131].","molecular_requirements":"Rnd1 co-expression was used for signalling readout [PMID:20043131]. Other requirements not reported in our evidence.","affinity_potency":[],"species_and_systems":"COS-7 cells and mouse hippocampal neurons [PMID:20043131]; the human pair is ortholog-inferred.","localisation_and_range":"SEMA4A is flagged secreted [flag]. IntAct lists a cross-linking study [DB:IntAct].","caveats":"One confirming paper, abstract only; binding is not specific to Plexin-B3. Three other rows were review_only.","key_references":[{"PMID":"20043131","why":"Sema4A binds Plexin-B3 in COS-7"}],"covers":["LR003277","LR006493"]},"LR008245":{"pair":"SEMA4D -> ERBB2:PLXNB1","headline":"SEMA4D engages plexin-B1 in a complex with ErbB-2, which it activates; one abstract-level functional paper.","interaction_type":"functional only","direction_and_effect":"Binding of Sema4D to plexin-B1 stimulates the intrinsic tyrosine kinase activity of ErbB-2, phosphorylating both plexin-B1 and ErbB-2; a dominant-negative ErbB-2 blocks Sema4D-induced RhoA activation and growth cone collapse [PMID:15210733].","molecular_requirements":"Plexin-B family members stably associate with ErbB-2; ErbB-2 is described as an important component of the plexin-B receptor system. Sema4D-induced phosphorylation was seen only for plexin-B1, not plexin-B2, -B3 or -D1 [PMID:15210733].","affinity_potency":[],"species_and_systems":"HEK293 cells with transfected plexin-B1 and Sema4D-containing medium; primary hippocampal neurons for growth cone collapse. Species not stated in the excerpts [PMID:15210733].","localisation_and_range":"Sema4D flagged secreted and transmembrane [flag]; the experiment used medium from cells expressing the extracellular portion [PMID:15210733].","caveats":"Direct ligand binding to the complex was not measured; Sema4D binding to plexin-B1 is the stated premise. Reactome also records this complex [DB:Reactome].","key_references":[{"PMID":"15210733","why":"ErbB-2 is activated by Sema4D via plexin-B1"}],"covers":["LR008245"]},"LR004762":{"pair":"SEMA6A -> PLXNA2","headline":"Plexin-A2 is supported as a Sema6A receptor by mouse binding and genetic evidence, plus a knockdown-rescue study in a glioblastoma line.","interaction_type":"direct binding","direction_and_effect":"A plexin-A2 semaphorin-domain point mutation abolished Sema6A binding to plexin-A2, and Plxna2-/- mice phenocopied Sema6a mutants in cerebellar granule cell migration; chimeras indicate cell-autonomous action [PMID:18327254]. In U87MG cells the contractile response to Sema6A (and Sema3B) was rescued by re-expressing plexin-A2 after silencing [PMID:25335892].","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Mouse in vivo and binding data [PMID:18327254]; U87MG glioblastoma cells (species not stated in our evidence) [PMID:25335892]. Human and mouse pairs are both listed.","localisation_and_range":"Ligand is flagged membrane-bound [flag]; Reactome lists a SEMA6A:PLXNA2,PLXNA4 plasma-membrane complex [DB:Reactome].","caveats":"The first paper was read as an abstract only. The second is knockdown-based and its Sema6A sentence comes from a browser-read quote whose spot-check is pending.","key_references":[{"PMID":"18327254","why":"Plexin-A2 mutation abolishes Sema6A binding; mouse genetics"},{"PMID":"25335892","why":"Plexin-A2 rescue restores Sema6A response (knockdown-based)"}],"covers":["LR001366","LR004762"]},"LR003286":{"pair":"SEMA6D -> PLXNA4","headline":"Plexin A4 is reported as the SEMA6D receptor in colorectal cancer cells by knockdown and rescue; abstract-only, no binding data.","interaction_type":"functional only","direction_and_effect":"Plexin A4 was identified as the key receptor mediating SEMA6D signalling in CRC; PlXNA4 knockdown, but not Plexin A1 depletion, reversed SEMA6D effects, and Plexin A4 overexpression rescued SEMA6D-knockdown HCT116 cells [PMID:41735257]. The SEMA6D-IRF9 axis was Plexin A4-dependent [PMID:41735257].","molecular_requirements":"Plexin A4, not Plexin A1, was needed in this system [PMID:41735257].","affinity_potency":[],"species_and_systems":"Human CRC cell lines (HCT116) and in vivo tumour assays (host species not stated); the pair is ortholog-inferred in the dossier.","localisation_and_range":"Ligand flagged membrane-bound [flag].","caveats":"Single recent paper read as abstract only with some excerpts; no direct binding shown, and effects were tumour-suppressive. One other judged row was a different entity.","key_references":[{"PMID":"41735257","why":"PLXNA4 knockdown reverses SEMA6D effects in CRC"}],"covers":["LR003286"]},"LR001369":{"pair":"SEMA7A -> ITGA1","headline":"Alpha1beta1 integrin is reported to mediate Sema7A-driven cytokine production; evidence is abstract-only and chain-level.","interaction_type":"functional only","direction_and_effect":"Sema7A on activated T cells stimulates cytokine production in monocytes and macrophages through alpha1beta1 integrin (VLA-1) [PMID:17377534]. Reactome lists a SEMA7A:Integrin alpha1beta1 complex [DB:Reactome].","molecular_requirements":"The alpha1 chain acts with beta1; chain-alone sufficiency is not reported in our evidence.","affinity_potency":[],"species_and_systems":"Curator notes describe human monocytes/macrophages and Sema7a-/- mice [PMID:17377534]. Human pair is ortholog-inferred.","localisation_and_range":"Ligand carries secreted and transmembrane flags; the abstract describes it as GPI-anchored [flag][PMID:17377534].","caveats":"Abstract only; the pair is the alpha1 chain of a heterodimer, no binding or affinity data in our evidence.","key_references":[{"PMID":"17377534","why":"Sema7A signals through alpha1beta1 integrin in monocytes/macrophages"}],"covers":["LR001369","LR004765"]},"LR004771":{"pair":"SERPINE1 -> PLAUR","headline":"Only one functional mouse neuron paper supports PAI-1 acting through PLAUR; no binding data in our evidence.","interaction_type":"functional only","direction_and_effect":"Mouse PLAUR-positive sensory neurons responded to Serpin E1 with enrichment of itch- and inflammation-related genes and protein release; a Serpin E1 inhibitor reduced MC903-induced itch [PMID:35596683]. The authors call PLAUR a putative receptor and place it with TLR2 in the signalling axis [PMID:35596683].","molecular_requirements":"PLAUR resides in TLR2-positive neurons and the response involves TLR2 and co-signalling proteins [PMID:35596683]; direct binding is not reported in our evidence.","affinity_potency":[],"species_and_systems":"Mouse sensory neurons and an MC903 atopic-dermatitis-like mouse model, with human skin expression data and human keratinocyte assays [PMID:35596683]. The human pair is ortholog-projected; the mouse pair is not.","localisation_and_range":"PLAUR is flagged secreted, receptor and transmembrane [flag]; neuron-skin paracrine communication is proposed [PMID:35596683].","caveats":"Single abstract-level curated paper; the paper describes PLAUR as putative and states receptors in Serpin E1 itch were not clarified before. One more row is pending.","key_references":[{"PMID":"35596683","why":"Serpin E1 acts on PLAUR-positive sensory neurons in itch"}],"covers":["LR001376","LR004771"]},"LR001972":{"pair":"SERPINF1 -> PLXDC2","headline":"PEDF binds the extracellular domain of PLXDC2 and PLXDC2 mediates cell-type-specific PEDF responses.","interaction_type":"direct binding","direction_and_effect":"PLXDC1 and PLXDC2 were identified as cell-surface receptors for PEDF; knockdown of either decreased PEDF response in RAW267.4 cells [PMID:25535841]. PEDF is reported to dissociate basal receptor homooligomers to activate them [PMID:25535841].","molecular_requirements":"Biotinylated PEDF bound HEK293 cells expressing PLXDC2, with extracellular-domain and intracellular-domain deleted constructs as controls [PMID:25535841].","affinity_potency":[],"species_and_systems":"Transfected HEK293 cells and mouse-derived cell lines named in the excerpts [PMID:25535841]; dossier labels species human. Mouse pair is ortholog-projected from human.","localisation_and_range":"PEDF is flagged secreted [flag]; PLXDC2 acts as a cell-surface receptor in the paper [PMID:25535841].","caveats":"Single paper; no affinity reported; the same evidence supports PLXDC1.","key_references":[{"PMID":"25535841","why":"Identifies PLXDC1 and PLXDC2 as PEDF receptors"}],"covers":["LR001972","LR005302"]},"LR001378":{"pair":"SERPING1 -> LRP1","headline":"C1-inhibitor-C1s complexes are degraded in an LRP-dependent manner; support is a single abstract-only paper.","interaction_type":"functional only","direction_and_effect":"C1-INH.125I-Cs complexes were efficiently degraded by LRP-expressing murine fibroblasts, reduced by chloroquine and RAP; RAP inhibited in vivo clearance and LRP-deficient fibroblasts did not degrade the complexes [PMID:9388254].","molecular_requirements":"The ligand is the protease-complexed C1-inhibitor; the complexes did not bind HepG2 cells, neutrophils or monocytes or cause chemotaxis [PMID:9388254].","affinity_potency":[],"species_and_systems":"Murine fibroblasts and knockout mice; dossier labels species human [PMID:9388254].","localisation_and_range":"SERPING1 is flagged secreted [flag]; plasma clearance by endocytosis.","caveats":"Evidence is clearance and degradation, with no direct binding measurement shown in the abstract; abstract only; only complexed, not free, C1-INH.","key_references":[{"PMID":"9388254","why":"LRP-mediated degradation of C1-INH-C1s complexes"}],"covers":["LR001378"]},"LR008416":{"pair":"SFRP1 -> WNT4","headline":"No confirmed paper; support is a BioGRID reconstituted-complex record.","interaction_type":"database-asserted only","direction_and_effect":"BioGRID lists a reconstituted-complex record [DB:BioGRID, PMID:11287180].","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Not reported in our evidence.","localisation_and_range":"SFRP1 is flagged secreted [flag]; ligand-ligand class.","caveats":"Judged papers were a different entity or review only. Rests on one database record alone.","key_references":[],"covers":["LR008416"]},"LR006508":{"pair":"SFTPA1 -> CKAP4","headline":"SP-A binds CKAP4 (p63) on type II pneumocytes by crosslinking and co-IP; one abstract-level paper plus Reactome.","interaction_type":"direct binding","direction_and_effect":"CKAP4/p63 was identified as an SP-A cell-surface binding protein; anti-p63 antibody blocked SP-A-mediated inhibition of ATP-stimulated phospholipid secretion [PMID:16556726]. The effect is inhibitory on secretion.","molecular_requirements":"not reported in our evidence.","affinity_potency":[],"species_and_systems":"Crosslinking on rat type II cell membranes and intact mouse type II cells with human SP-A as ligand; the human pair is ortholog-inferred, and so is the mouse pair [PMID:16556726].","localisation_and_range":"SFTPA1 is flagged secreted [flag]; CKAP4 is flagged a receptor [flag].","caveats":"One paper, abstract only. The paper refers to SP-A generally, not SFTPA1 specifically. Reactome has a PALM-C100-CKAP4 binding reaction [DB:Reactome].","key_references":[{"PMID":"16556726","why":"Identification of p63/CKAP4 as an SP-A binding protein"}],"covers":["LR003292","LR006508"]},"LR003295":{"pair":"SFTPA1 -> SIRPA","headline":"SP-A binds SIRPalpha through its globular heads and blocks proinflammatory signalling; one abstract-level paper plus Reactome.","interaction_type":"direct binding","direction_and_effect":"SP-A binds SIRPalpha through globular heads to initiate a signalling pathway that blocks proinflammatory mediator production; classified antagonist-like [PMID:14531999].","molecular_requirements":"Globular head domains mediate SIRPalpha binding; the same ligand uses collagenous tails for calreticulin/CD91 [PMID:14531999]. Reactome has an SIRPA:SFTPA oligomer complex [DB:Reactome].","affinity_potency":[],"species_and_systems":"Human ligand and receptor listed; both species pairs ortholog-inferred [PMID:14531999].","localisation_and_range":"SIRPA is flagged transmembrane and SP-A secreted [flag].","caveats":"One paper, abstract only; affinity not reported in our evidence; generic SP-A.","key_references":[{"PMID":"14531999","why":"SP-A/SP-D bind SIRPalpha via globular heads to suppress inflammation"}],"covers":["LR003295","LR006511"]},"LR010936":{"pair":"SHANK1 -> ADGRL2","headline":"Database-only protein-protein interaction record; SHANK1 is not a secreted ligand, so a ligand-receptor reading is doubtful.","interaction_type":"database-asserted only","direction_and_effect":"Direction and effect are not reported in our evidence; the only support is two-hybrid records [DB:BioGRID] [DB:IntAct].","molecular_requirements":"not reported in our evidence.","affinity_potency":[],"species_and_systems":"Experimental system: two-hybrid records [DB:BioGRID] [DB:IntAct]. Species is human per the pair record.","localisation_and_range":"SHANK1 has no secreted flag in the dossier; localisation as a ligand is not reported in our evidence.","caveats":"Rests on database records only; the judged paper rows were assigned to a different entity.","key_references":[],"covers":["LR010936"]},"LR010882":{"pair":"SHBG -> CD177","headline":"SHBG-CD177 rests on a single BioGRID two-hybrid record; one paper was review-only.","interaction_type":"database-asserted only","direction_and_effect":"Direction and effect are not reported in our evidence; the only record is a yeast two-hybrid [DB:BioGRID].","molecular_requirements":"not reported in our evidence.","affinity_potency":[],"species_and_systems":"Two-hybrid, species not reported in our evidence [DB:BioGRID].","localisation_and_range":"SHBG and CD177 are both flagged secreted in the dossier [flag].","caveats":"Database-only and weak method; the judged paper was a review without primary evidence.","key_references":[],"covers":["LR010882"]},"LR004780":{"pair":"SHH -> BOC","headline":"SHH binds BOC and BOC acts as an SHH receptor in axon guidance and patterning; two abstract-level papers plus Reactome.","interaction_type":"direct binding","direction_and_effect":"Agonist: Boc and Cdo bind Shh through a high-affinity interaction with a specific fibronectin repeat that is essential for activity [PMID:16647304]; Boc knockdown impairs commissural axon turning toward a Shh source [PMID:17086203].","molecular_requirements":"Binding involves a specific fibronectin repeat [PMID:16647304]. Reactome lists a Hh-Npp:BOC:PTCH1 complex, suggesting PTCH1 involvement [DB:Reactome].","affinity_potency":[],"species_and_systems":"Mouse genetics and mouse and rat neurons in vitro [PMID:16647304] [PMID:17086203]; the dossier lists the human pair with mouse ortholog-inferred.","localisation_and_range":"SHH is flagged secreted [flag].","caveats":"Both papers abstract-only; no numeric affinity is given though 'high-affinity' is stated. CDO/CDON also binds Shh in both papers.","key_references":[{"PMID":"16647304","why":"Cdo and Boc bind Shh via a fibronectin repeat"},{"PMID":"17086203","why":"Boc as Shh receptor in commissural axon guidance"}],"covers":["LR001385","LR004780"]},"LR007408":{"pair":"SHH -> BOC:PTCH2","headline":"Complex BOC:PTCH2 rests on one abstract showing PTCH2 is a functional SHH receptor in vitro; BOC's role is not shown.","interaction_type":"functional only","direction_and_effect":"Ptch2 is reported to be a functional Shh receptor that regulates Smo localization and activity in vitro [PMID:25448692]. UniProt notes PTCH2 interacts with SHH [DB:UniProt].","molecular_requirements":"The paper concerns Ptch2 alone; BOC is not mentioned in the evidence sentence or abstract [PMID:25448692]. Reactome's BOC complex record is for PTCH1 [DB:Reactome].","affinity_potency":[],"species_and_systems":"Abstract describes in vitro work plus mouse limb bud genetics (Ptch1 and Ptch2 co-expressed; loss of Ptch2 worsens the Ptch1-mutant limb defect) [PMID:25448692]. Cell system not specified.","localisation_and_range":"SHH is flagged secreted [flag]; the receptor is flagged transmembrane [flag], so signalling is paracrine to a membrane receptor.","caveats":"Abstract-only read. Evidence supports PTCH2, not the BOC:PTCH2 complex; no binding measurement is reported.","key_references":[{"PMID":"25448692","why":"Ptch2 is a functional Shh receptor in vitro"}],"covers":["LR007408"]},"LR006517":{"pair":"SHH -> GPC1","headline":"SHH engages GPC1 as a co-receptor in axon guidance; one abstract-level paper, no affinity.","interaction_type":"functional only","direction_and_effect":"GPC1 is required as a coreceptor for Shh-dependent induction of Hhip in commissural neurons; Shh binds GPC1 to induce its own receptor Hhip, which mediates repulsion of postcrossing axons [PMID:23931997].","molecular_requirements":"GPC1 is a coreceptor; it is not stated whether other subunits are needed [PMID:23931997].","affinity_potency":[],"species_and_systems":"Commissural neurons; species not given in the abstract. The pair in the database is ortholog-inferred in both human and mouse.","localisation_and_range":"GPC1 is flagged secreted [flag] (the paper calls it a heparan sulfate proteoglycan [PMID:23931997]); SHH is secreted [flag].","caveats":"Abstract-only. The experiments show GPC1 dependence of signalling; binding is stated in the abstract without an assay in the dossier. No database records.","key_references":[{"PMID":"23931997","why":"GPC1 as Shh coreceptor for Hhip induction"}],"covers":["LR003303","LR006517"]},"LR001387":{"pair":"SHH -> GPC5","headline":"SHH binds GPC5 through glycosaminoglycan chains and GPC5 promotes Hh signalling; two curator-verified papers.","interaction_type":"direct binding","direction_and_effect":"GPC5 increases Sonic Hh binding to Ptc1 and stimulates Hh signaling and rhabdomyosarcoma cell proliferation [PMID:21339334]. GPC5-containing HSPG co-receptors promote Shh binding and signaling in cerebellar granule cell precursors [PMID:23867465]. Reactome lists Hh-Np binds GPC5 [DB:Reactome].","molecular_requirements":"GPC5 binds Hh and Ptc1 through its glycosaminoglycan chains [PMID:21339334]. Needs a glypican 5 core protein with 2-O-sulfo-iduronic acid residues [PMID:23867465].","affinity_potency":[],"species_and_systems":"Human rhabdomyosarcoma cells (RH30, CW9019) with GPC5 siRNA or overexpression [PMID:21339334]; cerebellar granule cell precursors [PMID:23867465].","localisation_and_range":"GPC5 is flagged secreted [flag]; the papers describe it near the primary cilium [PMID:23867465] and localised to primary cilia [PMID:21339334]; SHH is secreted [flag].","caveats":"Binding depends on the glycan chains, so it is cell-type and glycosylation dependent. Three more papers were judged abstract-insufficient. No affinity reported.","key_references":[{"PMID":"21339334","why":"GPC5 GAG chains bind Hh and Ptc1"},{"PMID":"23867465","why":"GPC5/2-O-sulfo-iduronic acid HSPG co-receptor for Shh"}],"covers":["LR001387","LR004782"]},"LR001981":{"pair":"SLAMF1 -> SLAMF1","headline":"Homophilic SLAMF1 interaction supported by Fc-binding, functional T-B assays and IntAct records; the paper-level evidence is mixed in strength.","interaction_type":"direct binding","direction_and_effect":"Slamf1-Fc associated with Slamf1-transfected cells but not Slamf8-transfected cells [PMID:25799045]. In human T-B coculture, an anti-SLAMF1 mAb reduced IL-21 and IL-17A producing T cells and Ig production, framed as homophilic interaction [PMID:30058241]. SLAM engagement potentiated PKC-theta and NF-kB1 signalling in a SAP-dependent way [PMID:15539155].","molecular_requirements":"SAP (SH2D1A) is needed for the T-cell signalling effects in PMID:15539155; the Fc-binding assay used single-chain transfectants [PMID:25799045].","affinity_potency":[],"species_and_systems":"Mouse Slamf1-Fc on HEK293 transfectants [PMID:25799045]; human T and B cells from healthy donors and SLE patients [PMID:30058241]; mouse and human T cells [PMID:15539155].","localisation_and_range":"Entity is flagged both secreted and receptor [flag]; binding is cell-surface and contact-dependent in the papers.","caveats":"PMID:15539155 and PMID:30058241 use antibody ligation, which does not itself show binding; the curator notes the homophilic binding in PMID:15539155 is background-cited. mAb effect in PMID:30058241 was labelled antagonist. IntAct records include surface plasmon resonance [DB:IntAct]. No affinity in our evidence.","key_references":[{"PMID":"25799045","why":"Slamf1-Fc binds Slamf1 transfectants, not Slamf8"},{"PMID":"30058241","why":"SLAMF1 homophilic engagement in T-B crosstalk"},{"PMID":"15539155","why":"SLAM engagement signalling via SAP"}],"covers":["LR001981","LR005310"]},"LR006526":{"pair":"SLIT2 -> LRP1","headline":"SLIT2 directly binds LRP1 in a chondrocyte ligandome study; one abstract-only paper.","interaction_type":"direct binding","direction_and_effect":"Direct LRP1 binding of SLIT2 was confirmed among ten ligands, and affinity correlated with endocytosis rate [PMID:36028175]. Annotated agonist; LRP1 acts as an endocytic receptor in this study [PMID:36028175].","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Purified-protein binding assays and human chondrocytes, with LRP1-deficient fibroblasts and an Lrp1 conditional knockout mouse for the wider ligandome [PMID:36028175]. Mouse pair is ortholog-inferred.","localisation_and_range":"Soluble ligand taken up by cell-surface LRP1 [PMID:36028175]; SLIT2 flagged secreted [flag].","caveats":"Single paper read as abstract only; SLIT2-specific affinity not given. In vivo knockout data concern the ligand set as a whole, not SLIT2 alone.","key_references":[{"PMID":"36028175","why":"Top-down LRP1 ligandome; SLIT2 direct binding confirmed"}],"covers":["LR003312","LR006526"]},"LR001396":{"pair":"SLIT2 -> ROBO2","headline":"SLIT2 signals through ROBO2, supported by binding, in vitro and mouse knockout evidence.","interaction_type":"direct binding","direction_and_effect":"Slit2 binds Robo2 [PMID:10102268]. Mouse Slit2 or Robo2 mutants develop supernumerary ureteric buds, with signal transduced in nephrogenic mesenchyme [PMID:15130495]. SLIT2 binding to Gremlin inhibited SLIT2-ROBO2 signalling in neurons [PMID:29317497].","molecular_requirements":"Not reported in our evidence beyond the mixed Slit2 fragments used [PMID:10102268].","affinity_potency":[],"species_and_systems":"Human Slit2 on COS cells expressing rat Robo2 [PMID:10102268]; Slit2 and Robo2 mutant mice [PMID:15130495]; neurons and myoblasts/fibroblasts [PMID:29317497].","localisation_and_range":"SLIT2 secreted, ROBO2 flagged transmembrane [flag]; Reactome lists a ROBO2:SLIT2 plasma-membrane complex [DB:Reactome].","caveats":"Two of three papers are abstract-only. PMID:29317497 states SLIT2-ROBO2 binding as background and tests the Gremlin cross-talk, so it is not direct evidence for the pair. PMID:15130495 shows genetics, not binding.","key_references":[{"PMID":"10102268","why":"direct binding of Slit2 to Robo2"},{"PMID":"15130495","why":"Slit2/Robo2 mutant mice, kidney induction"},{"PMID":"29317497","why":"SLIT2-Gremlin cross-talk inhibits SLIT2-ROBO2"}],"covers":["LR001396","LR004791"]},"LR001990":{"pair":"SLITRK2 -> PTPRD","headline":"SLITRK2-PTPdelta has a crystal structure of the trans-synaptic complex plus cell aggregation evidence.","interaction_type":"direct binding","direction_and_effect":"Crystal structure of a synaptogenic trans-synaptic adhesion complex between Slitrk2 and PTPdelta, with mutagenesis defining splicing-dependent adhesion [PMID:25989451]. Slitrk2-expressing L cells aggregated with PTPdelta cells [PMID:23345436].","molecular_requirements":"Binding is splicing-dependent between Slitrks and type IIa RPTPs [PMID:25989451].","affinity_potency":[],"species_and_systems":"Structure abstract does not state species in our evidence [PMID:25989451]; mouse L cells [PMID:23345436].","localisation_and_range":"Trans-synaptic adhesion between pre- and postsynaptic membranes; SLITRK2 flagged transmembrane [flag][PMID:25989451].","caveats":"Structure paper is abstract only; no affinity reported. PMID:23345436 is a family-level assay. Four review-only rows not shown.","key_references":[{"PMID":"25989451","why":"Slitrk2-PTPdelta crystal structure"},{"PMID":"23345436","why":"Slitrk2 L-cell aggregation with PTPdelta"}],"covers":["LR001990","LR005319"]},"LR010756":{"pair":"SLURP1 -> CHRNA9","headline":"Synthetic SLURP-1 inhibits alpha9alpha10 nAChRs in functional assays; no direct binding shown for this subunit.","interaction_type":"functional only","direction_and_effect":"Synthetic SLURP-1 robustly inhibits human and rat alpha9alpha10 nAChRs (antagonist); inhibition was accentuated at higher ACh concentrations, suggesting allosteric binding. [PMID:29192197]","molecular_requirements":"Tested as the alpha9alpha10 heteromer; alpha9 alone is not reported in our evidence [PMID:29192197].","affinity_potency":[],"species_and_systems":"Human receptors expressed heterologously (two-electrode voltage clamp), synthetic human SLURP-1 tested at 10 uM [PMID:29192197].","localisation_and_range":"SLURP1 is flagged secreted [flag]; the paper describes it as a secreted protein that co-localizes with nAChRs [PMID:29192197]. ","caveats":"Curator read abstract level only. The evidence is inhibition of ACh-evoked currents, not binding. Synthetic SLURP-1 did not compete with alpha-bungarotoxin at human alpha7 or muscle-type nAChRs and did not inhibit alpha7 currents without PNU120596; earlier recombinant SLURP-1 with extensions gave conflicting results [PMID:29192197].","key_references":[{"PMID":"29192197","why":"Chemically synthesized human SLURP-1 tested on nAChR subtypes"}],"covers":["LR010756"]},"LR005329":{"pair":"SOSTDC1 -> LRP4","headline":"Wise (SOSTDC1) binding to LRP4 is shown in mouse tooth work with in vitro pull-downs; one paper, full text read.","interaction_type":"direct binding","direction_and_effect":"Lrp4 binds the secreted Bmp antagonist Wise, and the interaction modulates Wnt activity in epithelial cells [PMID:19116665]. Net effect is modulatory; a receptor-activating or blocking role is not stated in our evidence.","molecular_requirements":"Not reported in our evidence beyond Lrp4 ectodomain and Wise being sufficient for binding in the assays.","affinity_potency":[],"species_and_systems":"Mouse tooth development; binding tested in HEK293A cells expressing LRP4 and in a cell-free assay with LRP4 ectodomain-Fc, where Wise but not AP or RSpondin2 bound [PMID:19116665]. Mouse Lrp4 and Wise mutants share tooth phenotypes. Human pair is ortholog-inferred.","localisation_and_range":"Wise is secreted from mesenchyme and Lrp4 is on epithelial cells, so paracrine [PMID:19116665]; ligand secreted flag [flag].","caveats":"Single paper; no affinity reported. No database records.","key_references":[{"PMID":"19116665","why":"Wise binds Lrp4 in cell and cell-free assays; mouse tooth"}],"covers":["LR002001","LR005329"]},"LR006535":{"pair":"SPARC -> LRP1","headline":"SPARC is one of ten direct LRP1 ligands confirmed in human chondrocyte work; abstract only.","interaction_type":"direct binding","direction_and_effect":"Direct LRP1 binding of SPARC and nine other ligands was confirmed, and affinity for LRP1 correlated with endocytosis rate [PMID:36028175]. Direction: LRP1 mediates endocytosis of the ligand (clearance); curator label is agonist.","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Human chondrocytes, direct binding assays with purified LRP1, LRP1-deficient fibroblasts, and a conditional Lrp1 knockout mouse [PMID:36028175]. Mouse pair ortholog-inferred.","localisation_and_range":"SPARC flagged secreted [flag]; LRP1 on the cell surface mediates uptake.","caveats":"Abstract only (the abstract is cut off). Per-ligand affinity for SPARC is not given in our evidence. No database records.","key_references":[{"PMID":"36028175","why":"LRP1 chondrocyte ligandome; direct binding of SPARC confirmed"}],"covers":["LR003328","LR006535"]},"LR005338":{"pair":"SPP1 -> ITGB5","headline":"Osteopontin binds integrin alphavbeta5 in adhesion assays; two abstract-level papers support it, one with a stated affinity.","interaction_type":"direct binding","direction_and_effect":"Cells adhere to osteopontin through alphavbeta5 when beta5 is transfected [PMID:7592829]; alphavbeta5 binds the RGD site and is additionally sensitive to mutation of two aspartic acid residues upstream [PMID:16005200]. Effect direction not reported in our evidence.","molecular_requirements":"alphavbeta5 heterodimer; RGD site required; thrombin cleavage not required for optimal adhesion [PMID:16005200]. Divalent cations regulate binding, with highest affinity in Mn2+; Ca2+ does not support it [PMID:7592829].","affinity_potency":[{"value":"affinity 48 nM (Mn2+)","assay":"cell adhesion to GST-osteopontin","system":"HEK293 cells transfected with beta5","cite":"PMID:7592829"}],"species_and_systems":"Human recombinant GST-OPN and HEK293 cells [PMID:7592829]; species unspecified in the second paper [PMID:16005200].","localisation_and_range":"SPP1 is flagged secreted [flag]; OPN is an extracellular matrix protein [PMID:7592829].","caveats":"Both papers read as abstracts only. BioGRID lists a reconstituted complex [DB:BioGRID]. The mouse pair is ortholog-inferred. One further paper judged abstract-insufficient.","key_references":[{"PMID":"7592829","why":"alphavbeta5-mediated adhesion, 48 nM"},{"PMID":"16005200","why":"RGD and upstream aspartate requirements"}],"covers":["LR002010","LR005338"]},"LR004807":{"pair":"SST -> SSTR3","headline":"Somatostatin binds human SSTR3 with high affinity and SSTR3 couples to adenylyl cyclase inhibition; multiple abstract-level papers.","interaction_type":"direct binding","direction_and_effect":"Somatostatin is an agonist; SSTR3 binds [125I]CGP 23996 with rank order somatostatin-28 = CGP 23996 > somatostatin-14 > SMS-201-995, and somatostatin inhibits D1-stimulated cAMP when co-expressed [PMID:1337145]. A second paper reports SST-14 selectivity [PMID:8097479].","molecular_requirements":"SSTR3 alone suffices in transfected cells [PMID:1337145].","affinity_potency":[{"value":"Kd 0.2 nM (about 200 pM)","assay":"saturation binding with [125I]Leu8,D-Trp22,Tyr25 SST-28","system":"COS-7 membranes expressing human SSTR3","cite":"PMID:8097479"},{"value":"pKi 8.7-10.0","assay":"GtoPdb curated range","system":"not reported","cite":"PMID:8097479"}],"species_and_systems":"Human SSTR3 in COS-1, COS-7 and CCL39 cells [PMID:1337145][PMID:8097479][PMID:9650799]. Mouse pair is ortholog-inferred.","localisation_and_range":"SST flagged secreted [flag]; PDB 8ZBI has a structure with chains of P61278 and P32745 [DB:PDB 8ZBI].","caveats":"All abstract-only. The two cloning papers disagree on SST-28 versus SST-14 preference. The Kd is for a SST-28 analogue radioligand. Human SSTR3 differs from rat in pharmacology [PMID:8097479].","key_references":[{"PMID":"1337145","why":"Cloning of SSTR3; adenylyl cyclase coupling"},{"PMID":"8097479","why":"Human SSTR3 binding at about 200 pM"},{"PMID":"9650799","why":"Five human SSTRs, SRIF28 analogue control"}],"covers":["LR001412","LR004807"]},"LR006544":{"pair":"SVEP1 -> ITGB1","headline":"SVEP1 binds integrin beta1-containing heterodimers (alpha4beta1, alpha9beta1); beta1 evidence is indirect via alpha-chain studies.","interaction_type":"direct binding","direction_and_effect":"SVEP1 binding to integrin alpha9beta1 was confirmed and it also directly bound alpha4beta1 [PMID:35802072]. UniProt states ITGA9:ITGB1 and ITGA4:ITGB1 repress calcium influx and inhibit vasocontraction via SVEP1 [DB:UniProt].","molecular_requirements":"ITGB1 acts as the common beta subunit paired with alpha4 or alpha9; the alpha chain is needed for the complexes described [PMID:35802072][DB:UniProt]. Whether beta1 alone binds is not reported in our evidence.","affinity_potency":[],"species_and_systems":"Human iPSC-derived VSMCs and Svep1+/- mouse myography [PMID:35802072]. Mouse pair is projected from human.","localisation_and_range":"SVEP1 is flagged secreted [flag].","caveats":"One paper, abstract only; evidence concerns heterodimers, not ITGB1 alone, and CCC tools should score this with the alpha partner. Second confirmed row not shown.","key_references":[{"PMID":"35802072","why":"SVEP1 binds alpha9beta1 and alpha4beta1"}],"covers":["LR003337","LR006544"]},"LR004816":{"pair":"TAC4 -> TACR1","headline":"Hemokinin-1 (TAC4) binds human NK1 (TACR1) with high affinity, equal to substance P, in one abstract-only paper.","interaction_type":"direct binding","direction_and_effect":"Agonist. HEK-1 inhibited [3H]-substance P binding to human NK(1) receptor with high affinity, similar to SP (Ki=0.13 nM) [PMID:11786503]. GtoPdb lists a full agonist [DB:GtoPdb].","molecular_requirements":"Not reported in our evidence.","affinity_potency":[{"value":"Ki 0.175 nM","assay":"[3H]-substance P competition","system":"human NK1 receptor","cite":"PMID:11786503"},{"value":"pKi 9.8000001907","assay":"curated agonist affinity range","system":"GtoPdb record","cite":"DB:GtoPdb"}],"species_and_systems":"Human NK1 receptor binding; functional work in isolated rat, rabbit and guinea-pig tissue [PMID:11786503]. Mouse pair is ortholog-inferred.","localisation_and_range":"TAC4 flagged secreted and TACR1 transmembrane [flag].","caveats":"Abstract only; one paper. Mouse support is inferred.","key_references":[{"PMID":"11786503","why":"HEK-1 pharmacological profile at NK1, NK2 and NK3"}],"covers":["LR001421","LR004816"]},"LR003349":{"pair":"TAFA2 -> NRXN1","headline":"TAFA2 (FAM19A2) binds neurexins, including NRXN1, by disulfide linkage; one paper, mouse and HEK293T systems.","interaction_type":"direct binding","direction_and_effect":"FAM19A/TAFA proteins interact with all neurexins except neurexin-1\u03b3 [PMID:32706374]. FAM19A1 and FAM19A2 were isolated in a complex with neurexins from brain homogenates using multiple neurexin antibodies [PMID:32706374]. Rather than activating a receptor, FAM19A1 expression decreased neurexin O-glycosylation and heparan sulfate modification in hippocampal cultures [PMID:32706374].","molecular_requirements":"FAM19A1-A4 bind the cysteine-loop domain of neurexins by forming intermolecular disulfide bonds; both the cysteines and an adjacent neurexin sequence were required [PMID:32706374]. FAM19A5 does not bind [PMID:32706374].","affinity_potency":[],"species_and_systems":"Endogenous complexes from mouse brain; recombinant coIP in HEK293T cells with Nrxn1\u03b2-ECD; hippocampal cultures [PMID:32706374]. The human pair and the mouse pair are both listed, the human one projected from mouse-type evidence [flag].","localisation_and_range":"TAFA2 is annotated secreted and NRXN1 as transmembrane [flag]. Binding occurs within the secretory pathway and needs cis co-expression [PMID:32706374].","caveats":"Supported by one paper read as an abstract plus full-text excerpts; the abstract states that neurexin-1\u03b3 is the exception [PMID:32706374]. Binding is covalent and forms during transit through the secretory pathway, which is unusual for a ligand-receptor pair.","key_references":[{"PMID":"32706374","why":"Identifies FAM19A1-A4 as pan-neurexin ligands with disulfide-linked binding"}],"covers":["LR003349","LR006552"]},"LR006553":{"pair":"TAFA2 -> RNF167","headline":"TAFA2 binds the RING E3 ligase RNF167 ectodomain by SPR in one screening paper; no affinity or function reported.","interaction_type":"direct binding","direction_and_effect":"SPR sensorgrams showed human TAFA-2 binding to RNF167-ECD, with MCAM as a no-binding comparison [PMID:36178190]. RNF167 was a shared CRISPRa screen hit for PTN, TAFA-2 and TAFA-5 [PMID:36178190]. Effect on RNF167 is not reported in our evidence.","molecular_requirements":"RNF167 is described as a transmembrane PA-TM-RING E3 ligase; the ectodomain alone was used [PMID:36178190].","affinity_potency":[],"species_and_systems":"Recombinant human proteins, SPR [PMID:36178190]. Mouse pair is projected by orthology.","localisation_and_range":"TAFA2 annotated secreted [flag]; RNF167 annotated receptor [flag].","caveats":"Single paper. The authors note that RING E3 ligase interactions are characterised by weak affinity and fast kinetics [PMID:36178190]. Whether TAFA2 acts as a signalling ligand for an E3 ligase is not shown.","key_references":[{"PMID":"36178190","why":"SPR binding of TAFA-2 to RNF167-ECD after a CRISPRa screen"}],"covers":["LR003350","LR006553"]},"LR003358":{"pair":"TENM2 -> ADGRL2","headline":"Cell-adhesion evidence that teneurin-2 engages latrophilin-expressing cells including Lphn2; one paper, indirect.","interaction_type":"functional only","direction_and_effect":"Mixing HEK293T cells expressing Lphn1/2/3 with cells expressing Ten2 or Ten4 produced large cell aggregates indicating intercellular adhesion [PMID:24273166].","molecular_requirements":"Not reported separately for ADGRL2 in our evidence.","affinity_potency":[],"species_and_systems":"HEK293T cell aggregation assay [PMID:24273166]. Both listed pairs are ortholog-inferred.","localisation_and_range":"Both annotated transmembrane receptors [flag]; interaction is cell-contact (trans) adhesion [PMID:24273166].","caveats":"Aggregation does not isolate ADGRL2 from the other latrophilins in our excerpt, and no ADGRL2-specific affinity is reported. Other judged papers were review_only or abstract_insufficient.","key_references":[{"PMID":"24273166","why":"Cell aggregation of Lphn-expressing cells with Ten2 cells"}],"covers":["LR003358","LR006561"]},"LR006562":{"pair":"TENM2 -> ADGRL3","headline":"Strong evidence: cryo-EM structure of TEN2-LPHN3 complex plus cell adhesion and splice-dependence data.","interaction_type":"direct binding","direction_and_effect":"The 2.9 \u00c5 cryo-EM structure shows the LPHN3 N-terminal lectin domain binding the TEN2 barrel far from the alternatively spliced region [PMID:32358586]. Trans-synaptic TEN-LPHN interaction promotes excitatory synapse formation when LPHNs also bind FLRTs; an alternatively spliced TEN insertion abolishes binding and switches function to inhibitory synapses [PMID:32358586]. Latrophilin-expressing cells aggregate with Ten2 cells [PMID:24273166].","molecular_requirements":"A trimeric TEN2-LPHN3-FLRT3 complex exists [PMID:32358586]. Breaking ADGRL3-TEN2 binding preserved FLRT3 interaction [PMID:36746957]. An antibody LK30 binding the ADGRL3 Lec domain overlaps the teneurin epitope and agonises ADGRL3 but not ADGRL1 [PMID:36746957].","affinity_potency":[],"species_and_systems":"Human proteins in the cryo-EM study [PMID:32358586] and the LK30 work [PMID:36746957]; HEK293T aggregation assay [PMID:24273166]. Mouse pair ortholog-inferred. PDB 6VHH is listed [DB:PDB 6VHH].","localisation_and_range":"Both annotated transmembrane [flag]; trans-synaptic cell-contact interaction [PMID:32358586].","caveats":"Binding depends on the alternatively spliced TEN region: insertion abolishes it [PMID:32358586]. Affinity values are not in our excerpts. Key papers were partly read as abstracts.","key_references":[{"PMID":"32358586","why":"Cryo-EM structure of TEN2-LPHN3 and trimer with FLRT3"},{"PMID":"36746957","why":"Antibody overlapping TEN2 site on ADGRL3 separates TEN2 and FLRT3 binding"},{"PMID":"24273166","why":"Cell adhesion of latrophilin cells with Ten2 cells"}],"covers":["LR003359","LR006562"]},"LR004825":{"pair":"TFPI -> LRP1","headline":"High-affinity TFPI binding to LRP (Kd 2.3 nM) was seen only when heparan sulfate was blocked; LRP is required for TFPI degradation.","interaction_type":"direct binding","direction_and_effect":"LRP is absolutely required for degrading 125I-TFPI, i.e. it acts as an endocytic clearance receptor [PMID:8824219]. TFPI cross-links to LRP on hepatoma and LRP-heterozygous cells but not LRP-negative cells [PMID:8824219].","molecular_requirements":"HSPGs are a second TFPI catabolism system; with HSPGs blocked by protamine, TFPI bound in a 39-kDa-protein-inhibitable manner and 5-fold more TFPI cross-linked to LRP [PMID:8824219].","affinity_potency":[{"value":"Kd 2.3 nM","assay":"125I-TFPI binding with HSPGs blocked by protamine; 41,000 sites per cell","system":"hepatoma cells","cite":"PMID:8824219"}],"species_and_systems":"Hepatoma cells and LRP-gene-disrupted mouse embryonic fibroblasts [PMID:8824219]. Human and mouse pairs are both ortholog-inferred.","localisation_and_range":"TFPI is annotated secreted [flag]; endocytosis is cell-surface mediated.","caveats":"LRP-heterozygous and homozygous-negative cells bound 125I-TFPI similarly, and the 39-kDa protein did not alter binding in unblocked conditions, so binding in general is largely LRP-independent [PMID:8824219]. Abstract only.","key_references":[{"PMID":"8824219","why":"LRP knockout fibroblasts; Kd 2.3 nM with HSPGs blocked"}],"covers":["LR001430","LR004825"]},"LR003367":{"pair":"TGFB1 -> ACVR1","headline":"Functional evidence that ACVR1 is required downstream of TGFB1 for SMAD1/5 phosphorylation; direct ligand binding not shown.","interaction_type":"functional only","direction_and_effect":"TGF-beta-induced SMAD1/5 phosphorylation requires TGFBR1 and ACVR1; TGFBR1 phosphorylates and activates ACVR1, which phosphorylates SMAD1/5 [PMID:29376829].","molecular_requirements":"Receptors involved are deduced to be TGFBR1, a canonical BMP type I receptor (ACVR1 and/or BMPR1A) and TGFBR2 [PMID:29376829]. In vitro, SMAD1 is efficiently phosphorylated by ACVR1 but poorly by TGFBR1 [PMID:29376829].","affinity_potency":[],"species_and_systems":"Human cells in the curated label; NMuMG cells are also mentioned [PMID:29376829]. Mouse pair is ortholog-inferred.","localisation_and_range":"TGFB1 is annotated secreted and not transmembrane [flag].","caveats":"ACVR1 acts as a type I receptor kinase in a TGF-beta receptor complex; TGFB1 binding to ACVR1 itself is not reported in our evidence. Abstract plus excerpts only.","key_references":[{"PMID":"29376829","why":"TGFBR1 activates ACVR1 for SMAD1/5 signalling"}],"covers":["LR003367","LR006568"]},"LR004834":{"pair":"TGFB1 -> ITGAV","headline":"Multiple structural and binding papers show alphaV integrins (beta6, beta8) bind latent TGF-beta1; alphaVbeta3 binds weakly.","interaction_type":"direct binding","direction_and_effect":"alphaVbeta8 binds latent TGF-beta1, shown by cryo-EM, and binding is essential for activating it [PMID:31955848]. SLC binds alphaVbeta8, leading to MT1-MMP-dependent release of active TGF-beta [PMID:11970960]. alphaVbeta6 binds a RGDLXXL/I motif in TGF-beta1 prodomain [PMID:25383667]. UniProt: ITGAV:ITGB6 or ITGB8 interaction distorts the latency-associated peptide and releases active TGF-beta-1 [DB:UniProt].","molecular_requirements":"ITGAV pairs with a beta chain: beta6 or beta8 bind latent TGF-beta1 with high specificity [PMID:25383667] [PMID:31955848]. alphaVbeta3 did not bind latent TGF-beta1 strongly [PMID:27033701]. Leu-218 after the RGD motif defines alphaVbeta8 binding [PMID:27033701].","affinity_potency":[],"species_and_systems":"Crystal and cryo-EM structures, recombinant proteins and cells [PMID:25383667] [PMID:31955848]; human proteins in PMID:27033701; species unspecified in PMID:11970960.","localisation_and_range":"TGFB1 is flagged secreted [flag]. Ligand is bound in its latent complex at cell surface integrins.","caveats":"The entity is labelled alphaV beta3 [flag] yet the evidence concerns beta6 and beta8, so scoring should use the correct beta chain. The ligand is latent TGF-beta1, not mature. Three further papers judged abstract-insufficient. Three papers read as abstract only.","key_references":[{"PMID":"31955848","why":"Cryo-EM of alphaVbeta8 with latent TGF-beta"},{"PMID":"25383667","why":"alphaVbeta6 structure with TGF-beta prodomain motif"},{"PMID":"27033701","why":"alphaVbeta8 specificity for latent TGF-beta1"}],"covers":["LR001439","LR004834"]},"LR006571":{"pair":"TGFB1 -> ITGB1","headline":"Only adhesion of alpha8beta1 cells to LAP-TGFbeta1; ITGB1 evidence is indirect.","interaction_type":"functional only","direction_and_effect":"alpha8-transfected cells adhere to recombinant LAP-TGFbeta1 better than mock cells [PMID:12415008].","molecular_requirements":"The paper concerns alpha8beta1; beta1 is the partner chain, and alpha8 is required here [PMID:12415008]. Beta1 activating antibody 8A2 enhanced adhesion per curator notes [PMID:12415008].","affinity_potency":[],"species_and_systems":"Species not reported in our evidence; transfected cell lines [PMID:12415008].","localisation_and_range":"TGFB1 is flagged secreted [flag]. Receptor localisation not reported in our evidence.","caveats":"The same paper supports ITGA8; beta1 alone is not shown to bind. Latent LAP form assayed, read as abstract only. No database records.","key_references":[{"PMID":"12415008","why":"alpha8beta1 adhesion to LAP-TGFbeta1"}],"covers":["LR003370","LR006571"]},"LR004843":{"pair":"TGFB2 -> TGFBR3","headline":"TGF-beta2 to betaglycan: the cited paper shows betaglycan binds TGF-beta isoforms with two ligand-binding domains; betaglycan acts as co-receptor.","interaction_type":"direct binding","direction_and_effect":"Betaglycan is a coreceptor without kinase activity that presents ligand to TGFBR1/TGFBR2 and matters most for TGF-beta2 (curator note) [PMID:19842711]. 125I-TGF-beta2 labelled the intact receptor and both fragments [PMID:19842711].","molecular_requirements":"Two independent binding domains; either fragment binds ligand but blocks it poorly versus the intact form [PMID:19842711]. Reactome lists TGFB1,TGFB2:TGFBR3 and a TGFB2:pTGFBR3:TGFBR2 complex [DB:Reactome].","affinity_potency":[{"value":"Kd in the low nanomolar range","assay":"SPR, soluble betaglycan, three TGF-beta isoforms","system":"recombinant soluble betaglycan","cite":"PMID:19842711"}],"species_and_systems":"Rat recombinant soluble betaglycan from insect cells; GAG-less membrane betaglycan in COS-1 cells [PMID:19842711].","localisation_and_range":"Ligand secreted, betaglycan membrane-bound with a soluble form [flag][PMID:19842711].","caveats":"The affinity is given for the three isoforms collectively. Annotated stimulatory [flag] although betaglycan is a co-receptor.","key_references":[{"PMID":"19842711","why":"Two ligand binding domains of betaglycan, SPR affinity, TGF-beta2 labelling"}],"covers":["LR001448","LR004843"]},"LR007435":{"pair":"TGFB3 -> TGFBR1:TGFBR2","headline":"TGF-beta3 to the TGFBR1:TGFBR2 complex is supported by database records including co-crystal and reconstituted-complex entries; no verified paper.","interaction_type":"database-asserted only","direction_and_effect":"BioGRID lists TGFB3-TGFBR2 reconstituted complex and co-crystal structure [DB:BioGRID]; GtoPdb lists agonist for TGFBR1 and TGFBR2 [DB:GtoPdb]; IntAct has records [DB:IntAct].","molecular_requirements":"Both chains are in the row; the dossier does not show which are required.","affinity_potency":[],"species_and_systems":"No curator-verified paper; one abstract-insufficient.","localisation_and_range":"Ligand secreted, complex transmembrane [flag].","caveats":"Database-only; annotated stimulatory [flag].","key_references":[],"covers":["LR007435"]},"LR003376":{"pair":"TGFBI -> STAB1","headline":"One paper reports TGFBI as a circulating ligand of STAB1 by pulldown and endocytosis; single-paper, abstract-level support.","interaction_type":"direct binding","direction_and_effect":"TGFBi was independently confirmed as a novel circulating ligand of Stab1/2 [PMID:36325910]. Clearance by the stabilins suppresses monocyte activation in this paper's model [PMID:36325910].","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Ligand binding used GST-pulldown and endocytosis assays; the atherosclerosis work used mice [PMID:36325910]. Which species the binding assays used is not stated in the abstract.","localisation_and_range":"TGFBI is flagged secreted [flag]; the paper describes circulating plasma ligands cleared by liver sinusoidal endothelial cells [PMID:36325910].","caveats":"Only one paper, read as abstract only; the abstract does not detail the binding result for this specific pair. Stab1 and Stab2 are paralogs, with the same claim made for both.","key_references":[{"PMID":"36325910","why":"Stab1/2 scavenger receptor ligands including TGFBi"}],"covers":["LR003376","LR006577"]},"LR004852":{"pair":"TGM2 -> ITGB1","headline":"tTG interacts directly with beta1 integrins as an adhesion coreceptor for fibronectin, backed by BioGRID records.","interaction_type":"direct binding","direction_and_effect":"Cell-surface tTG interacts with beta1 and beta3 integrins and mediates their association with the 42-kD gelatin-binding domain of fibronectin [PMID:10684262]. It acts as an integrin-associated coreceptor to promote adhesion and spreading [PMID:10684262].","molecular_requirements":"Adhesive function does not require cross-linking activity but depends on stable noncovalent association with integrins [PMID:10684262].","affinity_potency":[],"species_and_systems":"Human tTG cDNA, cultured cells with co-immunoprecipitation [PMID:10684262]. The mouse pair is ortholog-inferred.","localisation_and_range":"TGM2 is flagged secreted [flag]; complexes form inside the cell and accumulate on the surface and in focal adhesions [PMID:10684262].","caveats":"The role is coreceptor with fibronectin rather than a classical signalling ligand; no affinity for the integrin is reported. BioGRID lists affinity capture-western and reconstituted complex [DB:BioGRID].","key_references":[{"PMID":"10684262","why":"tTG as integrin-binding adhesion coreceptor"}],"covers":["LR001457","LR004852"]},"LR006580":{"pair":"TGM2 -> LRP5","headline":"One abstract reports extracellular TG2 interacting with LRP5 and activating beta-catenin signalling in VSMCs.","interaction_type":"functional only","direction_and_effect":"Extracellular TG2 interacts with LRP5 and activates beta-catenin signalling in vascular smooth muscle cells [PMID:18405667].","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Primary vascular smooth muscle cells; species not stated in the abstract [PMID:18405667]. The mouse pair is the non-inferred one.","localisation_and_range":"TGM2 is flagged secreted [flag]; extracellular TG2 acts on the cell [PMID:18405667].","caveats":"One abstract only, no direct binding measurement described.","key_references":[{"PMID":"18405667","why":"Extracellular TG2 interacts with LRP5 in VSMCs"}],"covers":["LR003379","LR006580"]},"LR001459":{"pair":"TGM2 -> SDC4","headline":"Cell-surface TG2 associates with heparan sulfate chains of syndecan-4, shown by SPR and cell assays.","interaction_type":"direct binding","direction_and_effect":"Cell-surface TG2 directly associates with the HS chains of syndecan-4 without fibronectin mediation [PMID:19398782]. Syndecan-4-null fibroblasts fail to externalize TG2, which accumulates in the cytosol [PMID:19398782].","molecular_requirements":"Binding is via heparan sulfate chains; syndecan-4 plays a major but not exclusive role among HSPGs [PMID:19398782].","affinity_potency":[{"value":"high affinity for heparin/HS, comparable to fibronectin (no numeric value in abstract)","assay":"heparin/HS solid-binding assays and SPR","system":"purified TG2","cite":"PMID:19398782"}],"species_and_systems":"Human TG2 per curation; fibroblasts including syndecan-4-null cells [PMID:19398782]. Human and mouse pairs are both listed.","localisation_and_range":"Cell-surface syndecan-4 acts as a trafficking receptor for TG2 externalization [PMID:19398782].","caveats":"Abstract-only read. Binding is to glycosaminoglycan chains, so other HSPGs may also bind TG2.","key_references":[{"PMID":"19398782","why":"TG2 binds syndecan-4 heparan sulfate; trafficking"}],"covers":["LR001459","LR004854"]},"LR004861":{"pair":"THBS1 -> ITGA4","headline":"Functional support that alpha4beta1 mediates endothelial responses to THBS1 N-terminal regions; not direct binding data.","interaction_type":"functional only","direction_and_effect":"Alpha4beta1 supports adhesion of venous endothelial cells, but not microvascular endothelial cells, on immobilized THBS1 and its N-terminal regions; it mediates chemotaxis and promotes survival and proliferation (stimulatory), and alpha4beta1 antagonists inhibited angiogenesis in vivo [PMID:14699013]. Reactome lists THBS1 binding alpha3beta1/alpha4beta1 [DB:Reactome].","molecular_requirements":"Acts as the alpha4beta1 heterodimer; the THBS1 N-terminal region containing the alpha4beta1 binding sequence is sufficient [PMID:14699013]. Antagonism of FGF-2-stimulated chemotaxis was not mediated by this region [PMID:14699013].","affinity_potency":[],"species_and_systems":"Endothelial cells (species not specified in our evidence), chick chorioallantoic membrane, and mouse muscle explants, where inhibition was lost in THBS1-null explants [PMID:14699013].","localisation_and_range":"THBS1 is flagged secreted [flag], so it likely acts as a soluble or matrix-associated ligand; range is not reported in our evidence beyond that.","caveats":"One paper, read as abstract only; adhesion and chemotaxis are indirect readouts. Cell-type dependent: not active in microvascular endothelial cells. No affinity reported.","key_references":[{"PMID":"14699013","why":"alpha4beta1 mediates endothelial adhesion, chemotaxis and angiogenesis responses to THBS1"}],"covers":["LR001466","LR004861"]},"LR007075":{"pair":"THBS1 -> ITGAV:ITGB3","headline":"Old platelet affinity data and a recent kidney paper support alphaVbeta3 as a THBS1 receptor; modest evidence.","interaction_type":"direct binding","direction_and_effect":"Platelet alphaVbeta3 bound a THBS1 column and was eluted with GRGDSP peptide [PMID:2478219]. In FSGS kidney work, cyclo-RGDfK, an RGD-mimetic, blocked TSP-1 binding to ITGB3 and reduced tubular injury, with TSP-1 and ITGB3 colocalised [PMID:38960036]. BioGRID lists THBS1-ITGB3 records [DB:BioGRID].","molecular_requirements":"The kidney paper addresses ITGB3 only, not ITGAV [PMID:38960036]. The platelet paper identifies the alpha chain as alphaV-like by comigration and antibody [PMID:2478219].","affinity_potency":[],"species_and_systems":"Human platelets [PMID:2478219]; human HK-2 cells, FSGS patient tissue, and mouse adriamycin model [PMID:38960036].","localisation_and_range":"THBS1 is flagged secreted [flag], so it likely acts as a soluble or matrix-associated ligand; range is not reported in our evidence beyond that.","caveats":"The kidney paper does not show the alphaV partner, so it is chain-only evidence. One further paper was judged abstract-insufficient. No affinity reported.","key_references":[{"PMID":"2478219","why":"THBS1-Sepharose retains platelet alphaVbeta3"},{"PMID":"38960036","why":"TSP-1/ITGB3 blocked by cyclo-RGDfK in kidney injury (full text)"}],"covers":["LR007075"]},"LR001468":{"pair":"THBS1 -> ITGB1","headline":"THBS1 engages beta1 integrins (alpha6beta1, alpha4beta1, alpha3beta1) in adhesion and chemotaxis assays; abstract-level evidence only.","interaction_type":"functional only","direction_and_effect":"Beta1 integrins mediate cell adhesion and chemotaxis to THBS1; alpha6beta1 mediates adhesion and chemotaxis of microvascular endothelial and HT-1080 cells [PMID:12909644], alpha3beta1 does so in breast carcinoma cells [PMID:10196234]. Effect is receptor-mediated cell response; agonist/antagonist not reported in our evidence.","molecular_requirements":"ITGB1 acts as a partner of specific alpha chains: alpha6beta1 binds the N-terminal pentraxin module [PMID:12909644], alpha4beta1 is used by venous but not microvascular endothelial cells [PMID:14699013]. Beta1 integrins also recognise the type 1 and type 2 repeats in a pan-beta1 manner [PMID:15292271]. Reactome lists alpha3beta1/alpha4beta1:THBS1 complexes [DB:Reactome].","affinity_potency":[],"species_and_systems":"Human microvascular endothelial and HT-1080 cells [PMID:12909644], mouse endothelial cells and muscle explants [PMID:14699013], human and breast carcinoma cell lines (species unspecified) [PMID:10196234, PMID:15292271]. The mouse pair is ortholog-inferred.","localisation_and_range":"THBS1 is flagged secreted; used in these assays as immobilised matrix substrate, so contact/matrix signalling [flag] [PMID:12909644].","caveats":"All four papers were read as abstracts only. Evidence is adhesion/functional, with direct-binding labels resting on cell-adhesion readouts; integrin activation state matters (HUVEC respond only to certain agonists) [PMID:12909644]. Use the specific alpha:beta heterodimer when scoring. BioGRID lists an affinity-capture-western record [DB:BioGRID].","key_references":[{"PMID":"12909644","why":"alpha6beta1 adhesion/chemotaxis to THBS1 N-terminal module"},{"PMID":"14699013","why":"alpha4beta1 in endothelial responses and angiogenesis"},{"PMID":"15292271","why":"beta1 integrin sites in type 1/2 repeats"}],"covers":["LR001468","LR004863"]},"LR005347":{"pair":"THBS1 -> PTPRJ","headline":"THBS1 binds the CD148 (PTPRJ) ectodomain and raises its phosphatase activity, inhibiting endothelial growth; single abstract-level paper.","interaction_type":"direct binding","direction_and_effect":"Soluble THBS1 binds the extracellular part of CD148 with high affinity and specificity, and binding increases CD148 catalytic activity, causing substrate dephosphorylation [PMID:22308318]. CD148 mediates THBS1-induced growth inhibition, which soluble CD148 ectodomain or gene silencing antagonises [PMID:22308318]. The curated effect_direction label is antagonist, but the text describes activation of CD148 activity.","molecular_requirements":"Introduction of CD148 conferred THBS1 growth inhibition on cells lacking it [PMID:22308318]. Other subunits or co-receptors: not reported in our evidence.","affinity_potency":[],"species_and_systems":"Human CD148 and THBS1; HA-tagged CD148 expressed in cultured endothelial cells, identified by mass spectrometry [PMID:22308318].","localisation_and_range":"THBS1 is flagged secreted [flag]; soluble THBS1 acts on the cell-surface receptor [PMID:22308318].","caveats":"One paper, read as an abstract only; numeric affinity not given in the abstract. No database records.","key_references":[{"PMID":"22308318","why":"THBS1 identified as CD148 ligand that activates its phosphatase"}],"covers":["LR002019","LR005347"]},"LR006832":{"pair":"THBS1 -> SIRPA","headline":"Supported only by database records (GtoPdb, UniProt); no curated papers.","interaction_type":"database-asserted only","direction_and_effect":"UniProt describes THBS1 as a ligand for SIRPA and SIRPA as a receptor for THBS1 [DB:UniProt]. GtoPdb lists the action as Binding with no affinity [DB:GtoPdb]. Agonist or antagonist: not reported in our evidence.","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Not reported in our evidence; UniProt annotations cite PMID 24511121 but no curated paper in our dossier verifies it [DB:UniProt].","localisation_and_range":"SIRPA is flagged transmembrane; THBS1 flagged secreted [flag].","caveats":"No paper was verified by curators (one review_only row). The pair rests on database assertion alone.","key_references":[],"covers":["LR006832"]},"LR003385":{"pair":"THBS1 -> VLDLR","headline":"THBS1 is reported as a Reelin-independent ligand of VLDLR and ApoER2 that induces Dab1 phosphorylation; abstract-level evidence.","interaction_type":"direct binding","direction_and_effect":"THBS-1 binds VLDLR and ApoER2 and induces Dab1 phosphorylation, but unlike Reelin it does not induce Dab1 degradation or Akt phosphorylation and instead stabilises neuronal precursor chains [PMID:18946489]. Agonist label from curation.","molecular_requirements":"ApoER2 is also a receptor for THBS-1 [PMID:18946489]; whether VLDLR alone suffices is not reported in our evidence.","affinity_potency":[],"species_and_systems":"Subventricular zone and rostral migratory stream explants and THBS-1-deficient mice; curated species human, mouse pair ortholog-inferred [PMID:18946489].","localisation_and_range":"THBS1 is flagged secreted [flag]; present throughout the SVZ and rostral migratory stream [PMID:18946489].","caveats":"Abstract only; no affinity reported. Both species rows are ortholog-inferred, and the experiments appear to use mouse tissue.","key_references":[{"PMID":"18946489","why":"THBS-1 as ligand for ApoER2 and VLDLR"}],"covers":["LR003385","LR006586"]},"LR004870":{"pair":"THBS2 -> ITGB1","headline":"Beta1 integrins (alpha6beta1, alpha4beta1) mediate cell responses to the THBS2 N-terminal region; abstract-level functional evidence.","interaction_type":"functional only","direction_and_effect":"Alpha6beta1 mediates adhesion and chemotaxis to the TSP-2 N-terminal region [PMID:12909644]; alpha4beta1 mediates venous endothelial adhesion, chemotaxis, survival and proliferation on these regions [PMID:14699013].","molecular_requirements":"Beta1 pairs with alpha6 or alpha4; the N-terminal pentraxin module carries the alpha6beta1 site [PMID:12909644].","affinity_potency":[],"species_and_systems":"Human microvascular endothelial and HT-1080 cells [PMID:12909644]; mouse (chick CAM and mouse explants) [PMID:14699013].","localisation_and_range":"THBS2 flagged secreted; immobilised substrate [flag].","caveats":"Abstracts only; recombinant N-terminal regions, not full-length THBS2; adhesion-based. One row abstract_insufficient. Mouse pair is ortholog-inferred.","key_references":[{"PMID":"12909644","why":"alpha6beta1 recognises TSP-2 N-terminal region"},{"PMID":"14699013","why":"alpha4beta1 responses to TSP-2 N-terminal region"}],"covers":["LR001475","LR004870"]},"LR010675":{"pair":"THBS3 -> CD36","headline":"The only paper concerns thrombospondin generally (likely THBS1), so the THBS3-CD36 assignment is doubtful.","interaction_type":"functional only","direction_and_effect":"CD36 transfection conferred TSP binding to melanoma cells in a 1:1 ratio with CD36 expression [PMID:1379600].","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Human Bowes melanoma cells transfected with sense or antisense CD36 [PMID:1379600].","localisation_and_range":"Not reported in our evidence.","caveats":"Abstract says 'thrombospondin (TSP)' without paralog; curators note the THBS3 assignment is doubtful.","key_references":[{"PMID":"1379600","why":"CD36 transfection confers thrombospondin binding"}],"covers":["LR010675"]},"LR003394":{"pair":"THY1 -> ITGAV","headline":"THY1 binds alphavbeta3 integrin by SPR and single-molecule force assays; soluble Thy-1 antagonises alphav-driven fibrosis.","interaction_type":"direct binding","direction_and_effect":"Thy-1/alphavbeta3 drives neuron-astrocyte signalling [PMID:29212879][PMID:18346467]. Soluble Thy-1-Fc acted as antagonist: it reversed TGF-beta1-induced myofibroblast differentiation and promoted fibrosis resolution in mice, requiring its integrin-binding RGD motif [PMID:31672942].","molecular_requirements":"Both alphav and beta3 are required for neuron-astrocyte association; wild-type (RLD) but not RLE Thy-1 binds alphavbeta3 by SPR, promoted by divalent cations [PMID:18346467].","affinity_potency":[],"species_and_systems":"Optical tweezers with Thy-1-Fc and nonpurified alphavbeta3-Fc, slip-bond behaviour [PMID:29212879]; DI TNC1 astrocyte line, species not specified in the dossier [PMID:18346467]; bleomycin mouse models and cultured fibroblasts [PMID:31672942].","localisation_and_range":"Membrane-bound neuronal Thy-1 contacting astrocyte integrin (trans); soluble Thy-1-Fc used in the fibrosis study [PMID:18346467][PMID:31672942].","caveats":"All three papers abstract only. The fibrosis paper shows targeting of alphav by Thy-1-Fc, not the beta3 chain specifically. No numeric affinity reported.","key_references":[{"PMID":"18346467","why":"SPR binding of Thy-1 RLD to alphavbeta3"},{"PMID":"29212879","why":"Force spectroscopy, slip-bond"},{"PMID":"31672942","why":"Soluble Thy-1 antagonises alphav in fibrosis"}],"covers":["LR003394","LR006595"]},"LR007426":{"pair":"THY1 -> ITGAX:ITGB2","headline":"Thy-1 binds the alphaXbeta2 (CD11c/CD18) I-domain with micromolar affinity; one abstract-only paper.","interaction_type":"direct binding","direction_and_effect":"Specific, divalent-cation-dependent binding; effect not reported in our evidence [PMID:15850796].","molecular_requirements":"alphaX I-domain is the binding moiety; mutants D249 and KE243/244 lose affinity, mapping the betaD-alpha5 site. Whether beta2 contributes is not reported [PMID:15850796].","affinity_potency":[{"value":"KD 1.16muM","assay":"I-domain binding","system":"recombinant alphaX I-domain","cite":"PMID:15850796"}],"species_and_systems":"Human, recombinant I-domain assay [PMID:15850796].","localisation_and_range":"Membrane-bound integrin; contact-dependent.","caveats":"Abstract only; isolated I-domain, not the full heterodimer.","key_references":[{"PMID":"15850796","why":"alphaX I-domain binding to Thy-1"}],"covers":["LR007426"]},"LR008371":{"pair":"TIE1 -> NTRK1","headline":"Only evidence is a sentence naming TrkA and TIE1 as SPR negative controls; no support for this pair.","interaction_type":"conflicting","direction_and_effect":"Not reported in our evidence.","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Human protein screen, ELISA and SPR [PMID:32822567].","localisation_and_range":"Not reported in our evidence.","caveats":"The cited sentence says 'TrkA and TIE1, negative controls' in an SPR figure legend, so the paper used them as non-binders for other pairs [PMID:32822567].","key_references":[{"PMID":"32822567","why":"Source of the sentence, which concerns negative controls"}],"covers":["LR008371"]},"LR001477":{"pair":"TIMP1 -> CD63","headline":"TIMP-1 binds CD63 (yeast two-hybrid, co-IP) and CD63 is needed for TIMP-1 cell-surface binding; supported by databases too.","interaction_type":"direct binding","direction_and_effect":"Yeast two-hybrid identified CD63 as a TIMP-1 interactor, confirmed by co-immunoprecipitation and confocal colocalisation; CD63 shRNA knockdown reduced TIMP-1 cell-surface binding and reversed TIMP-1-driven integrin beta1 activation and survival signalling [PMID:16917503]. BioGRID, IntAct and UniProt records support TIMP1-CD63 physical interaction [DB:BioGRID][DB:IntAct][DB:UniProt].","molecular_requirements":"CD63 also co-immunoprecipitates with integrin beta1 and TIMP-1 on the cell surface [PMID:16917503]; UniProt states CD63 recruits TIMP1 to ITGB1 [DB:UniProt]. Whether CD63 alone suffices for signalling is not reported in our evidence.","affinity_potency":[],"species_and_systems":"Human breast epithelial MCF10A cells, including 3D Matrigel culture [PMID:16917503]. Mouse pair is ortholog-inferred.","localisation_and_range":"TIMP1 is flagged secreted and CD63 as a receptor [flag]; TIMP-1 binds the cell surface [PMID:16917503].","caveats":"Primary paper read as abstract only; no affinity reported. Signalling may depend on integrin beta1 as a partner.","key_references":[{"PMID":"16917503","why":"Identification of CD63 as TIMP-1 binding partner"}],"covers":["LR001477","LR004872"]},"LR006607":{"pair":"TIMP3 -> LRP1","headline":"TIMP-3 binds LRP-1 with high affinity by SPR and bridges metalloproteinases to it; endocytic receptor interaction.","interaction_type":"direct binding","direction_and_effect":"TIMP-3 bound LRP-1 with the highest affinity among proteins tested, and also bridged MMP-1, MMP-13 and MMP-14 to LRP-1, facilitating metalloproteinase clearance [PMID:32694578]. LRP-1 acts as an endocytic receptor here [PMID:32694578].","molecular_requirements":"Complex with MMP-1 binds with higher affinity: free MMP-1 KD 34.6 nM versus MMP-1/TIMP-3 4.96 nM [PMID:32694578]. TIMP-3 alone suffices for binding.","affinity_potency":[{"value":"KD 1.68 nM","assay":"surface plasmon resonance","system":"TIMP-3 over immobilised LRP-1","cite":"PMID:32694578"},{"value":"KD 4.96 nM","assay":"surface plasmon resonance","system":"MMP-1/TIMP-3 complex over LRP-1","cite":"PMID:32694578"}],"species_and_systems":"Human recombinant proteins by SPR and HTB94 cells for internalisation [PMID:32694578]; mouse pair is ortholog-inferred.","localisation_and_range":"TIMP3 is flagged secreted; uptake is by endocytosis [PMID:32694578].","caveats":"Both papers read as abstracts with excerpts. The role is clearance, not classical activation; the curated effect label is agonist though the evidence concerns endocytosis.","key_references":[{"PMID":"32694578","why":"SPR affinity of TIMP-3 for LRP-1 and bridging"}],"covers":["LR003406","LR006607"]},"LR008227":{"pair":"TNC -> ITGA7:ITGB1","headline":"Alpha7beta1 associates with a splice-region peptide of tenascin-C and mediates neurite outgrowth; abstract-only.","interaction_type":"direct binding","direction_and_effect":"Alpha7beta1 integrin associated with tenascin-C peptides containing VFDNFVLK, and function-blocking antibodies against both subunits abolished neurite outgrowth [PMID:14715956]. The mutant peptide did not cluster beta1 [PMID:14715956].","molecular_requirements":"Complex ITGA7:ITGB1 [flag]; both chains required for the response [PMID:14715956]. Splice-form-specific: the site is in alternatively spliced repeat D [PMID:14715956].","affinity_potency":[],"species_and_systems":"Human ligand and receptor per curator record; cerebellar granule neurons [PMID:14715956].","localisation_and_range":"Ligand flagged as secreted, non-transmembrane [flag]; presented as extracellular matrix, so acts locally on adjacent cells.","caveats":"Abstract-only; peptide rather than full-length protein. Reactome and UniProt records shown concern alpha8/alpha9 integrins, not alpha7 [DB:Reactome][DB:UniProt].","key_references":[{"PMID":"14715956","why":"alpha7beta1 and VFDNFVLK of tenascin-C"}],"covers":["LR008227"]},"LR001486":{"pair":"TNC -> ITGA8","headline":"Human alpha8beta1 mediates adhesion to tenascin; binding domain localised to the third FNIII repeat; abstract-only.","interaction_type":"direct binding","direction_and_effect":"Of RGD-containing proteins tested, only tenascin mediated adhesion of alpha8-transfected 293 cells; the alpha8beta1 binding domain was localised to the RGD-containing third fibronectin type III repeat [PMID:7559467]. Reactome also records alpha8beta1:tenascin-C [DB:Reactome].","molecular_requirements":"Alpha8 pairs with beta1 (alpha8beta1) [PMID:7559467]; stored per subunit though the heterodimer binds.","affinity_potency":[],"species_and_systems":"Human embryonic kidney 293 cells transfected with alpha8 cDNA [PMID:7559467].","localisation_and_range":"Ligand flagged as secreted, non-transmembrane [flag]; presented as extracellular matrix, so acts locally on adjacent cells.","caveats":"Abstract-only; cell-adhesion assay. Alpha8beta1 also binds fibronectin and vitronectin [PMID:7559467]. Curator notes the entry should be folded into the alpha8:beta1 complex.","key_references":[{"PMID":"7559467","why":"alpha8beta1 as receptor for tenascin, fibronectin, vitronectin"}],"covers":["LR001486","LR004881"]},"LR001495":{"pair":"TNFSF10 -> TNFRSF10D","headline":"TRAIL-R4 (TNFRSF10D) is a decoy-type TRAIL receptor that protects cells from TRAIL killing.","interaction_type":"direct binding","direction_and_effect":"Overexpressing TRAIL-R4 in TRAIL-sensitive cells confers complete protection, suggesting inhibition of TRAIL cytotoxicity (antagonist/decoy) [PMID:9430226]. It activates NF-kappaB similarly to TRAIL-R1 and -R2 but cannot induce apoptosis [PMID:9430226]. A decoy named TRID, with an extracellular TRAIL-binding domain and no intracellular signalling domain, protected cells from TRAIL-induced apoptosis [PMID:9242610].","molecular_requirements":"TRAIL-R4 keeps one third of a consensus death domain motif [PMID:9430226]; TRID has none of an intracellular domain [PMID:9242610].","affinity_potency":[],"species_and_systems":"Human proteins, transient overexpression [PMID:9430226]. BioGRID reconstituted complex [DB:BioGRID] and IntAct surface plasmon resonance [DB:IntAct] support physical binding.","localisation_and_range":"Membrane-bound receptor; TRAIL is flagged secreted and transmembrane [flag].","caveats":"Both papers were read as abstracts. The link between TRID and TRAIL-R4 is not spelled out in the 9242610 abstract, which names the decoy only as TRID.","key_references":[{"PMID":"9430226","why":"Cloning of TRAIL-R4 and protection from TRAIL"},{"PMID":"9242610","why":"Decoy receptor TRID for TRAIL"}],"covers":["LR001495"]},"LR006616":{"pair":"TNFSF11 -> LGR4","headline":"LGR4 is reported as a second RANKL receptor that competes with RANK and dampens osteoclast differentiation; one abstract-level paper.","interaction_type":"direct binding","direction_and_effect":"LGR4 competes with RANK for RANKL and suppresses canonical RANK signalling; RANKL binding to LGR4 activates the G-alpha-q and GSK3-beta pathway, reducing NFATC1 expression and activity [PMID:27064449]. Knockout mice show osteoclast hyperactivation, and soluble LGR4 ECD binds RANKL and blocks bone loss in three mouse osteoporosis models [PMID:27064449]. Effect: negative regulator, with decoy-like ECD.","molecular_requirements":"RANK competition is central; co-receptor requirements are not reported in our evidence [PMID:27064449].","affinity_potency":[],"species_and_systems":"Dossier records human, with mouse knockout and disease models in vivo [PMID:27064449]. No database records.","localisation_and_range":"RANKL is flagged secreted and transmembrane [flag].","caveats":"Only one paper, read as an abstract; no independent replication or affinity in our evidence.","key_references":[{"PMID":"27064449","why":"LGR4 as a second RANKL receptor"}],"covers":["LR003415","LR006616"]},"LR004906":{"pair":"TSHB -> TSHR","headline":"TSH activates the cloned human TSH receptor in CHO cells; established agonist pair supported by GtoPdb, PDB and Reactome.","interaction_type":"direct binding","direction_and_effect":"Agonist: CHO cells stably expressing the cloned receptor activated adenylate cyclase specifically in response to TSH [PMID:2558651]. GtoPdb lists Agonist/Agonist [DB:GtoPdb]; UniProt describes TSHR as the receptor for TSH [DB:UniProt].","molecular_requirements":"Single seven-transmembrane GPCR in the cloning paper [PMID:2558651]; the dossier notes Reactome records TSHR binding TSH/thyrostimulin [DB:Reactome R-HSA-391375]. Alpha subunit requirement not reported in our evidence.","affinity_potency":[],"species_and_systems":"Human thyroid cDNA, CHO cells; the TSH species is not stated in the abstract [PMID:2558651]. PDB complexes exist [DB:PDB 7T9I].","localisation_and_range":"TSHB flagged secreted; TSHR flagged transmembrane [flag].","caveats":"The cloning paper shows functional response, not direct binding, so the assay_class direct_binding is generous; abstract read only. The row is tagged mouse in the source though the paper is human. No affinity in the dossier.","key_references":[{"PMID":"2558651","why":"Cloning of human TSH receptor; TSH-specific adenylate cyclase activation"}],"covers":["LR001516","LR004906"]},"LR006625":{"pair":"TUB -> MERTK","headline":"Tubby binds MerTK selectively among TAM receptors and induces activation and phagocytosis; one abstract-read paper.","interaction_type":"direct binding","direction_and_effect":"Agonist: tubby binds only MerTK among the TAM receptors; both tubby and Tulp1 induced MerTK activation with receptor phosphorylation and signalling, and soluble MerTK extracellular domain blocked tubby-mediated phagocytosis [PMID:20978472].","molecular_requirements":"Tubby's N-terminal region is the MerTK-binding domain; the C-terminal region is the phagocytosis prey-binding domain, mapped to 54 conserved amino acids [PMID:20978472].","affinity_potency":[],"species_and_systems":"Retinal pigment epithelium and macrophage phagocytosis assays; species not stated in the abstract [PMID:20978472]. Human pair ortholog-inferred, mouse pair not.","localisation_and_range":"No classical signal peptide, unconventional secretion shown [PMID:20978472]; ligand flagged secreted [flag].","caveats":"Abstract read only; no affinity value. Bridging ligand with prey-binding domain.","key_references":[{"PMID":"20978472","why":"Tubby binds only MerTK among TAM receptors"}],"covers":["LR003424","LR006625"]},"LR007336":{"pair":"ULBP1 -> HCST:KLRK1","headline":"ULBP1 engages the NKG2D receptor on NK cells; one full-text functional paper plus database records, no affinity data.","interaction_type":"functional only","direction_and_effect":"Agonist, activating: ULBPs stimulate cytokine and chemokine production from NK cells and make NK-resistant target cells susceptible to NK cytotoxicity [PMID:11239445].","molecular_requirements":"NKG2D is required: anti-NKG2D antiserum blocked ULBP1-Fc binding to NKL cells, and the ULBPs are described as ligands for the activating receptor NKG2D/DAP10 [PMID:11239445]. HCST (DAP10) is named only through the statement that the receptor is 'probably NKG2D/DAP10'; HCST was not tested separately in our evidence [PMID:11239445].","affinity_potency":[],"species_and_systems":"Human proteins and human NKL cells, using Fc fusion proteins [PMID:11239445]. IntAct lists a surface plasmon resonance record between ULBP1 and KLRK1 [DB:IntAct] [PMID:28559451]; UniProt notes ULBP1 interacts with KLRK1/NKG2D [DB:UniProt] [PMID:11777960].","localisation_and_range":"Ligand is membrane-bound [flag]; the paper describes ULBPs as GPI-linked glycoproteins [PMID:11239445], so signalling is by cell contact.","caveats":"Blocking evidence was shown with ULBP1-Fc, with the paper's text extending it to all ULBP/MIC-Fc fusions per the curator. Binding affinity is not reported in our evidence. Only one paper supports this pair [PMID:11239445]; it is functional in vitro (human NKL cells), read in full text. Database records add physical-interaction support only.","key_references":[{"PMID":"11239445","why":"ULBPs bind NKG2D on NK cells and stimulate cytotoxicity"}],"covers":["LR007336"]},"LR006634":{"pair":"UNC5B -> FLRT2","headline":"UNC5B-FLRT2 binding shown in a mouse-protein screen; UniProt reports lower affinity than for FLRT3; one abstract-only paper judged negative.","interaction_type":"direct binding","direction_and_effect":"Binding was seen in an ELISA-based screen with AP/Fc-tagged extracellular domains, with every FLRT1-3 x Unc5A-D pair reported at or near saturation (mean Abs650nm value = 2.14) [PMID:26633812]. Titration with purified protein and CHO.K1 cell aggregation confirmed the family pairs [PMID:26633812]. In this paper Unc5-expressing neurons are repelled by FLRT, so FLRT acts as ligand and Unc5 as receptor, the reverse of the listed direction [PMID:26633812]. ","molecular_requirements":"Extracellular domains of both partners are used; no co-receptor or extra subunit is reported in our evidence.","affinity_potency":[],"species_and_systems":"Mouse proteins in recombinant ELISA and cell-aggregation assays; the human pair is ortholog-inferred and the mouse pair is the direct one [PMID:26633812].","localisation_and_range":"UNC5B is annotated as a transmembrane receptor and FLRT2 as both secreted and transmembrane [flag]; contact-mediated signalling is likely, but this is not tested here.","caveats":"The binding statement is family-wide rather than specific to this pair. Pair-specific functional data are absent. An abstract-only 2011 paper was judged pair_absent: it states Unc5D binds specifically to FLRT2 and names FLRT3 as Unc5B's partner [PMID:21673655]. UniProt notes UNC5B binds FLRT2 and FLRT3 but with higher affinity for FLRT3 [DB:UniProt]. No affinity value is given.","key_references":[{"PMID":"26633812","why":"Extracellular screen and titration binding of all FLRT x Unc5 pairs, mouse proteins"}],"covers":["LR003433","LR006634"]},"LR004915":{"pair":"UTS2 -> UTS2R","headline":"Urotensin-II is an established agonist of the UT (GPR14) receptor, with binding and calcium signalling in several species.","interaction_type":"direct binding","direction_and_effect":"Human and goby U-II bind recombinant human GPR14 with high affinity, coupled to calcium mobilisation [PMID:10499587]. Porcine UII, isolated from spinal cord, activated rat SENR (GPR14) with EC50 1 nM in arachidonic acid release [PMID:10548501]. GtoPdb and Reactome both record agonist binding [DB:GtoPdb, DB:Reactome]. UTS2B (URP) also binds and activates UT receptors, so the receptor is shared [PMID:14550283].","molecular_requirements":"UT is a single GPCR; no extra subunit is reported in our evidence. Reactome models the complex as UTSR with UTS2 or UTS2B [DB:Reactome].","affinity_potency":[{"value":"Kd 654 pM","assay":"[125I]human U-II saturation binding","system":"cloned mouse UT receptor","cite":"PMID:11976263"},{"value":"Kd 214 pM","assay":"[125I]human U-II saturation binding","system":"cloned monkey UT receptor","cite":"PMID:11976263"},{"value":"EC50 3.2 nM","assay":"human U-II intracellular Ca2+ rise","system":"mouse UT receptor","cite":"PMID:11976263"},{"value":"EC50 1.1 nM","assay":"human U-II intracellular Ca2+ rise","system":"monkey UT receptor","cite":"PMID:11976263"},{"value":"EC50 1 nM","assay":"arachidonic acid metabolite release by synthetic UII","system":"CHO cells expressing rat SENR","cite":"PMID:10548501"}],"species_and_systems":"Recombinant human GPR14 [PMID:10499587]; rat GPR14 in HEK293 [PMID:10581185]; mouse and monkey receptors with human U-II [PMID:11976263]; rat SENR with porcine UII [PMID:10548501]. The human UT receptor is not tested in the affinity paper.","localisation_and_range":"UTS2 is annotated as secreted and UTS2R as transmembrane [flag]; human U-II acts as a circulating vasoconstrictor on arteries [PMID:10499587].","caveats":"All papers were read as abstracts only. Affinity values come from non-human receptors. Our evidence lists 10 confirmed papers but only 6 are shown here; 1 is abstract_insufficient, 1 is review_only and 1 is pending.","key_references":[{"PMID":"10499587","why":"Human U-II binds and activates human GPR14"},{"PMID":"10548501","why":"UII identified as endogenous ligand of GPR14/SENR"},{"PMID":"11976263","why":"Kd and EC50 values at mouse and monkey UT receptors"}],"covers":["LR001526","LR004915"]},"LR006643":{"pair":"UTS2B -> SSTR5","headline":"UTS2B inhibits GLP-1 secretion in mouse gut via SSTR5 rather than UTS2R; functional evidence from one abstract.","interaction_type":"functional only","direction_and_effect":"UTS2B inhibits GLP-1 secretion in mouse intestinal crypts and organoids, not through UTS2R but through activation of SSTR5 [PMID:31556942]. Given to starved mice, UTS2B regulates blood glucose and plasma GLP-1 and insulin [PMID:31556942].","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Mouse intestinal crypts, organoids and whole animals; the human pair is ortholog-inferred [PMID:31556942].","localisation_and_range":"UTS2B is annotated as secreted [flag]; the curator notes describe paracrine action from a gut enteroendocrine cell source [PMID:31556942].","caveats":"Abstract only. No direct binding or affinity is shown, so SSTR5 engagement is inferred from function. The paper itself says UTS2R is not involved.","key_references":[{"PMID":"31556942","why":"UTS2B acts through SSTR5 to inhibit GLP-1 secretion in mouse gut"}],"covers":["LR003442","LR006643"]},"LR004924":{"pair":"VCAN -> SELP","headline":"Versican binds P-selectin via its chondroitin sulfate chain; one abstract-level paper.","interaction_type":"direct binding","direction_and_effect":"Human ACHN-derived versican binds P-selectin, mediated by the CS chain and the carbohydrate-binding domain [PMID:10950950].","molecular_requirements":"Inhibited by CS B, CS E and heparan sulfate; shares an overlapping site with L-selectin [PMID:10950950].","affinity_potency":[],"species_and_systems":"Human versican with soluble selectin [PMID:10950950]. Mouse pair is ortholog-inferred.","localisation_and_range":"Versican flagged secreted; SELP flagged transmembrane receptor [flag].","caveats":"Glycan-mediated; single abstract-level paper. BioGRID: reconstituted complex [DB:BioGRID].","key_references":[{"PMID":"10950950","why":"versican CS chain binds P-selectin"}],"covers":["LR001535","LR004924"]},"LR004933":{"pair":"VEGFB -> FLT1","headline":"VEGF-B binds VEGFR-1/Flt-1 selectively; foundational paper plus structural and pathway database support.","interaction_type":"direct binding","direction_and_effect":"VEGF-B binds selectively to VEGF receptor-1/Flt-1; binding to endothelial cells increases urokinase plasminogen activator and PAI-1 expression and activity; curators label it agonist [PMID:9751730].","molecular_requirements":"Binding was competed by excess VEGF, suggesting partially overlapping sites. Mutating Asp63, Asp64 and Glu67 reduced but did not abolish affinity. The 60-kDa VEGF-B186 dimer processed to a 34-kDa dimer contains the receptor-binding epitopes [PMID:9751730].","affinity_potency":[],"species_and_systems":"Human ligand and receptor per curator fields; abstract-level reading [PMID:9751730]. Mouse pair is ortholog-inferred.","localisation_and_range":"VEGFB flagged secreted and FLT1 transmembrane [flag].","caveats":"Curator read the abstract only; no affinity value reported in our evidence. Support also from a PDB structure [DB:PDB 2XAC], BioGRID reconstituted-complex and affinity-capture records [DB:BioGRID], and Reactome [DB:Reactome]. GtoPdb lists the pair without type or action [DB:GtoPdb]. Other judged rows (review-only, pending) are not shown.","key_references":[{"PMID":"9751730","why":"VEGF-B binds Flt-1 selectively; mapped determinants"}],"covers":["LR001544","LR004933"]},"LR001549":{"pair":"VEGFC -> KDR","headline":"VEGF-C activates KDR (VEGFR-2) in addition to FLT4; foundational papers and structures support it.","interaction_type":"direct binding","direction_and_effect":"VEGF-C induces tyrosine autophosphorylation of VEGFR-2 and binds KDR [PMID:8617204] [PMID:8612600]; curators label the effect stimulatory and agonist.","molecular_requirements":"No complex requirement reported in our evidence. VEGF-C also acts through FLT4 [PMID:8617204].","affinity_potency":[],"species_and_systems":"Human ligand and receptor, abstract-level reading [PMID:8612600]. Mouse pair is ortholog-inferred.","localisation_and_range":"VEGFC flagged secreted [flag]; KDR a transmembrane kinase receptor per the pair name's family, flag not shown here.","caveats":"The placenta paper is weak for this pair: its VEGF-C experiment reads out VEGFR-3 rather than VEGFR-2 [PMID:11332691]. Supporting structures [DB:PDB 2X1W], [DB:BioGRID] co-crystal record. No affinity in our evidence.","key_references":[{"PMID":"8617204","why":"VEGF-C activates VEGFR-2 and VEGFR-3"},{"PMID":"8612600","why":"VEGF-C binds Flt4 and KDR"}],"covers":["LR001549","LR004938"]},"LR000649":{"pair":"VEGFD -> ITGA9","headline":"VEGF-D binds integrin alpha9beta1 in a solid-phase assay; single paper and heterodimer-level evidence.","interaction_type":"direct binding","direction_and_effect":"Recombinant VEGF-D bound purified alpha9beta1 integrin dose- and cation-dependently; alpha9beta1-expressing cells adhered and migrated on VEGF-D, blocked by a function-blocking antibody [PMID:15590642].","molecular_requirements":"The evidence concerns the alpha9beta1 heterodimer, not ITGA9 alone [PMID:15590642].","affinity_potency":[],"species_and_systems":"Recombinant protein and cells including mouse embryonic fibroblasts, SW-480 cells and microvascular endothelial cells [PMID:15590642]. Both interactions are ortholog-inferred.","localisation_and_range":"VEGFD flagged secreted [flag].","caveats":"Single abstract-read paper; no affinity; no database records in this dossier.","key_references":[{"PMID":"15590642","why":"VEGF-D binds alpha9beta1 integrin"}],"covers":["LR000649","LR004133"]},"LR004942":{"pair":"VIP -> NPR3","headline":"One abstract-level study in Xenopus oocytes shows VIP displacing ANP from frog NPR-C; human and mouse pairs are inferred from it.","interaction_type":"direct binding","direction_and_effect":"VIP competitively and completely displaced [125I]ANP from Xenopus NPR-C expressed in oocytes. With PAC1 co-expressed, VIP and natriuretic peptides counteracted PACAP-induced cAMP [PMID:16723209]. So VIP acts as an antagonist of PACAP signalling via NPR-C in this system, not as a clear NPR-C agonist.","molecular_requirements":"NPR-C lacks the guanylyl cyclase domain and is negatively coupled to adenylyl cyclase via Gi; the antagonism required co-expression with PAC1 [PMID:16723209].","affinity_potency":[],"species_and_systems":"Experiments used Xenopus laevis NPR-C in oocytes; the ligand is annotated human. No human or mouse receptor data in our evidence [PMID:16723209].","localisation_and_range":"VIP is flagged secreted [flag]; NPR3 has no transmembrane flag in our entity record.","caveats":"Single paper, abstract only, non-mammalian receptor. No affinity value reported. Human and mouse pairs are ortholog-inferred. The paper calls the finding paradoxical [PMID:16723209].","key_references":[{"PMID":"16723209","why":"Sole evidence: VIP displaces ANP at frog NPR-C and antagonises PACAP signalling"}],"covers":["LR001553","LR004942"]},"LR003448":{"pair":"VTN -> C1QBP","headline":"Direct binding of the heparin-binding multimeric form of vitronectin to gC1qR (C1QBP), Kd about 20 nM, from one abstract-level human study.","interaction_type":"direct binding","direction_and_effect":"Multimeric vitronectin bound gC1qR in a purified system; binding was inhibited by heparin but not chondroitin sulfate [PMID:8900153]. Signalling effect is not reported in our evidence.","molecular_requirements":"Only the heparin-binding multimeric form of vitronectin bound, not the plasma form. A truncated gC1qR lacking the N-terminal 22 residues hardly bound vitronectin but still bound C1q; C1q and vitronectin do not compete [PMID:8900153].","affinity_potency":[{"value":"Kd 20 nM","assay":"saturable binding, purified system","system":"Raji-cell-isolated and recombinant gC1qR with vitronectin","cite":"PMID:8900153"}],"species_and_systems":"Raji cell membrane-derived and recombinant bacterially expressed gC1qR; recombinant/purified in vitro system [PMID:8900153]. IntAct lists an ELISA record [DB:IntAct P04004-Q07021].","localisation_and_range":"Vitronectin is flagged secreted; C1QBP is a receptor by flag but not transmembrane [flag].","caveats":"Single paper, abstract only. Vitronectin was found complexed with thrombin-antithrombin, which alone did not bind gC1qR [PMID:8900153]. Kd is approximate.","key_references":[{"PMID":"8900153","why":"Direct vitronectin-gC1qR binding with Kd about 20 nM"}],"covers":["LR003448","LR006649"]},"LR001558":{"pair":"VTN -> ITGA5","headline":"No support for alpha5 as a vitronectin receptor; the one judged paper pairs vitronectin with alphaVbeta3 instead.","interaction_type":"database-asserted only","direction_and_effect":"Direction and effect are not reported in our evidence. The one judged paper was marked pair_absent: it consistently links vitronectin to alphaVbeta3, not alpha5beta1 [PMID:11331280].","molecular_requirements":"Not reported in our evidence for ITGA5. The Reactome records shown list alphaVbeta1, alphaVbeta3, alpha3beta5 and alphaIIBbeta3, not alpha5beta1 [DB:Reactome].","affinity_potency":[],"species_and_systems":"The negative paper used human ovarian cancer cells (OV-MZ-6) [PMID:11331280].","localisation_and_range":"Vitronectin is flagged as secreted and not transmembrane [flag]; the integrin is a membrane receptor, so signalling is by cell contact with soluble or matrix-bound ligand. The dossier's papers do not describe range further.","caveats":"Verified negative [PMID:11331280] (abstract only); 7 further papers had insufficient abstracts and 2 were pair_absent in total. The only positive signal is a database assertion [DB:Reactome]. Alpha5 likely belongs to a fibronectin receptor rather than a vitronectin one per the curator note, but this is not shown directly.","key_references":[{"PMID":"11331280","why":"Verified negative: vitronectin linked to alphaVbeta3, not alpha5beta1"}],"covers":["LR001558","LR004947"]},"LR004951":{"pair":"VTN -> ITGB3","headline":"Vitronectin binds beta3 integrins on platelets and acts through alphaVbeta3 in smooth muscle and ovarian cancer cells; three abstract-level papers.","interaction_type":"direct binding","direction_and_effect":"Vitronectin bound stimulated human platelets (GPIIb/IIIa) in a calcium-dependent, specific, saturable manner, inhibited by RGDS and anti-GPIIb/IIIa antibodies [PMID:1692034]. AlphaVbeta3-mediated adhesion to vitronectin changed uPA and PAI-1 expression [PMID:11331280]. Residues 177-184 of beta3 were necessary for vitronectin binding to alphaVbeta3 and for the response of smooth muscle cells to IGF-I [PMID:16195248].","molecular_requirements":"Beta3 pairs with an alpha chain: alphaIIb on platelets (GPIIb/IIIa) [PMID:1692034] or alphaV in the other papers [PMID:11331280] [PMID:16195248]. Beta3 residues 177-184 are required [PMID:16195248].","affinity_potency":[{"value":"Kd 320 nM","assay":"vitronectin binding to platelets","system":"thrombin-stimulated human platelets","cite":"PMID:1692034"},{"value":"Kd 93 and 116 nM","assay":"vitronectin binding to platelets","system":"epinephrine- or ADP-stimulated human platelets","cite":"PMID:1692034"}],"species_and_systems":"Human platelets, human ovarian cancer cells; smooth muscle cell species not reported in our evidence. Mouse pair is ortholog-inferred.","localisation_and_range":"Vitronectin is flagged as secreted and not transmembrane [flag]; the integrin is a membrane receptor, so signalling is by cell contact with soluble or matrix-bound ligand. The dossier's papers do not describe range further.","caveats":"Chain-only entry; the evidence is for alphaIIbbeta3 or alphaVbeta3 heterodimers. All papers abstract only; 3 further abstracts were insufficient and 1 is pending.","key_references":[{"PMID":"1692034","why":"Kd values for vitronectin on stimulated platelets"},{"PMID":"16195248","why":"beta3 177-184 needed for vitronectin binding to alphaVbeta3"},{"PMID":"11331280","why":"alphaVbeta3-vitronectin adhesion alters gene expression"}],"covers":["LR001562","LR004951"]},"LR001567":{"pair":"VTN -> PVR","headline":"CD155 (PVR) binds vitronectin directly by SPR with a Kd of 72 nM; one abstract-only paper.","interaction_type":"direct binding","direction_and_effect":"CD155 binds vitronectin specifically, and both colocalise on follicular dendritic cells and B cells in tonsil germinal centres [PMID:11437656]. Signalling effect is not reported in our evidence.","molecular_requirements":"No co-receptor or subunit requirement is reported in our evidence.","affinity_potency":[{"value":"Kd 72 nM","assay":"surface plasmon resonance","system":"human CD155 and vitronectin","cite":"PMID:11437656"}],"species_and_systems":"Human protein experiments; the mouse pair is ortholog-inferred [PMID:11437656]. A BioGRID reconstituted-complex record cites the same paper [DB:BioGRID].","localisation_and_range":"Vitronectin is flagged secreted; PVR is flagged secreted, receptor and transmembrane [flag]. The paper describes cell-to-matrix contact [PMID:11437656].","caveats":"Abstract-only read. The paralogue mPRR2 binds vitronectin only weakly [PMID:11437656], so paralogs are not interchangeable. The database record rests on the same paper.","key_references":[{"PMID":"11437656","why":"SPR binding of CD155 to vitronectin, Kd 72 nM"}],"covers":["LR001567","LR004956"]},"LR007444":{"pair":"VWF -> GP1BA:GP1BB","headline":"VWF acts on the GPIb complex; the one paper shows a GP1BA mutation reduces VWF binding, with structure and Reactome records for the GP1BA part.","interaction_type":"direct binding","direction_and_effect":"A GP1BA p.N103D mutation reduces affinity of the GPIb-GPIX receptor for VWF in iPSC-derived megakaryocytes [PMID:40045897]; blocking anti-CD42b antibody confirmed binding specificity.","molecular_requirements":"The paper tests GPIb-GPIX, not GP1BB alone; binding via GP1BA is supported by database records for GP1BA-VWF [DB:BioGRID] [DB:PDB 1M10]. Reactome lists a collagen:VWF multimer:GP1BA:GP1BB:GP9:GP5 complex [DB:Reactome]. Each subunit's required role is not reported in our evidence.","affinity_potency":[],"species_and_systems":"Human iPSC-derived megakaryocytes from a patient with heterozygous GP1BA p.N103D, ristocetin 0.5 mg/mL with soluble VWF [PMID:40045897].","localisation_and_range":"GP1BA is flagged transmembrane and a receptor, VWF secreted [flag].","caveats":"Evidence is a mutant showing reduced binding, from a paper focused on RhoA signalling; abstract-level curation but full text excerpts available. The database records name GP1BA-VWF, not GP1BB.","key_references":[{"PMID":"40045897","why":"N103D GPIbalpha reduces GPIb-IX affinity for VWF"}],"covers":["LR007444"]},"LR006652":{"pair":"VWF -> ITGA4","headline":"The VWF propolypeptide (not mature VWF) promotes alpha4beta1-dependent cell adhesion; one paper, functional only.","interaction_type":"functional only","direction_and_effect":"The propolypeptide of VWF (pp-vWF) promoted adhesion of MOLT-3 cells through alpha4beta1, binding the same 15 residue site (T2-15) as alpha9beta1 [PMID:10816592]. Blocking by anti-alpha4 antibody is noted by the curators.","molecular_requirements":"alpha4 pairs with beta1 in the cited cells; the ligand is the propolypeptide, a processed form [PMID:10816592].","affinity_potency":[],"species_and_systems":"Human MOLT-3 and G-361 cells, with transfected SW480 cells for alpha9beta1 [PMID:10816592]. Both human and mouse pairs are ortholog-inferred.","localisation_and_range":"Not reported in our evidence.","caveats":"Ligand is pp-vWF cleaved from the precursor, so the result may not apply to mature circulating VWF. Cell adhesion assay, not binding. Chain-level evidence for alpha4.","key_references":[{"PMID":"10816592","why":"pp-vWF supports alpha4beta1 and alpha9beta1 mediated adhesion"}],"covers":["LR003452","LR006652"]},"LR003457":{"pair":"VWF -> LRP1","headline":"Macrophage LRP1 helps clear VWF; binding is shear-dependent; one abstract-only paper.","interaction_type":"direct binding","direction_and_effect":"VWF-coated beads adhered to LRP1 only above 2.5 dyne/cm(2) shear; half-life of human VWF was increased in macrophage LRP1-deficient mice [PMID:22234691]. LRP1 acts as a clearance receptor.","molecular_requirements":"A beta2-integrin mechanism binding both VWF and LRP1 is implicated, as beta2-integrin inhibition raised VWF in control but not macLRP1- mice [PMID:22234691].","affinity_potency":[],"species_and_systems":"Human VWF in mice with macrophage-specific LRP1 deficiency; basal VWF 1.6 +/- 0.4 vs 1.0 +/- 0.4 U/mL [PMID:22234691]. Both listed pairs are ortholog-inferred.","localisation_and_range":"Macrophage cell surface receptor clearing plasma VWF [PMID:22234691].","caveats":"Abstract-only. Binding was detected only under shear; the paper notes earlier reports of no interaction. No affinity reported.","key_references":[{"PMID":"22234691","why":"macrophage LRP1 and shear-dependent VWF binding"}],"covers":["LR003457","LR006657"]},"LR006661":{"pair":"WFIKKN2 -> IGDCC4","headline":"WFIKKN2 is reported as a secreted axon-guidance ligand acting through IGDCC4 (Nope); evidence is a preprint abstract only.","interaction_type":"functional only","direction_and_effect":"WFIKKN2 guides mouse peripheral sensory axons through Nope-mediated repulsion, whereas its attraction of motor axons does not use Nope [PMID:37398498]. The curator labelled the effect as antagonist.","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Mouse axon-guidance experiments are described in the abstract; the dossier lists human proteins [PMID:37398498].","localisation_and_range":"WFIKKN2 is flagged secreted [flag]; the receptor is flagged as a receptor [flag].","caveats":"No direct binding assay for this pair in our evidence. Only one paper, a bioRxiv preprint read as abstract only [PMID:37398498]. Other judged rows were abstract_insufficient.","key_references":[{"PMID":"37398498","why":"WFIKKN2 repels sensory axons via Nope (abstract only)"}],"covers":["LR003461","LR006661"]},"LR005356":{"pair":"WNT1 -> FZD10","headline":"FZD10 is reported as a WNT1 receptor in chick spinal cord, with a proximity-ligation interaction and LRP6-dependent signalling.","interaction_type":"direct binding","direction_and_effect":"In HEK293T cells FZD10 with LRP6 increased WNT1 signalling in an 8xSuperTopFlash assay, and proximity ligation showed an FZD10-WNT1 interaction [PMID:24599775].","molecular_requirements":"LRP6 co-expression was needed for FZD10 to promote WNT1 signalling; FZD10 alone with WNT1 inhibited signalling. PLA punctae formed with or without exogenous LRP6 [PMID:24599775].","affinity_potency":[],"species_and_systems":"Chick embryo spinal cord expression; reporter assay in HEK293T and PLA in transfected COS7 cells [PMID:24599775]. Human and mouse pairs are ortholog-inferred.","localisation_and_range":"WNT1 is flagged secreted and non-transmembrane [flag]; the receptor is flagged as a receptor [flag], so signalling is presumably paracrine, but range is not reported in our evidence.","caveats":"Interaction shown by proximity within 40 nm, not purified-protein binding. Overexpressed FZD10 alone inhibited WNT1 signalling [PMID:24599775].","key_references":[{"PMID":"24599775","why":"FZD10 as WNT1 receptor: PLA and LRP6-dependent reporter"}],"covers":["LR002030","LR005356"]},"LR008137":{"pair":"WNT1 -> FZD4:LRP5","headline":"WNT1 to FZD4:LRP5 has no verified evidence; only a UniProt note on LRP5.","interaction_type":"database-asserted only","direction_and_effect":"Not reported in our evidence.","molecular_requirements":"UniProt notes an LRP5 interaction enhanced by WNT1 or WNT3A [DB:UniProt]; FZD4 is not mentioned.","affinity_potency":[],"species_and_systems":"Not reported in our evidence.","localisation_and_range":"WNT1 is flagged secreted and non-transmembrane [flag]; the receptor is flagged as a receptor [flag], so signalling is presumably paracrine, but range is not reported in our evidence.","caveats":"No verified paper; six rows were abstract_insufficient and one review_only.","key_references":[],"covers":["LR008137"]},"LR008164":{"pair":"WNT1 -> FZD7:LRP5","headline":"WNT1 signals through FZD7 in a rescue assay; the LRP5 part of this complex is not tested.","interaction_type":"functional only","direction_and_effect":"FZD7 expression rescued Wnt1-dependent TCF4/Wnt reporter activity in FZD-knockout HEK293T cells [PMID:28733458].","molecular_requirements":"Only FZD7 was tested in the paper; LRP5 is not reported in our evidence for this paper. UniProt describes an LRP5 subunit interaction enhanced in the presence of GSK3B and WNT1 or WNT3A [DB:UniProt]. A CCC tool scoring this complex needs both FZD7 and LRP5 expressed.","affinity_potency":[],"species_and_systems":"Human HEK293T cells [PMID:28733458].","localisation_and_range":"WNT1 is flagged as secreted [flag], so signalling would be paracrine or autocrine; this comes from the annotation flag, not from a paper.","caveats":"The complex is supported only by its FZD7 member; LRP5 contribution rests on a database note.","key_references":[{"PMID":"28733458","why":"Wnt1 rescue by FZD7"}],"covers":["LR008164"]},"LR001576":{"pair":"WNT1 -> FZD8","headline":"WNT1 signals via FZD8 in a human reporter-cell knockout panel; BioGRID lists a reconstituted complex.","interaction_type":"functional only","direction_and_effect":"Wnt1, Wnt8a, Wnt7b, Wnt8b and Wnt10a induced signalling via FZD5 and FZD8 in an FZD knockout panel, a stimulatory effect on TCF reporter signalling [PMID:28733458]. BioGRID lists a WNT1-FZD8 reconstituted complex [DB:BioGRID].","molecular_requirements":"FZD8 and FZD5 were both responsive; FZD8 is not unique. Co-receptors not reported in our evidence.","affinity_potency":[],"species_and_systems":"Human HEK293 reporter cells with multiplex CRISPR FZD knockouts, full text [PMID:28733458]. The mouse pair is projected from human.","localisation_and_range":"WNT1 is flagged as secreted [flag], so signalling would be paracrine or autocrine; this comes from the annotation flag, not from a paper.","caveats":"The curator's sentence summarises the paper's interaction map; it is not a binding assay. Two further papers were abstract_insufficient or pending.","key_references":[{"PMID":"28733458","why":"Functional Wnt-FZD interaction map"}],"covers":["LR001576","LR004965"]},"LR008092":{"pair":"WNT1 -> FZD8:LRP6","headline":"Database-asserted only: WNT1 with FZD8:LRP6, no curated paper.","interaction_type":"database-asserted only","direction_and_effect":"No paper evidence. BioGRID lists LRP6-WNT1 and WNT1-FZD8 reconstituted complexes [DB:BioGRID]. UniProt notes LRP6 interacts via its extracellular domain with WNT1 [DB:UniProt].","molecular_requirements":"The two subunits are supported separately by pairwise records, not as a combined receptor. Reactome complexes cited involve Frizzled1, not FZD8 [DB:Reactome].","affinity_potency":[],"species_and_systems":"System of the records not reported in our evidence.","localisation_and_range":"WNT1 is flagged as secreted [flag], so signalling would be paracrine or autocrine; this comes from the annotation flag, not from a paper.","caveats":"Database-only; no curator-verified paper.","key_references":[],"covers":["LR008092"]},"LR008173":{"pair":"WNT10A -> FZD8:LRP5","headline":"Complex-level pair with no curated paper; rests on one IntAct co-immunoprecipitation record only.","interaction_type":"database-asserted only","direction_and_effect":"Direction and effect (agonist or antagonist) not reported in our evidence. The only support is an IntAct record of association by anti-tag coimmunoprecipitation [DB:IntAct EBI-54877040].","molecular_requirements":"Receptor is listed as a two-chain complex; whether both chains, or either alone, are required is not reported in our evidence. ","affinity_potency":[],"species_and_systems":"Pair is human; the experimental system of the IntAct record is not reported in our evidence.","localisation_and_range":"Ligand is flagged secreted [flag]; the receptor chains are flagged as receptors, with LRP chain transmembrane [flag]. Range is not otherwise reported in our evidence.","caveats":"Only the database record supports this pair; one abstract was judged insufficient and no paper is confirmed. Whether WNT10A binding was tested directly is not reported in our evidence.","key_references":[],"covers":["LR008173"]},"LR003466":{"pair":"WNT10B -> FZD4","headline":"Functional evidence from an abstract: WNT-10B stimulation dissociated a FZD4-G protein complex in live human cells.","interaction_type":"functional only","direction_and_effect":"The FZD4-Galpha12/13 complex dissociates upon stimulation with WNT-3A, WNT-5A, WNT-7A and WNT-10B, so WNT10B acts on FZD4 as an activating ligand in this readout [PMID:27458145].","molecular_requirements":"FZD4 assembles with Galpha12/13 in a DVL-independent manner, not with Galphai1, Galphao, Galphas or Galphaq; LRP involvement not reported in our evidence [PMID:27458145].","affinity_potency":[],"species_and_systems":"Live-cell FRAP imaging in HEK293 cells with human FZD4 [PMID:27458145]; mouse pair is ortholog-inferred.","localisation_and_range":"Ligand flagged secreted [flag]; range not otherwise reported.","caveats":"Indirect readout of receptor engagement, no binding measurement. Abstract only was read. Several other WNTs gave the same effect, so this is not specific to WNT10B.","key_references":[{"PMID":"27458145","why":"WNT-10B dissociates the FZD4-Galpha12/13 complex in live cells"}],"covers":["LR003466","LR006666"]},"LR006670":{"pair":"WNT10B -> LRP6","headline":"WNT10B acting through LRP6 is supported by co-culture IP and antibody-blocking assays; the binding evidence is indirect.","interaction_type":"functional only","direction_and_effect":"An anti-LRP6 antibody class that binds LRP6 propeller 1 blocked signalling by a group of Wnts including Wnt10b in a reporter assay [PMID:20713706]. SMOC-2 enhanced Wnt10b-LRP6 interaction in co-culture IP, with agonist direction annotated [PMID:30594556].","molecular_requirements":"LRP6 is treated as a Wnt co-receptor; Wnt10b is in the class inhibited by propeller-1 antibodies [PMID:20713706]. Whether Wnt10b binds LRP6 alone is not reported in our evidence.","affinity_potency":[],"species_and_systems":"Human HEK293 and HEK293T cells (recombinant, tagged proteins); the mouse pair is projected from human evidence. Both papers were read as abstract only or by browser, not as stored text.","localisation_and_range":"Ligand is flagged secreted and LRP6 transmembrane [flag]; signalling is likely paracrine to a cell-surface receptor.","caveats":"Neither paper shows a Wnt10b-LRP6 binding measurement alone: the first shows SMOC-2-dependent enhancement, the second blockade by antibodies. No affinity reported.","key_references":[{"PMID":"20713706","why":"Wnt10b among Wnts blocked by Wnt1-class anti-LRP6 Fabs (SuperTopFlash, HEK293)"},{"PMID":"30594556","why":"Co-culture IP: SMOC-2 enhanced Wnt10b-LRP6 interaction"}],"covers":["LR003470","LR006670"]},"LR004960":{"pair":"WNT11 -> FZD7","headline":"WNT11 binds FZD7 by co-IP in Xenopus and a 2026 CRC paper reports direct interaction; both are supported mainly by abstract-level reads.","interaction_type":"direct binding","direction_and_effect":"Myc-tagged Xwnt11 co-immunoprecipitated with the extracellular domain of Xfz7 and Xfz7 recruited Xwnt11 to the plasma membrane; overexpression affected convergent extension [PMID:10862746]. A colorectal cancer paper states Wnt11 directly interacts with FZD7 to activate PCP/ROCK signalling and YAP [PMID:42760160].","molecular_requirements":"The Xenopus co-IP used the extra-cellular (secreted) form of Xfz7, so the receptor ectodomain suffices for binding there [PMID:10862746]. No co-receptor requirement reported.","affinity_potency":[],"species_and_systems":"Xenopus laevis embryos with Xenopus orthologs [PMID:10862746]; human colorectal cancer cells [PMID:42760160]. Human and mouse pairs are ortholog-inferred.","localisation_and_range":"Ligand flagged secreted [flag]; Reactome lists WNT:FZD at the plasma membrane [DB:Reactome].","caveats":"The binding quote for 10862746 was browser-read and not spot-checked; the abstract-only CRC paper's method for 'direct' interaction is not stated. No affinity.","key_references":[{"PMID":"10862746","why":"Xwnt11 co-IPs with Xfz7 ectodomain; functional interaction in Xenopus"},{"PMID":"42760160","why":"Wnt11 reported to interact directly with FZD7 in CRC cells"}],"covers":["LR001571","LR004960"]},"LR003475":{"pair":"WNT11 -> MUSK","headline":"WNT11 is reported to bind the MuSK extracellular domain directly, based on an abstract-level read.","interaction_type":"direct binding","direction_and_effect":"Wnt11 binds the extracellular domain of MuSK, inducing MuSK dimerization and tyrosine phosphorylation; Wnt11 induced acetylcholine receptor clustering (agonist) [PMID:22309736].","molecular_requirements":"Wnt-induced AChR clustering requires LRP4, so LRP4 acts alongside MuSK [PMID:22309736].","affinity_potency":[],"species_and_systems":"Mammalian Wnts screened for AChR clustering in muscle cells; the dossier labels species as human, and the mouse pair is not ortholog-inferred [PMID:22309736].","localisation_and_range":"Wnt11 is flagged secreted [flag]; it is expressed in developing muscle [PMID:22309736].","caveats":"Abstract only; the binding assay and cell type are not reported in our evidence. Wnt11 effect was non-additive with agrin. No affinity.","key_references":[{"PMID":"22309736","why":"Wnt9a and Wnt11 bind MuSK ectodomain, require LRP4"}],"covers":["LR003475","LR006675"]},"LR005365":{"pair":"WNT16 -> LRP5","headline":"WNT16 acting via LRP5 is supported by knockdown in human osteoblast-like cells; no direct binding data.","interaction_type":"functional only","direction_and_effect":"IL-1beta raised Wnt16 and Lrp5/Fzd2; exogenous Wnt16 increased MMP-13 and proliferation, and siRNAs against Wnt16 and Lrp5 suppressed the IL-1beta-induced proliferation (agonist annotated) [PMID:26861315].","molecular_requirements":"Lrp5 was inferred together with Fzd2 as the Wnt receptor; whether LRP5 alone suffices is not reported in our evidence [PMID:26861315].","affinity_potency":[],"species_and_systems":"Human skeletal muscle stem cell-derived osteoblast-like cells, abstract only [PMID:26861315]. Mouse pair is not ortholog-inferred.","localisation_and_range":"Wnt16 flagged secreted and LRP5 transmembrane [flag].","caveats":"Knockdown cannot separate LRP5 binding from pathway effects. No affinity.","key_references":[{"PMID":"26861315","why":"IL-1beta to Wnt16 to Lrp5 to MMP-13 axis; siRNA rescue"}],"covers":["LR002039","LR005365"]},"LR010657":{"pair":"WNT2 -> FZD7","headline":"WNT2 to FZD7 is supported only by an in silico docking and dynamics study.","interaction_type":"functional only","direction_and_effect":"Homology modelling, docking and MD simulations suggest an interaction mode of Wnt2 with the Fzd7 cysteine-rich domain [PMID:30191337].","molecular_requirements":"The model involves the Fzd7 cysteine-rich domain; electrostatic and hydrophobic interactions dominate binding energy [PMID:30191337].","affinity_potency":[],"species_and_systems":"Purely computational, no cells or animals [PMID:30191337].","localisation_and_range":"Wnt2 flagged secreted [flag].","caveats":"No experimental binding or signalling data in our evidence; one other row abstract_insufficient, one different_entity.","key_references":[{"PMID":"30191337","why":"Docking and MD of Wnt2 with Fzd7 CRD"}],"covers":["LR010657"]},"LR008065":{"pair":"WNT2B -> FZD4:LRP6","headline":"No paper evidence; rests on UniProt notes about the WNT2B-FZD4 interaction.","interaction_type":"database-asserted only","direction_and_effect":"UniProt notes that TSKU competes with WNT2B for binding to FZD4, inhibiting Wnt signalling [DB:UniProt].","molecular_requirements":"Nothing reported on the complex or on LRP6 in our evidence.","affinity_potency":[],"species_and_systems":"Species not stated; UniProt accession Q61088 is cited [DB:UniProt].","localisation_and_range":"WNT2B is annotated as secreted [flag].","caveats":"No curator-verified paper; only database text, and it concerns TSKU competition, not LRP6 [DB:UniProt].","key_references":[],"covers":["LR008065"]},"LR011269":{"pair":"WNT2B -> FZD5:LRP5","headline":"No paper evidence; UniProt notes FZD5 interacts with WNT2B.","interaction_type":"database-asserted only","direction_and_effect":"UniProt states that FZD5 interacts with WNT2B [DB:UniProt].","molecular_requirements":"Nothing reported on LRP5 or the complex in our evidence.","affinity_potency":[],"species_and_systems":"Species not stated [DB:UniProt].","localisation_and_range":"WNT2B is annotated as secreted [flag].","caveats":"Database assertion only, with no verified paper; it supports the FZD5 subunit, not the LRP5 complex [DB:UniProt].","key_references":[],"covers":["LR011269"]},"LR003484":{"pair":"WNT3 -> FZD10","headline":"Functional: Wnt3/Wnt3a signalled via all FZDs in HEK293T rescue assays; six other papers were abstract-insufficient.","interaction_type":"functional only","direction_and_effect":"Wnt3/Wnt3a induced signalling via all FZDs, unlike more selective Wnts [PMID:28733458].","molecular_requirements":"Tested by rescuing FZD-mutant HEK293T cells; FZD10 clusters with FZD4 in the reported map [PMID:28733458].","affinity_potency":[],"species_and_systems":"Human HEK293T CRISPR mutant cells with TCF4/Wnt luciferase [PMID:28733458].","localisation_and_range":"Localisation not reported in our evidence.","caveats":"Broad, non-selective result across all FZDs; no direct binding shown for FZD10. Six judged papers were abstract_insufficient and are not used.","key_references":[{"PMID":"28733458","why":"Wnt3/3a signal through all FZDs in rescue assay"}],"covers":["LR003484","LR006684"]},"LR008128":{"pair":"WNT3 -> FZD2:LRP5","headline":"Functional Wnt3-FZD2 signalling in HEK293T is supported, but nothing in our evidence tests the FZD2:LRP5 complex itself.","interaction_type":"functional only","direction_and_effect":"The single curated paper reports that FZD1, FZD2 and FZD7 \"specifically induce signaling after binding of Wnt3 and Wnt3a\" [PMID:28733458]; this is a statement in the Discussion, and the paper's tested readout was TCF4/Wnt reporter signalling.","molecular_requirements":"FZD2 is the evidence-bearing subunit; the paper's excerpts do not test LRP5 as a partner, so whether the full complex or FZD2 alone is needed is not reported in our evidence.","affinity_potency":[],"species_and_systems":"Human ligand and receptor; HEK293T cells with CRISPR FZD mutations [PMID:28733458].","localisation_and_range":"WNT3 carries a secreted annotation flag [flag], so it acts as a secreted ligand; range is not reported in our evidence.","caveats":"Complex-level support is inferred from a single-chain Frizzled result; the paper is a functional map, not a binding study.","key_references":[{"PMID":"28733458","why":"Functional Wnt-FZD map in FZD-mutant HEK293T cells"}],"covers":["LR008128"]},"LR010738":{"pair":"WNT3 -> FZD3:LRP6","headline":"No curated paper supports WNT3 -> FZD3:LRP6; the only record is a database interaction entry.","interaction_type":"database-asserted only","direction_and_effect":"Direction and effect are not reported in our evidence.","molecular_requirements":"Not reported in our evidence beyond the complex name.","affinity_potency":[],"species_and_systems":"Species of the database experiment not reported in our evidence; the pair is annotated human.","localisation_and_range":"Ligand is flagged secreted [flag]; range not reported in our evidence.","caveats":"No paper was confirmed for this pair (outcomes: review_only, abstract_insufficient, different_entity). The one IntAct record is a surface plasmon resonance entry for accession pair O75581-P56703 [DB:IntAct] and does not identify the Frizzled member [PMID:31036956].","key_references":[],"covers":["LR010738"]},"LR001594":{"pair":"WNT3 -> FZD5","headline":"Wnt3 induced signalling through FZD5 in a human cell reporter screen, a generic functional result; mouse pair is projected.","interaction_type":"functional only","direction_and_effect":"Agonist-type signalling: the paper states \"Wnt3/Wnt3a induced signaling via all FZDs, in contrast to other Wnts that were more selective\" [PMID:28733458]. Our annotation lists a stimulatory modulatory effect for this pair.","molecular_requirements":"Co-receptor and subunit requirements are not reported in our evidence.","affinity_potency":[],"species_and_systems":"HEK293T FZD1,2,7 (and FZD1,2,4,5,7,8) CRISPR-mutant cells, TCF4/Wnt luciferase [PMID:28733458]; mouse pair is ortholog-inferred.","localisation_and_range":"Ligand is flagged secreted [flag]; range not reported in our evidence.","caveats":"The sentence is generic across FZDs; specifics sit in a figure matrix not in the dossier. Functional rescue only, no binding. Many other papers were abstract_insufficient.","key_references":[{"PMID":"28733458","why":"Wnt-FZD rescue map in CRISPR FZD-mutant HEK293T cells"}],"covers":["LR001594","LR004983"]},"LR010693":{"pair":"WNT3 -> FZD9:LRP6","headline":"No curated paper supports WNT3 -> FZD9:LRP6; the only record is a database interaction entry.","interaction_type":"database-asserted only","direction_and_effect":"Direction and effect are not reported in our evidence.","molecular_requirements":"Not reported in our evidence beyond the complex name.","affinity_potency":[],"species_and_systems":"Species of the database experiment not reported in our evidence; the pair is annotated human.","localisation_and_range":"Ligand is flagged secreted [flag]; range not reported in our evidence.","caveats":"No paper was confirmed for this pair (outcomes: review_only, abstract_insufficient, different_entity). The one IntAct record is a surface plasmon resonance entry for accession pair O75581-P56703 [DB:IntAct] and does not identify the Frizzled member [PMID:31036956].","key_references":[],"covers":["LR010693"]},"LR001585":{"pair":"WNT3A -> FZD1","headline":"Supported by co-IP, binding-affinity mapping and functional rescue studies; WNT3A activates canonical signalling through FZD1.","interaction_type":"direct binding","direction_and_effect":"WNT3A activates canonical beta-catenin signalling: Hfz1 enhanced WNT3A-induced TCF-dependent transcription in a dose-dependent way [PMID:10557084]. Curators label it agonist, and a CRISPR rescue map shows WNT3A signals through a broad spectrum of FZDs [PMID:28733458].","molecular_requirements":"Truncating the Hfz1 carboxy terminus markedly reduced its capacity to enhance Wnt signalling [PMID:10557084]. The FZD cysteine-rich domain is described as required for Wnt binding [PMID:28733458]. Co-receptor need for FZD1 specifically is not reported in our evidence.","affinity_potency":[],"species_and_systems":"Human Hfz1 co-immunoprecipitated with Wnt-3a in transfected cells [PMID:10557084]; bio-layer interferometry with purified WNTs and FZD cysteine-rich domains in a separate study [PMID:25605717]; multiplex FZD1/FZD2/FZD7 mutant HEK293T cells [PMID:28733458]. BioGRID records Affinity Capture-Western [DB:BioGRID].","localisation_and_range":"WNT3A is flagged secreted and not transmembrane [flag], so signalling is expected to be paracrine or autocrine; range is not measured in our evidence.","caveats":"All three papers were read as abstracts (the third has full-text excerpts that concern FZD1 only as a targeted gene). Wnt-5a also co-precipitated with Hfz1 without TCF signalling, so binding alone does not predict activation [PMID:10557084]. No affinity value is given for FZD1 in our abstracts.","key_references":[{"PMID":"10557084","why":"Hfz1 co-IP with Wnt-3a and TCF signalling enhancement"},{"PMID":"25605717","why":"bio-layer interferometry WNT-FZD binding map"},{"PMID":"28733458","why":"CRISPR FZD rescue map of Wnt ligands"}],"covers":["LR001585","LR004974"]},"LR008119":{"pair":"WNT3A -> FZD1:LRP5","headline":"No curated paper confirms this complex; support is limited to database records.","interaction_type":"database-asserted only","direction_and_effect":"Direction and effect are not reported in our evidence for this complex.","molecular_requirements":"Receptor is a complex of FZD1 and LRP5.; whether both chains are needed is not reported in our evidence.","affinity_potency":[],"species_and_systems":"No experiments in our verified evidence. BioGRID lists WNT3A-FZD1 Affinity Capture-Western [DB:BioGRID] [PMID:10557084]; UniProt says FZD1 is activated by WNT3A, WNT3 and WNT1 [DB:UniProt] [PMID:10557084].","localisation_and_range":"WNT3A is flagged secreted and not transmembrane [flag], so signalling is expected to be paracrine or autocrine; range is not measured in our evidence.","caveats":"The FZD1 record covers the FZD1 chain only; LRP5 involvement is not shown. Only review articles or abstracts too thin to judge were found (outcome counts show review_only and abstract_insufficient), so no primary evidence is verified.","key_references":[],"covers":["LR008119"]},"LR008056":{"pair":"WNT3A -> FZD3:LRP6","headline":"No curated paper confirms this complex; support is limited to database records.","interaction_type":"database-asserted only","direction_and_effect":"Direction and effect are not reported in our evidence for this complex.","molecular_requirements":"Receptor is a complex of FZD3 and LRP6.; whether both chains are needed is not reported in our evidence.","affinity_potency":[],"species_and_systems":"No experiments in our verified evidence. BioGRID lists LRP6-WNT3A Affinity Capture-Western [DB:BioGRID] [PMID:19910923]; IntAct lists co-immunoprecipitation and bio-layer interferometry records [DB:IntAct] [PMID:22726442] [PMID:21944579]; Reactome has a WNT3A:FZD:LRP5/6 complex [DB:Reactome].","localisation_and_range":"WNT3A is flagged secreted and not transmembrane [flag], so signalling is expected to be paracrine or autocrine; range is not measured in our evidence.","caveats":"These records concern LRP6 and WNT3A, not FZD3. Only review articles or abstracts too thin to judge were found (outcome counts show review_only and abstract_insufficient), so no primary evidence is verified.","key_references":[],"covers":["LR008056"]},"LR003493":{"pair":"WNT3A -> GPC5","headline":"GPC5 is reported to bind Wnt3a at the cell surface and suppress Wnt/beta-catenin signalling; evidence is a single abstract-only paper.","interaction_type":"functional only","direction_and_effect":"GPC5 suppresses Wnt/beta-catenin signalling by binding Wnt3a at the cell surface, acting as an antagonist or sequestering decoy [PMID:27157618].","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Lung adenocarcinoma cells and tissue, human; in vivo tumour growth reported [PMID:27157618]. Mouse version projected from human.","localisation_and_range":"Both partners are flagged secreted [flag]; the paper places the binding at the cell surface [PMID:27157618].","caveats":"Read as abstract only; the binding assay is not described in our evidence, no affinity given. No database records.","key_references":[{"PMID":"27157618","why":"GPC5 binds Wnt3a and suppresses Wnt signalling in lung adenocarcinoma"}],"covers":["LR003493","LR006693"]},"LR007642":{"pair":"WNT3A -> SFRP1","headline":"Only Reactome complex records support WNT3A:sFRP; the curated paper pool has no verified paper for SFRP1.","interaction_type":"database-asserted only","direction_and_effect":"Annotated as inhibitory ligand-ligand interaction: sFRP binds Wnt, a decoy that blocks receptor engagement [DB:Reactome].","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Not reported in our evidence beyond Reactome records.","localisation_and_range":"Both are secreted proteins [flag]; Reactome places the complex in the extracellular region [DB:Reactome].","caveats":"No curator-verified paper; one row was review-only. The Reactome complex is the generic 'WNT3A:sFRP' record, not specific to one sFRP. This is a ligand-ligand pair, not a receptor.","key_references":[],"covers":["LR007642"]},"LR008083":{"pair":"WNT5A -> FZD6:LRP6","headline":"No paper evidence for WNT5A with the FZD6:LRP6 complex; database records only.","interaction_type":"database-asserted only","direction_and_effect":"Not reported in our evidence. BioGRID records LRP6 - WNT5A Affinity Capture-Western [DB:BioGRID]; GtoPdb lists WNT5A-FZD6 as agonist [DB:GtoPdb].","molecular_requirements":"Not reported in our evidence; records concern individual chains.","affinity_potency":[],"species_and_systems":"Not reported in our evidence.","localisation_and_range":"WNT5A is flagged secreted and not transmembrane [flag], so signalling would be paracrine or autocrine by this annotation.","caveats":"Rests on database records alone; the judged papers were review-only.","key_references":[],"covers":["LR008083"]},"LR006706":{"pair":"WNT5A -> LRP6","headline":"Physical interaction reported, but non-productive: Lrp6 binds Wnt5a without signalling and acts as an inhibitor of noncanonical Wnt5a signalling.","interaction_type":"direct binding","direction_and_effect":"Lrp6 physically interacts with Wnt5a without Lrp6 phosphorylation or Wnt/beta-catenin activation; Lrp6 overexpression blocks activation of Rac1, a Wnt5a target, and Lrp6-/- mouse defects were rescued by Wnt5a deletion [PMID:19056682]. Curated as antagonist.","molecular_requirements":"Effect depends on intact Lrp6 extracellular domains [PMID:19056682].","affinity_potency":[],"species_and_systems":"Mouse knockouts and Xenopus morphants plus in vitro cells [PMID:19056682]. BioGRID records an affinity capture-Western [DB:BioGRID 692083].","localisation_and_range":"Ligand flagged secreted, LRP6 transmembrane [flag].","caveats":"Abstract only; interaction method and affinity not reported in our evidence. Acts as a sequestering inhibitor, not an activating receptor, so treat as antagonist/decoy-like.","key_references":[{"PMID":"19056682","why":"Lrp6 binds Wnt5a and inhibits noncanonical signalling in mouse and Xenopus"}],"covers":["LR003506","LR006706"]},"LR008038":{"pair":"WNT5B -> FZD1:LRP6","headline":"No verified paper supports this WNT5B complex; the only database line says FZD1 is apparently not activated by WNT5B.","interaction_type":"database-asserted only","direction_and_effect":"Direction and effect not reported in our evidence. UniProt says FZD1 is apparently not activated by WNT5B (nor WNT5A, WNT4, WNT6) [DB:UniProt].","molecular_requirements":"Annotated as FZD1 plus LRP6; no evidence on which subunits are required.","affinity_potency":[],"species_and_systems":"Not reported in our evidence.","localisation_and_range":"Ligand is annotated as secreted [flag], so paracrine or endocrine range is implied by the annotation only.","caveats":"Papers read were review-only or abstract-insufficient, none confirmed. The sole database record is a negative statement for FZD1 [DB:UniProt].","key_references":[],"covers":["LR008038"]},"LR006715":{"pair":"WNT5B -> FZD7","headline":"WNT5B appears to bind the FZD7 CRD only weakly in a single BLI mapping study.","interaction_type":"direct binding","direction_and_effect":"Binding only: WNT-5B showed weak binding (KD > 40 nm) to the listed CRDs, which appear to include FZD7 [PMID:25605717].","molecular_requirements":"CRD only; co-receptors not reported in our evidence.","affinity_potency":[{"value":"KD > 40 nm","assay":"bio-layer interferometry, FZD CRD-Fc","system":"purified mouse proteins","cite":"PMID:25605717"}],"species_and_systems":"Mouse proteins (purified WNT binding to FZD CRD-Fc), bio-layer interferometry [PMID:25605717]; human pair is ortholog-inferred.","localisation_and_range":"Ligand is annotated as secreted [flag], so paracrine or endocrine range is implied by the annotation only.","caveats":"Binding only; Wnt5b was not shown to activate signalling in this paper (the abstract reports WNT-3A but not WNT-5A as the activator in 32D cells) [PMID:25605717]. Only the abstract was curated, with excerpts from a browser read. The sentence names FZD7 only for WNT-5A; the WNT-5B statement says 'these' CRDs.","key_references":[{"PMID":"25605717","why":"BLI mapping of WNT-FZD CRD binding"}],"covers":["LR003515","LR006715"]},"LR005374":{"pair":"WNT6 -> FZD7","headline":"FZD7 is a putative Wnt6 receptor from co-expression and canonical signalling; weak, abstract-level evidence.","interaction_type":"functional only","direction_and_effect":"Agonist: Wnt6 signals through the canonical pathway in renal epithelial cells; FzD7 was identified as a putative receptor [PMID:27122540].","molecular_requirements":"Canonical beta-catenin/TCF-Lef signalling; no binding or subunit data [PMID:27122540].","affinity_potency":[],"species_and_systems":"Mouse developing kidney (mesonephros), human renal biopsies, renal epithelial cells in 3D culture [PMID:27122540].","localisation_and_range":"Ligand is annotated as secreted [flag], so paracrine or endocrine range is implied by the annotation only.","caveats":"'Putative' receptor; no direct binding assay is described. Abstract only [PMID:27122540].","key_references":[{"PMID":"27122540","why":"Wnt6 canonical signalling with putative FzD7 receptor in renal epithelium"}],"covers":["LR002048","LR005374"]},"LR007750":{"pair":"WNT6 -> SFRP2","headline":"SFRP2 reported to bind Wnt6 and inhibit its canonical signalling in one abstract-only study; ligand-ligand pair, not a receptor.","interaction_type":"direct binding","direction_and_effect":"Sfrp2 binding to Wnt6 and inhibition of the Wnt6 canonical pathway was reported as essential for inhibiting cardiac progenitor cell proliferation [PMID:26071893]. SFRP2 acts as an inhibitor (modulatory effect Inhibitory in the dossier).","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Mouse cardiac progenitor cells (isolated from FVB mice) [PMID:26071893]; the human pair is the dossier's primary species.","localisation_and_range":"Both partners are flagged secreted and non-receptor/non-transmembrane [flag]; extracellular decoy-type interaction.","caveats":"Binding is asserted in the abstract only; the full-text excerpts shown are methods and background and give no binding data. One paper.","key_references":[{"PMID":"26071893","why":"Sfrp2 binds Wnt6 and inhibits its canonical pathway in cardiac progenitors"}],"covers":["LR007750"]},"LR006724":{"pair":"WNT7A -> LRP5","headline":"WNT7A binds recombinant LRP5 ECD in HEK293 conditioned medium; one full-text paper.","interaction_type":"direct binding","direction_and_effect":"Recombinant LRP5 ECD bound WNT7A in conditioned medium from WNT7A-expressing HEK293 RECK-/- cells; DKK1, an LRP5/6 antagonist, dose-dependently inhibited RECK/GPR124/WNT7 signalling [PMID:30304675].","molecular_requirements":"LRP5/6 act with FZD and RECK/GPR124 in WNT7 canonical signalling [PMID:30304675].","affinity_potency":[],"species_and_systems":"Human proteins, HEK293 RECK-/- cells [PMID:30304675]. Mouse pair is ortholog-inferred.","localisation_and_range":"Ligand is flagged secreted and non-transmembrane [flag], so paracrine or autocrine action is expected; the paper's own data on range are not reported in our evidence. Receptor is flagged transmembrane [flag].","caveats":"Single paper; no affinity reported. Active WNT7A is short-lived in medium [PMID:30304675]. The curated evidence sentence concerns FZD4 with LRP5 co-transfection, not LRP5 binding.","key_references":[{"PMID":"30304675","why":"LRP5 and LRP6 ECDs bound WNT7A"}],"covers":["LR003524","LR006724"]},"LR003529":{"pair":"WNT7B -> LRP6","headline":"WNT7B is blocked by anti-LRP6 antibodies, implying LRP6 involvement; no direct binding data.","interaction_type":"functional only","direction_and_effect":"Wnt7b signalling was among those inhibited by Wnt1-class anti-LRP6 Fab fragments (A1-Fab, A2-Fab) [PMID:20713706].","molecular_requirements":"LRP6 first propeller is implicated; Wnt1-class antibodies bind it [PMID:20713706]. Frizzled requirement is not reported in our evidence.","affinity_potency":[],"species_and_systems":"Human ligand and receptor; SuperTopFlash reporter in HEK293 cells [PMID:20713706]. The mouse pair is projected from human.","localisation_and_range":"WNT ligand is flagged secreted and not transmembrane [flag], so signalling would be paracrine or autocrine; no paper in our evidence measured range.","caveats":"Antibody blockade shows pathway dependence, not direct Wnt7b-LRP6 binding. Curator read of the full text was done in a browser with the quote unverified (spot-check pending); the abstract in the dossier is truncated.","key_references":[{"PMID":"20713706","why":"Anti-LRP6 Fabs inhibit Wnt1-class signalling including Wnt7b"}],"covers":["LR003529","LR006729"]},"LR006733":{"pair":"WNT8A -> ROR2","headline":"WNT8A activates ROR2 per one abstract on cytoneme-based Wnt transport; evidence is functional.","interaction_type":"functional only","direction_and_effect":"Upon Wnt8a binding, the receptor tyrosine kinase Ror2 becomes activated, leading to Ror2/PCP signalling that induces cytonemes transporting Wnt8a to neighbouring cells (agonist) [PMID:30060804].","molecular_requirements":"Ror2 alone is described; co-receptors are not reported in our evidence.","affinity_potency":[],"species_and_systems":"Zebrafish development, murine intestinal crypt and human cancer organoids [PMID:30060804]. The dossier labels the pair human, with the human and mouse entries projected from this evidence.","localisation_and_range":"Wnt8a is carried on cytonemes to neighbouring cells, giving contact-dependent paracrine delivery [PMID:30060804]; ligand also flagged secreted [flag].","caveats":"Abstract only. The 'binding' statement is part of a mechanism narrative; no binding assay or affinity is described. The only excerpt is a methods passage.","key_references":[{"PMID":"30060804","why":"Ror2 activation by Wnt8a drives cytoneme Wnt transport"}],"covers":["LR003533","LR006733"]},"LR008182":{"pair":"WNT9A -> EGFR:FZD9:LRP5","headline":"WNT9A signals through FZD9, LRP5/6 and EGFR with EGFR-dependent endocytosis; functional evidence from one paper, read as abstract only.","interaction_type":"functional only","direction_and_effect":"Wnt9a signals through Fzd9b, LRP5/6 and EGFR; EGFR-dependent endocytosis of the ligand-receptor complex was required for signalling [PMID:38626007].","molecular_requirements":"LRP5/6 and AXIN were required for Wnt9a-Fzd9b signalling but not for endocytosis; EGFR-mediated phosphorylation of the Fzd9b tail, caveolin and EPS15 were required for endocytosis [PMID:38626007]. The paper states EGFR is an obligate co-factor and was colocalised with Wnt9a-Fzd9b endosomes (excerpts, citing prior work for the obligate-cofactor point) [PMID:38626007].","affinity_potency":[],"species_and_systems":"Fluorescently labelled Wnt9a and Fzd9b fusion proteins in human cells (HEK293 EGFR knockout cells used); EPS15 loss impaired haematopoietic stem cell development in zebrafish [PMID:38626007].","localisation_and_range":"Secreted ligand per the entity annotation flag [flag]; paracrine range is inferred from that flag only, not reported in the papers.","caveats":"Curated as abstract-only. Subunit requirements are functional; which LRP (5 or 6) is used is not resolved here. One further judged row was abstract_insufficient.","key_references":[{"PMID":"38626007","why":"Endocytosis of Wnt9a-Fzd9b requires EGFR; LRP5/6 needed for signalling."}],"covers":["LR008182"]},"LR008047":{"pair":"WNT9A -> FZD10:LRP6","headline":"WNT9A signals through FZD10 in a reporter-cell rescue map; functional evidence from one paper, no binding data.","interaction_type":"functional only","direction_and_effect":"WNT9A signalled only via FZD4 and FZD10 among the FZDs tested, inducing canonical reporter signalling (agonism) [PMID:28733458].","molecular_requirements":"The receptor is listed as FZD10 plus LRP6; the paper's statement names only the Frizzled, and a requirement for LRP6 is not reported in our evidence.","affinity_potency":[],"species_and_systems":"Experiments used reporter cells in a rescue design with FZD-mutant lines [PMID:28733458]; species of the cells is not stated in the excerpts.","localisation_and_range":"Secreted ligand per the entity annotation flag [flag]; paracrine range is inferred from that flag only, not reported in the papers.","caveats":"Functional reporter readout only; no direct binding shown. Paper is a genetic rescue map of Wnt-FZD pairs, so paralog FZDs differ in specificity [PMID:28733458].","key_references":[{"PMID":"28733458","why":"Multiplex CRISPR FZD-knockout rescue map of Wnt-Frizzled signalling (full text read)."}],"covers":["LR008047"]},"LR005383":{"pair":"WNT9A -> FZD4","headline":"WNT9A signals through FZD4 in a reporter-cell rescue map; functional evidence from one paper, no binding data.","interaction_type":"functional only","direction_and_effect":"WNT9A signalled only via FZD4 and FZD10 among the FZDs tested, inducing canonical reporter signalling (agonism) [PMID:28733458].","molecular_requirements":"Only the Frizzled receptor is tested; co-receptors are not reported in our evidence.","affinity_potency":[],"species_and_systems":"Experiments used reporter cells in a rescue design with FZD-mutant lines [PMID:28733458]; species of the cells is not stated in the excerpts. The mouse pair is projected from the human evidence (ortholog-inferred).","localisation_and_range":"Secreted ligand per the entity annotation flag [flag]; paracrine range is inferred from that flag only, not reported in the papers.","caveats":"Functional reporter readout only; no direct binding shown. Paper is a genetic rescue map of Wnt-FZD pairs, so paralog FZDs differ in specificity [PMID:28733458].","key_references":[{"PMID":"28733458","why":"Multiplex CRISPR FZD-knockout rescue map of Wnt-Frizzled signalling (full text read)."}],"covers":["LR002057","LR005383"]},"LR008074":{"pair":"WNT9B -> FZD5:LRP6","headline":"Database-asserted WNT9B to FZD5:LRP6 complex; no curator-verified paper supports the complex as a unit.","interaction_type":"database-asserted only","direction_and_effect":"Direction and effect are not reported in our evidence. UniProt subunit notes assert that FZD-family O14905 (WNT9B) interacts directly in the complex with LRP6 and that LRP6 (via beta-propeller regions 1 and 2) interacts with WNT9B [DB:UniProt].","molecular_requirements":"The complex is the FZD5 plus LRP6 pair; no experiment in our evidence tests the combination. Support is from UniProt notes about WNT9B and LRP6 only [DB:UniProt].","affinity_potency":[],"species_and_systems":"Not reported in our evidence; the UniProt records cite PMID 20093360 and PMID 11357136 but no dossier paper was verified for this complex [DB:UniProt].","localisation_and_range":"WNT9B is flagged as secreted [flag], so signalling would be paracrine; the receptor is a membrane receptor [flag].","caveats":"Rests on database records alone; the notes do not name the Frizzled chain. Papers were judged only as review_only or abstract_insufficient. Treat as a projection from WNT9B-LRP6 evidence.","key_references":[],"covers":["LR008074"]},"LR010765":{"pair":"WNT9B -> FZD9:LRP6","headline":"FZD9:LRP6 complex is supported only through WNT9B-LRP6 binding; the FZD9 chain has no direct evidence.","interaction_type":"direct binding","direction_and_effect":"Wnt9b binds the LRP6 extracellular domain at E1E2, and Wnt3a and Wnt9b bind LRP6 simultaneously [PMID:20093360].","molecular_requirements":"Evidence addresses LRP6 only; FZD9 is not tested in our evidence. UniProt notes that WNT9B interacts with LRP6 (beta-propeller 1 and 2) [DB:UniProt].","affinity_potency":[],"species_and_systems":"Purified proteins (soluble Fz8 CRD and LRP6 ectodomain); curated as human ligand and receptor, abstract only [PMID:20093360].","localisation_and_range":"WNT9B is flagged as secreted [flag], so signalling would be paracrine; the receptor is a membrane receptor [flag].","caveats":"Chain-only evidence: the LRP6 chain alone; FZD9 not shown. Read as abstract only.","key_references":[{"PMID":"20093360","why":"Wnt9b binds LRP6 E1E2"}],"covers":["LR010765"]},"LR003547":{"pair":"WNT9B -> LRP6","headline":"WNT9B binds the E1E2 region of the LRP6 extracellular domain, shown with purified proteins.","interaction_type":"direct binding","direction_and_effect":"Wnt9b binds a different part of the LRP6 extracellular domain, E1E2, than Wnt3a (E3E4), and both bind LRP6 at the same time; curators label it agonist [PMID:20093360]. Dkk1 competes with both for LRP6 [PMID:20093360].","molecular_requirements":"Soluble Fz8-CRD and LRP6 ectodomain inhibit Wnt/beta-catenin signalling in cell assays; the Fz8 CRD.Wnt3a.LRP6 complex was reconstituted with Wnt3a [PMID:20093360]. UniProt records the direct interaction [DB:UniProt].","affinity_potency":[],"species_and_systems":"Insect-cell expressed mouse Fz8 CRD and human LRP6 ectodomain, purified proteins; mouse and human pairs are ortholog-inferred [PMID:20093360].","localisation_and_range":"WNT9B is flagged as secreted [flag], so signalling would be paracrine; the receptor is a membrane receptor [flag].","caveats":"Read as abstract only; no Wnt9b-LRP6 affinity appears in our excerpts. Agonist label is a curator inference.","key_references":[{"PMID":"20093360","why":"Wnt9b binds LRP6 E1E2, independently of Wnt3a"}],"covers":["LR003547","LR006747"]},"LR012385":{"pair":"ZNRF3 -> FZD6:LRP6","headline":"Database-asserted only: ZNRF3 (an E3 ligase) is listed as inhibiting a FZD:LRP receptor complex; no curator-verified paper.","interaction_type":"database-asserted only","direction_and_effect":"Marked inhibitory in the resource, with ZNRF3 acting as a membrane receptor-receptor regulator rather than a classical secreted ligand [flag]. UniProt states ZNRF3 interacts with LRP6, FZD4, FZD5, FZD6 and FZD8 [PMID:22575959][DB:UniProt]; IntAct records anti-bait co-immunoprecipitation (Q9ULT6-O60353, Q9ULT6-O75581) [DB:IntAct]; BioGRID records ZNRF3 - LRP6: Affinity Capture-Western; LRP6 - ZNRF3: Affinity Capture-Western [DB:BioGRID]; Reactome lists ZNRF3,RNF43 binding the FZD:LRP5/6 receptor complex [DB:Reactome]. Functional effect not reported in our evidence.","molecular_requirements":"The listed FZD6 partner is named in the UniProt statement; LRP6 evidence is present [DB:UniProt]. Whether FZD or LRP alone suffices is not reported in our evidence.","affinity_potency":[],"species_and_systems":"Human. Experimental system not reported in our evidence beyond the database assay labels.","localisation_and_range":"ZNRF3 is flagged as a receptor, not secreted [flag]; this is a membrane-level interaction.","caveats":"All papers for this pair are pending or insufficient; support comes only from databases. The pair is a receptor-receptor complex projection and a given FZD paralog may not have been tested individually.","key_references":[],"covers":["LR012385"]},"LR004186":{"pair":"GDF6 -> BMPR1A","headline":"Functional and binding evidence from papers using ALK3/BMPR-IA naming; GDF6 acts as an agonist, though one study found only weak BMPR-IA binding.","interaction_type":"functional only","direction_and_effect":"Overexpressing ALK3 or ALK6 in COS7 cells conferred GDF6 signalling, and ALK3 shRNA suppressed Smad signalling induced by GDF6 and two other ligands, consistent with an agonist [PMID:16049014]. CDMP-2 (GDF6) bound BMPR-IB and BMPR-II with affinity and BMPR-IA only weakly [PMID:9525338].","molecular_requirements":"Both type I receptors ALK3 and ALK6 conferred GDF6 signalling [PMID:16049014]. CDMP-2 signalling through BMPR-IB needed BMPR-II [PMID:9525338]. A third paper tested BMP13 (named GDF6's alias in PMID:16049014) and reported binding of ALK3, ALK6 and type II receptors [PMID:21702718].","affinity_potency":[],"species_and_systems":"Human recombinant ligand and receptors in all three papers; cells were COS7 and MC3T3 [PMID:16049014] and primary chondrocytes plus osteogenic cell lines [PMID:9525338]. Binding was by Octet or surface plasmon resonance [PMID:21702718].","localisation_and_range":"GDF6 is flagged secreted and BMPR1A transmembrane [flag], so paracrine signalling is implied by the flags.","caveats":"All three papers were read as abstracts (two have full-text excerpts). The CDMP-2 binding result is weak for BMPR-IA [PMID:9525338]. The BioGRID record in the dossier is for GDF6 - BMPR1B, not BMPR1A [DB:BioGRID]. Receptor names (ALK3, BMPR-IA) are mapped to BMPR1A by the curators. The mouse pair is projected from human evidence.","key_references":[{"PMID":"16049014","why":"ALK3 overexpression and knockdown set GDF6 signalling"},{"PMID":"9525338","why":"CDMP-2 (GDF6) receptor binding, BMPR-IA weak"},{"PMID":"21702718","why":"BMP13 binding to type I and II receptors"}],"covers":["LR000702","LR004186"]},"LR008407":{"pair":"TXLNA -> STX4","headline":"Database-asserted binding of TXLNA to STX4; no curated papers, support rests on BioGRID and Reactome records.","interaction_type":"database-asserted only","direction_and_effect":"Direction and effect (agonist, antagonist or other) are not reported in our evidence. Reactome lists a binding reaction (TXLNA binds syntaxin4) and a TXLNA:STX4 complex at the plasma membrane [DB:Reactome] [PMID:12558796].","molecular_requirements":"Subunit or co-receptor requirements are not reported in our evidence. The records describe a two-protein complex.","affinity_potency":[],"species_and_systems":"Human pair [DB:BioGRID]. BioGRID labels the record a reconstituted complex [PMID:12558796].","localisation_and_range":"Reactome places the complex at the plasma membrane [DB:Reactome]; range from annotation flags or paper text is not reported in our evidence.","caveats":"No curated paper was judged for this pair (the one judged row was classed different_entity), so support comes only from database records. Papers were not read by curators for this pair.","key_references":[{"PMID":"12558796","why":"Source cited by BioGRID and Reactome for the binding record"}],"covers":["LR008407"]}};